TURATH_CHUNK(81,[{"num":16200,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَوَّلُ مَا يُقْضَى بَيْنَ النَّاسِ يَوْمَ الْقِيَامَةِ فِي الدِّمَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6533)، ومسلم في القسامة (28:1678) كلاهما من طريق الأعمش، عن شقيق أبي وائل، عن عبد الله، فذكره.","grade":"متفق عليه","chapter_ar":"باب أول ما يقضى بين الناس يوم القيامة من حقوقهم في الدماء","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6533) and Muslim (28:1678).","chapter_en":"The First Disputes among the People to Be Judged on the Day of Resurrection Will Concern Bloodshed","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":30,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “The first matters to be judged between the people on the Day of Resurrection will concern bloodshed.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6533)، ومسلم (28:1678)."},{"num":16201,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَّلُ خَصْمَيْنِ يَوْمَ الْقِيَامَةِ جَارَانِ."],"takhrij":"حسن: رواه أحمد (17372)، والطبراني في الكبير (17/ح 836) كلاهما من طريق قتيبة بن سعيد، حدثنا ابن لهيعة، عن أبي عشانة، عن عقبة بن عامر، فذكره.","grade":"حسن","chapter_ar":"باب أول خصمين يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17372) and al-Ṭabarānī in al-Muʿjam al-Kabīr (17/309).","chapter_en":"The First Two Litigants on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":31,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated that the Messenger of Allah ﷺ said: “The first two disputants on the Day of Resurrection will be two neighbors.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13196,14183],"tks":"حسن: رواه أحمد (17372)، والطبراني في الكبير (17/ح 836)."},{"num":16202,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَوَّلَ مَا يُسْأَلُ عَنْهُ يَوْمَ الْقِيَامَةِ يَعْنِي الْعَبْدَ مِنَ النَّعِيمِ أَنْ يُقَالَ لَهُ: أَلَمْ نُصِحَّ لَكَ جِسْمَكَ، وَنُرْوِيكَ مِنَ الْمَاءِ الْبَارِدِ."],"takhrij":"صحيح: رواه الترمذي (3358)، والبزار (9408)، وعبد الله بن أحمد في زوائد الزهد (ص 31)، وصحّحه ابن حبان (7364)، والحاكم (7203) كلهم من طريق عبد الله بن العلاء بن زبر، عن الضحاك بن عبد الرحمن بن عرزم –أو عرزب- الأشعري قال: سمعت أبا هريرة يقول فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في السؤال عن النعيم","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3358), al-Bazzār (9408), and ʿAbdullāh ibn Aḥmad in Zawāʾid al-Zuhd (p. 31).","chapter_en":"What Has Been Narrated Concerning Being Questioned about Blessings","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The first blessing about which the servant will be questioned on the Day of Resurrection will be that it is said to him: ‘Did We not give you a healthy body and give you cold water to drink?’”"]},"intro":{"ar":["قال تعالى:","﴿ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ﴾ [سورة التكاثر: ٨]."],"en":["Allah, the Exalted, says:","“Then, on that Day, you will surely be questioned about the blessings.”","[al-Takāthur 102:8]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3358)، والبزار (9408)، وعبد الله بن أحمد في زوائد الزهد (ص 31)."},{"num":16203,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ أَوْ لَيْلَةٍ، فَإِذَا هُوَ بِأَبِي بَكْرٍ، وَعُمَرَ، فَقَالَ: مَا أَخْرَجَكُمَا مِنْ بُيُوتِكُمَا هَذِهِ السَّاعَةَ؟. قَالَا: الْجُوعُ يَا رَسُولَ اللَّهِ. قَالَ: وَأَنَا وَالَّذِي نَفْسِي بِيَدِهِ، لَأَخْرَجَنِي الَّذِي أَخْرَجَكُمَا، قُومُوا. فَقَامُوا مَعَهُ، فَأَتَى رَجُلًا مِنَ الْأَنْصَارِ، فَإِذَا هُوَ لَيْسَ فِي بَيْتِهِ، فَلَمَّا رَأَتْهُ الْمَرْأَةُ قَالَتْ: مَرْحَبًا وَأَهْلًا، فَقَالَ لَهَا رَسُولُ اللَّهِ: صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيْنَ فُلَانٌ؟ قَالَتْ: ذَهَبَ يَسْتَعْذِبُ لَنَا مِنَ الْمَاءِ، إِذْ جَاءَ الْأَنْصَارِيُّ فَنَظَرَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَاحِبَيْهِ، ثُمَّ قَالَ: الْحَمْدُ لِلهِ، مَا أَحَدٌ الْيَوْمَ أَكْرَمَ أَضْيَافًا مِنِّي. قَالَ: فَانْطَلَقَ، فَجَاءَهُمْ بِعِذْقٍ، فِيهِ بُسْرٌ وَتَمْرٌ وَرُطَبٌ، فَقَالَ: كُلُوا مِنْ هَذِهِ. وَأَخَذَ الْمُدْيَةَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِيَّاكَ وَالْحَلُوبَ. فَذَبَحَ لَهُمْ فَأَكَلُوا مِنَ الشَّاةِ، وَمِنْ ذَلِكَ الْعِذْقِ، وَشَرِبُوا، فَلَمَّا أَنْ شَبِعُوا وَرَوُوا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ، وَعُمَرَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَتُسْأَلُنَّ عَنْ هَذَا النَّعِيمِ يَوْمَ الْقِيَامَةِ، أَخْرَجَكُمْ مِنْ بُيُوتِكُمُ الْجُوعُ، ثُمَّ لَمْ تَرْجِعُوا حَتَّى أَصَابَكُمْ هَذَا النَّعِيمُ.","وَفِي رِوَايَةِ: لَا تذبحنَّ ذاتَ دُرٍّ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2038: 140) عن أبي بكر بن أبي شيبة، ثنا خلف بن خليفة، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في السؤال عن النعيم","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (140 :2038).","chapter_en":"What Has Been Narrated Concerning Being Questioned about Blessings","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ went out one day—or one night—and found Abū Bakr and ʿUmar. He asked: “What brought you out of your homes at this hour?” They replied: “Hunger, O Messenger of Allah.” He said: “By the One in whose hand is my soul, the same thing that brought you out brought me out as well. Get up.” So they went with him to the home of a man from the Anṣār, but he was not at home. When his wife saw them, she said: “Welcome and greetings.” The Messenger of Allah ﷺ asked her: “Where is so-and-so?” She replied: “He has gone to fetch sweet water for us.” Then the Anṣārī man arrived. When he saw the Messenger of Allah ﷺ and his two companions, he said: “All praise is due to Allah. No one today has more honored guests than I do.” He went and brought them a cluster of dates containing unripe, ripe, and fresh dates and said: “Eat from these.” Then he took up a knife. The Messenger of Allah ﷺ said to him: “Do not slaughter a milk-giving animal.” He slaughtered an animal for them, and they ate from the sheep and from the dates and drank. When they had eaten their fill and quenched their thirst, the Messenger of Allah ﷺ said to Abū Bakr and ʿUmar: “By the One in whose hand is my soul, you will surely be questioned about this blessing on the Day of Resurrection. Hunger brought you out of your homes, and you did not return until this blessing had reached you.” In another narration: “Do not slaughter an animal that gives milk.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7296,13770],"tks":"صحيح: رواه مسلم (2038: 140)."},{"num":16204,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ الأَسْلَمِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَزُولُ قَدَمَا عَبْدٍ يَوْمَ الْقِيَامَةِ حَتَّى يُسْأَلَ عَنْ عُمْرِهِ فِيمَا أَفْنَاهُ، وَعَنْ عِلْمِهِ فِيمَا فَعَلَ، وَعَنْ مَالِهِ مِنْ أَيْنَ اكْتَسَبَهُ وَفِيمَا أَنْفَقَهُ، وَعَنْ جِسْمِهِ فِيمَا أَبْلاَهُ."],"takhrij":"حسن: رواه الترمذي (2417) عن عبد الله بن عبد الرحمن، أخبرنا الأسود بن عامر، حدثنا أبو بكر بن عياش، عن الأعمش، عن سعيد بن عبد الله بن جريج، عن أبي برزة الأسلمي، فذكره.","grade":"حسن","chapter_ar":"باب يسأل العبد يوم القيامة عن أربع: عن عمره، وعلمه، وماله، وجسمه","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2417).","chapter_en":"The Servant Will Be Questioned on the Day of Resurrection about Four Things: His Life, His Knowledge, His Wealth, and His Body","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":33,"content":{"translation":{"en":["Abū Barzah al-Aslamī narrated that the Messenger of Allah ﷺ said: “The feet of a servant will not move on the Day of Resurrection until he is questioned about his life and how he spent it, about his knowledge and what he did with it, about his wealth—where he earned it and how he spent it—and about his body and how he wore it out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2417)."},{"num":16205,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُدْعَى نُوحٌ يَوْمَ الْقِيَامَةِ، فَيَقُولُ: لَبَّيْكَ وَسَعْدَيْكَ يَا رَبِّ. فَيَقُولُ: هَلْ بَلَّغْتَ؟ فَيَقُولُ: نَعَمْ. فَيُقَالُ لأُمَّتِهِ: هَلْ بَلَّغَكُمْ؟ فَيَقُولُونَ: مَا أَتَانَا مِنْ نَذِيرٍ. فَيَقُولُ: مَنْ يَشْهَدُ لَكَ؟ فَيَقُولُ: مُحَمَّدٌ وَأُمَّتُهُ. فَتَشْهَدُونَ أَنَّهُ قَدْ بَلَّغَ. {وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا} فَذَلِكَ قَوْلُهُ جَلَّ ذِكْرُهُ: ﴿وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ [سورة البقرة: 143]}. وَالْوَسَطُ: الْعَدْلُ.","وفي لفظ: يَجِيءُ النَّبِيُّ يَوْمَ الْقِيَامَةِ، وَمَعَهُ الرَّجُلُ، وَالنَّبِيُّ وَمَعَهُ الرَّجُلَانِ، وَأَكْثَرُ مِنْ ذَلِكَ، فَيُدْعَى قَوْمُهُ، فَيُقَالُ لَهُمْ: هَلْ بَلَّغَكُمْ هَذَا؟ فَيَقُولُونَ: لَا. فَيُقَالُ لَهُ: هَلْ بَلَّغْتَ قَوْمَكَ؟ فَيَقُولُ: نَعَمْ. فَيُقَالُ لَهُ: مَنْ يَشْهَدُ لَكَ؟ فَيَقُولُ: مُحَمَّدٌ وَأُمَّتُهُ. فَيُدْعَى وَأُمَّتُهُ، فَيُقَالُ لَهُمْ: هَلْ بَلَّغَ هَذَا قَوْمَهُ؟ فَيَقُولُونَ: نَعَمْ. فَيُقَالُ: وَمَا عِلْمُكُمْ؟ فَيَقُولُونَ: جَاءَنَا نَبِيُّنَا، فَأَخْبَرَنَا أَنَّ الرُّسُلَ قَدْ بَلَّغُوا، فَذَلِكَ قَوْلُهُ: وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا قَالَ: يَقُولُ: عَدْلًا ﴿لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ [سورة الْبَقَرَةِ: 143]143]."],"takhrij":"صحيح: رواه البخاري في التفسير (4487) عن يوسف بن راشد، حدثنا جرير، عن الأعمش، عن أبي صالح، عن أبي سعيد الخدري، فذكره.","grade":"صحيح","chapter_ar":"باب شهادة النبي ﷺ وأمته على الأمم","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4487). The second wording was narrated by Aḥmad (11558).","chapter_en":"The Testimony of the Prophet ﷺ and His Ummah against the Nations","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":34,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Nūḥ will be summoned on the Day of Resurrection and will say: ‘At Your service and ready to obey, my Lord.’ Allah will ask: ‘Did you convey the message?’ He will reply: ‘Yes.’ His nation will then be asked: ‘Did he convey the message to you?’ They will say: ‘No warner came to us.’ It will be said to Nūḥ: ‘Who will testify for you?’ He will reply: ‘Muḥammad and his Ummah.’ So you will testify that he conveyed the message, and the Messenger will be a witness over you. This is the meaning of the statement of Allah, Glorious is His remembrance: ‘Thus We have made you a just and balanced nation so that you may be witnesses over mankind and the Messenger may be a witness over you.’ [al-Baqarah 2:143]” The word “wasaṭ” means just.","In another wording: “A Prophet will come on the Day of Resurrection accompanied by one man, another Prophet accompanied by two men, and another by more than that. His people will be summoned and asked: ‘Did this man convey the message to you?’ They will say: ‘No.’ The Prophet will be asked: ‘Did you convey the message to your people?’ He will reply: ‘Yes.’ It will be asked: ‘Who will testify for you?’ He will say: ‘Muḥammad and his Ummah.’ Muḥammad and his Ummah will then be summoned and asked: ‘Did this Prophet convey the message to his people?’ They will reply: ‘Yes.’ It will be asked: ‘How do you know?’ They will say: ‘Our Prophet came to us and informed us that the Messengers had conveyed their messages.’ That is the meaning of His statement: ‘Thus We have made you a wasaṭ nation’—meaning just—‘so that you may be witnesses over mankind and the Messenger may be a witness over you.’”"]},"intro":{"ar":["قال تعالى:","﴿وَكَذَٰلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا﴾ [البقرة: ١٤٣]."],"en":["Allah, the Exalted, says:","“Thus We have made you a just and balanced nation so that you may be witnesses over mankind and the Messenger may be a witness over you.”","[al-Baqarah 2:143]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4487)، واللفظ الثاني رواه أحمد (11558)."},{"num":16206,"demo":false,"sanad":"","matn":["عَنْ يُحَنَِّسَ مَوْلَى الزُّبَيْرِ، أَخْبَرَهُ  أَنَّهُ كَانَ جَالِسًا عِنْدَ عَبْدِ اللَّهِ بْنِ عُمَرَ فِي الْفِتْنَةِ، فَأَتَتْهُ مَوْلَاةٌ لَهُ تُسَلِّمُ عَلَيْهِ، فَقَالَتْ: إِنِّي أَرَدْتُ الْخُرُوجَ، يَا أَبَا عَبْدِ الرَّحْمَنِ، اشْتَدَّ عَلَيْنَا الزَّمَانُ، فَقَالَ لَهَا عَبْدُ اللَّهِ: اقْعُدِي لَكَاعِ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: لَا يَصْبِرُ عَلَى لَأْوَائِهَا وَشِدَّتِهَا أَحَدٌ، إِلَّا كُنْتُ لَهُ شَهِيدًا أَوْ شَفِيعًا يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مالك في الجامع (3) عن قطن بن وهب بن عمير بن الأجدع، عن يحنس مولى الزبير، فذكره.","grade":"صحيح","chapter_ar":"باب شهادة النبي ﷺ وشفاعته لمن صبر على لأواء المدينة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in al-Jāmiʿ (3) and Muslim (482:1377).","chapter_en":"The Prophet’s ﷺ Testimony and Intercession for Whoever Patiently Endures the Hardships of Madinah","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Yaḥnas, the freedman of al-Zubayr ibn al-ʿAwwām, narrated that he was sitting with ʿAbdullāh ibn ʿUmar during a time of tribulation when a female servant of his came to greet him. She said: “I want to leave, O Abū ʿAbd al-Raḥmān. Times have become difficult for us.” ʿAbdullāh said to her: “Remain here, foolish woman, for I heard the Messenger of Allah ﷺ say: ‘No one patiently endures the hardships and severity of Madinah except that I will be a witness or an intercessor for him on the Day of Resurrection.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10631],"tks":"صحيح: رواه مالك (3) ومسلم (482:1377)."},{"num":16207,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ مَوْلَى الْمَهْرِيِّ،  أَنَّهُ جَاءَ أَبَا سَعِيدٍ الْخُدْرِيَّ لَيَالِيَ الْحَرَّةِ، فَاسْتَشَارَهُ فِي الْجَلَاءِ مِنَ الْمَدِينَةِ، وَشَكَا إِلَيْهِ أَسْعَارَهَا، وَكَثْرَةَ عِيَالِهِ، وَأَخْبَرَهُ أَنْ لَا صَبْرَ لَهُ عَلَى جَهْدِ الْمَدِينَةِ وَلَأْوَائِهَا، فَقَالَ لَهُ: وَيْحَكَ! لَا آمُرُكَ بِذَلِكَ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَصْبِرُ أَحَدٌ عَلَى لَأْوَائِهَا، فَيَمُوتَ، إِلَّا كُنْتُ لَهُ شَفِيعًا أَوْ شَهِيدًا يَوْمَ الْقِيَامَةِ إِذَا كَانَ مُسْلِمًا."],"takhrij":"صحيح: رواه مسلم في الحج (477:1374) عن قتيبة بن سعيد، حدثنا ليث، عن سعيد بن أبي سعيد، عن أبي سعيد، مولى المهري، فذكره.","grade":"صحيح","chapter_ar":"باب شهادة النبي ﷺ وشفاعته لمن صبر على لأواء المدينة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (477:1374).","chapter_en":"The Prophet’s ﷺ Testimony and Intercession for Whoever Patiently Endures the Hardships of Madinah","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Abū Saʿīd, the freedman of al-Mahrī, came to Abū Saʿīd al-Khudrī during the nights of al-Ḥarrah and consulted him about leaving Madinah. He complained about its high prices and his large family and told him that he could no longer endure the hardship and difficulty of life in Madinah. Abū Saʿīd said: “Woe to you! I will not advise you to do that. I heard the Messenger of Allah ﷺ say: ‘No Muslim patiently endures the hardships of Madinah until he dies except that I will be an intercessor or a witness for him on the Day of Resurrection.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10634],"tks":"صحيح: رواه مسلم (477:1374)."},{"num":16208,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -فِي حَدِيثِ رُؤْيَةِ الرب يَوْمَ الْقِيَامَةِ-: ثُمَّ يُقَالُ لَهُ: الْآنَ نَبْعَثُ شَاهِدَنَا عَلَيْكَ، وَيَتَفَكَّرُ فِي نَفْسِهِ: مَنْ ذَا الَّذِي يَشْهَدُ عَلَيَّ؟ فَيُخْتَمُ عَلَى فِيهِ، وَيُقَالُ لِفَخِذِهِ وَلَحْمِهِ وَعِظَامِهِ: انْطِقِي، فَتَنْطِقُ فَخِذُهُ وَلَحْمُهُ وَعِظَامُهُ بِعَمَلِهِ، وَذَلِكَ لِيُعْذِرَ مِنْ نَفْسِهِ، وَذَلِكَ الْمُنَافِقُ وَذَلِكَ الَّذِي يَسْخَطُ اللهُ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2968) عن محمد بن أبي عمر، حدثنا سفيان، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما يشهد يوم القيامة من أعضاء الإنسان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2968).","chapter_en":"The Parts of the Human Body That Will Testify on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":36,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said, in the hadith concerning seeing the Lord on the Day of Resurrection: “Then it will be said to him: ‘Now We will bring Our witness against you.’ He will think to himself: ‘Who could testify against me?’ His mouth will then be sealed, and his thigh, flesh, and bones will be told: ‘Speak.’ His thigh, flesh, and bones will then speak about his deeds. This will be so that every excuse is removed from him. That is the hypocrite, and that is the one with whom Allah is angry.”"]},"intro":{"ar":["قال تعالى:","﴿يَوْمَ تَشْهَدُ عَلَيْهِمْ أَلْسِنَتُهُمْ وَأَيْدِيهِمْ وَأَرْجُلُهُمْ بِمَا كَانُوا يَعْمَلُونَ﴾ [النور: ٢٤].","وقال تعالى:","﴿حَتَّىٰ إِذَا مَا جَاءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَارُهُمْ وَجُلُودُهُمْ بِمَا كَانُوا يَعْمَلُونَ ۝ وَقَالُوا لِجُلُودِهِمْ لِمَ شَهِدْتُمْ عَلَيْنَا قَالُوا أَنْطَقَنَا اللَّهُ الَّذِي أَنْطَقَ كُلَّ شَيْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ﴾ [فصلت: ٢٠-٢١]."],"en":["Allah, the Exalted, says:","“On the Day when their tongues, their hands, and their feet will testify against them concerning what they used to do.”","[al-Nūr 24:24]","And He, the Exalted, says:","“Until, when they reach it, their hearing, their sight, and their skins will testify against them concerning what they used to do. They will say to their skins: ‘Why did you testify against us?’ They will reply: ‘Allah, who gives speech to everything, has made us speak. He created you the first time, and to Him you are being returned.’”","[Fuṣṣilat 41:20-21]"]}},"tuhfa":{},"full":1,"rep":[13150],"tks":"صحيح: رواه مسلم (2968)."},{"num":16209,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:  كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَضَحِكَ، فَقَالَ: هَلْ تَدْرُونَ مِمَّ أَضْحَكُ؟. قَالَ: قُلْنَا: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: مِنْ مُخَاطَبَةِ الْعَبْدِ رَبَّهُ، يَقُولُ: يَا رَبِّ، أَلَمْ تُجِرْنِي مِنَ الظُّلْمِ؟. قَالَ: يَقُولُ: بَلَى. قَالَ: فَيَقُولُ: فَإِنِّي لَا أُجِيزُ عَلَى نَفْسِي إِلَّا شَاهِدًا مِنِّي. قَالَ: فَيَقُولُ: كَفَى بِنَفْسِكَ الْيَوْمَ عَلَيْكَ شَهِيدًا، وَبِالْكِرَامِ الْكَاتِبِينَ شُهُودًا. قَالَ: فَيُخْتَمُ عَلَى فِيهِ، فَيُقَالُ لِأَرْكَانِهِ: انْطِقِي. قَالَ: فَتَنْطِقُ بِأَعْمَالِهِ. قَالَ: ثُمَّ يُخَلَّى بَيْنَهُ وَبَيْنَ الْكَلَامِ. قَالَ: فَيَقُولُ: بُعْدًا لَكُنَّ وَسُحْقًا، فَعَنْكُنَّ كُنْتُ أُنَاضِلُ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2968) عن أبي بكر بن النضر بن أبي النضر، حدثني أبو النضر هاشم بن القاسم، حدثنا عبيد الله الأشجعي، عن سفيان الثوري، عن عبيد المكتب، عن فضيل، عن الشعبي، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ما يشهد يوم القيامة من أعضاء الإنسان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2968).","chapter_en":"The Parts of the Human Body That Will Testify on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":36,"content":{"translation":{"en":["Anas ibn Mālik narrated: We were with the Messenger of Allah ﷺ when he laughed. He asked: “Do you know what made me laugh?” We replied: “Allah and His Messenger know best.” He said: “It is because of the conversation between a servant and his Lord. The servant will say: ‘My Lord, did You not protect me from injustice?’ Allah will say: ‘Yes.’ The servant will say: ‘Then I will accept no witness against myself except one from myself.’ Allah will say: ‘Today you are sufficient as a witness against yourself, and the noble recording angels are sufficient as witnesses.’ Then his mouth will be sealed, and his limbs will be told: ‘Speak.’ They will speak about his deeds. Then he will be allowed to speak again, and he will say to his limbs: ‘Away with you! Woe to you! It was on your behalf that I was arguing!’”"]}},"tuhfa":{},"full":1,"rep":[12860,13151,13685],"tks":"صحيح: رواه مسلم (2968)."},{"num":16210,"demo":false,"sanad":"","matn":["عَنْ بَهْزِ بْنِ حَكِيمٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ فِي حَدِيثِ طَوِيلٍ: مَا لِي أُمْسِكُ بِحُجَزِكُمْ عَنِ النَّارِ؟ أَلَا إِنَّ رَبِّي دَاعِيَّ وَإِنَّهُ سَائِلِي: هَلْ بَلَّغْتُ عِبَادَهُ؟ وَإِنِّي قَائِلٌ: رَبِّ إِنِّي قَدْ بَلَّغْتُهُمْ فَلْيُبَلِّغِ الشَّاهِدُ مِنْكُمُ الْغَائِبَ، ثُمَّ إِنَّكُمْ مَدْعُوُّونَ مُفَدَّمَةً أَفْوَاهُكُمْ بِالْفِدَامِ، ثُمَّ إِنَّ أَوَّلَ مَا يُبِينُ عَنْ أَحَدِكُمْ لَفَخِذُهُ وَكَفُّهُ. قُلْتُ يَا نَبِيَّ اللَّهِ: هَذَا دِينُنَا؟ قَالَ: هَذَا دِينُكُمْ وَأَيْنَمَا تُحْسِنْ يَكْفِكَ."],"takhrij":"حسن: رواه أحمد (20043) عن إسماعيل، أخبرنا بهز بن حكيم، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ما يشهد يوم القيامة من أعضاء الإنسان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20043).","chapter_en":"The Parts of the Human Body That Will Testify on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":36,"content":{"translation":{"en":["Bahz ibn Ḥakīm narrated from his father, from his grandfather: I came to the Prophet ﷺ, and in a lengthy hadith he said: “Why am I holding you back by your waistbands from the Fire? Indeed, my Lord will call me and ask me: ‘Did you convey My message to My servants?’ I will say: ‘My Lord, I conveyed it to them.’ So let those who are present convey it to those who are absent. Then you will be summoned with your mouths restrained by a muzzle, and the first part of one of you to speak will be his thigh and his hand.” I asked: “O Prophet of Allah, is this our religion?” He replied: “This is your religion, and wherever you do good, it will suffice you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20043)."},{"num":16211,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ أَنَّهُ قَالَ لِعَبْدِ اللَّهِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي صَعْصَعَةَ الأَنْصَارِيِّ ثُمَّ الْمَازِنِيِّ: إِنِّي أَرَاكَ تحبُ الْغَنَمَ وَالْبَادِيَةَ، فَإِذَا كُنْتَ فِي غَنَمِكَ، أَوْ بَادِيَتِكَ، فأذَّنت بِالصَّلاَةِ فَارْفَعْ صَوْتَكَ بِالنِّدَاءِ، فَإِنَّهُ: لاَ يَسْمَعُ مَدَى صوتِ الْمُؤَذِّنِ جنٌّ وَلاَ إِنْسٌ وَلاَ شيءٌ، إِلاَّ شَهِدَ لَهُ يَوْمَ الْقِيَامَةِ. قَالَ أَبُو سَعِيدٍ: سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ."],"takhrij":"صحيح: أخرجه مالك في الصلاة (5) عن عبدالرحمن بن عبدالله بن","grade":"صحيح","chapter_ar":"باب شهادة الإنس والجن وكل رطب ويابس للمؤذن","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in al-Ṣalāh (5) and al-Bukhārī (609).","chapter_en":"The Testimony of Humans, Jinn, and Every Living and Inanimate Thing for the Muʾadhdhin","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":37,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said to ʿAbdullāh ibn ʿAbd al-Raḥmān ibn Abī Ṣaʿṣaʿah al-Anṣārī al-Māzinī: “I see that you love sheep and the open countryside. When you are with your sheep or out in the desert and call the adhān for prayer, raise your voice with the call, for: ‘No jinn, human being, or anything else within the range of the muʾadhdhin’s voice hears it except that it will testify for him on the Day of Resurrection.’” Abū Saʿīd said: “I heard this from the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1859,8229],"tks":"صحيح: أخرجه مالك (5) والبخاري (609)."},{"num":16212,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: الْمُؤَذِّنُ يُغْفَرُ لَهُ مَدَى صَوْتِهِ، وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ، وَشَاهِدُ الصَّلاَةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ صَلاَةً، وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا."],"takhrij":"حسن: رواه أبو داود (515) واللفظ له، والنسائي (645) وابن ماجه (724) كلهم من طريق شعبة، عن موسى بن أبي عثمان، عن أبي يحيى، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب شهادة الإنس والجن وكل رطب ويابس للمؤذن","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (515), whose wording this is, al-Nasā’ī (645), and Ibn Mājah (724).","chapter_en":"The Testimony of Humans, Jinn, and Every Living and Inanimate Thing for the Muʾadhdhin","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":37,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The mu’adhdhin will be forgiven to the extent reached by his voice, and every living and inanimate thing will testify for him. Whoever attends the prayer will have the reward of twenty-five prayers recorded for him, and the sins committed between the two prayers will be expiated.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (515) واللفظ له، والنسائي (645) وابن ماجه (724)."},{"num":16213,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحَجَرِ: وَاللَّهِ لَيَبْعَثَنَّهُ اللَّهُ يَوْمَ الْقِيَامَةِ، لَهُ عَيْنَانِ يُبْصِرُ بِهِمَا، وَلِسَانٌ يَنْطِقُ بِهِ، يَشْهَدُ عَلَى مَنِ اسْتَلَمَهُ بِحَقٍّ."],"takhrij":"حسن: رواه الترمذي (961)، وابن ماجه (2944)، وأحمد (2215، 2398، 2643)، وصحّحه ابن خزيمة (2735)، وابن حبان (3712)، والحاكم (1/457) كلهم من طريق ابن خثيم، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب شهادة الحجر الأسود لمن استلمه بحق","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (961), Ibn Mājah (2944), and Aḥmad (2643, 3398, 2215), and authenticated by Ibn Khuzaymah (2735), Ibn Ḥibbān (3712), and al-Ḥākim (1/664).","chapter_en":"The Black Stone Will Testify for Whoever Touched It Rightfully","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":38,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said concerning the Black Stone: “By Allah, Allah will surely resurrect it on the Day of Resurrection with two eyes by which it will see and a tongue by which it will speak, testifying for whoever touched it rightfully.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4984,10614],"tks":"حسن: رواه الترمذي (961)، وابن ماجه (2944)، وأحمد (2643، 3398، 2215)، وصححه ابن خزيمة (2735)، وابن حبان (3712)، والحاكم (1/664)."},{"num":16214,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بْنِ مُحْرِزٍ قَالَ:  قَالَ رَجُلٌ لِابْنِ عُمَرَ: كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ فِي النَّجْوَى؟ قَالَ: سَمِعْتُهُ يَقُولُ: يُدْنَى الْمُؤْمِنُ يَوْمَ الْقِيَامَةِ مِنْ رَبِّهِ عَزَّ وَجَلَّ، حَتَّى يَضَعَ عَلَيْهِ كَنَفَهُ، فَيُقَرِّرُهُ بِذُنُوبِهِ، فَيَقُولُ: هَلْ تَعْرِفُ؟ فَيَقُولُ: أَيْ رَبِّ أَعْرِفُ، قَالَ: فَإِنِّي قَدْ سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا، وَإِنِّي أَغْفِرُهَا لَكَ الْيَوْمَ، فَيُعْطَى صَحِيفَةَ حَسَنَاتِهِ، وَأَمَّا الْكُفَّارُ وَالْمُنَافِقُونَ، فَيُنَادَى بِهِمْ عَلَى رُؤُوسِ الْخَلَائِقِ: هَؤُلَاءِ الَّذِينَ كَذَبُوا عَلَى اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4685)، ومسلم في التوبة (2768) كلاهما من طريق هشام الدستوائي، عن قتادة، عن صفوان بن مُحْرز قال: قال رجل لابن عمر فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب يقرر الله المؤمن بذنوبه يوم القيامة ثم يغفرها له","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4685) and Muslim (2768). The wording is Muslim’s.","chapter_en":"Allah Will Make the Believer Acknowledge His Sins on the Day of Resurrection and Then Forgive Him","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":40,"content":{"translation":{"en":["Ṣafwān ibn Muḥriz narrated: A man asked Ibn ʿUmar: “How did you hear the Messenger of Allah ﷺ describe the private conversation?” He replied: I heard him say: “The believer will be brought near to his Lord, Mighty and Majestic, on the Day of Resurrection until He places His covering over him. He will make him acknowledge his sins and ask: ‘Do you recognize them?’ He will say: ‘Yes, my Lord, I recognize them.’ Allah will say: ‘I concealed them for you in the world, and today I forgive them for you.’ Then he will be given the record of his good deeds. As for the disbelievers and hypocrites, it will be proclaimed before all creation: ‘These are the ones who lied about Allah.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4685)، ومسلم (2768). واللفظ لمسلم."},{"num":16215,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ اللَّهَ لَا يَظْلِمُ مُؤْمِنًا حَسَنَةً، يُعْطَى بِهَا فِي الدُّنْيَا، وَيُجْزَى بِهَا فِي الْآخِرَةِ، وَأَمَّا الْكَافِرُ فَيُطْعَمُ بِحَسَنَاتِ مَا عَمِلَ بِهَا لِلهِ فِي الدُّنْيَا، حَتَّى إِذَا أَفْضَى إِلَى الْآخِرَةِ، لَمْ تَكُنْ لَهُ حَسَنَةٌ يُجْزَى بِهَا."],"takhrij":"صحيح: رواه مسلم في صفة القيامة والجنة والنار (2808) من طرق عن يزيد بن هارون، أخبرنا همام بن يحيى، عن قتادة، عن أنس بن مالك، قال: فذكره.","grade":"صحيح","chapter_ar":"باب جزاء المؤمن بحسناته في الدنيا والآخرة، وتعجيل حسنات الكافر في الدنيا","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2808).","chapter_en":"The Believer Is Rewarded for His Good Deeds in This World and the Hereafter, While the Disbeliever’s Reward for Good Deeds Is Hastened for Him in This World","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":41,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Allah does not wrong a believer regarding any good deed. He is given something for it in this world and rewarded for it in the Hereafter. As for the disbeliever, he is given worldly provision in return for the good deeds he performed for Allah, until when he reaches the Hereafter, he has no good deed remaining for which he will be rewarded.” In another marfūʿ narration recorded by Muslim: “When a disbeliever performs a good deed, he is given some worldly benefit because of it. As for the believer, Allah stores his good deeds for him in the Hereafter and also grants him provision in this world because of his obedience.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13240],"tks":"صحيح: رواه مسلم (2808)."},{"num":16216,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  قَالُوا: يَا رَسُولَ اللَّهِ، هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ قَالَ: هَلْ تُضَارُّونَ فِي رُؤْيَةِ الشَّمْسِ فِي الظَّهِيرَةِ، لَيْسَتْ فِي سَحَابَةٍ؟. قَالُوا: لَا. قَالَ: فَهَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ، لَيْسَ فِي سَحَابَةٍ؟. قَالُوا: لَا. قَالَ: فَوَالَّذِي نَفْسِي بِيَدِهِ، لَا تُضَارُّونَ فِي رُؤْيَةِ رَبِّكُمْ، إِلَّا كَمَا تُضَارُّونَ فِي رُؤْيَةِ أَحَدِهِمَا. قَالَ: فَيَلْقَى الْعَبْدَ، فَيَقُولُ: أَيْ فُلْ، أَلَمْ أُكْرِمْكَ، وَأُسَوِّدْكَ، وَأُزَوِّجْكَ، وَأُسَخِّرْ لَكَ الْخَيْلَ وَالْإِبِلَ، وَأَذَرْكَ تَرْأَسُ وَتَرْبَعُ؟ فَيَقُولُ: بَلَى. قَالَ: فَيَقُولُ: أَفَظَنَنْتَ أَنَّكَ مُلَاقِيَّ؟ فَيَقُولُ: لَا. فَيَقُولُ: فَإِنِّي أَنْسَاكَ كَمَا نَسِيتَنِي. ثُمَّ يَلْقَى الثَّانِيَ فَيَقُولُ: أَيْ فُلْ، أَلَمْ أُكْرِمْكَ، وَأُسَوِّدْكَ، وَأُزَوِّجْكَ، وَأُسَخِّرْ لَكَ الْخَيْلَ وَالْإِبِلَ، وَأَذَرْكَ تَرْأَسُ، وَتَرْبَعُ؟ فَيَقُولُ: بَلَى، أَيْ رَبِّ. فَيَقُولُ: أَفَظَنَنْتَ أَنَّكَ مُلَاقِيَّ؟ فَيَقُولُ: لَا. فَيَقُولُ: فَإِنِّي أَنْسَاكَ كَمَا نَسِيتَنِي. ثُمَّ يَلْقَى الثَّالِثَ، فَيَقُولُ لَهُ مِثْلَ ذَلِكَ، فَيَقُولُ: يَا رَبِّ، آمَنْتُ بِكَ، وَبِكِتَابِكَ، وَبِرُسُلِكَ، وَصَلَّيْتُ، وَصُمْتُ، وَتَصَدَّقْتُ. وَيُثْنِي بِخَيْرٍ مَا اسْتَطَاعَ. فَيَقُولُ: هَا هُنَا إِذًا. قَالَ: ثُمَّ يُقَالُ لَهُ: الْآنَ نَبْعَثُ شَاهِدَنَا عَلَيْكَ. وَيَتَفَكَّرُ فِي نَفْسِهِ: مَنْ ذَا الَّذِي يَشْهَدُ عَلَيَّ؟ فَيُخْتَمُ عَلَى فِيهِ، وَيُقَالُ لِفَخِذِهِ وَلَحْمِهِ وَعِظَامِهِ: انْطِقِي، فَتَنْطِقُ فَخِذُهُ وَلَحْمُهُ وَعِظَامُهُ بِعَمَلِهِ، وَذَلِكَ لِيُعْذِرَ مِنْ نَفْسِهِ، وَذَلِكَ الْمُنَافِقُ، وَذَلِكَ الَّذِي يَسْخَطُ اللهُ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2968) عن محمد بن أبي عمر، حدثنا سفيان، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب مصير من نسي لقاء ربه يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2968).","chapter_en":"The Fate of Those Who Forgot the Meeting with Their Lord on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Abū Hurayrah narrated: They asked: “O Messenger of Allah, will we see our Lord on the Day of Resurrection?” He replied: “Do you have difficulty seeing the sun at midday when there is no cloud?” They said: “No.” He asked: “Do you have difficulty seeing the full moon on a cloudless night?” They replied: “No.” He said: “By the One in whose hand is my soul, you will have no more difficulty seeing your Lord than you have seeing either of those. A servant will then meet Him, and Allah will say: ‘O so-and-so, did I not honor you, make you a leader, give you a spouse, subject horses and camels to you, and allow you to lead and enjoy a quarter share of the spoils?’ He will reply: ‘Yes.’ Allah will ask: ‘Did you think that you would meet Me?’ He will reply: ‘No.’ Allah will say: ‘Then today I forget you just as you forgot Me.’ Then He will meet a second person and say the same to him. He will likewise reply that he did not think he would meet Allah, so Allah will say: ‘Today I forget you just as you forgot Me.’ Then He will meet a third person and say the same to him. The man will say: ‘My Lord, I believed in You, Your Book, and Your Messengers. I prayed, fasted, and gave charity,’ and he will praise himself with as much good as he can. Allah will say: ‘Then remain here.’ Then it will be said to him: ‘Now We will bring Our witness against you.’ He will think to himself: ‘Who could testify against me?’ His mouth will then be sealed, and his thigh, flesh, and bones will be told: ‘Speak.’ His thigh, flesh, and bones will speak about his deeds. This will be so that no excuse remains for him. That is the hypocrite, and that is the one with whom Allah is angry.”"]},"intro":{"ar":["قال تعالى:","﴿وَبَدَا لَهُمْ سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ ۝ وَقِيلَ الْيَوْمَ نَنْسَاكُمْ كَمَا نَسِيتُمْ لِقَاءَ يَوْمِكُمْ هَذَا وَمَأْوَاكُمُ النَّارُ وَمَا لَكُمْ مِنْ نَاصِرِينَ﴾ [سورة الجاثية: ٣٣-٣٤]."],"en":["Allah, the Exalted, says:","“The evil consequences of what they did will become apparent to them, and what they used to mock will surround them. And it will be said: ‘Today We will forget you just as you forgot the meeting of this Day of yours. Your refuge is the Fire, and you will have no helpers.’”","[al-Jāthiyah 45:33-34]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2968)."},{"num":16217,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، وَعَنْ أَبِي سَعِيدٍ، قَالاَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُؤْتَى بِالْعَبْدِ يَوْمَ الْقِيَامَةِ فَيَقُولُ اللَّهُ لَهُ: أَلَمْ أَجْعَلْ لَكَ سَمْعًا وَبَصَرًا وَمَالاً وَوَلَدًا، وَسَخَّرْتُ لَكَ الأَنْعَامَ وَالْحَرْثَ، وَتَرَكْتُكَ تَرْأَسُ وَتَرْبَعُ فَكُنْتَ تَظُنُّ أَنَّكَ مُلاَقِيَّ يَوْمَكَ هَذَا؟ قَالَ فَيَقُولُ: لاَ. فَيَقُولُ لَهُ: الْيَوْمَ أَنْسَاكَ كَمَا نَسِيتَنِي."],"takhrij":"حسن: رواه الترمذي (2428) عن عبد الله بن محمد الزهري البصري، قال: حدثنا مالك بن سعير أبو محمد التميمي الكوفي، قال: حدثنا الأعمش، عن أبي صالح، عن أبي هريرة، وعن أبي سعيد، قالا: فذكراه.","grade":"حسن","chapter_ar":"باب مصير من نسي لقاء ربه يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2428).","chapter_en":"The Fate of Those Who Forgot the Meeting with Their Lord on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":42,"content":{"translation":{"en":["Abū Hurayrah and Abū Saʿīd narrated that the Messenger of Allah ﷺ said: “A servant will be brought on the Day of Resurrection, and Allah will say to him: ‘Did I not give you hearing, sight, wealth, and children? Did I not subject livestock and cultivated land to you and allow you to lead and enjoy a share of the spoils? Did you think that you would meet this Day of yours?’ He will reply: ‘No.’ Allah will say to him: ‘Today I forget you just as you forgot Me.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2428)."},{"num":16218,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: لأَعْلَمَنَّ أَقْوَامًا مِنْ أُمَّتِي يَأْتُونَ يَوْمَ الْقِيَامَةِ بِحَسَنَاتٍ أَمْثَالِ جِبَالِ تِهَامَةَ بِيضًا، فَيَجْعَلُهَا اللَّهُ عَزَّ وَجَلَّ هَبَاءً مَنْثُورًا. قَالَ ثَوْبَانُ: يَا رَسُولَ اللَّهِ، صِفْهُمْ لَنَا، جَلِّهِمْ لَنَا أَنْ لاَ نَكُونَ مِنْهُمْ، وَنَحْنُ لاَ نَعْلَمُ. قَالَ: أَمَا إِنَّهُمْ إِخْوَانُكُمْ، وَمِنْ جِلْدَتِكُمْ، وَيَأْخُذُونَ مِنَ اللَّيْلِ كَمَا تَأْخُذُونَ، وَلَكِنَّهُمْ أَقْوَامٌ إِذَا خَلَوْا بِمَحَارِمِ اللَّهِ انْتَهَكُوهَا."],"takhrij":"حسن: رواه ابن ماجه (4245)، والروياني في مسنده (658)، والطبراني في الأوسط (4632) كلهم من حديث عيسى بن يونس الرملي، قال: حدثنا عقبة بن علقمة بن حديج المعافري، عن أرطاة بن المنذر، عن أبي عامر الألهاني، عن ثوبان، فذكره.","grade":"حسن","chapter_ar":"باب مصير من ينتهك محارم الله في الخلوة يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4245), al-Rūyānī in his Musnad (658), and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (4632).","chapter_en":"The Fate on the Day of Resurrection of Those Who Violate Allah’s Sacred Limits in Private","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":43,"content":{"translation":{"en":["Thawbān narrated that the Prophet ﷺ said: “I certainly know of people from my Ummah who will come on the Day of Resurrection with good deeds as great and white as the mountains of Tihāmah, but Allah, Mighty and Majestic, will turn them into scattered dust.” Thawbān said: “O Messenger of Allah, describe them to us and make them clear to us so that we do not unknowingly become among them.” He replied: “Indeed, they are your brothers and are from your own people. They take a portion of the night for worship just as you do. But they are people who, when alone with what Allah has forbidden, violate it.”"]},"buhuth":{"en":["The author explains that the statement:","“When they are alone with what Allah has forbidden, they violate it”","means that they treat those prohibitions as permissible.","Some scholars said that this specifically refers to hypocrites, based on the statement of Allah, the Exalted:","“They seek to hide from people, but they do not seek to hide from Allah, while He is with them when they plot by night words with which He is not pleased. Allah encompasses all that they do.”","[al-Nisāʾ 4:108]","Others said that this was abrogated after the statement of the Prophet ﷺ:","“All of my Ummah may be pardoned except those who openly publicize their sins. Among publicizing sins is that a man does something at night, then wakes in the morning after Allah had concealed it for him and says: ‘O so-and-so, last night I did such-and-such.’ His Lord had concealed him throughout the night, yet in the morning he removes Allah’s concealment from himself.”","Narrated by al-Bukhārī and Muslim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4245)، والروياني في مسنده (658)، والطبراني في الأوسط (4632)."},{"num":16219,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يَخْلُصُ الْمُؤْمِنُونَ مِنَ النَّارِ، فَيُحْبَسُونَ عَلَى قَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ، فَيُقَصُّ لِبَعْضِهِمْ مِنْ بَعْضٍ مَظَالِمُ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا، حَتَّى إِذَا هُذِّبُوا وَنُقُّوا أُذِنَ لَهُمْ فِي دُخُولِ الْجَنَّةِ، فَوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لأَحَدُهُمْ أَهْدَى بِمَنْزِلِهِ فِي الْجَنَّةِ مِنْهُ بِمَنْزِلِهِ كَانَ فِي الدُّنْيَا."],"takhrij":"صحيح: رواه البخاري (6535) عن الصلت بن محمد، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، عن أبي المتوكل الناجي، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6535).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “When the believers have been delivered from the Fire, they will be held on a bridge between Paradise and the Fire. There, the wrongs that occurred between them in this world will be settled. When they have been purified and cleansed, they will be given permission to enter Paradise. By the One in whose hand is the soul of Muḥammad, each of them will know his dwelling in Paradise better than he knew his dwelling in this world.”"]}},"tuhfa":{},"full":1,"rep":[12607,12718,13279,16373,16410],"tks":"صحيح: رواه البخاري (6535)."},{"num":16220,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ كَانَتْ عِنْدَهُ مَظْلَمَةٌ لأَخِيهِ فَلْيَتَحَلَّلْهُ مِنْهَا، فَإِنَّهُ لَيْسَ ثَمَّ دِينَارٌ وَلاَ دِرْهَمٌ، مِنْ قَبْلِ أَنْ يُؤْخَذَ لأَخِيهِ مِنْ حَسَنَاتِهِ، فَإِنْ لَمْ يَكُنْ لَهُ حَسَنَاتٌ أُخِذَ مِنْ سَيِّئَاتِ أَخِيهِ، فَطُرِحَتْ عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6534) عن إسماعيل، حدثني مالك، عن سعيد المقبري، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6534).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever has wronged his brother should seek to be absolved by him now, for there will be neither dinars nor dirhams there. Before that Day comes, some of his good deeds will be taken and given to his brother. If he has no good deeds, then some of his brother’s sins will be taken and cast upon him.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6534)."},{"num":16221,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ:  أَتَدْرُونَ مَا الْمُفْلِسُ؟ قَالُوا: الْمُفْلِسُ فِينَا مَنْ لَا دِرْهَمَ لَهُ، وَلَا مَتَاعَ، فَقَالَ: إِنَّ الْمُفْلِسَ مِنْ أُمَّتِي يَأْتِي يَوْمَ الْقِيَامَةِ بِصَلَاةٍ، وَصِيَامٍ، وَزَكَاةٍ، وَيَأْتِي قَدْ شَتَمَ هَذَا، وَقَذَفَ هَذَا، وَأَكَلَ مَالَ هَذَا، وَسَفَكَ دَمَ هَذَا، وَضَرَبَ هَذَا، فَيُعْطَى هَذَا مِنْ حَسَنَاتِهِ، وَهَذَا مِنْ حَسَنَاتِهِ، فَإِنْ فَنِيَتْ حَسَنَاتُهُ قَبْلَ أَنْ يُقْضَى مَا عَلَيْهِ أُخِذَ مِنْ خَطَايَاهُمْ فَطُرِحَتْ عَلَيْهِ، ثُمَّ طُرِحَ فِي النَّارِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة والآداب (2581) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2581).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ asked: “Do you know who the bankrupt person is?” They replied: “The bankrupt among us is the one who has neither money nor possessions.” He said: “The bankrupt person from my Ummah is the one who comes on the Day of Resurrection with prayer, fasting, and zakāh, but he also comes having insulted this person, falsely accused that person, consumed another’s wealth, shed another’s blood, and struck another. This person will be given from his good deeds, and that person will be given from his good deeds. If his good deeds run out before all that he owes has been settled, some of their sins will be taken and cast upon him, then he will be cast into the Fire.”"]}},"tuhfa":{},"full":1,"rep":[5924,12735,12981,14897],"tks":"صحيح: رواه مسلم (2581)."},{"num":16222,"demo":false,"sanad":"","matn":["عن عبدالله بن أُنَيْسٍ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ - أَوْ قَالَ: الْعِبَادُ - عُرَاةً غُرْلًا بُهْمًا. قَالَ: قُلْنَا: وَمَا بُهْمًا؟ قَالَ: لَيْسَ مَعَهُمْ شَيْءٌ، ثُمَّ يُنَادِيهِمْ بِصَوْتٍ يَسْمَعُهُ مِنْ [بُعْدٍ كَمَا يَسْمَعُهُ مِنْ] قُرْبٍ: أَنَا الْمَلِكُ، أَنَا الدَّيَّانُ، وَلَا يَنْبَغِي لِأَحَدٍ مِنْ أَهْلِ النَّارِ، أَنْ يَدْخُلَ النَّارَ، وَلَهُ عِنْدَ أَحَدٍ مِنْ أَهْلِ الْجَنَّةِ حَقٌّ، حَتَّى أَقُصَّهُ مِنْهُ، وَلَا يَنْبَغِي لِأَحَدٍ مِنْ أَهْلِ الْجَنَّةِ أَنْ يَدْخُلَ الْجَنَّةَ، وَلِأَحَدٍ مِنْ أَهْلِ النَّارِ عِنْدَهُ حَقٌّ، حَتَّى أَقُصَّهُ مِنْهُ، حَتَّى اللَّطْمَةُ. قَالَ: قُلْنَا: كَيْفَ وَإِنَّا إِنَّمَا نَأْتِي اللَّهَ عَزَّ وَجَلَّ عُرَاةً غُرْلًا بُهْمًا؟ قَالَ: بِالْحَسَنَاتِ وَالسَّيِّئَاتِ."],"takhrij":"حسن: رواه أحمد (16042)-واللّفظ له-، والبخاريّ في الأدب المفرد (970)، وابن أبي عاصم في السنة (514)، وصحّحه الحاكم (3638) كلّهم من طرق عن همّام بن يحيى، عن القاسم بن عبدالواحد المكيّ، عن عبدالله بن محمد بن عقيل، عن جابر بن عبدالله، عن عبدالله بن أنيس فذكره.","grade":"حسن","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (16042), al-Bukhārī in al-Adab al-Mufrad (970), Ibn Abī ʿĀṣim in al-Sunnah (514), and authenticated by al-Ḥākim (3638).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["ʿAbdullāh ibn Unays narrated: I heard the Messenger of Allah ﷺ say: “The people—or he said, the servants—will be gathered on the Day of Resurrection naked, uncircumcised, and possessing nothing.” We asked: “What does ‘possessing nothing’ mean?” He replied: “They will have nothing with them. Then He will call them with a voice heard by the distant just as the near hear it: ʿI am the King. I am the One who gives full recompense. No one from the people of the Fire should enter the Fire while someone from the people of Paradise has a right against him until I settle it from him. And no one from the people of Paradise should enter Paradise while someone from the people of the Fire has a right against him until I settle it from him—even for a slap.’” We asked: “How can that be when we come before Allah, Mighty and Majestic, naked, uncircumcised, and possessing nothing?” He replied: “Through good deeds and bad deeds.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[406,958,1116,16152],"tks":"حسن: رواه أحمد (16042)، والبخاري في الأدب المفرد (970)، وابن أبي عاصم في السنة (514)، وصححه الحاكم (3638)."},{"num":16223,"demo":false,"sanad":"","matn":["عَنْ سَلْمَانَ، وَغَيْرِهِ مِنْ أَصْحَابِ مُحَمَّدٍ، قَالُوا: إِنَّ الرَّجُلَ يَجِيءُ يَوْمَ الْقِيَامَةِ قَدْ عَمِلَ عَمَلًا يَرْجُو أَنْ يَنْجُوَ بِهِ، قَالَ: فَمَا يَزَالُ الرَّجُلُ يَأْتِيهِ فَيَشْتَكِي مَظْلِمَةً فَيُؤْخَذُ مِنْ حَسَنَاتِهِ فَيُعْطَاهَا حَتَّى مَا تَبْقَى لَهُ حَسَنَةٌ، وَيَجِيءُ الْمُشْتَكِي يَشْتَكِي مَظْلَمَةً فَيُؤْخَذُ مِنْ سَيِّئَاتِهِ فَتُوضَعُ عَلَى سَيِّئَاتِهِ، ثُمَّ يُكَبُّ فِي النَّارِ أَوْ يُلْقَى فِي النَّارِ."],"takhrij":"حسن: رواه ابن أبي شيبة في المصنف (35814) عن أبي أسامة، حدثنا عثمان بن غياث، عن أبي عثمان النهدي، عن سلمان وغيره من أصحاب محمد صلى الله عليه وسلم قالوا: الحديث.","grade":"حسن","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Shaybah in al-Muṣannaf (35814) and al-Ḥākim (4/570).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Salmān and others among the Companions of Muḥammad ﷺ said: A man will come on the Day of Resurrection having performed deeds by which he hopes to be saved. But one person after another will come to him complaining of wrongs committed against them. Some of his good deeds will be taken and given to them until he has no good deeds left. Then another claimant will come complaining of a wrong. Some of that person’s sins will be taken and added to his sins. Then he will be thrown face-first into the Fire—or cast into the Fire."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة في المصنف (35814) والحاكم (4/570)."},{"num":16224,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَجِيءُ الظَّالِمُ يَوْمَ الْقِيَامَةِ، حَتَّى إِذَا كَانَ عَلَى جِسْرِ جَهَنَّمَ بَيْنَ الظُّلْمَةِ، وَالْوَعْرَةِ، لَقِيَهُ الْمَظْلُومُ، فَعَرَفَهُ، وَعَرَفَ مَا ظَلَمَهُ بِهِ، فَمَا يَبْرَحُ الَّذِينَ ظُلِمُوا يَقْضُونَ مِنَ الَّذِينَ ظَلَمُوا، حَتَّى يَنْزَعُوا مَا فِي أَيْدِيهُمْ مِنَ الْحَسَنَاتِ، فَإِنْ لَمْ يَكُنْ لَهُمْ حَسَنَاتٌ أَدْرَكَ عَلَيْهِمْ مِنْ سَيِّئَاتِهِمْ مِثْلَ مَا ظَلَمُوا، حَتَّى يُورِدُوا الدَّرَكَ الْأَسْفَلَ مِنَ النَّارِ."],"takhrij":"حسن: رواه الطبراني في الأوسط (5973) –والسياق له، والبخاري في التاريخ الكبير (2/228)، ولم يسق لفظ الحديث، كلاهما من طرقٍ عن حسين المعلم، عن أيوب، عن الجهم بن فضالة الباهلي، عن أبي أمامة الباهلي قال: فذكره.","grade":"حسن","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (5973), whose wording this is, and al-Bukhārī in al-Tārīkh al-Kabīr (2/228).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī narrated that the Messenger of Allah ﷺ said: “The wrongdoer will come on the Day of Resurrection until, when he reaches a bridge over Hell between darkness and rugged terrain, the one he wronged will meet him. The wronged person will recognize him and recognize the wrong he committed against him. Those who were wronged will continue taking their due from those who wronged them until all the good deeds in their hands have been taken away. If they have no good deeds, then sins equal to the amount of their wrongdoing will be placed upon them, until they are brought to the lowest depth of the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (5973) - والسياق له -، والبخاري في التاريخ الكبير (2/228)."},{"num":16225,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ ضَرَبَ ضَرْبًا ظُلْمًا اقْتُصَّ مِنْهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (186) والبزار (9535) كلاهما من طريق عبد الله بن رجاء، حدثنا أبو العوام عمران القطان، عن قتادة، عن عبد الله بن شقيق، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (186) and al-Bazzār (9535).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever strikes another person unjustly will have retaliation exacted from him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (186) والبزار (9535)."},{"num":16226,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَتُؤَدَُّنَّ الْحُقُوقَُ إِلَى أَهْلِهَا يَوْمَ الْقِيَامَةِ، حَتَّى يُقَادَ لِلشَّاةِ الْجَلْحَاءِ مِنَ الشَّاةِ الْقَرْنَاءِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة والآداب (2582) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2582).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Rights will certainly be restored to those entitled to them on the Day of Resurrection, to the extent that retaliation will be taken for the hornless sheep from the horned sheep.”"]},"buhuth":{"en":["Aḥmad (8756) narrated a similar report through another chain and added:","“Even for one tiny ant from another tiny ant.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5925],"tks":"صحيح: رواه مسلم (2582)."},{"num":16227,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ جَالِسًا، وَشَاتَانِ تَعْتلفَانِ، فَنَطَحَتْ إِحْدَاهُمَا الْأُخْرَى، فَأَجْهَضَتْهَا، قَالَ: فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقِيلَ لَهُ: مَا يُضْحِكُكَ يَا رَسُولَ اللَّهِ؟ قَالَ: عَجِبْتُ لَهَا، وَالَّذِي نَفْسِي بِيَدِهِ، لَيُقَادَنَّ لَهَا يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه عبدالله بن أحمد في مسند أبيه (21511)، فقال: وجدت هذا الحديث في كتاب أبي بخط يديه: حدثنا عبيد الله بن محمد، أخبرنا حماد بن سلمة، أخبرنا ليث، عن عبد الرحمن بن ثروان، عن الهزيل بن شرحبيل، عن أبي ذر فذكره.","grade":"حسن","chapter_ar":"باب اقتصاص المظالم بين الخلق يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by ʿAbdullāh ibn Aḥmad in his father’s Musnad (21511).","chapter_en":"Settling Wrongs between Created Beings on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":44,"content":{"translation":{"en":["Abū Dharr narrated: The Messenger of Allah ﷺ was sitting while two sheep were feeding. One of them butted the other and caused it to miscarry. The Messenger of Allah ﷺ laughed. He was asked: “What makes you laugh, O Messenger of Allah?” He replied: “I am amazed at it. By the One in whose hand is my soul, retaliation will certainly be taken for it on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبدالله بن أحمد في مسند أبيه (21511)."},{"num":16228,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ، سُبْحَانَ اللَّهِ الْعَظِيمِ، سُبْحَانَ اللَّهِ وَبِحَمْدِهِ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6406)، ومسلم في الذكر والدعاء (2694) كلاهما من طريق ابن فضيل، عن عمارة بن القعقاع، عن أبي زرعة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الميزان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6406) and Muslim (2694).","chapter_en":"What Has Been Narrated Concerning the Scale","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":45,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Two phrases are light upon the tongue, heavy in the Scale, and beloved to the Most Merciful: ‘Glory and praise be to Allah; glory be to Allah, the Magnificent.’”"]},"intro":{"ar":["قال تعالى:","﴿وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْئًا وَإِنْ كَانَ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَاسِبِينَ﴾ [سورة الأنبياء: ٤٧].","وقال تعالى:","﴿وَالْوَزْنُ يَوْمَئِذٍ الْحَقُّ فَمَنْ ثَقُلَتْ مَوَازِينُهُ فَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ ۝ وَمَنْ خَفَّتْ مَوَازِينُهُ فَأُولَٰئِكَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ بِمَا كَانُوا بِآيَاتِنَا يَظْلِمُونَ﴾ [سورة الأعراف: ٨-٩].","وقال تعالى:","﴿فَأَمَّا مَنْ ثَقُلَتْ مَوَازِينُهُ ۝ فَهُوَ فِي عِيشَةٍ رَاضِيَةٍ ۝ وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ ۝ فَأُمُّهُ هَاوِيَةٌ ۝ وَمَا أَدْرَاكَ مَا هِيَهْ ۝ نَارٌ حَامِيَةٌ﴾ [سورة القارعة: ٦-١١]."],"en":["Allah, the Exalted, says:","“We will set up the scales of justice for the Day of Resurrection, so no soul will be wronged in the least. Even if a deed is the weight of a mustard seed, We will bring it forth. And sufficient are We as Reckoners.”","[al-Anbiyāʾ 21:47]","And He, the Exalted, says:","“The weighing on that Day will be the truth. Those whose scales are heavy—it is they who will be successful. And those whose scales are light—it is they who will have lost themselves because they used to wrongfully reject Our signs.”","[al-Aʿrāf 7:8-9]","And He, the Exalted, says:","“As for the one whose scales are heavy, he will be in a pleasant life. But as for the one whose scales are light, his refuge will be the Abyss. And what can make you know what it is? A blazing Fire.”","[al-Qāriʿah 101:6-11]"]}},"tuhfa":{},"full":1,"rep":[10821,13497],"tks":"متفق عليه: رواه البخاري (6406)، ومسلم (2694)."},{"num":16229,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  الطُّهُورُ شَطْرُ الْإِيمَانِ، وَالْحَمْدُ لِلهِ تَمْلَأُ الْمِيزَانَ، وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلهِ تَمْلَآنِ - أَوْ تَمْلَأُ - مَا بَيْنَ السَّمَاوَاتِ وَالْأَرْضِ، وَالصَّلَاةُ."],"takhrij":"صحيح: رواه مسلم في الطهارة (223)، عن إسحاق بن منصور، ثنا حبان بن هلال، ثنا أبان (هو ابن يزيد العطار)، ثنا يحيى (هو ابن أبي كثير) أن زيدا حدثه أن أبا سلام حدثه عن أبي مالك الأشعري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الميزان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (223).","chapter_en":"What Has Been Narrated Concerning the Scale","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":45,"content":{"translation":{"en":["Abū Mālik al-Ashʿarī narrated that the Messenger of Allah ﷺ said: “Purification is half of faith. ‘Al-ḥamdu lillāh’ fills the Scale, and ‘subḥān Allah’ and ‘al-ḥamdu lillāh’ fill—or one of them fills—what is between the heavens and the earth…” The hadith continues."]}},"tuhfa":{},"full":1,"rep":[10822],"tks":"صحيح: رواه مسلم (223)."},{"num":16230,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنِ احْتَبَسَ فَرَسًا فِي سَبِيلِ اللَّهِ إِيمَانًا بِاللَّهِ، وَتَصْدِيقًا بِوَعْدِهِ؛ فَإِنَّ شِبَعَهُ وَرِيَّهُ وَرَوْثَهُ وَبَوْلَهُ فِي مِيزَانِهِ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2853) عن علي بن حفص، حدثنا ابن المبارك، أخبرنا طلحة بن أبي أسيد قال: سمعت سعيدا المقبري يحدّث أنه سمع أبا هريرة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الميزان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2853).","chapter_en":"What Has Been Narrated Concerning the Scale","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":45,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever keeps a horse for the sake of Allah, out of faith in Allah and belief in His promise, then its food, drink, dung, and urine will all be placed in his Scale on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"rep":[7956],"tks":"صحيح: رواه البخاري (2853)."},{"num":16231,"demo":false,"sanad":"","matn":["عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ، يَقُولُ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ سَيُخَلِّصُ رَجُلاً مِنْ أُمَّتِي عَلَى رُءُوسِ الْخَلاَئِقِ يَوْمَ الْقِيَامَةِ فَيَنْشُرُ عَلَيْهِ تِسْعَةً وَتِسْعِينَ سِجِلاًّ كُلُّ سِجِلٍّ مِثْلُ مَدِّ الْبَصَرِ، ثُمَّ يَقُولُ: أَتُنْكِرُ مِنْ هَذَا شَيْئًا؟ أَظَلَمَكَ كَتَبَتِي الْحَافِظُونَ؟ فَيَقُولُ: لاَ يَا رَبِّ. فَيَقُولُ: أَفَلَكَ عُذْرٌ؟ فَيَقُولُ: لاَ يَا رَبِّ. فَيَقُولُ: بَلَى إِنَّ لَكَ عِنْدَنَا حَسَنَةً فَإِنَّهُ لاَ ظُلْمَ عَلَيْكَ الْيَوْمَ، فَتَخْرُجُ بِطَاقَةٌ فِيهَا: أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. فَيَقُولُ: احْضُرْ وَزْنَكَ فَيَقُولُ: يَا رَبِّ مَا هَذِهِ الْبِطَاقَةُ مَعَ هَذِهِ السِّجِلاَّتِ؟ فَقَالَ: إِنَّكَ لاَ تُظْلَمُ. قَالَ: فَتُوضَعُ السِّجِلاَّتُ فِي كِفَّةٍ وَالْبِطَاقَةُ فِي كِفَّةٍ، فَطَاشَتِ السِّجِلاَّتُ وَثَقُلَتِ الْبِطَاقَةُ، فَلاَ يَثْقُلُ مَعَ اسْمِ اللَّهِ شَيْءٌ."],"takhrij":"صحيح: رواه الترمذي (2639) - واللفظ له -، وابن ماجه (4300) كلاهما من حديث الليث بن سعد، قال: حدثني عامر بن يحيى، عن أبي عبدالرحمن المعافري ثم الحبلي، قال: سمعت عبدالله بن عمرو بن العاص، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في الميزان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2639), whose wording this is, and Ibn Mājah (4300).","chapter_en":"What Has Been Narrated Concerning the Scale","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":45,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “Allah will single out a man from my Ummah before all creation on the Day of Resurrection. Ninety-nine records will be spread out before him, each record extending as far as the eye can see. Then Allah will say: ‘Do you deny anything in these? Have My recording angels wronged you?’ He will reply: ‘No, my Lord.’ Allah will ask: ‘Do you have any excuse?’ He will reply: ‘No, my Lord.’ Allah will say: ‘Rather, you have one good deed with Us, and there will be no injustice against you today.’ Then a card will be brought out upon which is written: ‘I testify that there is no deity except Allah, and I testify that Muḥammad is His servant and Messenger.’ Allah will say: ‘Come and witness your weighing.’ The man will say: ‘My Lord, what is this card compared with all these records?’ He will say: ‘You will not be wronged.’ The records will then be placed on one side of the Scale and the card on the other. The records will become light and the card will outweigh them, for nothing can outweigh the Name of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2639) - واللفظ له -، وابن ماجه (4300)."},{"num":16232,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّهُ كَانَ يَجْتَنِي سِوَاكًا مِنَ الْأَرَاكِ، وَكَانَ دَقِيقَ السَّاقَيْنِ، فَجَعَلَتِ الرِّيحُ تَكْفَؤُهُ، فَضَحِكَ الْقَوْمُ مِنْهُ، فَقَالَ رَسُولُ اللَّهِ: صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِمَّ تَضْحَكُونَ؟ قَالُوا: يَا نَبِيَّ اللَّهِ، مِنْ دِقَّةِ سَاقَيْهِ، فَقَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَهُمَا أَثْقَلُ فِي الْمِيزَانِ مِنْ أُحُدٍ."],"takhrij":"حسن: رواه أحمد (3991) وأبو يعلى (5310) والبزار في كشف الأستار (2678) والطبراني في الكبير (8452) كلهم من طريق عاصم، عن زَرّ بن حُبيش عن ابن مسعود فذكره. وصحّحه ابن حبَّان (7069) فرواه من هذا الوجه.","grade":"حسن","chapter_ar":"باب ما جاء في الميزان","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (3991), Abū Yaʿlā (5310), al-Bazzār in Kashf al-Astār (2678), and al-Ṭabarānī in al-Muʿjam al-Kabīr (8452), all through ʿĀṣim, from Zirr ibn Ḥubaysh, from Ibn Masʿūd. Ibn Ḥibbān authenticated it (7069) through this route.","chapter_en":"What Has Been Narrated Concerning the Scale","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":45,"content":{"translation":{"en":["Ibn Masʿūd was gathering siwāk sticks from an arāk tree. His legs were very thin, and the wind began causing him to sway. The people laughed at him. The Messenger of Allah ﷺ asked: “What are you laughing at?” They replied: “O Prophet of Allah, at the thinness of his legs.” He said: “By the One in whose hand is my soul, they are heavier in the Scale than Mount Uḥud.”"]},"buhuth":{"en":["Taken together, these hadiths indicate that what will be weighed in the Scale on the Day of Resurrection includes the deed, the person who performed it, and the record of his deeds."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1376],"tks":"حسن: رواه أحمد (3991) وأبو يعلى (5310) والبزار في كشف الأستار (2678) والطبراني في الكبير (8452). وصححه ابن حبان (7069) فرواه من هذا الوجه."},{"num":16233,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّهُ لَيَأْتِي الرَّجُلُ الْعَظِيمُ السَّمِينُ يَوْمَ الْقِيَامَةِ، لاَ يَزِنُ عِنْدَ اللَّهِ جَنَاحَ بَعُوضَةٍ وَقَالَ: اقْرَءُوا ﴿فَلاَ نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾ [سورة الكهف: 105]}."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4729)، ومسلم في صفة القيامة والجنة والنار (2785) كلاهما من طريق يحيى بن بكير، حدثني المغيرة بن عبدالرحمن الحزامي، حدثني أبو الزناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يقيم الله للكافر وزنًا يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4729) and Muslim (2785).","chapter_en":"Allah Will Assign No Weight to the Disbeliever on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":46,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “A huge, corpulent man will come on the Day of Resurrection, yet with Allah he will not weigh as much as the wing of a mosquito.” Then he said: “Recite: ‘We will assign no weight to them on the Day of Resurrection.’ [al-Kahf 18:105]”"]},"intro":{"ar":["قال تعالى:","﴿قُلْ هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا ۝ الَّذِينَ ضَلَّ سَعْيُهُمْ فِي الْحَيَاةِ الدُّنْيَا وَهُمْ يَحْسَبُونَ أَنَّهُمْ يُحْسِنُونَ صُنْعًا ۝ أُولَٰئِكَ الَّذِينَ كَفَرُوا بِآيَاتِ رَبِّهِمْ وَلِقَائِهِ فَحَبِطَتْ أَعْمَالُهُمْ فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾ [سورة الكهف: ١٠٣-١٠٥]."],"en":["Allah, the Exalted, says:","“Say: Shall We inform you of those who are the greatest losers in their deeds? They are those whose efforts in the life of this world have gone astray while they thought they were doing good. Those are the ones who disbelieved in the signs of their Lord and in meeting Him, so their deeds became worthless, and We will assign no weight to them on the Day of Resurrection.”","[al-Kahf 18:103-105]"]}},"tuhfa":{},"full":1,"rep":[12697],"tks":"متفق عليه: رواه البخاري (4729)، ومسلم (2785)."},{"num":16234,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَوْضِي مَسِيرَةُ شَهْرٍ، مَاؤُهُ أَبْيَضُ مِنَ اللَّبَنِ، وَرِيحُهُ أَطْيَبُ مِنَ الْمِسْكِ، وَكِيزَانُهُ كَنُجُومِ السَّمَاءِ، مَنْ شَرِبَ مِنْهَا فَلاَ يَظْمَأُ أَبَدًا.","وفي لفظ: حوضي مسيرة شهر، وزواياه سواء، وماؤه أبيض من الورق. والباقي مثله."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6577) عن سعيد بن أبي مريم، حدثنا نافع بن عمر، عن ابن أبي مليكة، قال: قال عبد الله بن عمرو: فذكره.","grade":"متفق عليه","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6577) and Muslim (2292).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Prophet ﷺ said: “My Ḥawḍ is a month’s journey in length. Its water is whiter than milk, its fragrance is more pleasant than musk, and its drinking vessels are like the stars of the sky. Whoever drinks from it will never thirst again.” In another wording: “My Ḥawḍ is a month’s journey, its sides are equal, and its water is whiter than silver.” The remainder is similar."]},"intro":{"ar":["قال تعالى:","﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ [الكوثر: ١]."],"en":["Allah, the Exalted, says:","“Indeed, We have granted you al-Kawthar.”","[al-Kawthar 108:1]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6577) ومسلم (2292)."},{"num":16235,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ:  قُلْتُ: يَا رَسُولَ اللَّهِ، مَا آنِيَةُ الْحَوْضِ؟ قَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَآنِيَتُهُ أَكْثَرُ مِنْ عَدَدِ نُجُومِ السَّمَاءِ وَكَوَاكِبِهَا، أَلَا فِي اللَّيْلَةِ الْمُظْلِمَةِ الْمُصْحِيَةِ، آنِيَةُ الْجَنَّةِ، مَنْ شَرِبَ مِنْهَا لَمْ يَظْمَأْ آخِرَ مَا عَلَيْهِ، يَشْخُبُ فِيهِ مِيزَابَانِ مِنَ الْجَنَّةِ، مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ، عَرْضُهُ مِثْلُ طُولِهِ، مَا بَيْنَ عَمَّانَ إِلَى أَيْلَةَ، مَاؤُهُ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَحْلَى مِنَ الْعَسَلِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2300) من طرق عن عبدالعزيز بن عبدالصمد العمي، عن أبي عمران الجوني، عن عبدالله بن الصامت، عن أبي ذر، فذكره.","grade":"صحيح","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2300).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["Abū Dharr narrated: I asked: “O Messenger of Allah, what are the vessels of the Ḥawḍ like?” He replied: “By the One in whose hand is the soul of Muḥammad, its vessels are more numerous than the stars and planets of the sky on a dark, clear night. They are vessels from Paradise. Whoever drinks from them will never thirst again. Two channels from Paradise pour into it. Whoever drinks from it will never thirst. Its width is equal to its length, extending from ʿAmmān to Aylah. Its water is whiter than milk and sweeter than honey.”"]},"buhuth":{"ar":["قوله: ألا في الليلة المظلمة المصحية تخفيف وهي للاستفتاح، وخص الليلة المظلمة؛ لأن النجوم ترى فيها أكثر، والمراد بالمظلمة: التي لا قمر فيها مع أن النجوم طالعة، فإن وجود القمر يستر كثيرًا من النجوم.","وقوله: يشخب فيه ميزابان الشخب: السيلان، وأصله ما يخرج من تحت يد الحالب عند كل غمزة وعصرة لضرع الشاة."],"en":["Regarding the phrase “on a dark, clear night,” the author explains that it introduces and emphasizes the description. A dark night is specifically mentioned because more stars can be seen when there is no moon, since moonlight obscures many stars.","Regarding the phrase “two channels pour into it,” shakhb means flowing or streaming. Its original usage refers to the stream of milk that comes from an animal’s udder each time it is squeezed during milking."]}},"tuhfa":{},"full":1,"rep":[837],"tks":"صحيح: رواه مسلم (2300)."},{"num":16236,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَمَا أَنَا أَسِيرُ فِي الْجَنَّةِ، إِذَا أَنَا بِنَهَرٍ، حَافَتَاهُ قِبَابُ الدُّرِّ الْمُجَوَّفِ، قُلْتُ: مَا هَذَا يَا جِبْرِيلُ؟ قَالَ: هَذَا الْكَوْثَرُ، الَّذِي أَعْطَاكَ رَبُّكَ. فَإِذَا طِينُهُ ـ أَوْ طِيبُهُ ـ مِسْكٌ أَذْفَرُ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6581) من طرق عن همام، حدثنا قتادة، حدثنا أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6581).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “While I was walking in Paradise, I came upon a river whose banks were domes of hollow pearls. I asked: ‘What is this, O Jibrīl?’ He replied: ‘This is al-Kawthar, which your Lord has granted you.’ Its mud—or its fragrance—was intensely fragrant musk.”"]}},"tuhfa":{},"full":1,"rep":[804],"tks":"صحيح: رواه البخاري (6581)."},{"num":16237,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : وَالَّذِي نَفْسِي بِيَدِهِ لأَذُودَنَّ رِجَالاً عَنْ حَوْضِي كَمَا تُذَادُ الْغَرِيبَةُ مِنَ الإِبِلِ عَنِ الْحَوْضِ."],"takhrij":"متفق عليه: رواه البخاريّ في المساقاة (2367)، ومسلم في الفضائل (2302) من طرق عن محمد بن زياد، عن أبي هريرة، فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2367) and Muslim (2302).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “By the One in whose hand is my soul, I will certainly drive certain men away from my Ḥawḍ just as stray camels are driven away from a watering place.”"]}},"tuhfa":{},"full":1,"rep":[816],"tks":"متفق عليه: رواه البخاري (2367)، ومسلم (2302)."},{"num":16238,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّ حَوْضِي أَبْعَدُ مِنْ أَيْلَةَ مِنْ عَدَنٍ، لَهُوَ أَشَدُّ بَيَاضًا مِنَ الثَّلْجِ، وَأَحْلَى مِنَ الْعَسَلِ بِاللَّبَنِ، وَلَآنِيَتُهُ أَكْثَرُ مِنْ عَدَدِ النُّجُومِ، وَإِنِّي لَأَصُدُّ النَّاسَ عَنْهُ كَمَا يَصُدُّ الرَّجُلُ إِبِلَ النَّاسِ عَنْ حَوْضِهِ، قَالُوا: يَا رَسُولَ اللَّهِ، أَتَعْرِفُنَا يَوْمَئِذٍ؟ قَالَ: نَعَمْ، لَكُمْ سِيمَا لَيْسَتْ لِأَحَدٍ مِنَ الْأُمَمِ، تَرِدُونَ عَلَيَّ غُرًّا مُحَجَّلِينَ مِنْ أَثَرِ الْوُضُوءِ.","وفي رواية: تَرِدُ عَلَيَّ أُمَّتِي الْحَوْضَ وَأَنَا أَذُودُ النَّاسَ عَنْهُ كَمَا يَذُودُ الرَّجُلُ إِبِلَ الرَّجُلِ عَنْ إِبِلِهِ. قَالُوا: يَا نَبِيَّ اللَّهِ، أَتَعْرِفُنَا؟ قَالَ: نَعَمْ لَكُمْ سِيمَا لَيْسَتْ لِأَحَدٍ غَيْرِكُمْ. تَرِدُونَ عَلَيَّ غُرًّا مُحَجَّلِينَ مِنْ آثَارِ الْوُضُوءِ. وَلَيُصَدَّنَّ عَنِّي طَائِفَةٌ مِنْكُمْ فَلَا يَصِلُونَ، فَأَقُولُ: يَا رَبِّ، هَؤُلَاءِ مِنْ أَصْحَابِي، فَيُجِيبُنِي مَلَكٌ فَيَقُولُ: وَهَلْ تَدْرِي مَا أَحْدَثُوا بَعْدَكَ؟."],"takhrij":"صحيح: رواه مسلم في الطّهارة (247) من طرق عن مروان الفزاريّ، عن أبي مالك الأشجعيّ سعد بن طارق، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (247).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “My Ḥawḍ is farther in extent than the distance from Aylah to ʿAdan. It is whiter than snow and sweeter than honey mixed with milk. Its vessels are more numerous than the stars. I will keep people away from it just as a man keeps other people’s camels away from his own watering place.” They asked: “O Messenger of Allah, will you recognize us on that Day?” He replied: “Yes. You will have a distinguishing mark that no other nation has. You will come to me with radiant faces and limbs from the traces of wuḍūʾ.” In another narration: “My Ummah will come to me at the Ḥawḍ, while I drive other people away from it just as a man drives another man’s camels away from his own camels.” They asked: “O Prophet of Allah, will you recognize us?” He replied: “Yes. You will have a distinguishing mark that no one else has. You will come to me with radiant faces and limbs from the traces of wuḍūʾ. Yet a group from among you will certainly be kept away from me and will not reach me. I will say: ‘My Lord, these are from my Companions.’","An angel will answer me: ‘Do you know what they introduced after you?’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[820],"tks":"صحيح: رواه مسلم (247)."},{"num":16239,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا فَرَطُكُمْ عَلَى الْحَوْضِ، لَيُرْفَعَنَّ إِلَىَّ رِجَالٌ مِنْكُمْ، حَتَّى إِذَا أَهْوَيْتُ لأُنَاوِلَهُمُ اخْتُلِجُوا دُونِي، فَأَقُولُ: أَىْ رَبِّ أَصْحَابِي. يَقُولُ: لاَ تَدْرِي مَا أَحْدَثُوا بَعْدَكَ."],"takhrij":"متفق عليه: رواه البخاريّ في الفتن (7049)، ومسلم في الفضائل (2297) كلاهما من طريق مغيرة، عن أبي وائل، عن عبدالله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7049) and Muslim (2297).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “I will precede you to the Ḥawḍ. Men from among you will be brought toward me, but when I reach out to give them water, they will be snatched away before reaching me. I will say: ‘My Lord, my Companions!’ He will say: ‘You do not know what they introduced after you.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7049)، ومسلم (2297)."},{"num":16240,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيَرِدَنَّ عَلَيَّ الْحَوْضَ أَقْوَامٌ فَيُخْتَلَجُونَ دُونِي فَأَقُولُ: رَبِّ أُصَيْحَابِي، رَبِّ أُصَيْحَابِي، فَيُقَالُ لِي: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2297) وأحمد (23290) من طرق عن حصين، عن أبي وائل، عن حذيفة، فذكره. واللفظ لأحمد، ولم يذكر مسلم لفظه، وإنما أحال على حديث قبله.","grade":"صحيح","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2297) and Aḥmad (23290).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["Ḥudhayfah narrated that the Messenger of Allah ﷺ said: “Certain people will come to the Ḥawḍ but will be snatched away before reaching me. I will say: ‘My Lord, my Companions! My Lord, my Companions!’ It will be said to me: ‘You do not know what they introduced after you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2297) وأحمد (23290)."},{"num":16241,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ، قَالَ: سَمِعْتُ سَهْلَ بْنَ سَعْدٍ، يَقُولُ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَنَا فَرَطُكُمْ، عَلَى الْحَوْضِ، مَنْ وَرَدَهُ شَرِبَ مِنْهُ، وَمَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ بَعْدَهُ أَبَدًا، لَيَرِدُ عَلَىَّ أَقْوَامٌ أَعْرِفُهُمْ وَيَعْرِفُونِي، ثُمَّ يُحَالُ بَيْنِي وَبَيْنَهُمْ.","قَالَ أَبُو حَازِمٍ: فَسَمِعَنِي النُّعْمَانُ بْنُ أَبِي عَيَّاشٍ، وَأَنَا أُحَدِّثُهُمْ هَذَا، فَقَالَ: هَكَذَا سَمِعْتَ سَهْلًا؟ فَقُلْتُ: نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ عَلَى أَبِي سَعِيدٍ الْخُدْرِيِّ لَسَمِعْتُهُ يَزِيدُ فِيهِ، قَالَ: إِنَّهُمْ مِنِّي، فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا بَدَّلُوا بَعْدَكَ، فَأَقُولُ: سُحْقًا سُحْقًا لِمَنْ بَدَّلَ بَعْدِي."],"takhrij":"متفق عليه: رواه البخاريّ في الفتن (7050، 7051)، ومسلم في الفضائل (2290) كلاهما من طريق يعقوب بن عبدالرحمن القاري، عن أبي حازم، فذكره.","grade":"متفق عليه","chapter_ar":"باب في الحوض","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7051, 7050) and Muslim (2290).","chapter_en":"Concerning the Ḥawḍ","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":47,"content":{"translation":{"en":["Abū Ḥāzim narrated: I heard Sahl ibn Saʿd say: I heard the Prophet ﷺ say: “I will precede you to the Ḥawḍ. Whoever comes to it will drink from it, and whoever drinks from it will never thirst again. Certain people whom I recognize and who recognize me will come to me, but then a barrier will be placed between me and them.” Abū Ḥāzim said: Al-Nuʿmān ibn Abī ʿAyyāsh heard me narrating this and asked: “Is this how you heard Sahl narrate it?”","I replied: “Yes.” He said: “And I testify that I heard Abū Saʿīd al-Khudrī add to it that the Prophet ﷺ said: ‘They are from me.’ Then it will be said: ‘You do not know what they changed after you.’ So I will say: ‘Away with them! Away with those who changed after me!’”"]},"buhuth":{"en":["Benefits and Lessons from This Chapter","The Ḥawḍ is the place in which water gathers, and its water comes from a river of Paradise.","As narrated in Ṣaḥīḥ Muslim (400), Anas said:","One day the Messenger of Allah ﷺ was among us when he dozed briefly. Then he raised his head smiling.","We asked:","“What made you smile, O Messenger of Allah?”","He replied:","“A sūrah was just revealed to me.”","Then he recited:","“Indeed, We have granted you al-Kawthar. So pray to your Lord and sacrifice. Indeed, the one who hates you is the one cut off.”","Then he asked:","“Do you know what al-Kawthar is?”","We replied:","“Allah and His Messenger know best.”","He said:","“It is a river that my Lord, Mighty and Majestic, has promised me. It contains abundant good. It is a Ḥawḍ to which my Ummah will come on the Day of Resurrection. Its vessels are as numerous as the stars.","A servant from among them will be pulled away, and I will say: ‘My Lord, he is from my Ummah.’","He will say: ‘You do not know what he introduced after you.’”","The Prophet ﷺ informed that apostasy would occur after him, and it indeed occurred after the death of the Prophet ﷺ.","It is said that there was no mosque, apart from the mosques of Makkah and Madinah, in which apostasy did not occur.","The hadiths concerning the Ḥawḍ are mutawātir, and belief in the Ḥawḍ is part of the creed of Ahl al-Sunnah.","4 – The Vast Size of the Ḥawḍ","Its dimensions have been described as:","a journey of one month;","the distance between Ṣanʿāʾ and Madinah;","the distance between Jarbāʾ and Adhruḥ, two villages in al-Shām;","the distance between Madinah and ʿAmmān;","the distance between Aylah and al-Juḥfah;","and other descriptions.","There is no contradiction in these reports. Rather, the Prophet ﷺ spoke at different times, and each group of narrators transmitted comparisons using distances between places familiar to them.","Among the miracles of the Prophet ﷺ is that he mentioned these cities even though he had neither visited nor seen them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7051 ،7050)، ومسلم (2290)."},{"num":16242,"demo":false,"sanad":"","matn":["عَنْ جَرِيرٍ، قَالَ: كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ نَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالَ: إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ، لاَ تُضَامُّونَ فِي رُؤْيَتِهِ، فَإِنِ اسْتَطَعْتُمْ أَنْ لاَ تُغْلَبُوا عَلَى صَلاَةٍ قَبْلَ طُلُوعِ الشَّمْسِ، وَصَلاَةٍ قَبْلَ غُرُوبِ الشَّمْسِ، فَافْعَلُوا."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7434)، ومسلم في المساجد (633) كلاهما من طريق إسماعيل بن أبي خالد، ثنا قيس بن أبي حازم، قال: سمعت جرير بن عبدالله، فذكره.","grade":"متفق عليه","chapter_ar":"باب رؤية المؤمنين ربهم يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7434) and Muslim (633).","chapter_en":"The Believers Will See Their Lord on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":48,"content":{"translation":{"en":["Jarīr ibn ʿAbdullāh narrated: We were sitting with the Prophet ﷺ when he looked at the moon on the night of the full moon and said: “Indeed, you will see your Lord just as you see this moon, without crowding or difficulty in seeing Him. So if you are able not to be overcome in performing a prayer before sunrise and a prayer before sunset, then do so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7434)، ومسلم (633)."},{"num":16243,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، ـ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً، قَالَ: يَا نَبِيَّ اللَّهِ كَيْفَ يُحْشَرُ الْكَافِرُ عَلَى وَجْهِهِ قَالَ: أَلَيْسَ الَّذِي أَمْشَاهُ عَلَى الرِّجْلَيْنِ فِي الدُّنْيَا، قَادِرًا عَلَى أَنَّ يُمْشِيَهُ عَلَى وَجْهِهِ يَوْمَ الْقِيَامَةِ.","قَالَ قَتَادَةُ: بَلَى، وَعِزَّةِ رَبِّنَا."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6523)، ومسلم في صفة القيامة والجنة والنار (2806) كلاهما من طريق يونس بن محمد البغدادي، حدثنا شيبان، عن قتادة، حدثنا أنس بن مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب يحشر الكافر إلى النار على وجهه","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6523) and Muslim (2806).","chapter_en":"The Disbeliever Will Be Gathered to the Fire upon His Face","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":49,"content":{"translation":{"en":["Anas narrated: A man asked: “O Messenger of Allah, how will the disbeliever be gathered upon his face on the Day of Resurrection?” He replied: “Is not the One who made him walk upon his two feet in this world able to make him walk upon his face on the Day of Resurrection?” Qatādah said: “Yes, by the Might of our Lord.”"]},"intro":{"ar":["قال تعالى:","﴿الَّذِينَ يُحْشَرُونَ عَلَىٰ وُجُوهِهِمْ إِلَىٰ جَهَنَّمَ أُولَٰئِكَ شَرٌّ مَكَانًا وَأَضَلُّ سَبِيلًا﴾ [سورة الفرقان: ٣٤]."],"en":["Allah, the Exalted, says:","“Those who will be gathered upon their faces toward Hell—those are in the worst place and are furthest astray from the path.”","[al-Furqān 25:34]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6523)، ومسلم (2806)."},{"num":16244,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَوْلِهِ عَزَّ وَجَلَّ: ﴿يَوْمَ تُبَدَّلُ الأَرْضُ غَيْرَ الأَرْضِ وَالسَّمَاوَاتُ﴾ فَأَيْنَ يَكُونُ النَّاسُ يَوْمَئِذٍ يَا رَسُولَ اللَّهِ؟ فَقَالَ: عَلَى الصِّرَاطِ."],"takhrij":"صحيح: رواه مسلم في صفة القيامة والجنة والنار (2791) عن أبي بكر بن أبي شيبة، حدثنا علي بن مُسْهر، عن داود، عن الشعبي، عن مسروق، عن عائشة، قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب المرور على الصراط يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2791).","chapter_en":"Crossing the Ṣirāṭ on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["ʿĀ’ishah narrated: I asked the Messenger of Allah ﷺ concerning the statement of Allah, Mighty and Majestic: “On the Day the earth will be replaced by another earth, and the heavens as well.” [Ibrāhīm 14:48] I asked: “Where will the people be at that time, O Messenger of Allah?” He replied: “Upon the Ṣirāṭ.”"]},"intro":{"ar":["قال تعالى:","﴿يَوْمَ تَرَى الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ يَسْعَىٰ نُورُهُمْ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ بُشْرَاكُمُ الْيَوْمَ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ۝ يَوْمَ يَقُولُ الْمُنَافِقُونَ وَالْمُنَافِقَاتُ لِلَّذِينَ آمَنُوا انْظُرُونَا نَقْتَبِسْ مِنْ نُورِكُمْ قِيلَ ارْجِعُوا وَرَاءَكُمْ فَالْتَمِسُوا نُورًا فَضُرِبَ بَيْنَهُمْ بِسُورٍ لَهُ بَابٌ بَاطِنُهُ فِيهِ الرَّحْمَةُ وَظَاهِرُهُ مِنْ قِبَلِهِ الْعَذَابُ ۝ يُنَادُونَهُمْ أَلَمْ نَكُنْ مَعَكُمْ قَالُوا بَلَىٰ وَلَٰكِنَّكُمْ فَتَنْتُمْ أَنْفُسَكُمْ وَتَرَبَّصْتُمْ وَارْتَبْتُمْ وَغَرَّتْكُمُ الْأَمَانِيُّ حَتَّىٰ جَاءَ أَمْرُ اللَّهِ وَغَرَّكُمْ بِاللَّهِ الْغَرُورُ ۝ فَالْيَوْمَ لَا يُؤْخَذُ مِنْكُمْ فِدْيَةٌ وَلَا مِنَ الَّذِينَ كَفَرُوا مَأْوَاكُمُ النَّارُ هِيَ مَوْلَاكُمْ وَبِئْسَ الْمَصِيرُ﴾ [سورة الحديد: ١٢-١٥].","وقال تعالى:","﴿يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا عَسَىٰ رَبُّكُمْ أَنْ يُكَفِّرَ عَنْكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ يَوْمَ لَا يُخْزِي اللَّهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ نُورُهُمْ يَسْعَىٰ بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ يَقُولُونَ رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ﴾ [التحريم: ٨]."],"en":["Allah, the Exalted, says:","“On the Day you will see the believing men and believing women, their light proceeding before them and on their right: ‘Glad tidings for you today—Gardens beneath which rivers flow, remaining therein forever. That is the tremendous success.’","On that Day the hypocrite men and hypocrite women will say to those who believed: ‘Wait for us so that we may take some of your light.’ It will be said: ‘Go back behind you and seek light.’ Then a wall containing a gate will be placed between them. Inside it will be mercy, while outside it will be punishment.","They will call to them: ‘Were we not with you?’ They will reply: ʿYes, but you put yourselves into temptation, waited, doubted, and false hopes deceived you until the command of Allah came, and the deceiver deceived you concerning Allah.","So today no ransom will be accepted from you or from those who disbelieved. Your refuge is the Fire. It is your proper abode, and what a wretched destination.’”","[al-Ḥadīd 57:12-15]","And He, the Exalted, says:","“O you who believe, turn to Allah in sincere repentance. Perhaps your Lord will remove your sins from you and admit you into Gardens beneath which rivers flow, on the Day when Allah will not disgrace the Prophet and those who believed with him. Their light will proceed before them and on their right. They will say: ‘Our Lord, perfect our light for us and forgive us. Indeed, You are capable of all things.’”","[al-Taḥrīm 66:8]"]}},"tuhfa":{},"full":1,"rep":[12599],"tks":"صحيح: رواه مسلم (2791)."},{"num":16245,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ نَاسًا فِي زَمَنِ رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: يَا رَسُولَ اللَّهِ! هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : نَعَمْ فِي حَدِيثِ طَوِيلٍ، وَجَاءَ فِيهِ: ثُمَّ يُضْربُ الجسْرُ عَلَى جَهَنَّمَ وتَحِلُّ الشَّفاعةُ. وَيَقُولُونَ: اللّهمَّ سَلِّمْ سَلِّمْ. قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا الْجِسْرُ؟ قَالَ: دَحْضٌ مَزِلَّةٌ، فِيهِ خَطَاطِيُف وَكَلَالِيبُ وَحَسَكٌ، تَكُونُ بِنَجْدٍ فِيهَا شُوَيْكةٌ يُقَالُ: لَهَا السَّعْدانُ، فَيَمُرُّ الْمُؤْمِنُونَ كطَرْف الْعَيْنِ وَكَالْبَرْقِ وَكَالرِّيحِ وَكَالطَّيْرِ وَكَأَجَاوِيدِ الْخَيْلِ وَالرِّكَابِ، فَنَاجٍ مُسَلَّمٌ ومَخْدُوشٌ مُرْسَلٌ ومَكْدُوٌس فِي نَارِ جَهَنَّم. حَتَّى إِذَا خَلَصَ الْمُؤْمِنُونَ مِنَ النَّارِ، فَوَالَّذِي نَفْسِي بِيَدِهِ مَا مِنْكُمْ مِنْ أَحَدٍ بأشدَّ مُناشَدةً لِلهِ فِي اسْتِقْصَاءِ الحقِّ مِنَ الْمُؤْمِنِينَ لِلهِ يَوْمَ الْقِيَامَةِ لِإِخْوَانِهِمُ الَّذِينَ فِي النَّارِ... الْحَدِيثِ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4581)، ومسلم في الإيمان (183) كلاهما من حديث حفص بن ميسرة، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدريّ، فذكر الحديث، واللّفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب المرور على الصراط يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4581) and Muslim (183). The wording is Muslim’s.","chapter_en":"Crossing the Ṣirāṭ on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: Some people during the time of the Messenger of Allah ﷺ asked: “O Messenger of Allah, will we see our Lord on the Day of Resurrection?” The Messenger of Allah ﷺ replied: “Yes.” In the lengthy hadith, he said: “Then the bridge will be placed over Hell, and intercession will be permitted. They will say: ‘O Allah, grant safety! Grant safety!’” It was asked: “O Messenger of Allah, what is the bridge?” He replied: “It is slippery and causes feet to slip. Upon it are hooks, grappling irons, and thorns like the thorny plant found in Najd called al-Saʿdān. The believers will cross like the blink of an eye, like lightning, like the wind, like birds, and like the finest horses and riding animals. Some will cross safely and unharmed, some will be scratched but released, and some will be thrown into the Fire of Hell. When the believers have been delivered from the Fire, then by the One in whose hand is my soul, none of you will plead more intensely with Allah for the complete restoration of a right than the believers will plead with Allah on the Day of Resurrection for their brothers who are in the Fire.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4581)، ومسلم (183)، واللفظ لمسلم."},{"num":16246,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ وحذيفة فِي حَدِيثِ الشفاعة الطويل: فَيَأْتُونَ محمّداً صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيَقُومُ فَيُؤْذَنُ لَهُ، وَتُرْسَلُ الْأَمَانَةُ وَالرَّحِمُ، فَتَقُومَانِ جَنَبَتَيْ الصِّراطِ يَمِينًا وَشِمَالًا فيمرُّ أَوَّلُكُمْ كَالْبَرْقِ. قَالَ: قلتُ: بِأَبِي أَنْتَ وَأُمِّي أَيُّ شَيْءٍ كَمَرِّ الْبَرْقِ؟ قَالَ: أَلَمْ تَرَوْا إِلَى الْبَرْقِ كَيْفَ يَمُرُّ وَيَرْجِعُ فِي طَرْفَةِ عَيْنٍ؟ ثُمَّ كمرّ الرِّيحِ، ثُمَّ كمرّ الطَّيْرِ وشدّ الرِّجَالِ، تَجْرِي بِهِمْ أَعْمَالُهُمْ، وَنَبِيُّكُمْ قَائِمٌ عَلَى الصِّرَاطِ يَقُولُ: ربِّ سَلِّم سَلِّم، حتّى تَعْجِز أَعْمَالُ الْعِبَادِ حَتَّى يَجِيءَ الرَّجُل فَلَا يَسْتَطِيعُ السَّيْر إلاّ زَحْفًا. قَالَ: وَفِي حَافَتَيِ الصِّرَاطِ كَلَالِيبُ مُعَلَّقة مَأْمُورَةٌ بِأَخْذِ مَنْ أُمِرتْ بِهِ، فَمَخْدُوشٌ ناجٍ، وَمَكْدُوسٌ فِي النَّارِ. وَالَّذِي نَفْسُ أَبِي هُرَيْرَةَ بِيَدِهِ، إِنَّ قَعْرَ جَهَنَّمَ لَسَبْعُونَ خَرِيفًا."],"takhrij":"صحيح: رواه مسلم في الإيمان (195) عن محمد بن طريف بن خليفة، حدّثنا محمد بن فضيل، حدّثنا أبو مالك الأشجعيّ، عن أبي حازم، عن أبي هريرة، وأبو مالك، عن ربعي، عن حذيفة فذكراه.","grade":"صحيح","chapter_ar":"باب المرور على الصراط يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (195).","chapter_en":"Crossing the Ṣirāṭ on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["Abū Hurayrah and Ḥudhayfah narrated in the lengthy hadith of intercession: “They will come to Muḥammad ﷺ, and he will stand, and permission will be granted to him. Then the Trust and the ties of kinship will be sent forth, and they will stand on the two sides of the Ṣirāṭ, one on the right and one on the left. The first of you will pass over it like lightning.” The narrator said: I asked: “May my father and mother be sacrificed for you—what is passing like lightning?” He replied: “Have you not seen how lightning passes and returns in the blink of an eye? Then some will pass like the wind, then like birds, and then like men running swiftly. Their deeds will carry them along. Your Prophet will stand upon the Ṣirāṭ saying: ‘My Lord, grant safety! Grant safety!’ This will continue until the deeds of the servants become too weak to carry them swiftly, until a man comes who can only move by crawling.” He continued: “On the two sides of the Ṣirāṭ are suspended hooks commanded to seize those whom they are commanded to seize. Some will be scratched but saved, while others will be piled into the Fire.” By the One in whose hand is the soul of Abū Hurayrah, the depth of Hell is a journey of seventy years."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (195)."},{"num":16247,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  آخِرُ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ، فَهُوَ يَمْشِي مَرَّةً، وَيَكْبُو مَرَّةً، وَتَسْفَعُهُ النَّارُ مَرَّةً، فَإِذَا مَا جَاوَزَهَا الْتَفَتَ إِلَيْهَا، فَقَالَ: تَبَارَكَ الَّذِي نَجَّانِي مِنْكِ، لَقَدْ أَعْطَانِيَ اللَّهُ شَيْئًا مَا أَعْطَاهُ أَحَدًا مِنَ الْأَوَّلِينَ وَالْآخِرِينَ، فَتُرْفَعُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (187) عن أبي بكر بن أبي شيبة، حدّثنا عفّان بن مسلم، حدّثنا حمّاد بن سلمة، حدّثنا ثابت، عن أنس بن مالك، عن ابن مسعود، فذكره.","grade":"صحيح","chapter_ar":"باب المرور على الصراط يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (187).","chapter_en":"Crossing the Ṣirāṭ on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “The last person to enter Paradise will be a man who walks at one time, stumbles at another, and is scorched by the Fire at another. When he finally passes beyond it, he will turn toward it and say: ‘Blessed is the One who saved me from you! Allah has given me something that He has not given anyone among the first or the last…’” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (187)."},{"num":16248,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَسْمَاءَ: أَنَّهُ دَخَلَ عَلَى أَبِي ذَرٍّ، وَهُوَ بِالرَّبَذَةِ، وَعِنْدَهُ امْرَأَةٌ لَهُ سَوْدَاءُ مُشْبَعَةٌ لَيْسَ عَلَيْهَا أَثَرُ الْمَجَاسِدِ وَلَا الْخَلُوقِ، قَالَ: فَقَالَ: أَلَا تَنْظُرُونَ إِلَى مَا تَأْمُرُنِي بِهِ هَذِهِ السُّوَيْدَاءُ؟ تَأْمُرُنِي أَنْ آتِيَ الْعِرَاقَ، فَإِذَا أَتَيْتُ الْعِرَاقَ مَالُوا عَلَيَّ بِدُنْيَاهُمْ، وَإِنَّ خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَهِدَ إِلَيَّ: أَنَّ دُونَ جِسْرِ جَهَنَّمَ طَرِيقًا ذَا دَحْضٍ وَمَزِلَّةٍ، وَإِنَّا نَأْتِي عَلَيْهِ وَفِي أَحْمَالِنَا اقْتِدَارٌ. وَحَدَّثَ مَطَرٌ، أَيْضًا بِالْحَدِيثِ أَجْمَعَ فِي قَوْلِ أَحَدِهِمَا: أَنْ نَأْتِيَ عَلَيْهِ وَفِي أَحْمَالِنَا اقْتِدَارٌ. وَقَالَ الْآخَرَانِ: نَأْتِيَ عَلَيْهِ وَفِي أَحْمَالِنَا اضْطِمَارٌ، أَحْرَى أَنْ نَنْجُوَ مَنْ أَنْ نَأْتِيَ عَلَيْهِ وَنَحْنُ مَوَاقِيرُ."],"takhrij":"صحيح: رواه أحمد (21416) والحارث بن أبي أسامة كما في بغية الباحث (1087) كلاهما عن عفان، حدثنا همام، حدثنا قتادة، عن أبي قلابة، عن أبي أسماء الرحبي، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب المرور على الصراط يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (21416) and al-Ḥārith ibn Abī Usāmah, as cited in Bughyat al-Bāḥith (1087).","chapter_en":"Crossing the Ṣirāṭ on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["Abū Asmāʾ narrated: He entered upon Abū Dharr while he was at al-Rabadhah. With him was a dark-skinned woman who was not adorned and bore no traces of perfume or cosmetic coloring. Abū Dharr said: “Do you not see what this woman is telling me to do? She tells me to go to Iraq. But if I go to Iraq, they will incline toward me with their worldly possessions. The Prophet ﷺ, my close friend, entrusted me with the knowledge that before the bridge over Hell there is a path that is slippery and causes feet to slip. For us to come to it while our burdens are light is more likely to save us than to come to it heavily laden.” Maṭar also narrated the complete report. In one wording: “That we come to it while we are able to carry our loads…” And in the other two versions: “That we come to it with our burdens reduced…” is more likely to lead to salvation than coming to it while heavily burdened."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21416) والحارث بن أبي أسامة كما في بغية الباحث (1087)."},{"num":16249,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُوضَعُ الصِّرَاطُ بَيْنَ ظَهْرَي جَهَنَّمَ، عَلَيْهِ حَسَكٌ كحَسَكِ السَّعْدان، ثُمَّ يَسْتجيزُ النّاسُ، فَنَاجٍ مُسَلَّمٌ، ومجروحٌ بِهِ، ثُمَّ ناجِ ومُحْتَبس بِهِ فَمَنْكُوسٌ فِيهَا... الحديث بِطُولِهِ."],"takhrij":"حسن: رواه أحمد (11081) واللّفظ له، وابن خزيمة في التوحيد (648)، وابن ماجه (4280) مختصراً، والحاكم (8738) - وصحّحه - كلّهم من طريق محمد بن إسحاق، قال: حدّثني عبيد الله بن المغيرة بن مُعيقيب، عن سليمان بن عمرو بن عبد العُتْواريّ -أحد بني ليث- وكان يتيماً في حجر أبي سعيد، قال: سمعت أبا سعيد يقول: فذكره.","grade":"حسن","chapter_ar":"باب المرور على الصراط يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (11081), whose wording this is, Ibn Khuzaymah in al-Tawḥīd (648), Ibn Mājah (4280) in abbreviated form, and al-Ḥākim (4/585-586), who authenticated it.","chapter_en":"Crossing the Ṣirāṭ on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: I heard the Messenger of Allah ﷺ say: “The Ṣirāṭ will be placed over Hell. Upon it are thorns like the thorns of al-Saʿdān. Then the people will attempt to cross. Some will be saved unharmed, some will be wounded by it and then saved, while others will be caught by it and overturned into the Fire…” The hadith continues at length."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11081) واللفظ له، وابن خزيمة في التوحيد (648)، وابن ماجه (4280) مختصرا، والحاكم (8738) - وصححه -."},{"num":16250,"demo":false,"sanad":"","matn":["عن أَبِي بَكْرَةَ، عن النّبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُحْمَلُ النَّاسُ عَلَى الصِّرَاطِ يَوْمَ الْقِيَامَةِ، فَتَقَادَعُ بِهِمْ جَنَبَتَا الصِّرَاطِ تَقَادُعَ الْفَرَاشِ فِي النَّارِ. ، قَالَ: فَيُنْجِي اللهُ بِرَحْمَتِهِ مَنْ يَشَاءُ."],"takhrij":"حسن: رواه أحمد (20440)، والبزّار (3671)، وابن أبي عاصم في السنة (838) كلّهم من حديث عفّان بن مسلم، حدّثنا سعيد بن زيد، قال: سمعت أبا سليمان العصريّ، حدّثنا عقبة بن صُهبان، عن أبي بكرة، فذكره.","grade":"حسن","chapter_ar":"باب المرور على الصراط يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20440), al-Bazzār (3671), and Ibn Abī ʿĀṣim in al-Sunnah (838).","chapter_en":"Crossing the Ṣirāṭ on the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":50,"content":{"translation":{"en":["Abū Bakrah narrated that the Prophet ﷺ said: “The people will be brought onto the Ṣirāṭ on the Day of Resurrection, and the two sides of the Ṣirāṭ will cause them to fall one after another just as moths fall into a fire. Then Allah will save by His mercy whomever He wills.” The hadith continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20440)، والبزار (3671)، وابن أبي عاصم في السنة (838)."},{"num":16251,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ،  أَنَّ نَاسًا فِي زَمَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: يَا رَسُولَ اللَّهِ، هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، قَالَ: هَلْ تُضَارُّونَ فِي رُؤْيَةِ الشَّمْسِ بِالظَّهِيرَةِ صَحْوًا لَيْسَ مَعَهَا سَحَابٌ؟ وَهَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ صَحْوًا لَيْسَ فِيهَا سَحَابٌ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ، قَالَ: مَا تُضَارُّونَ فِي رُؤْيَةِ اللهِ تَبَارَكَ وَتَعَالَى يَوْمَ الْقِيَامَةِ إِلَّا كَمَا تُضَارُّونَ فِي رُؤْيَةِ أَحَدِهِمَا، إِذَا كَانَ يَوْمُ الْقِيَامَةِ أَذَّنَ مُؤَذِّنٌ لِيَتَّبِعْ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ، فَلَا يَبْقَى أَحَدٌ كَانَ يَعْبُدُ غَيْرَ اللهِ سُبْحَانَهُ مِنَ الْأَصْنَامِ وَالْأَنْصَابِ إِلَّا يَتَسَاقَطُونَ فِي النَّارِ، حَتَّى إِذَا لَمْ يَبْقَ إِلَّا مَنْ كَانَ يَعْبُدُ اللَّهَ مِنْ بَرٍّ وَفَاجِرٍ وَغُبَّرِ أَهْلِ الْكِتَابِ، فَيُدْعَى الْيَهُودُ فَيُقَالُ لَهُمْ: مَا كُنْتُمْ تَعْبُدُونَ؟ قَالُوا: كُنَّا نَعْبُدُ عُزَيْرَ ابْنَ اللهِ. فَيُقَالُ: كَذَبْتُمْ، مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ وَلَا وَلَدٍ، فَمَاذَا تَبْغُونَ؟ قَالُوا: عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا، فَيُشَارُ إِلَيْهِمْ أَلَا تَرِدُونَ؟ فَيُحْشَرُونَ إِلَى النَّارِ كَأَنَّهَا سَرَابٌ يَحْطِمُ بَعْضُهَا بَعْضًا، فَيَتَسَاقَطُونَ فِي النَّارِ، ثُمَّ يُدْعَى النَّصَارَى، فَيُقَالُ لَهُمْ: مَا كُنْتُمْ تَعْبُدُونَ؟ قَالُوا: كُنَّا نَعْبُدُ الْمَسِيحَ ابْنَ اللهِ، فَيُقَالُ لَهُمْ: كَذَبْتُمْ، مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ وَلَا وَلَدٍ، فَيُقَالُ لَهُمْ: مَاذَا تَبْغُونَ؟ فَيَقُولُونَ: عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا، قَالَ: فَيُشَارُ إِلَيْهِمْ أَلَا تَرِدُونَ؟ فَيُحْشَرُونَ إِلَى جَهَنَّمَ كَأَنَّهَا سَرَابٌ يَحْطِمُ بَعْضُهَا بَعْضًا، فَيَتَسَاقَطُونَ فِي النَّارِ، حَتَّى إِذَا لَمْ يَبْقَ إِلَّا مَنْ كَانَ يَعْبُدُ اللَّهَ تَعَالَى مِنْ بَرٍّ وَفَاجِرٍ أَتَاهُمْ رَبُّ الْعَالَمِينَ سُبْحَانَهُ وَتَعَالَى فِي أَدْنَى صُورَةٍ مِنَ الَّتِي رَأَوْهُ فِيهَا، قَالَ: فَمَا تَنْتَظِرُونَ؟ تَتْبَعُ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ، قَالُوا: يَا رَبَّنَا، فَارَقْنَا النَّاسَ فِي الدُّنْيَا أَفْقَرَ مَا كُنَّا إِلَيْهِمْ وَلَمْ نُصَاحِبْهُمْ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: نَعُوذُ بِاللهِ مِنْكَ، لَا نُشْرِكُ بِاللهِ شَيْئًا - مَرَّتَيْنِ أَوْ ثَلَاثًا - حَتَّى إِنَّ بَعْضَهُمْ لَيَكَادُ أَنْ يَنْقَلِبَ، فَيَقُولُ: هَلْ بَيْنَكُمْ وَبَيْنَهُ آيَةٌ فَتَعْرِفُونَهُ بِهَا؟ فَيَقُولُونَ: نَعَمْ، فَيُكْشَفُ عَنْ سَاقٍ، فَلَا يَبْقَى مَنْ كَانَ يَسْجُدُ لِلهِ مِنْ تِلْقَاءِ نَفْسِهِ إِلَّا أَذِنَ اللَّهُ لَهُ بِالسُّجُودِ، وَلَا يَبْقَى مَنْ كَانَ يَسْجُدُ اتِّقَاءً وَرِيَاءً إِلَّا جَعَلَ اللَّهُ ظَهْرَهُ طَبَقَةً وَاحِدَةً، كُلَّمَا أَرَادَ أَنْ يَسْجُدَ خَرَّ عَلَى قَفَاهُ ثُمَّ يَرْفَعُونَ رُؤُوسَهُمْ وَقَدْ تَحَوَّلَ فِي صُورَتِهِ الَّتِي رَأَوْهُ فِيهَا أَوَّلَ مَرَّةٍ، فَقَالَ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: أَنْتَ رَبُّنَا، ثُمَّ يُضْرَبُ الْجِسْرُ عَلَى جَهَنَّمَ، وَتَحِلُّ الشَّفَاعَةُ، وَيَقُولُونَ: اللَّهُمَّ سَلِّمْ سَلِّمْ. قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا الْجِسْرُ؟ قَالَ: دَحْضٌ مَزَِلَّةٌ، فِيهِ خَطَاطِيفُ وَكَلَالِيبُ، وَحَسَكٌ تَكُونُ بِنَجْدٍ فِيهَا شُوَيْكَةٌ يُقَالُ لَهَا: السَّعْدَانُ، فَيَمُرُّ الْمُؤْمِنُونَ كَطَرْفِ الْعَيْنِ وَكَالْبَرْقِ وَكَالرِّيحِ وَكَالطَّيْرِ وَكَأَجَاوِيدِ الْخَيْلِ وَالرِّكَابِ، فَنَاجٍ مُسَلَّمٌ وَمَخْدُوشٌ مُرْسَلٌ، وَمَكْدُوسٌ فِي نَارِ جَهَنَّمَ، حَتَّى إِذَا خَلَصَ الْمُؤْمِنُونَ مِنَ النَّارِ، فَوَالَّذِي نَفْسِي بِيَدِهِ مَا مِنْكُمْ مِنْ أَحَدٍ بِأَشَدَّ مُنَاشَدَةً لِلهِ فِي اسْتِقْصَاءِ الْحَقِّ مِنَ الْمُؤْمِنِينَ لِلهِ يَوْمَ الْقِيَامَةِ لِإِخْوَانِهِمُ الَّذِينَ فِي النَّارِ، يَقُولُونَ: رَبَّنَا، كَانُوا يَصُومُونَ مَعَنَا وَيُصَلُّونَ وَيَحُجُّونَ، فَيُقَالُ لَهُمْ: أَخْرِجُوا مَنْ عَرَفْتُمْ، فَتُحَرَّمُ صُوَرُهُمْ عَلَى النَّارِ، فَيُخْرِجُونَ خَلْقًا كَثِيرًا قَدْ أَخَذَتِ النَّارُ إِلَى نِصْفِ سَاقَيْهِ وَإِلَى رُكْبَتَيْهِ، ثُمَّ يَقُولُونَ: رَبَّنَا، مَا بَقِيَ فِيهَا أَحَدٌ مِمَّنْ أَمَرْتَنَا بِهِ، فَيَقُولُ: ارْجِعُوا، فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ دِينَارٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ، فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا، لَمْ نَذَرْ فِيهَا أَحَدًا مِمَّنْ أَمَرْتَنَا، ثُمَّ يَقُولُ: ارْجِعُوا، فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ نِصْفِ دِينَارٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ، فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا، لَمْ نَذَرْ فِيهَا مِمَّنْ أَمَرْتَنَا أَحَدًا، ثُمَّ يَقُولُ: ارْجِعُوا، فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ خَيْرٍ فَأَخْرِجُوهُ، فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا، لَمْ نَذَرْ فِيهَا خَيْرًا، وَكَانَ أَبُو سَعِيدٍ الْخُدْرِيُّ يَقُولُ: إِنْ لَمْ تُصَدِّقُونِي بِهَذَا الْحَدِيثِ فَاقْرَؤُوا إِنْ شِئْتُمْ: ﴿إِنَّ اللَّهَ لا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا﴾، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: شَفَعَتِ الْمَلَائِكَةُ وَشَفَعَ النَّبِيُّونَ وَشَفَعَ الْمُؤْمِنُونَ، وَلَمْ يَبْقَ إِلَّا أَرْحَمُ الرَّاحِمِينَ، فَيَقْبِضُ قَبْضَةً مِنَ النَّارِ فَيُخْرِجُ مِنْهَا قَوْمًا لَمْ يَعْمَلُوا خَيْرًا قَطُّ قَدْ عَادُوا حُمَمًا، فَيُلْقِيهِمْ فِي نَهَْرٍ فِي أَفْوَاهِ الْجَنَّةِ، يُقَالُ لَهُ: نَهَْرُ الْحَيَاةِ، فَيَخْرُجُونَ كَمَا تَخْرُجُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ، أَلَا تَرَوْنَهَا تَكُونُ إِلَى الْحَجَرِ أَوْ إِلَى الشَّجَرِ؟ مَا يَكُونُ إِلَى الشَّمْسِ أُصَيْفِرُ وَأُخَيْضِرُ، وَمَا يَكُونُ مِنْهَا إِلَى الظِّلِّ يَكُونُ أَبْيَضَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، كَأَنَّكَ كُنْتَ تَرْعَى بِالْبَادِيَةِ، قَالَ: فَيَخْرُجُونَ كَاللُّؤْلُؤِ فِي رِقَابِهِمُ الْخَوَاتِمُ يَعْرِفُهُمْ أَهْلُ الْجَنَّةِ، هَؤُلَاءِ عُتَقَاءُ اللَّهِ الَّذِينَ أَدْخَلَهُمُ اللهُ الْجَنَّةَ بِغَيْرِ عَمَلٍ عَمِلُوهُ وَلَا خَيْرٍ قَدَّمُوهُ، ثُمَّ يَقُولُ: ادْخُلُوا الْجَنَّةَ فَمَا رَأَيْتُمُوهُ فَهُوَ لَكُمْ، فَيَقُولُونَ: رَبَّنَا، أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنَ الْعَالَمِينَ، فَيَقُولُ: لَكُمْ عِنْدِي أَفْضَلُ مِنْ هَذَا، فَيَقُولُونَ: يَا رَبَّنَا، أَيُّ شَيْءٍ أَفْضَلُ مِنْ هَذَا؟ فَيَقُولُ: رِضَايَ، فَلَا أَسْخَطُ عَلَيْكُمْ بَعْدَهُ أَبَدًا.","وفي رواية بعد قوله: بغير عمل عملوه، ولا خير قدموه: لكم ما رأيتم ومثله معه.","وقال أَبُو سَعِيدٍ: \"بَلَغَنِي أَنَّ الْجِسْرَ أَدَقُّ مِنَ الشَّعَْرَةِ وَأَحَدُّ مِنَ السَّيْفِ\"."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7439)، ومسلم في الإيمان (183) كلاهما من طريق زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدري، فذكره. واللفظ لمسلم. وليس عند البخاري في هذه الرواية: فيقولون ربنا أعطيتنا...الخ. وقول أبي سعيد الأخير ذكره مسلم.","grade":"متفق عليه","chapter_ar":"باب جامع في ذكر عدد من مشاهد يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7439) and Muslim (183). The wording is Muslim’s.","chapter_en":"A Comprehensive Chapter Mentioning a Number of the Scenes of the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":51,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: Some people during the lifetime of the Messenger of Allah ﷺ asked: “O Messenger of Allah, will we see our Lord on the Day of Resurrection?” The Messenger of Allah ﷺ replied: “Yes.” He then asked: “Do you have any difficulty seeing the sun at midday on a clear day when there are no clouds? And do you have any difficulty seeing the full moon on a clear night when there are no clouds?” They replied: “No, O Messenger of Allah.” He said: “You will have no more difficulty seeing Allah, Blessed and Exalted, on the Day of Resurrection than you have seeing either of those. When the Day of Resurrection comes, a caller will announce that every nation should follow what it used to worship. No one who worshipped anything besides Allah—idols or objects of worship—will remain except that they will fall into the Fire. When none remain except those who worshipped Allah, both the righteous and the sinful, along with the remnants of the People of the Book, the Jews will be summoned. They will be asked: ‘What did you worship?’ They will reply: ‘We used to worship ʿUzayr, the son of Allah.’ It will be said: ‘You have lied. Allah has taken neither a wife nor a son. What do you seek?’ They will say: ‘Our Lord, we are thirsty, so give us drink.’ They will be directed: ‘Will you not go to drink?’ Then they will be gathered toward the Fire, which will appear like a mirage, its parts crashing into one another, and they will fall into the Fire. Then the Christians will be summoned. They will be asked: ‘What did you worship?’ They will say: ‘We used to worship the Messiah, the son of Allah.’ It will be said: ‘You have lied. Allah has taken neither a wife nor a son.’ They will be asked: ‘What do you seek?’ They will reply: ‘Our Lord, we are thirsty, so give us drink.’ They will be directed: ‘Will you not go to drink?’ Then they will be gathered toward Hell, which will appear like a mirage, its parts crashing into one another, and they will fall into the Fire. When none remain except those who worshipped Allah, the righteous among them and the sinful, the Lord of the worlds, Glorified and Exalted, will come to them in a form less recognizable than the form in which they had seen Him before. He will say: ‘What are you waiting for? Every nation has followed what it used to worship.’ They will say: ‘Our Lord, we separated ourselves from the people in the world at the time when we were most in need of them, and we did not accompany them.’ He will say: ‘I am your Lord.’ They will say: ‘We seek refuge in Allah from you! We do not associate anything with Allah,’ repeating this two or three times, until some of them will almost turn back. He will ask: ‘Is there a sign between you and Him by which you will recognize Him?’ They will reply: ‘Yes.’ Then the Shin will be uncovered. Everyone who used to prostrate to Allah sincerely of his own accord will be permitted by Allah to prostrate. As for anyone who used to prostrate merely out of fear of people or to show off, Allah will make his back into a single rigid piece. Whenever he tries to prostrate, he will fall backward onto his neck. Then they will raise their heads, and He will have returned to the form in which they had recognized Him the first time. He will say: ‘I am your Lord.’ They will say: ‘You are our Lord.’ Then the bridge will be placed over Hell, intercession will be permitted, and they will say: ‘O Allah, grant safety! Grant safety!’” It was asked: “O Messenger of Allah, what is the bridge?” He replied: “It is slippery and causes feet to slip. Upon it are hooks, grappling irons, and thorns like a thorny plant found in Najd called al-Saʿdān. The believers will cross like the blink of an eye, like lightning, like the wind, like birds, and like the finest horses and riding animals. Some will pass safely and unharmed, some will be scratched but released, and some will be piled into the Fire of Hell. When the believers have been delivered from the Fire, then by the One in whose hand is my soul, none of you will plead with Allah more intensely for the full restoration of a right than the believers will plead with Allah on the Day of Resurrection on behalf of their brothers who are in the Fire. They will say: ‘Our Lord, they used to fast with us, pray with us, and perform Ḥajj with us.’ It will be said to them: ‘Bring out those whom you recognize.’ Their forms will be made forbidden to the Fire. They will bring out a great many people, some of whom the Fire had reached halfway up their shins and others up to their knees. Then they will say: ‘Our Lord, no one remains therein from among those whom You commanded us to bring out.’ He will say: ‘Go back, and whoever you find in whose heart there is goodness equal to the weight of a dinar, bring him out.’ They will bring out a great many people. Then they will say: ‘Our Lord, we have not left therein anyone whom You commanded us to bring out.’ Then He will say: ‘Go back, and whoever you find in whose heart there is goodness equal to half a dinar, bring him out.’ They will bring out a great many people. Then they will say: ‘Our Lord, we have not left therein anyone whom You commanded us to bring out.’ Then He will say: ‘Go back, and whoever you find in whose heart there is goodness equal to the weight of an atom, bring him out.’ They will bring out a great many people, then say: ‘Our Lord, we have left no good therein.’” Abū Saʿīd al-Khudrī used to say: “If you do not believe me concerning this hadith, then recite, if you wish: ‘Indeed, Allah does not wrong even by the weight of an atom. If there is a good deed, He multiplies it and gives from Himself a tremendous reward.’ [al-Nisāʾ 4:40]” Then the Prophet ﷺ continued: “Allah, Mighty and Majestic, will say: ‘The angels have interceded, the Prophets have interceded, and the believers have interceded. None remains except the Most Merciful of those who show mercy.’ Then He will take a handful from the Fire and bring out from it people who had never done any good whatsoever and who had become charred like coal. He will cast them into a river at the entrances of Paradise called the River of Life. They will emerge just as a seed sprouts in the silt carried by a flood. Have you not seen how such a seed grows beside a rock or tree—the portion exposed to the sun being yellowish and greenish, while the portion in the shade is white?” They said: “O Messenger of Allah, it is as though you used to herd animals in the desert.” He continued: “They will emerge looking like pearls, with seals around their necks by which the people of Paradise will recognize them. These are those whom Allah has set free, whom Allah admitted into Paradise without any deed they had performed or any good they had sent ahead. Then He will say: ‘Enter Paradise. Whatever you see is yours.’ They will say: ‘Our Lord, You have given us what You have not given anyone among all creation.’ He will say: ‘I have something better than this for you.’ They will ask: ‘Our Lord, what could be better than this?’ He will say: ‘My pleasure. I will never be angry with you after this.’” In another narration, after the words: “Without any deed they had performed or any good they had sent ahead,” it adds: “You will have whatever you see and an equal amount with it.” Abū Saʿīd said: “It has reached me that the bridge is finer than a hair and sharper than a sword.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7439)، ومسلم (183). واللفظ لمسلم."},{"num":16252,"demo":false,"sanad":"","matn":["عَنْ عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ، أَنَّ أَبَا هُرَيْرَةَ أَخْبَرَهُ، أنّ نَاسًا قَالُوا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يَا رَسُولَ اللَّهِ، هَلْ نَرَى ربَّنا يَوْمَ الْقِيَامَةِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : هَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ؟. قَالُوا: لاَ يَا رَسُولَ اللَّهِ. قَالَ: هَلْ تُضَارُّونَ فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ؟. قَالُوا: لاَ يَا رَسُولَ اللَّهِ. قَالَ: فَإِنَّكُمْ تَرَوْنَهُ كَذَلِكَ. يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ، فَيَقُولُ: مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْهُ فيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الشّمسَ الشَّمسَ، ويَتَّبِعُ مَنْ كَانَ يَعْبُدُ الْقَمَرَ الْقَمَرَ، ويَتَّبِعُ مَنْ كَانَ يَعْبُدُ الطَّوَاغِيتَ الطَّوَاغِيتَ، وَتَبْقَى هَذِهِ الأمّةُ فِيهَا مُنَافِقُوهَا، فَيَأْتِيهِمُ اللَّهُ تَبَارَكَ وَتَعَالَى فِي صورةٍ غيرِ صُورَتِهِ الَّتِي يَعْرِفُونَ. فَيَقُولُ: أَنَا ربُّكم، فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ! هَذَا مَكَانُنَا حتّى يَأْتِيَنَا ربُّنا، فَإِذَا جَاءَ ربُّنا عَرَفْنَاهُ، فَيَأْتِيهِمُ اللَّهُ تَعَالَى فِي صُورَتِهِ الَّتِي يَعْرِفُونَ فَيَقُولُ: أَنَا ربُّكم. فَيَقُولُونَ: أَنْتَ ربُّنا، فيَتَّبِعُونه. ويُضْرَبُ الصِّراطُ بَيْنَ ظَهْرَي جَهَنَّمَ. فَأَكُونُ أَنَا وأمَّتي أوَّلُ مَنْ يُجيزُ، وَلاَ يتكلَّمُ يَوْمَئِذٍ إِلاَّ الرُّسُل، ودَعْوَى الرُّسُلِ يَوْمَئِذٍ: اللَّهمَّ سَلِّمْ، سَلِّمْ. وَفِي جهنَّمَ كَلاَلِيبُ مثلُ شَوك السَّعْدان، هَلْ رَأَيْتُمُ السَّعْدان؟. قَالُوا: نَعَمْ، يَا رَسُولَ اللَّهِ. قَالَ: فَإِنَّهَا مثلُ شَوْك السَّعْدَانِ، غَيْرَ أنّه لاَ يَعْلَمُ مَا قَدْرُ عِظَمِها إلاّ اللَّهُ، تَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ. فَمِنْهُمُ المؤمن بَقِيَ بِعَمَلِهِ، وَمِنْهُمُ الْمُجَازَى حتَّى يُنَجَّى. حتَّى إِذَا فَرَغَ اللَّهُ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ، وَأَرَادَ أَنْ يُخْرِجَ بِرَحْمَتِهِ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ، أَمَرَ الْمَلاَئِكَةَ أَنْ يُخْرِجُوا مِنَ النَّارِ مَنْ كَانَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا مِمَّنْ أَرَادَ اللَّهُ تَعَالَى أَنْ يَرْحَمَهُ مِمَّنْ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ، فَيَعْرِفُونَهُمْ فِي النَّار، يعرفونهم بِأَثَرِ السُّجُودِ، تَأْكُلُ النّارُ من ابنِ آدَمَ إلاّ أَثَرَ السُّجُودِ، حرَّم اللَّهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ، فيُخْرجُون مِنَ النَّارِ وَقَدْ امْتُحِشُوا، فَيُصَبُّ عَلَيْهِمْ ماءُ الْحَيَاةِ فَيَنْبُتُون تَحْتَهُ كَمَا تَنْبُتُ الحبَّةُ فِي حَمِيل السَّيْل. ثُمَّ يفرُغُ اللَّهُ تَعَالَى مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ، وَيَبْقَى رَجُلٌ مُقْبِلٌ بِوَجْهِهِ عَلَى النَّارِ - وَهُوَ آخِرُ أَهْلِ الْجَنَّةِ دُخُولاً الْجَنَّةَ - فَيَقُولُ: أي ربِّ اصْرِفْ وَجْهِي عَنِ النَّارِ، فَإِنَّهُ قَدْ قَشَبَنِي رِيحُهَا وَأَحْرَقَنِي ذَكَاؤُهَا. فيدْعُو اللَّهَ مَا شاءَ اللَّهُ أَنْ يَدْعُوهُ، ثُمَّ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى: هَلْ عَسَيْتَ إنْ فعلتُ ذَلِكَ بِكَ أَنْ تَسْألَ غَيْرَه؟ فَيَقُولُ: لاَ أَسْأَلُكَ غَيْرَهُ، وَيُعْطِي ربَّه مِنْ عُهُودٍ وَمَوَاثِيقَ مَا شَاءَ اللَّهُ، فَيَصْرِفُ اللَّهُ وَجْهَه عَنِ النَّار، فَإِذَا أَقْبَلَ عَلَى الجنَّة وَرَآهَا سكتَ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ. ثمّ يَقُولُ: أيْ ربِّ قَدِّمْني إِلَى بَابِ الْجَنَّةِ. فَيَقُولُ اللَّهُ لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ لاَ تَسْأَلَنِي غَيْرَ الَّذِي أَعْطَيْتُكَ، ويَلْك يَا ابنَ آدَمَ مَا أغْدَرَكَ! فَيَقُولُ: أيْ ربِّ وَيَدْعُو اللَّهَ حتّى يَقُولَ لَهُ: فَهلْ عَسَيْتَ إنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَ غيْرَه؟ فَيَقُولُ: لاَ وعِزَّتِك فيعطي ربَّه مَا شَاءَ اللَّهُ مِنْ عُهُودٍ وَمَوَاثِيقَ فيقدِّمُه إِلَى بَابِ الْجَنَّةِ، فَإِذَا قَامَ عَلَى بَابِ الجنَّة انْفَهَقَتْ لَهُ الجنَّةُ، فَرَأَى مَا فِيهَا مِنَ الْخَيْرِ وَالسُّرُورِ، فَيَسْكُتُ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ، ثُمَّ يَقُولُ: أَيْ ربِّ أَدْخِلني الجنَّةَ. فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ أَنْ لاَ تَسْأَلَ غَيْرَ مَا أُعْطِيتَ؟! وَيْلَكَ يَا ابْنَ آدَمَ مَا أَغْدَرَكَ! فَيَقُولُ: أيْ ربَّ لاَ أكون أَشْقَى خَلْقِك، فَلاَ يَزَالُ يَدْعُو اللَّهَ حتّى يضْحَكَ اللَّهُ تَبَارَكَ وَتَعَالَى مِنْهُ فَإِذَا ضَحِكَ اللَّهُ مِنْهُ. قَالَ: ادْخُل الجنَّة، فَإِذَا دَخَلَهَا قَالَ اللَّهُ لَهُ: تَمَنَّهْ فيسأل ربَّه ويتمَنّى، حتّى إنَّ اللَّهَ ليُذَكِّرُه مِنْ كَذَا وَكَذَا، حتَّى إِذَا انْقَطَعَتْ بِهِ الأَمَانِيُّ. قَالَ اللَّهُ تَعَالَى: ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ.","قَالَ عَطَاءُ بْنُ يَزِيدَ: وَأَبُو سَعِيدٍ الْخُدْرِيُّ مَعَ أَبِي هُرَيْرَةَ لَا يَرُدُّ عَلَيْهِ مِنْ حَدِيثِهِ شَيْئًا حَتَّى إِذَا حَدَّثَ أَبُو هُرَيْرَةَ: أَنَّ اللهَ قَالَ لِذَلِكَ الرَّجُلِ: وَمِثْلُهُ مَعَهُ. قَالَ أَبُو سَعِيدٍ: وَعَشَرَةُ أَمْثَالِهِ مَعَهُ يَا أَبَا هُرَيْرَةَ. قَالَ أَبُو هُرَيْرَةَ: مَا حَفِظْتُ إِلَّا قَوْلَهُ ذَلِكَ: ذلك لَكَ وَمِثْلُهُ مَعَهُ. قَالَ أَبُو سَعِيدٍ: أَشْهَدُ أَنِّي حَفِظْتُ مِنْ رَسُولِ اللهِ  صلى الله عليه وسلمقوله ذلك: ذَلِكَ لَكَ وَعَشَرَةُ أَمْثَالِهِ. قَالَ أَبُو هُرَيْرَةَ: وَذَلِكَ الرَّجُلُ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7437)، ومسلم في الإيمان (182) كلاهما من حديث إبراهيم بن سعد، عن ابن شهاب، عن عطاء بن يزيد اللّيثيّ، فذكره.","grade":"متفق عليه","chapter_ar":"باب جامع في ذكر عدد من مشاهد يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7437) and Muslim (182).","chapter_en":"A Comprehensive Chapter Mentioning a Number of the Scenes of the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":51,"content":{"translation":{"en":["ʿAṭāʾ ibn Yazīd al-Laythī narrated that Abū Hurayrah informed him that some people asked the Messenger of Allah ﷺ: “O Messenger of Allah, will we see our Lord on the Day of Resurrection?” The Messenger of Allah ﷺ said: “Do you have any difficulty seeing the full moon?” They replied: “No, O Messenger of Allah.” He asked: “Do you have any difficulty seeing the sun when there is no cloud before it?” They replied: “No, O Messenger of Allah.” He said: “You will see Him in the same way. Allah will gather the people on the Day of Resurrection and say: ‘Whoever used to worship something, let him follow it.’ Those who worshipped the sun will follow the sun, those who worshipped the moon will follow the moon, and those who worshipped false deities will follow those false deities. This Ummah will remain, including its hypocrites. Then Allah, Blessed and Exalted, will come to them in a form other than the form they recognize. He will say: ‘I am your Lord.’ They will say: ‘We seek refuge in Allah from you! We will remain here until our Lord comes to us. When our Lord comes, we will recognize Him.’ Then Allah, the Exalted, will come to them in the form they recognize and say: ‘I am your Lord.’ They will reply: ‘You are our Lord,’ and they will follow Him. Then the Ṣirāṭ will be placed across the middle of Hell. I and my Ummah will be the first to cross it. No one will speak on that Day except the Messengers, and the supplication of the Messengers on that Day will be: ‘O Allah, grant safety! Grant safety!’ In Hell there will be hooks like the thorns of al-Saʿdān. Have you seen al-Saʿdān?” They replied: “Yes, O Messenger of Allah.” He said: “They are like the thorns of al-Saʿdān, except that no one knows the enormity of their size except Allah. They will seize people according to their deeds. Among them will be the believer who remains safe because of his deeds, and among them will be one who is punished until he is eventually saved. When Allah has finished judging between the servants and wishes by His mercy to bring out from the Fire whomever He wills, He will command the angels to bring out of the Fire those whom He wishes to have mercy upon among those who did not associate anything with Allah and who used to say: ‘There is no deity except Allah.’ The angels will recognize them in the Fire by the marks of prostration. The Fire consumes every part of the son of Ādam except the marks of prostration; Allah has forbidden the Fire from consuming the marks of prostration. They will be brought out of the Fire completely charred, and the Water of Life will be poured over them. They will grow beneath it just as a seed grows in the silt carried by a flood. Then Allah, the Exalted, will finish judging between the servants, and one man will remain with his face turned toward the Fire. He will be the last of the people of Paradise to enter Paradise. He will say: ‘My Lord, turn my face away from the Fire, for its wind has poisoned me and its blaze has burned me.’ He will continue supplicating to Allah for as long as Allah wills. Then Allah, Blessed and Exalted, will say: ‘If I do that for you, perhaps you will ask Me for something else?’ He will reply: ‘I will ask You for nothing else,’ and he will give his Lord whatever pledges and covenants Allah wills. So Allah will turn his face away from the Fire. When he faces Paradise and sees it, he will remain silent for as long as Allah wills. Then he will say: ‘My Lord, bring me nearer to the gate of Paradise.’ Allah will say to him: ‘Did you not give Me your pledges and covenants that you would ask for nothing beyond what I gave you? Woe to you, son of Ādam! How treacherous you are!’ He will say: ‘My Lord…’ and continue supplicating until Allah says to him: ‘If I give you that, perhaps you will ask for something else?’ He will say: ‘No, by Your Might.’ He will give his Lord whatever pledges and covenants Allah wills, so Allah will bring him to the gate of Paradise. When he stands at the gate of Paradise, Paradise will open wide before him and he will see the goodness and joy within it. He will remain silent for as long as Allah wills. Then he will say: ‘My Lord, admit me into Paradise.’ Allah, Blessed and Exalted, will say: ‘Did you not give Me your pledges and covenants that you would ask for nothing beyond what I gave you? Woe to you, son of Ādam! How treacherous you are!’ He will say: ‘My Lord, do not make me the most miserable of Your creation.’ He will continue supplicating to Allah until Allah, Blessed and Exalted, laughs at him. When Allah laughs at him, He will say: ‘Enter Paradise.’ When he enters it, Allah will say to him: ‘Wish.’ He will ask his Lord and continue wishing, and Allah will remind him to ask for such-and-such, until all his wishes are exhausted. Then Allah, the Exalted, will say: ‘All of that is yours, and the like of it with it.’” ʿAṭāʾ ibn Yazīd said: Abū Saʿīd al-Khudrī was present with Abū Hurayrah and did not object to anything in his narration until Abū Hurayrah narrated that Allah said to the man: “And the like of it with it.”","Then Abū Saʿīd said: “And ten times the like of it with it, O Abū Hurayrah.” Abū Hurayrah replied: “I only memorized the wording: ‘That is yours, and the like of it with it.’” Abū Saʿīd said: “I testify that I memorized from the Messenger of Allah ﷺ the wording: ‘That is yours, and ten times the like of it with it.’” Abū Hurayrah said: “That man is the last of the people of Paradise to enter Paradise.”"]},"buhuth":{"ar":["قوله: تبقى هذه الأمة فيها منافقوها أي يبقى المنافقون مع المؤمنين كما كانوا في الدنيا متسترين معهم.","وقوله: فيأتيهم الله في صورة غير صورته التي يعرفون أي بصورة المخلوق، وقد علموا من قوله تعالى:","﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾ [الشورى: ١١]","أي أنه منزه عن صفات هذه الصورة.","وقوله: فيأتيهم اللّه في صورته التي يعرفون فقال المؤمنون: أنت ربنا فيتبعونه.","وأما المنافقون: فيضرب الصراط بين ظهري جهنم فيبقى المنافقون وراء الصراط، ولا يرون اللّٰه تعالى لأن نور المؤمنين قد حجب عنهم.","وقوله: فأكون أنا وأمتي أول من يجيز أي بدون المنافقين لأنهم قد وقعوا في قعر جهنم كما قال تعالى:","﴿إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ﴾ [النساء: ١٤٥].","وبهذا يحرم المنافقون من رؤية اللّٰه تعالى إلى الأبد كما هو مذهب أهل السنة والجماعة."],"en":["Regarding the statement:","“This Ummah will remain, including its hypocrites,”","the author explains that the hypocrites will remain among the believers, just as they concealed themselves among them in this world.","Regarding the statement:","“Allah will come to them in a form other than the form they recognize,”","the author explains this as a form resembling that of created beings, while they know from the statement of Allah:","“There is nothing like Him, and He is the All-Hearing, the All-Seeing.”","[al-Shūrā 42:11]","that Allah is exalted above the attributes of such a form.","Regarding the statement:","“Then Allah will come to them in the form they recognize,”","the believers will say:","“You are our Lord,”","and they will follow Him.","As for the hypocrites, when the Ṣirāṭ is placed across Hell, they will remain behind the Ṣirāṭ and will not see Allah, the Exalted, because the light of the believers will have been withheld from them.","Regarding the statement:","“I and my Ummah will be the first to cross,”","the author explains that this does not include the hypocrites, because they will have fallen into the lowest depth of Hell, as Allah, the Exalted, says:","“Indeed, the hypocrites will be in the lowest depth of the Fire.”","[al-Nisāʾ 4:145]","Accordingly, the author says that the hypocrites will be permanently deprived of seeing Allah, the Exalted, as held by Ahl al-Sunnah wa-l-Jamāʿah."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7437)، ومسلم (182)."},{"num":16253,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فِي صَعِيدٍ وَاحِدٍ، ثُمَّ يَطَّلِعُ عَلَيْهِمْ رَبُّ الْعَالَمِينَ فَيَقُولُ: أَلاَ يَتْبَعُ كُلُّ إِنْسَانٍ مَا كَانُوا يَعْبُدُونَهُ. فَيُمَثَّلُ لِصَاحِبِ الصَّلِيبِ صَلِيبُهُ، وَلِصَاحِبِ التَّصَاوِيرِ تَصَاوِيرُهُ، وَلِصَاحِبِ النَّارِ نَارُهُ، فَيَتْبَعُونَ مَا كَانُوا يَعْبُدُونَ، وَيَبْقَى الْمُسْلِمُونَ فَيَطَّلِعُ عَلَيْهِمْ رَبُّ الْعَالَمِينَ فَيَقُولُ: أَلاَ تَتَّبِعُونَ النَّاسَ؟ فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ، نَعُوذُ بِاللَّهِ مِنْكَ، اللَّهُ رَبُّنَا، هَذَا مَكَانُنَا حَتَّى نَرَى رَبَّنَا. وَهُوَ يَأْمُرُهُمْ وَيُثَبِّتُهُمْ، ثُمَّ يَتَوَارَى ثُمَّ يَطَّلِعُ فَيَقُولُ: أَلاَ تَتَّبِعُونَ النَّاسَ؟ فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ، نَعُوذُ بِاللَّهِ مِنْكَ، اللَّهُ رَبُّنَا، وَهَذَا مَكَانُنَا حَتَّى نَرَى رَبَّنَا. وَهُوَ يَأْمُرُهُمْ وَيُثَبِّتُهُمْ. قَالُوا: وَهَلْ نَرَاهُ يَا رَسُولَ اللَّهِ؟ قَالَ: وَهَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ. قَالُوا: لاَ يَا رَسُولَ اللَّهِ. قَالَ: فَإِنَّكُمْ لاَ تُضَارُّونَ فِي رُؤْيَتِهِ تِلْكَ السَّاعَةَ. ثُمَّ يَتَوَارَى، ثُمَّ يَطَّلِعُ فَيُعَرِّفُهُمْ نَفْسَهُ، ثُمَّ يَقُولُ: أَنَا رَبُّكُمْ فَاتَّبِعُونِي. فَيَقُومُ الْمُسْلِمُونَ، وَيُوضَعُ الصِّرَاطُ فَيَمُرُّونَ عَلَيْهِ مِثْلَ جِيَادِ الْخَيْلِ وَالرِّكَابِ وَقَوْلُهُمْ عَلَيْهِ: سَلِّمْ سَلِّمْ. وَيَبْقَى أَهْلُ النَّارِ فَيُطْرَحُ مِنْهُمْ فِيهَا فَوْجٌ ثُمَّ يُقَالُ هَلِ امْتَلأْتِ؟ فَتَقُولُ: هَلْ مِنْ مَزِيدٍ. ثُمَّ يُطْرَحُ فِيهَا فَوْجٌ، فَيُقَالُ: هَلِ امْتَلأْتِ. فَتَقُولُ: هَلْ مِنْ مَزِيدٍ. حَتَّى إِذَا أُوعِبُوا فِيهَا وَضَعَ الرَّحْمَنُ قَدَمَهُ فِيهَا، وَأُزْوِيَ بَعْضُهَا إِلَى بَعْضٍ، ثُمَّ قَالَ: قَطْ، قَالَتْ: قَطْ قَطْ، فَإِذَا أَدْخَلَ اللَّهُ أَهْلَ الْجَنَّةِ الْجَنَّةَ وَأَهْلَ النَّارِ النَّارَ، قَالَ: أُتِيَ بِالْمَوْتِ مُلَبَّبًا فَيُوقَفُ عَلَى السُّورِ الَّذِي بَيْنَ أَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ، ثُمَّ يُقَالُ: يَا أَهْلَ الْجَنَّةِ. فَيَطَّلِعُونَ خَائِفِينَ، ثُمَّ يُقَالُ: يَا أَهْلَ النَّارِ. فَيَطَّلِعُونَ مُسْتَبْشِرِينَ يَرْجُونَ الشَّفَاعَةَ، فَيُقَالُ لأَهْلِ الْجَنَّةِ وَأَهْلِ النَّارِ: هَلْ تَعْرِفُونَ هَذَا؟ فَيَقُولُونَ هَؤُلاَءِ وَهَؤُلاَءِ: قَدْ عَرَفْنَاهُ، هُوَ الْمَوْتُ الَّذِي وُكِّلَ بِنَا. فَيُضْجَعُ فَيُذْبَحُ ذَبْحًا عَلَى السُّورِ الَّذِي بَيْنَ الْجَنَّةِ وَالنَّارِ، ثُمَّ يُقَالُ: يَا أَهْلَ الْجَنَّةِ خُلُودٌ لاَ مَوْتَ، وَيَا أَهْلَ النَّارِ خُلُودٌ لاَ مَوْتَ."],"takhrij":"حسن: رواه الترمذيّ (2557)، وابن خزيمة في التوحيد (150) كلاهما من طريق عبدالعزيز بن محمد الدّراورديّ، عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب جامع في ذكر عدد من مشاهد يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2557) and Ibn Khuzaymah in al-Tawḥīd (150).","chapter_en":"A Comprehensive Chapter Mentioning a Number of the Scenes of the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":51,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah will gather the people on the Day of Resurrection upon a single plain. Then the Lord of the worlds will appear to them and say: ‘Let every person follow what he used to worship.’ The cross will be represented to the one who worshipped the cross, images will be represented to the one who worshipped images, and fire will be represented to the one who worshipped fire. They will then follow what they used to worship. The Muslims will remain. Then the Lord of the worlds will appear to them and say: ‘Will you not follow the people?’ They will say: ‘We seek refuge in Allah from you! We seek refuge in Allah from you! Allah is our Lord, and this is our place until we see our Lord.’ He will command them and keep them firm. Then He will withdraw and appear again, saying: ‘Will you not follow the people?’ They will say: ‘We seek refuge in Allah from you! We seek refuge in Allah from you! Allah is our Lord, and this is our place until we see our Lord.’” They asked: “Will we see Him, O Messenger of Allah?” He replied: “Do you have difficulty seeing the full moon?” They said: “No, O Messenger of Allah.” He said: “You will likewise have no difficulty seeing Him at that time. Then He will withdraw and appear again, making Himself known to them, and say: ‘I am your Lord, so follow Me.’ The Muslims will rise, and the Ṣirāṭ will be placed. They will pass over it like fine horses and riding animals, saying while upon it: ‘Safety! Safety!’ The people of the Fire will remain, and a group of them will be thrown into it. It will be asked: ‘Are you full?’ It will reply: ‘Are there any more?’ Then another group will be thrown into it, and it will again be asked: ‘Are you full?’ It will reply: ‘Are there any more?’ When they have all been placed into it, the Most Merciful will place His Foot upon it, and its parts will contract toward one another. Then He will say: ‘Enough.’ It will say: ‘Enough! Enough!’ When Allah has admitted the people of Paradise into Paradise and the people of the Fire into the Fire, death will be brought restrained and placed upon the wall separating the people of Paradise from the people of the Fire. Then it will be said: ‘O people of Paradise!’ They will look up fearfully. Then it will be said: ‘O people of the Fire!’ They will look up joyfully, hoping for intercession. It will be said to the people of Paradise and the people of the Fire: ‘Do you recognize this?’ Both groups will say: ‘We recognize it. It is death, which had been appointed over us.’ Then it will be laid down and slaughtered upon the wall between Paradise and the Fire. Then it will be said: ‘O people of Paradise, eternity with no death! O people of the Fire, eternity with no death!’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2557)، وابن خزيمة في التوحيد (150)."},{"num":16254,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجْمَعُ اللَّهُ الْأَوَّلِينَ وَالْآخِرِينَ لِمِيقَاتِ يَوْمٍ مَعْلُومٍ قِيَامًا أَرْبَعِينَ سَنَةً شَاخِصَةً أَبْصَارُهُمْ إِلَى السَّمَاءِ يَنْتَظِرُونَ فَصْلَ الْقَضَاءِ، قَالَ: وَيَنْزِلُ اللَّهُ عَزَّ وَجَلَّ فِي ظُلَلٍ مِنَ الْغَمَامِ مِنَ الْعَرْشِ إِلَى الْكُرْسِيِّ، ثُمَّ يُنَادِي مُنَادٍ: أَيُّهَا النَّاسُ أَلَمْ ترضوا من رَبِّكُمُ الَّذِي خَلَقَكُمْ وَرَزَقَكُمْ وَأَمَرَكُمْ أَنْ تَعْبُدُوهُ وَلَا تُشْرِكُوا بِهِ شَيْئًا أَنْ يُوَلِّيَ كُلَّ ناس مِنْكُمْ مَا كَانُوا يتولون ويعبدون فِي الدِّينِ؟ أَلَيْسَ ذَلِكَ عَدْلًا مِنْ رَبِّكُمْ؟ قَالُوا: بَلَى. قَالَ: فلينطلق كلُّ قومٍ إِلَى مَا كَانُوا يَعْبُدُونَ فِي الدُّنْيَا. قَالَ: فَيَنْطَلِقُونَ، وَيُمَثَّلُ لَهُمْ أَشْيَاءَ مَا كَانُوا يَعْبُدُونَ؛ فَمِنْهُمْ مَنْ يَنْطَلِقُ إِلَى الشَّمْسِ، وَمِنْهُمْ مَنْ يَنْطَلِقُ إِلَى الْقَمَرِ، وَإِلَى الْأَوْثَانِ مِنَ الْحِجَارَةِ، وَأشْبَاهِ مَا كَانُوا يَعْبُدونَ. قَالَ: ويُمثَّل لِمَنْ كَانَ يَعْبُدُ عِيسَى شَيْطَانُ عِيسَى، ويُمثّل لِمَنْ كَانَ يَعْبُدُ عزيراً شَيْطَانُ عُزَيْرٍ، وَيَبْقَى مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وأمّتُه. قَالَ: فيتمثل الرَّبُّ عَزَّ وَجَلَّ فَيَأْتِيهِمُ فَيَقُولُ: مَا لَكُمْ لَا تنطلقون كَمَا انْطَلَقَ النَّاسُ؟ قَالَ: فَيَقُولُونَ: إِنَّ لَنَا لإلهاً مَا رَأَيْنَاهُ بعدُ. فَيَقُولُ: هَلْ تَعْرِفُونَهُ إِنْ رَأَيْتُمُوهُ؟ فَيَقُولُونَ: إنّ بَيْنَنَا وَبَيْنَهُ عَلَامَةٌ إِذَا رأيناها عرفناها؟ قَالَ: فَيَقُولُ: مَا هِيَ؟ فَيَقُولُونَ: يكشف عَنْ سَاقِهِ. قَالَ: فَعِنْدَ ذَلِكَ يكشف عَنْ سَاقٍ، فيخرُّ كلُّ مَنْ كَانَ بظهره طَبَقٌ، وَيَبْقَى قَوْمٌ ظُهُورُهُمْ كَصَيَاصِي الْبَقَرِ يُرِيدُونَ السُّجُودَ فلايستطيعون، وَقَدْ كَانَ يُدْعَوْنَ إِلَى السُّجُودِ وَهُمْ سَالِمُونَ، ثُمَّ يَقُولُ: ارْفَعُوا رؤوسكم، فيرفعون رؤوسهم، فَيُعْطِيهِمْ نُورَهُمْ عَلَى قَدْرِ أَعْمَالِهِمْ، فَمِنْهُمْ مَنْ يُعْطَى نُورَهُ مِثْلَ الْجَبَلِ الْعَظِيمِ يَسْعَى بَيْنَ يَدَيْهِ، وَمِنْهُمْ مَنْ يُعْطَى نُورَهُ أَصْغَرَ مِنْ ذَلِكَ، وَمِنْهُمْ مَنْ يُعْطَى نُورًا مِثْلَ النَّخْلَةِ بِيَمِينِهِ، وَمِنْهُمْ مَنْ يُعْطَى نُورًا أَصْغَرَ مِنْ ذَلِكَ، حَتَّى يَكُونَ آخِرُهُمْ رَجُلًا يُعْطَى نُورَهُ عَلَى إِبْهَامِ قَدَمِهِ يُضِيءُ مَرَّةً وَيُطْفِئُ مَرَّةً، فَإِذَا أضاء قدّم قَدَمِهِ فَمَشَى، وَإِذَا طفئ قَامَ. قَالَ: والربُّ عَزَّ وَجَلَّ أَمَامَهُمْ حَتَّى يَمُرَّ فِي النَّارِ فَيَبْقَى أَثَرُهُ كَحَدِّ السَّيْفِ دَحْضَ مَزِلَّةٍ. قَالَ: وَيَقُولُ: مُرُّوا، فيمرون عَلَى قَدْرِ نُورَهُمْ، مِنْهُمْ من يمر كطرف الْعَيْنِ، وَمِنْهُمْ مَنْ يَمُرُّ كَالْبَرْقِ، وَمِنْهُمْ مَنْ يَمُرُّ كالسحاب، وَمِنْهُمْ مَنْ يمر كَانْقِضَاضِ الكوكب، وَمِنْهُمْ مَنْ يمرُّ كَالرِّيحِ، وَمِنْهُمْ مَنْ يمرُّ كشدّ الْفَرَسِ، وَمِنْهُمْ مَنْ يمرّ كشدّ الرَّجُلِ، حَتَّى يَمُرَّ الَّذِي أعطي نُورَهُ عَلَى إِبْهَامِ قَدَمَيْهِ يَحْبُو عَلَى وَجْهِهِ وَيَدَيْهِ وَرِجْلَيْهِ، تخرّ يد وتعلق يد، تخرّ رَجُلٌ وتعلق رَجُلٌ، ويصيب جوانبه النَّارِ، فَلَا يَزَالُ كَذَلِكَ حَتَّى يَخْلُصَ، فَإِذَا خَلَصَ وَقَفَ عَلَيْهَا، ثُمَّ قَالَ: الْحَمْدُ لله لَقَدْ أعطاني اللَّهُ مَا لَمْ يُعْطِ أَحَدًا أَنْ نَجَّانِي مِنْهَا بَعْدَ إِذْ رَأَيْتُهَا. قَالَ: فَيُنْطَلَقُ بِهِ إِلَى غَدِيرٍ عِنْدَ بَابِ الْجَنَّةِ، فيغتسل، فَيَعُودُ إِلَيْهِ رِيحُ أَهْلِ الْجَنَّةِ وَأَلْوَانُهُمْ، فَيَرَى مَا فِي الْجَنَّةِ مِنْ خِلَالِ الْبَابِ، فَيَقُولُ: ربِّ أَدْخِلْنِي الْجَنَّةَ. فَيَقُولُ اللَّهُ لَهُ: أَتَسْأَلُ الْجَنَّةَ وَقَدْ نَجَّيْتُكَ مِنَ النَّارِ؟ فَيَقُولُ: ربّ اجْعَلْ بَيْنِي وَبَيْنَهَا حِجَابًا لَا أَسْمَعُ حَسِيسَهَا. قَالَ: فَيَدْخُلُ الْجَنَّةَ. قَالَ: فَيَرَى أَوْ يُرْفَعُ لَهُ منزلاً أَمَامَ ذَلِكَ كَأَنَّمَا هُوَ فِيهِ إِلَيْهِ حُلْمٌ. فَيَقُولُ: ربّ أَعْطِنِي ذَلِكَ الْمَنْزِلَ. فَيَقُولُ لَهُ: فَلَعَلَّكَ إِنْ أعطيتكه تَسْأَلُ غيره؟ فَيَقُولُ: لَا وعزّتِك لَا أَسْأَلُكَ غَيْرَهُ، وأيُّ مَنْزِلٍ يَكُونُ أَحْسَنَ مِنْهُ؟ فيعطيه فَيَنْزِلُهُ، وَيَرَى أَمَامَ ذَلِكَ منـزلاً كَأَنَّمَا هُوَ فِيهِ إِلَيْهِ حُلْمٌ، قَالَ: رَبِّ أَعْطِنِي ذَلِكَ الْمَنْزِلَ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُ: فَلَعَلَّكَ إن أعطيتكه تَسْأَلُ غَيْرَهُ، فَيَقُولُ: لَا وَعِزَّتِكَ لَا أَسْأَلُكَ غَيْرَهُ، وَأَيُّ مَنْزِلٍ يَكُونُ أَحْسَنَ مِنْهُ، قَالَ: فيعطى منزله، قَالَ: وَيَرَى أَوْ يُرْفَعُ لَهُ أَمَامَ ذَلِكَ منزل آخر كَأَنَّمَا هُوَ إِلَيْهِ حُلْمٌ، فَيَقُولُ: أَعْطِنِي ذَلِكَ الْمَنْزِلَ. فَيَقُولُ اللَّهُ جَلَّ جلاله: فَلَعَلَّكَ إنْ أعطيتُكَهُ تَسْأَلُ غَيْرَهُ؟ قَالَ: لَا وعزّتِك لَا أَسْأَلُكَ غَيْرَهُ، وأيُّ مَنْزِلٍ يَكُونُ أَحْسَنَ مِنْهُ. قَالَ: فَيُعْطَاهُ فَيَنْزِلُهُ، ثُمَّ يَسْكُتُ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: مَا لَكَ لَا تَسْأَلُ؟ فَيَقُولُ: ربّ لَقَدْ سَأَلْتُكَ حَتَّى اسْتَحْيَيْتُكَ، وَأَقْسَمْتُ لَكَ حَتَّى اسْتَحْيَيْتُكَ. فَيَقُولُ اللَّهُ تَعَالَى: أَلَمْ ترضَ أَنْ أُعْطِيَكَ مِثْلَ الدُّنْيَا مُنْذُ خَلَقْتُهَا إِلَى يَوْمِ أَفْنَيْتُهَا وَعَشَرَةَ أضعافه؟ فَيَقُولُ: أتستهزئ بِي وَأَنْتَ ربُّ العِزّة، فَيَضْحَكُ الرّبُّ عزّ وجلّ مِنْ قَوْلِهِ.","قَالَ: فَرَأَيْتُ عبدالله بْنَ مَسْعُودٍ إِذَا بَلَغَ هَذَا الْمَكَانَ مِنْ هَذَا الْحَدِيثِ ضَحِكَ. فَقَالَ لَهُ رَجُلٌ: يَا أَبَا عَبْدِ الرَّحْمَنِ قَدْ سَمِعْتُكَ تُحَدِّثُ هَذَا الْحَدِيثَ مِرَارًا، كُلَّمَا بَلَغْتَ هَذَا الْمَكَانَ ضَحِكْتَ ؟ - فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يُحَدِّثُ هَذَا الْحَدِيثَ مِرَارًا، كُلَّمَا بَلَغَ هَذَا الْمَكَانَ مِنْ هَذَا الْحَدِيثِ ضَحِكَ حَتَّى تَبْدُوَ أَضْرَاسُهُ.","قَالَ: فَيَقُولُ الرَّبُّ عَزَّ وَجَلَّ: لاَ، وَلَكِنِّى عَلَى ذَلِكَ قَادِرٌ سَلْ، فَيَقُولُ: أَلْحِقْنِى بِالنَّاسِ، فَيَقُولُ: الْحَقُّ النّاس. قَالَ: فَيَنْطَلِقُ يَرْمُلُ فِى الْجَنَّةِ حَتَّى إِذَا دَنَا مِنَ النَّاسِ، رُفِعَ لَهُ قَصْرٌ مِنْ دَرَّةٍ فَيَخِرُّ سَاجِدًا. فيقال لَهُ: ارْفَعْ رَأْسَكَ، مَالَكَ؟ فَيَقُولُ: رَأَيْتُ رَبِّى أَوْ تراءى لِى رَبِّى! فَيُقَالُ لَهُ: إِنَّمَا هو مَنْزِلٌ مِنْ مَنَازِلِكَ. قَالَ: ثُمَّ يَلْقَى رَجُلًا فَيَتَهَيَّأُ للسجود له، فَيُقَالُ لَهُ: مَهْ مَالِكٌ؟ فَيَقُولُ: رَأَيْتُ أَنَّكَ مَلَكٌ مِنَ الْمَلائِكَةِ، فَيَقُولُ: إِنَّمَا أَنَا خَازِنٌ مِنْ خِزَّانِكَ، عَبْدٌ مِنْ عَبِيدِكَ، تَحْتَ يَدَى أَلْفُ قَهْرَمَانَ عَلَى مِثْلِ مَا أنا عَلَيْهِ. قَالَ: فَيَنْطَلِقُ أَمَامُهُ حَتَّى يَفْتَحَ لَهُ الْقَصْرُ. قَالَ: وَهُوَ في دُرَّةٌ مُجَوَّفَةٌ سَقَائِفُهَا وَأَبْوَابُهَا وَأَغْلاقُهَا ومفاتيحها مِنْهَا تستقبله جوهرة، جَوْهَرَةٌ خَضْرَاءُ مُبَطَّنَةٌ بحمراء، كُلُّ جَوْهَرَةٍ تُفْضَى إِلَى جَوْهَرَةٍ عَلَى غَيْرِ لَوْنِ الأُخْرَى، فِى كُلِّ جَوْهَرَةٍ سُرْرٌ وَأَزْوَاجٌ وَوَصَائِفُ أدناهن حوراء عيناء عَلَيْهَا سَبْعُونَ حُلَّةً، يَرَى مُخَّ سَاقِهَا مِنْ وَرَاءِ حللها، كَبِدُهَا مَرْآتُهُ وَكَبِدَهُ مَرَّاتِهَا، إِذَا أَعْرَضَ عَنْهَا إِعْرَاضَةً ازْدَادَتْ فِى عَيْنِهِ سَبْعِينَ ضِعْفًا عَمَّا كانت قَبْلَ ذَلِكَ، وَإِذَا أَعْرَضْتَ عَنْهُ إِعْرَاضَةٌ ازْدَادَ فِى عَيْنِهَا سَبْعِينَ ضِعْفًا عَمَّا كَانَ قَبْلَ ذَلِكَ. فَيَقُولُ لَهَا: وَاللَّهِ لَقَدِ ازْدَدْتُ فِى عَيْنِى سَبْعِينَ ضَعْفًا! وتقول له: وَأَنْتَ وَاللَّهِ لَقَدِ ازْدَدْتُ فِى عَيْنِى سَبْعِينَ ضَعْفًا! فَيُقَالُ لَهُ: أَشْرِفُ. قَالَ: فيُشْرِفُ، فيقال لَهُ: مَلِكُكَ مَسِيرَةُ مِائَةِ عَامٍ ينفذه بصره.","قَالَ: فَقَالَ عُمَرُ: أَلَا تَسْمَعُ مَا يُحَدِّثُنَا ابْنُ أُمِّ عَبْدٍ يَا كَعْبُ عَنْ أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلًا، فَكَيْفَ أَعْلَاهُمْ؟ فَقَالَ كَعْبٌ: يَا أَمِيرَ الْمُؤْمِنِينَ، مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ، إِنَّ اللهَ عز وجل جَعَلَ دَارًا، فَجَعَلَ فِيهَا مَا شَاءَ مِنَ الْأَزْوَاجِ وَالثَّمَرَاتِ وَالْأَشْرِبَةِ، ثُمَّ أَطْبَقَهَا، ثُمَّ لَمْ يَرَهَا أَحَدٌ مِنَ خَلْقِهِ لَا جِبْرِيلُ وَلَا غَيْرُهُ مِنَ الْمَلَائِكَةِ، ثُمَّ قَرَأَ كَعْبٌ: ﴿فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيَنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ﴾ [سورة السجدة: 17]17] ","قَالَ: وَخَلَقَ دُونَ ذَلِكَ جَنَّتَيْنِ وزينهما بِمَا شَاءَ، وَأَرَاهُمَا مَنْ شَاءَ مِنْ خَلْقِهِ. ثُمَّ قَالَ: مَنْ كَانَ كِتَابُهُ فِي عِلِّيِّينَ نَزَلَ تِلْكَ الدَّارَ الَّتِي لَمْ يَرَهَا أَحَدٌ، حَتَّى إِنَّ الرَّجُلَ مِنْ أَهْلِ عِلِّيِّينَ لِيَخْرُجُ فَيَسِيرُ فِي مُلْكِهِ، فَمَا تَبْقَى خَيْمَةٌ مِنْ خيم الْجَنَّةِ إِلَّا دَخَلَهَا مِنْ ضَوْءِ وَجْهِهِ فيستبشرون بِرِيحِهِ، فيقولون: وَاهًا لهذا الرِّيحِ! هذا رجل مِنْ أَهْلِ عِلِّيِّينَ قَدْ خَرَجَ يَسِيرُ فِي مُلْكِهِ فَقَالَ: وَيْحَكَ يَا كَعْبُ! إِنَّ هَذِهِ الْقُلُوبَ قَدِ اسْتَرْسَلَتْ واقبضها. فَقَالَ كَعْبٌ: وَالَّذِي نَفْسِي بِيَدِهِ إِنَّ لِجَهَنَّمَ يَوْمَ الْقِيَامَةِ لَزَفْرَةً مَا مِنْ مَلَكٍ مُقَرَّبٍ وَلَا نَبِيٍّ مُرْسَلٍ إِلَّا يَخِرُّ لِرُكْبَتَيْهِ حَتَّى إِنَّ إِبْرَاهِيمَ خَلِيلَ الله لَيَقُولُ: رَبِّ نَفْسِي نَفْسِي، حَتَّى لَوْ كَانَ لَكَ عَمَلُ سَبْعِينَ نَبِيًّا إِلَى عَمَلِكَ لَظَنَنْتُ أَنَّكَ لا تَنْجُوَ."],"takhrij":"حسن: رواه محمد بن نصر المروزي في تعظيم قدر الصلاة (278)، وعبد الله بن أحمد في السنة (1203)، الطبرانيّ في الكبير (9763)، والدارقطني في الرؤية (161)، وابن منده في التوحيد (531)، وصحّحه الحاكم (4/589-592) من طريقين عن المنهال بن عمرو، عن أبي عبيدة بن عبد الله، عن مسروق بن الأجدع، عن عبد الله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب جامع في ذكر عدد من مشاهد يوم القيامة","chapter_ur":"","part_ar":"كتاب صفة القيامة، وأهوالها","part_ur":"","takhrij_en":"Hasan: Narrated by Muḥammad ibn Naṣr al-Marwazī in Taʿẓīm Qadr al-Ṣalāh (278), ʿAbdullāh ibn Aḥmad in al-Sunnah (1203), al-Ṭabarānī in al-Muʿjam al-Kabīr (9/416-421), al-Dāraquṭnī in al-Ruʾyah (161), Ibn Mandah in al-Tawḥīd (531), and authenticated by al-Ḥākim (4/589-592).","chapter_en":"A Comprehensive Chapter Mentioning a Number of the Scenes of the Day of Resurrection","part_en":"The Description of the Resurrection and Its Terrors","group_ar":"جموع ما جاء في صفة يوم القيامة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the Day of Judgment","part_no":66,"group_no":1,"chapter_no":51,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “Allah will gather the first and the last generations at the appointed time of a known Day. They will remain standing for forty years, their eyes fixed toward the sky, awaiting the decisive judgment. Then Allah, Mighty and Majestic, will descend in canopies of cloud from the Throne to the Kursī. A caller will proclaim: ‘O people, are you not content that your Lord—the One who created you, provided for you, and commanded you to worship Him without associating anything with Him—should place every group with whatever they used to follow and worship in the world? Is that not justice from your Lord?’ They will say: ‘Yes.’ Then every group will go toward what it used to worship in the world. Things resembling their objects of worship will be represented to them. Some will go toward the sun, some toward the moon, some toward stone idols, and others toward whatever they used to worship. For those who used to worship ʿĪsā, the devil of ʿĪsā will be represented, and for those who used to worship ʿUzayr, the devil of ʿUzayr will be represented. Muḥammad ﷺ and his Ummah will remain. Then the Lord, Mighty and Majestic, will appear to them and say: ‘Why do you not depart as the other people departed?’ They will reply: ‘We have a deity whom we have not yet seen.’ He will ask: ‘Will you recognize Him if you see Him?’ They will say: ‘There is a sign between us and Him. If we see it, we will recognize Him.’ He will ask: ‘What is it?’ They will say: ‘He will uncover His Shin.’ At that point the Shin will be uncovered. Everyone whose back had remained flexible will fall in prostration, while some people’s backs will become like the horns of cattle. They will want to prostrate but will be unable to do so, though they had previously been called to prostrate while they were sound. Then He will say: ‘Raise your heads.’ They will raise their heads, and He will give them light in proportion to their deeds. Some will be given a light like a tremendous mountain proceeding before them. Some will receive less than that. Some will be given a light like a palm tree on their right. Others will receive less than that, until the last of them will be a man whose light is upon the big toe of his foot, shining at one time and going out at another. When it shines, he will move his foot forward and walk; when it goes out, he will stop. The Lord, Mighty and Majestic, will be before them until He passes over the Fire, and His path will remain like the edge of a sword—slippery and causing feet to slip. He will say: ‘Pass over.’ They will cross according to the amount of their light. Some will pass like the blink of an eye, some like lightning, some like clouds, some like a falling star, some like the wind, some like the running of a horse, and some like the running of a man. Eventually the man whose light is only on the big toes of his feet will cross crawling upon his face, hands, and feet. One hand will slip while the other clings; one foot will slip while the other clings. The Fire will strike his sides. He will remain like this until he is finally delivered. When he is delivered, he will stand over it and say: ‘All praise belongs to Allah! Allah has given me something He has given no one else—He saved me from it after I had seen it.’ He will then be taken to a pool near the gate of Paradise and bathe in it. The fragrance and complexion of the people of Paradise will return to him. Through the gate he will see what is inside Paradise and say: ‘My Lord, admit me into Paradise.’ Allah will say to him: ‘You ask for Paradise after I have saved you from the Fire?’ He will say: ‘My Lord, place a barrier between me and it so that I no longer hear its sound.’ Then he will enter Paradise. A dwelling will be shown to him beyond that, appearing so wonderful that what he already has seems like a dream beside it. He will say: ‘My Lord, give me that dwelling.’ Allah will say: ‘Perhaps if I give it to you, you will ask for another?’ He will reply: ‘No, by Your Might. I will ask for nothing else. What dwelling could be better than it?’ So Allah will give it to him and settle him there. Then another dwelling beyond it will be shown to him, and what he has will seem like a dream beside it. He will say: ‘My Lord, give me that dwelling.’ Allah, Mighty and Majestic, will say: ‘Perhaps if I give it to you, you will ask for another?’ He will say: ‘No, by Your Might. I will ask for nothing else. What dwelling could be better than it?’ So it will be given to him. Then another dwelling beyond that will be shown to him, and he will ask for it as before. It will be given to him and he will settle there. Then he will become silent. Allah, Mighty and Majestic, will say: ‘Why do you not ask?’ He will say: ‘My Lord, I have asked You until I became ashamed before You. I have sworn to You until I became ashamed before You.’ Allah, the Exalted, will say: ‘Would you be satisfied if I gave you the equivalent of the world from the day I created it until the day I destroy it, and ten times as much?’ He will say: ‘Are You mocking me while You are the Lord of Might?’ The Lord, Mighty and Majestic, will laugh at his statement.” The narrator said: I saw ʿAbdullāh ibn Masʿūd laugh whenever he reached this part of the hadith. A man asked him: “O Abū ʿAbd al-Raḥmān, I have heard you narrate this hadith many times, and every time you reach this point you laugh. Why?” He replied: “I heard the Messenger of Allah ﷺ narrate this hadith many times, and whenever he reached this part, he laughed until his molar teeth became visible.” The Prophet ﷺ continued: “The Lord, Mighty and Majestic, will say: ‘No, but I am capable of that. Ask.’ The man will say: ‘Let me join the people.’","He will say: ‘Go and join the people.’ The man will run through Paradise until, when he approaches the people, a palace made of a single pearl will be raised before him, and he will fall in prostration. It will be said to him: ‘Raise your head. What is wrong with you?’ He will say: ‘I saw my Lord—or my Lord appeared to me!’ It will be said: ‘That is only one of your dwellings.’ Then he will meet a man and prepare to prostrate to him. It will be said to him: ‘Stop! What are you doing?’","He will say: ‘I thought you were an angel.’ The man will reply: ‘I am only one of your treasurers, one of your servants. Under my authority are one thousand managers like me.’ He will go ahead of him and open the palace for him. The palace will be inside a hollow pearl; its roofs, doors, locks, and keys will all be made from it. A green jewel lined with red will face him, and each jewel will lead into another jewel of a different color. In every jewel will be couches, wives, and maidservants. The least of them will be a wide-eyed ḥūrī wearing seventy garments, yet the marrow of her shin will be visible through her garments. Her inner beauty will reflect him like a mirror, and his will reflect her. Whenever he turns away from her and then looks back, she will have increased seventyfold in beauty in his eyes compared with before. And whenever she turns away from him and then looks back, he will have increased seventyfold in beauty in her eyes. He will say to her: ‘By Allah, you have increased seventyfold in beauty in my eyes!’ She will say: ‘And by Allah, you too have increased seventyfold in beauty in my eyes!’ Then it will be said to him: ‘Look out over your kingdom.’ He will look out, and it will be said: ‘Your kingdom extends a journey of one hundred years, all of which your sight can encompass.’” The narrator continued: ʿUmar said: “O Kaʿb, do you not hear what Ibn Umm ʿAbd is telling us concerning the lowest-ranking person in Paradise? Then what about the highest-ranking among them?”","Kaʿb replied: “O Commander of the Believers, it is what no eye has seen and no ear has heard. Allah, Mighty and Majestic, created a dwelling and placed in it whatever He willed of spouses, fruits, and drinks. Then He sealed it, and no one from His creation has ever seen it—not Jibrīl nor any other angel.” Then Kaʿb recited: “No soul knows what comfort of the eyes has been hidden for them as a reward for what they used to do.” [al-Sajdah 32:17] He continued: “Below that, Allah created two Gardens and adorned them with whatever He willed, and He showed them to whomever He willed among His creation.","Whoever has his record in ʿIlliyyīn will enter that dwelling which no one has seen. A man from the people of ʿIlliyyīn will go out walking through his kingdom, and no tent among the tents of Paradise will remain except that light from his face enters it. Its inhabitants will rejoice at his fragrance and say: ‘How wonderful this fragrance is! A man from the people of ʿIlliyyīn has gone out walking through his kingdom.’” Then someone said: “Woe to you, O Kaʿb! These hearts have become carried away, so restrain them.” Kaʿb replied: “By the One in whose hand is my soul, Hell will have such a sigh on the Day of Resurrection that no angel brought near and no Messenger sent will remain except that he will fall to his knees. Even Ibrāhīm, the intimate friend of Allah, will say: ‘My Lord, myself! Myself!’ Even if you possessed deeds equal to the deeds of seventy Prophets in addition to your own deeds, you would still think that you might not be saved.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه محمد بن نصر المروزي في تعظيم قدر الصلاة (278)، وعبد الله بن أحمد في السنة (1203)، والطبراني في الكبير (9723)، والدارقطني في الرؤية (161)، وابن منده في التوحيد (531)، وصححه الحاكم (4/589-592)."},{"num":16255,"demo":false,"sanad":"","matn":["عن أَبِي بن كَعْبٍ عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ خَافَ أَدْلَجَ، وَمَنْ أَدْلَجَ فَقَدْ بَلَغَ الْمَنْزِلَ، أَلَا إِنَّ سِلْعَةَ اللَّهِ غَالِيَةٌ! أَلَا إِنَّ سِلْعَةَ اللَّهِ الْجَنَّةُ، جَاءَتِ الرَّاجِفَةُ، تَتْبَعُهَا الرَّادِفَةُ، جَاءَ الْمَوْتُ بِمَا فِيهِ."],"takhrij":"حسن: رواه الحاكم (7852)، وأبو نعيم في الحلية (2106) كلاهما من طرق عن سفيان الثوري، عن عبد الله بن محمد بن عقيل، عن الطفيل بن أبي بن كعب، عن أبيه، قال: فذكره.","grade":"حسن","chapter_ar":"باب أن الجنة سلعة الله الغالية","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (4/308) and Abū Nuʿaym in al-Ḥilyah (8/377).","chapter_en":"Paradise Is the Precious Commodity of Allah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Ubayy ibn Kaʿb narrated that the Messenger of Allah ﷺ said: “Whoever fears sets out at the beginning of the night, and whoever sets out early reaches the destination. Indeed, the commodity of Allah is precious! Indeed, the commodity of Allah is Paradise. The first blast has come, followed by the second; death has come with all that it contains.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (7852)، وأبو نعيم في الحلية (2106)."},{"num":16256,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ خَافَ أَدْلَجَ، وَمَنْ أَدْلَجَ بَلَغَ الْمَنْزِلَ، أَلاَ إِنَّ سِلْعَةَ اللَّهِ غَالِيَةٌ، أَلاَ إِنَّ سِلْعَةَ اللَّهِ الْجَنَّةُ."],"takhrij":"حسن: رواه الترمذي (2450) وعبد بن حميد (1460) والحاكم (7852) كلهم من طريق أبي النضر هاشم بن القاسم، حدثنا أبو عقيل الثقفي قال: حدثنا أبو فروة يزيد بن سنان التميمي قال: حدثني بكير بن فيروز، قال: سمعت أبا هريرة، يقول: فذكره.","grade":"حسن","chapter_ar":"باب أن الجنة سلعة الله الغالية","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2450), ʿAbd ibn Ḥumayd (1460), and al-Ḥākim (4/307).","chapter_en":"Paradise Is the Precious Commodity of Allah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever fears sets out early in the night, and whoever sets out early reaches the destination. Indeed, the commodity of Allah is precious. Indeed, the commodity of Allah is Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2450) وعبد بن حميد (1460) والحاكم (7852)."},{"num":16257,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ فِي قِصَّةِ غزوة بَدْرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : قُومُوا إِلَى جَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ قَالَ: يَقُولُ عُمَيْرُ بْنُ الْحُمَامِ الْأَنْصَارِيُّ: يَا رَسُولَ اللَّهِ! جَنَّةٌ عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ؟ قَالَ: نَعَمْ قَالَ: بَخٍ بَخٍ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَا يَحْمِلُكَ عَلَى قول بَخٍ بَخٍ؟ قَالَ: لَا، وَاللهِ يَا رَسُولَ اللَّهِ! إِلَّا رَجَاءَةَ أَنْ أَكُونَ مِنْ أَهْلِهَا، قَالَ: فَإِنَّكَ مِنْ أَهْلِهَا فَأَخْرَجَ تَمَرَاتٍ مِنْ قَرَنِهِ فَجَعَلَ يَأْكُلُ مِنْهُنَّ، ثُمَّ قَالَ: لَئِنْ أَنَا حَيِيتُ حَتَّى آكُلَ تَمَرَاتِي هَذِهِ إِنَّهَا لَحَيَاةٌ طَوِيلَةٌ، قَالَ: فَرَمَى بِمَا كَانَ مَعَهُ مِنَ التَّمْرِ، ثُمَّ قَاتَلَهُمْ حَتَّى قُتِلَ."],"takhrij":"صحيح: رواه مسلم في الإمارة (145:1901) من طرق عن هاشم بن القاسم، حدثنا سليمان (هو ابن المغيرة) عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في سعة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (145 :1901).","chapter_en":"What Has Been Narrated Concerning the Vastness of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated concerning the Battle of Badr that the Messenger of Allah ﷺ said: “Rise toward a Paradise whose breadth is the heavens and the earth.” ʿUmayr ibn al-Ḥumām al-Anṣārī asked: “O Messenger of Allah, a Paradise whose breadth is the heavens and the earth?” He replied: “Yes.” ʿUmayr said: “Excellent! Excellent!” The Messenger of Allah ﷺ asked: “What made you say, ‘Excellent! Excellent!’?” He replied: “Nothing, by Allah, O Messenger of Allah, except the hope that I might be among its people.” He said: “You are among its people.” ʿUmayr then took some dates from his quiver and began eating them. Then he said: “If I live long enough to finish eating these dates, that would indeed be a long life.” So he threw away the dates he had with him and fought them until he was killed."]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَسَارِعُوا إِلَىٰ مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ أُعِدَّتْ لِلْمُتَّقِينَ﴾ [آل عمران: ١٣٣].","وقال تعالى:","﴿سَابِقُوا إِلَىٰ مَغْفِرَةٍ مِنْ رَبِّكُمْ وَجَنَّةٍ عَرْضُهَا كَعَرْضِ السَّمَاءِ وَالْأَرْضِ أُعِدَّتْ لِلَّذِينَ آمَنُوا بِاللَّهِ وَرُسُلِهِ ذَٰلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ﴾ [الحديد: ٢١]."],"en":["Allah, the Exalted, says:","“Hasten toward forgiveness from your Lord and a Paradise as vast as the heavens and the earth, prepared for the righteous.”","[Āl ʿImrān 3:133]","And He, the Exalted, says:","“Race toward forgiveness from your Lord and a Paradise whose breadth is like the breadth of the heaven and the earth, prepared for those who believe in Allah and His Messengers. That is the bounty of Allah, which He grants to whomever He wills. And Allah is the Possessor of tremendous bounty.”","[al-Ḥadīd 57:21]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (145 :1901)."},{"num":16258,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا مُحَمَّدُ، أَرَأَيْتَ جَنَّةً عَرْضُهَا السَّمَاوَاتُ وَالْأَرْضُ فَأَيْنَ النَّارُ؟ قَالَ: أَرَأَيْتَ اللَّيْلَ الَّذِي قَدْ أَلْبَسَ كُلَّ شَيْءٍ فَأَيْنَ جَعَلَ النَّهَارَ؟ قَالَ: اللَّهُ أَعْلَمُ، قَالَ: كَذَلِكَ يَفْعَلُ اللَّهُ مَا يَشَاءُ."],"takhrij":"صحيح: رواه إسحاق بن راهويه (437)، والبزار (9380)، وصحّحه ابن حبان (103)، والحاكم (103) كلهم من طريق عبد الواحد بن زياد، ثنا عبد الله بن عبد الله بن الأصم، ثنا يزيد بن الأصم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في سعة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Isḥāq ibn Rāhawayh (437), al-Bazzār (9380), authenticated by Ibn Ḥibbān (103), and al-Ḥākim (1/36).","chapter_en":"What Has Been Narrated Concerning the Vastness of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated: A man came to the Prophet ﷺ and said: “O Muḥammad, if Paradise is as vast as the heavens and the earth, then where is the Fire?” He replied: “Consider the night when it covers everything—where does the day go?” The man said: “Allah knows best.” He said: “Likewise, Allah does whatever He wills.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه إسحاق بن راهويه (437)، والبزار (9380)، وصححه ابن حبان (103)، والحاكم (103)."},{"num":16259,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فِي الْجَنَّةِ ثَمَانِيَةُ أَبْوَابٍ، فِيهَا باب يُسَمَّى الرَّيَّانَ، لاَ يَدْخُلُهُ إِلاَّ الصَّائِمُونَ."],"takhrij":"صحيح: رواه البخاري في بدء الخلق (3257)، عن سعيد بن أبي مريم، حدثنا محمد بن مطرف، قال: حدثني أبو حازم، عن سهل بن سعد، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في عدد أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3257).","chapter_en":"What Has Been Narrated Concerning the Number of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Prophet ﷺ said: “Paradise has eight gates. Among them is a gate called al-Rayyān, through which none will enter except those who fasted.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّىٰ إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾ [سورة الزمر: ٧٣]."],"en":["Allah, the Exalted, says:","“Those who feared their Lord will be driven to Paradise in groups, until when they reach it and its gates are opened, its keepers will say to them: ‘Peace be upon you. You have done well, so enter it to remain forever.’”","[al-Zumar 39:73]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3257)."},{"num":16260,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الصَّامِتِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَأَنَّ عِيسَى عَبْدُ اللَّهِ، وَابْنُ أَمَتِهِ، وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ، وَأَنَّ الْجَنَّةَ حَقٌّ، وَأَنَّ النَّارَ حَقٌّ، أَدْخَلَهُ اللَّهُ مِنْ أَيِّ أَبْوَابِ الْجَنَّةِ الثَّمَانِيَةِ شَاءَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (28) عن داود بن رشيد، حدثنا الوليد -يعني ابن مسلم-، عن ابن جابر، قال: حدثني عمير بن هانئ، قال: حدثني جنادة بن أبي أمية، حدثنا عبادة بن الصامت، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في عدد أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (28).","chapter_en":"What Has Been Narrated Concerning the Number of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated that the Messenger of Allah ﷺ said: “Whoever testifies that there is no deity except Allah alone, without partner; that Muḥammad is His servant and Messenger; that ʿĪsā is the servant of Allah, the son of His female servant, His Word which He cast to Maryam, and a spirit from Him; and that Paradise is true and the Fire is true—Allah will admit him through whichever of the eight gates of Paradise he wishes.”"]}},"tuhfa":{},"full":1,"rep":[13183],"tks":"صحيح: رواه مسلم (28)."},{"num":16261,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ:  كَانَتْ عَلَيْنَا رِعَايَةُ الْإِبِلِ، فَجَاءَتْ نَوْبَتِي، فَرَوَّحْتُهَا بِعَشِيٍّ، فَأَدْرَكْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمًا يُحَدِّثُ النَّاسَ، فَأَدْرَكْتُ مِنْ قَوْلِهِ: مَا مِنْ مُسْلِمٍ يَتَوَضَّأُ فَيُحْسِنُ وُضُوءَهُ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، مُقْبِلٌ عَلَيْهِمَا بِقَلْبِهِ وَوَجْهِهِ، إِلَّا وَجَبَتْ لَهُ الْجَنَّةُ، قَالَ: فَقُلْتُ: مَا أَجْوَدَ هَذِهِ، فَإِذَا قَائِلٌ بَيْنَ يَدَيَّ يَقُولُ: الَّتِي قَبْلَهَا أَجْوَدُ، فَنَظَرْتُ فَإِذَا عُمَرُ قَالَ: إِنِّي قَدْ رَأَيْتُكَ جِئْتَ آنِفًا، قَالَ: مَا مِنْكُمْ مِنْ أَحَدٍ يَتَوَضَّأُ فَيُبْلِغُ - أَوْ فَيُسْبِغُ - الْوَُضُوءَ، ثُمَّ يَقُولُ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ إِلَّا فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ، يَدْخُلُ مِنْ أَيِّهَا شَاءَ."],"takhrij":"صحيح: رواه مسلم في الطهارة (234) من طرق عن جبير بن نفير، عن عقبة بن عامر، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في عدد أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (234).","chapter_en":"What Has Been Narrated Concerning the Number of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: We used to take turns tending the camels. When my turn came, I brought them back in the evening and found the Messenger of Allah ﷺ standing and speaking to the people. I heard him say: “No Muslim performs wuḍūʾ and performs it well, then stands and prays two rakʿahs, turning toward them with both his heart and face, except that Paradise becomes obligatory for him.” I said: “How excellent this is!” Then someone in front of me said: “What came before it was even better.” I looked and saw that it was ʿUmar. He said: “I saw that you had just arrived.” Then he related that the Prophet ﷺ said: “There is none among you who performs wuḍūʾ and completes—or perfects—his wuḍūʾ, then says: ‘I testify that there is no deity except Allah, and that Muḥammad is the servant of Allah and His Messenger,’ except that the eight gates of Paradise are opened for him, and he may enter through whichever of them he wishes.”"]}},"tuhfa":{},"full":1,"rep":[13184,13210],"tks":"صحيح: رواه مسلم (234)."},{"num":16262,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ قَالَ: فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: إِنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ مَاتَ لَا يُشْرَكُ بِاللَّهِ تَعَالَى شَيْئًا، فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ، يَدْخُلُ مِنْ أَيِّهَا شَاءَ، وَلَهَا ثَمَانِيَةُ أَبْوَابٍ، فَخَرَجَ."],"takhrij":"حسن: رواه الطبراني في الأوسط (7943) –وعنه أبو نعيم في الحلية (2296)- عن موسى بن عيسى بن المنذر، قال: حدثنا محمد بن المبارك الصوري، قال: حدثنا يحيى بن حمزة، عن الوضين بن عطاء، عن القاسم أبي عبدالرحمن، عن عقبة بن عامر قال: فذكره في حديث طويل.","grade":"حسن","chapter_ar":"باب ما جاء في عدد أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (7943), and from him Abū Nuʿaym in al-Ḥilyah (9/307).","chapter_en":"What Has Been Narrated Concerning the Number of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated that ʿUmar ibn al-Khaṭṭāb said: The Prophet of Allah ﷺ said: “Whoever dies without associating anything with Allah, the Exalted, the gates of Paradise will be opened for him and he may enter through whichever of them he wishes. Paradise has eight gates…” The hadith continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (7943) - وعنه أبو نعيم في الحلية (2296)."},{"num":16263,"demo":false,"sanad":"","matn":["عن عُتْبَةَ بن عَبْدِ السُّلَمِيِّ فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَا مِنْ مُسْلِمٍ يَمُوتُ لَهُ ثَلاَثَةٌ مِنَ الْوَلَدِ لَمْ يَبْلُغُوا الْحِنْثَ، إِلاَّ تَلَقَّوْهُ مِنْ أَبْوَابِ الْجَنَّةِ الثَّمَانِيَةِ، مِنْ أَيِّهَا شَاءَ دَخَلَ."],"takhrij":"حسن: رواه ابن ماجه (1604) عن محمد بن عبد الله بن نمير قال: حدثنا إسحاق بن سليمان قال: حدثنا حريز بن عثمان، عن شرحبيل بن شفعة، قال: لقيني عتبة بن عبد السلمي، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في عدد أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (1604).","chapter_en":"What Has Been Narrated Concerning the Number of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":3,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulamī narrated: I heard the Messenger of Allah ﷺ say: “No Muslim has three children die before reaching the age of accountability except that they will meet him at the eight gates of Paradise, and he may enter through whichever gate he wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3371],"tks":"حسن: رواه ابن ماجه (1604)."},{"num":16264,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، يَقُولُ: مَنْ أَنْفَقَ زَوْجَيْنِ مِنْ شَيْءٍ مِنَ الأَشْيَاءِ فِي سَبِيلِ اللَّهِ دُعِيَ مِنْ أَبْوَابِ - يَعْنِي الْجَنَّةَ-: يَا عَبْدَ اللَّهِ هَذَا خَيْرٌ، فَمَنْ كَانَ مِنْ أَهْلِ الصَّلاَةِ دُعِيَ مِنْ باب الصَّلاَةِ، وَمَنْ كَانَ مِنْ أَهْلِ الْجِهَادِ دُعِيَ مِنْ باب الْجِهَادِ، وَمَنْ كَانَ مِنْ أَهْلِ الصَّدَقَةِ دُعِيَ مِنْ باب الصَّدَقَةِ، وَمَنْ كَانَ مِنْ أَهْلِ الصِّيَامِ دُعِيَ مِنْ باب الصِّيَامِ، وَبَابِ الرَّيَّانِ، فَقَالَ أَبُو بَكْرٍ: مَا عَلَى هَذَا الَّذِي يُدْعَى مِنْ تِلْكَ الأَبْوَابِ مِنْ ضَرُورَةٍ، وَقَالَ: هَلْ يُدْعَى مِنْهَا كُلِّهَا أَحَدٌ يَا رَسُولَ اللَّهِ؟ قَالَ: نَعَمْ، وَأَرْجُو أَنْ تَكُونَ مِنْهُمْ يَا أَبَا بَكْرٍ."],"takhrij":"متفق عليه: رواه البخاري في فضائل الصحابة (3666)، ومسلم في الزكاة (85-1027) كلاهما من طرق عن الزهري، قال: أخبرني حميد بن عبد الرحمن بن عوف، أن أبا هريرة، قال: فذكره. وهذا لفظ البخاري، وسياق المسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أسماء أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3666) and Muslim (85 - 1027).","chapter_en":"What Has Been Narrated Concerning the Names of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “Whoever spends two of anything in the path of Allah will be called from the gates of Paradise: ‘O servant of Allah, this is good!’ Whoever was among the people of prayer will be called from the Gate of Prayer. Whoever was among the people of jihād will be called from the Gate of Jihād. Whoever was among the people of charity will be called from the Gate of Charity. And whoever was among the people of fasting will be called from the Gate of Fasting, the Gate of al-Rayyān.” Abū Bakr said: “There is no hardship upon someone who is called from one of those gates, but will anyone be called from all of them, O Messenger of Allah?” He replied: “Yes, and I hope that you will be among them, O Abū Bakr.”"]},"buhuth":{"en":["In another wording narrated by both:","“Whoever spends two of anything in the path of Allah will be called by the keepers of Paradise, each keeper from his gate: ‘O so-and-so, come!’”","Abū Bakr said:","“O Messenger of Allah, such a person will have no loss upon him.”","The Messenger of Allah ﷺ said:","“I certainly hope that you will be among them.”","The expression “lā tawā” means: there will be no destruction or loss."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9847,13211],"tks":"متفق عليه: رواه البخاري (3666)، ومسلم (85 - 1027)."},{"num":16265,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ:  تُفْتَحُ أَبْوَابُ الْجَنَّةِ يَوْمَ الِاثْنَيْنِ، وَيَوْمَ الْخَمِيسِ، فَيُغْفَرُ لِكُلِّ عَبْدٍ لَا يُشْرِكُ بِاللهِ شَيْئًا، إِلَّا رَجُلًا كَانَتْ بَيْنَهُ وَبَيْنَ أَخِيهِ شَحْنَاءُ، فَيُقَالُ: أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا، أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا، أَنْظِرُوا هَذَيْنِ حَتَّى يَصْطَلِحَا."],"takhrij":"صحيح: رواه مالك في حسن الخلق (17) عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب فتح أبواب الجنة في يومي الاثنين والخميس","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in Ḥusn al-Khuluq (17) and Muslim (2565).","chapter_en":"The Gates of Paradise Are Opened on Mondays and Thursdays","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The gates of Paradise are opened on Monday and Thursday, and every servant who does not associate anything with Allah is forgiven, except a man between whom and his brother there is hostility. It will be said: ‘Delay these two until they reconcile. Delay these two until they reconcile. Delay these two until they reconcile.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10727,14931],"tks":"صحيح: رواه مالك (17) ومسلم (2565)."},{"num":16266,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أُتِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بلَحْم، فَرُفِعَ إِلَيْهِ الذِّرَاعُ، وَكَانَتْ تُعْجِبُهُ، فَذَكَرَ حَدِيثَ الشفاعة الطويل، وَجَاءَ فِيهِ: فَأَقُولُ: يَا رَبِّ، أُمَّتِي أُمَّتِي، فَيُقَالُ: يَا مُحَمَّدُ، أَدْخِلِ الْجَنَّةَ مِنْ أُمَّتِكَ مَنْ لَا حِسَابَ عَلَيْهِ مِنَ الْبَابِ الْأَيْمَنِ مِنْ أَبْوَابِ الْجَنَّةِ، وَهُمْ شُرَكَاءُ النَّاسِ فِيمَا سِوَى ذَلِكَ مِنَ الْأَبْوَابِ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، إِنَّ مَا بَيْنَ الْمِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ لَكَمَا بَيْنَ مَكَّةَ وَهَجَرٍ، أَوْ كَمَا بَيْنَ مَكَّةَ وَبُصْرَى."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4712)، ومسلم في الإيمان (194) كلاهما من طريق أبي حيان التيمي، عن أبي زرعة بن عمرو بن جرير، عن أبي هريرة قال: فذكره. واللفظ لمسلم، ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في عرض أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4712) and Muslim (194).","chapter_en":"What Has Been Narrated Concerning the Width of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated: One day meat was brought to the Messenger of Allah ﷺ, and the foreleg was presented to him, which he liked. He then mentioned the lengthy hadith of intercession, in which he said: “I will say: ‘My Lord, my Ummah! My Ummah!’ It will be said: ʿO Muḥammad, admit into Paradise from your Ummah those who will have no reckoning through the right-hand gate of the gates of Paradise. They will share with the other people in the remaining gates. By the One in whose hand is the soul of Muḥammad, the distance between the two leaves of one of the gates of Paradise is like the distance between Makkah and Hajar, or like the distance between Makkah and Buṣrā.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4712)، ومسلم (194)."},{"num":16267,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بْنِ عُمَيْرٍ الْعَدَوِيِّ قَالَ:  خَطَبَنَا عُتْبَةُ بْنُ غَزْوَانَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَمَّا بَعْدُ، فَإِنَّ الدُّنْيَا قَدْ آذَنَتْ بِصُرْمٍ، وَوَلَّتْ حَذَّاءَ، وَلَمْ يَبْقَ مِنْهَا إِلَّا صُبَابَةٌ كَصُبَابَةِ الْإِنَاءِ، يَتَصَابُّهَا صَاحِبُهَا، وَإِنَّكُمْ مُنْتَقِلُونَ مِنْهَا إِلَى دَارٍ لَا زَوَالَ لَهَا، فَانْتَقِلُوا بِخَيْرِ مَا بِحَضْرَتِكُمْ، فَإِنَّهُ قَدْ ذُكِرَ لَنَا: أَنَّ الْحَجَرَ يُلْقَى مِنْ شَفَةِ جَهَنَّمَ، فَيَهْوِي فِيهَا سَبْعِينَ عَامًا، لَا يُدْرِكُ لَهَا قَعْرًا، وَوَاللهِ لَتُمْلَأَنَّ، أَفَعَجِبْتُمْ؟ وَلَقَدْ ذُكِرَ لَنَا أَنَّ مَا بَيْنَ مِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ، مَسِيرَةُ أَرْبَعِينَ سَنَةً، وَلَيَأْتِيَنَّ عَلَيْهَا يَوْمٌ وَهُوَ كَظِيظٌ مِنَ الزِّحَامِ، وَلَقَدْ رَأَيْتُنِي سَابِعَ سَبْعَةٍ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا لَنَا طَعَامٌ إِلَّا وَرَقُ الشَّجَرِ، حَتَّى قَرِحَتْ أَشْدَاقُنَا، فَالْتَقَطْتُ بُرْدَةً."],"takhrij":"صحيح: رواه مسلم في الزهد (2967) عن شيبان بن فروخ، حدثنا سليمان بن المغيرة، حدثنا حميد بن هلال، عن خالد بن عمير العدوي، فذكره بطوله.","grade":"صحيح","chapter_ar":"باب ما جاء في عرض أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2967).","chapter_en":"What Has Been Narrated Concerning the Width of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Khālid ibn ʿUmayr al-ʿAdawī narrated: ʿUtbah ibn Ghazwān delivered a sermon to us. He praised Allah and extolled Him, then said: “To proceed: This world has announced that it is coming to an end and has turned away swiftly. Nothing remains of it except a small amount like the dregs left in a vessel, which its owner tries to drink. You are moving from it to an abode that will never pass away, so move there with the best deeds you are able to take with you. We have been told that a stone will be thrown from the edge of Hell and will fall through it for seventy years without reaching its bottom. By Allah, it will certainly be filled. Are you surprised? And we have been told that the distance between two leaves of one of the gates of Paradise is a journey of forty years, yet a day will certainly come when it will be crowded with people. I remember myself as one of seven people with the Messenger of Allah ﷺ, and we had nothing to eat except the leaves of trees, until the corners of our mouths became ulcerated…” The hadith continues at length."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2967)."},{"num":16268,"demo":false,"sanad":"","matn":["عَنْ حَكِيمِ بْنِ مُعَاوِيَةَ، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنْتُمْ تُوفُونَ سَبْعِينَ أُمَّةً، أَنْتُمْ آخِرُهَا، وَأَكْرَمُهَا عَلَى اللَّهِ، وَمَا بَيْنَ مِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ مَسِيرَةُ أَرْبَعِينَ عَامًا، وَلَيَأْتِيَنَّ عَلَيْهِ يَوْمٌ وَإِنَّهُ لَكَظِيظٌ."],"takhrij":"حسن: رواه أحمد (20025) وعبد بن حميد (411) كلاهما عن الحسن بن موسى، قال: حدثنا حماد بن سلمة، قال: سمعت الجريري، يحدث عن حكيم بن معاوية، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في عرض أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20025) and ʿAbd ibn Ḥumayd (411).","chapter_en":"What Has Been Narrated Concerning the Width of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["Muʿāwiyah ibn Ḥaydah al-Qushayrī narrated that the Messenger of Allah ﷺ said: “You complete seventy nations. You are the last of them and the most honored of them before Allah. The distance between two leaves of one of the gates of Paradise is a journey of forty years, and a day will certainly come when it will be packed with people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20025) وعبد بن حميد (411)."},{"num":16269,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن سلاّم قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إنَّ مَا بَيْنَ مِصْرَاعَي الْجَنَّةِ مقدارُ أَرْبَعِينَ عَامًا، وَلَيَأْتِيَنَّ عَلَيْهِ يومٌ يُزاحَم عَلَيْهِ كَازْدِحَامِ الْإِبِلِ وَرَدَتْ لِخَمْسٍ ظِمَاءً."],"takhrij":"حسن: رواه الطبراني في الكبير (14/ح 387) عن إبراهيم بن مَتُّويه الأصبهاني، حدثنا محمد بن صُدْران، حدثنا يعقوب بن إسحاق الحضرمي، حدثنا زُريك بن زُريك، عن معاوية بن قُرّة، عن عبدالله بن سلاّم فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في عرض أبواب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (14/338, no. 14970).","chapter_en":"What Has Been Narrated Concerning the Width of the Gates of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn Salām narrated that the Messenger of Allah ﷺ said: “The distance between the two leaves of the gate of Paradise is a journey of forty years, and a day will certainly come when people will crowd at it like thirsty camels crowding when they come to water after five days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (338/14 رقم 14970)."},{"num":16270,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ دَعَاهُ خَزَنَةُ الْجَنَّةِ -كُلُّ خَزَنَةِ باب- أي فُلْ هلُمَّ، قَالَ أَبُو بَكْرٍ: يَا رَسُولَ اللَّهِ ذَاكَ الَّذِي لاَ تَوَى عَلَيْهِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنِّي لأَرْجُو أَنْ تَكُونَ مِنْهُمْ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2841)، ومسلم في الزكاة (1027: 86) كلاهما من طريق شيبان بن عبد الرحمن، عن يحيى بن أبي كثير، عن أبي سلمة بن عبد الرحمن أنه سمع أبا هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خزنة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2841) and Muslim (86 :1027).","chapter_en":"What Has Been Narrated Concerning the Keepers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever spends two of anything in the path of Allah will be called by the keepers of Paradise—each keeper from his own gate—saying: ‘O so-and-so, come!’” Abū Bakr said: “O Messenger of Allah, such a person has nothing to fear from loss.” The Prophet ﷺ replied: “I certainly hope that you will be among them.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّىٰ إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾ [سورة الزمر: ٧٣]."],"en":["Allah, the Exalted, says:","“Those who feared their Lord will be driven to Paradise in groups, until when they reach it and its gates are opened, its keepers will say to them: ‘Peace be upon you. You have done well, so enter it to remain forever.’”","[al-Zumar 39:73]"]}},"tuhfa":{},"full":1,"rep":[7783],"tks":"متفق عليه: رواه البخاري (2841)، ومسلم (1027: 86)."},{"num":16271,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَهْلَ الْجَنَّةِ لَيَتَرَاءَوْنَ الْغُرَفَ فِي الْجَنَّةِ، كَمَا تَتَرَاءَوْنَ الْكَوْكَبَ فِي السَّمَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6555)، ومسلم في الجنة وصفة نعيمها وأهلها (2830) كلاهما من طريق أبي حازم، عن سهل بن سعد، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غرف الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6555) and Muslim (2830).","chapter_en":"What Has Been Narrated Concerning the Chambers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Prophet ﷺ said: “The people of Paradise will see the lofty chambers in Paradise just as you see a star in the sky.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿لَكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ غُرَفٌ مِنْ فَوْقِهَا غُرَفٌ مَبْنِيَّةٌ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ وَعْدَ اللَّهِ لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾ [الزمر: ٢٠].","وقال تعالى:","﴿وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَنُبَوِّئَنَّهُمْ مِنَ الْجَنَّةِ غُرَفًا تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نِعْمَ أَجْرُ الْعَامِلِينَ﴾ [العنكبوت: ٥٨]."],"en":["Allah, the Exalted, says:","“But those who feared their Lord will have lofty chambers, with other chambers built above them, beneath which rivers flow. This is the promise of Allah, and Allah never fails in His promise.”","[al-Zumar 39:20]","And He, the Exalted, says:","“Those who believe and perform righteous deeds, We will surely settle them in lofty chambers of Paradise beneath which rivers flow, remaining therein forever. Excellent indeed is the reward of those who work righteousness.”","[al-ʿAnkabūt 29:58]"]}},"tuhfa":{},"full":1,"rep":[13191],"tks":"متفق عليه: رواه البخاري (6555)، ومسلم (2830)."},{"num":16272,"demo":false,"sanad":"","matn":["عن أبي سعيد الخدري، عن النبي صلى الله عليه وسلم قال: إن أهل الجنة ليتراءون الغرف في الجنة، كما تراءون الكوكب الغارب في الأفق الشرقي والغربي."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6556)، ومسلم في الجنة وصفة نعيمها وأهلها (2831) كلاهما من طريق أبي حازم -وهو سلمة بن دينار-، عن النعمان بن أبي عياش قال: سمعت أبا سعيد الخدري، يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غرف الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6556) and Muslim (2831).","chapter_en":"What Has Been Narrated Concerning the Chambers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Prophet ﷺ said: “The people of Paradise will see the lofty chambers in Paradise just as you see a distant star setting on the eastern or western horizon.”"]}},"tuhfa":{},"full":1,"rep":[13192],"tks":"متفق عليه: رواه البخاري (6556)، ومسلم (2831)."},{"num":16273,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَهْلَ الْجَنَّةِ يَتَرَاءَيُونَ أَهْلَ الْغُرَفِ مِنْ فَوْقِهِمْ، كَمَا يَتَرَاءَيُونَ الْكَوْكَبَ الدُّرِّيَّ الْغَابِرَ فِي الأُفُقِ مِنَ الْمَشْرِقِ أَوِ الْمَغْرِبِ، لِتَفَاضُلِ مَا بَيْنَهُمْ. قَالُوا: يَا رَسُولَ اللَّهِ، تِلْكَ مَنَازِلُ الأَنْبِيَاءِ لاَ يَبْلُغُهَا غَيْرُهُمْ، قَالَ: بَلَى، وَالَّذِي نَفْسِي بِيَدِهِ، رِجَالٌ آمَنُوا بِاللَّهِ وَصَدَّقُوا الْمُرْسَلِينَ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3256)، ومسلم في الجنة وصفة نعيمها وأهلها (633) كلاهما من طريق مالك بن أنس، عن صفوان بن سُليم، عن عطاء بن يسار، عن أبي سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في غرف الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3256) and Muslim (633).","chapter_en":"What Has Been Narrated Concerning the Chambers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “The people of Paradise will see those who dwell in the lofty chambers above them just as you see a brilliant star far away on the eastern or western horizon, because of the difference in rank between them.” They asked: “O Messenger of Allah, are those the dwellings of the Prophets, which no one else can reach?” He replied: “Yes. By the One in whose hand is my soul, they are for men who believed in Allah and affirmed the truthfulness of the Messengers.”"]}},"tuhfa":{},"full":1,"rep":[7053,12353,12729,13120,13501],"tks":"متفق عليه: رواه البخاري (3256)، ومسلم (633)."},{"num":16274,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنَّ أَهْلَ الْجَنَّةِ لَيَتَرَاءَوْنَ فِي الْغُرْفَةِ كَمَا تَتَرَاءَوْنَ الْكَوْكَبَ الشَّرْقِيَّ أَوِ الْكَوْكَبَ الْغَرْبِيَّ الْغَارِبَ فِي الأُفُقِ أَوِ الطَّالِعَ، فِي تَفَاضُلِ الدَّرَجَاتِ. فَقَالُوا: يَا رَسُولَ اللَّهِ، أُولَئِكَ النَّبِيُّونَ. قَالَ: بَلَى، وَالَّذِي نَفْسِي بِيَدِهِ، وَأَقْوَامٌ آمَنُوا بِاللَّهِ وَرَسُولِهِ وَصَدَّقُوا الْمُرْسَلِينَ."],"takhrij":"حسن: رواه الترمذي (2556)، وأحمد (8423)، ونعيم بن حماد في زوائده على الزهد لابن المبارك (418) كلهم من طريق فليح بن سليمان، عن هلال بن علي، عن عطاء بن يسار، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في غرف الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2556), Aḥmad (8423), and Nuʿaym ibn Ḥammād in his additions to Ibn al-Mubārak’s al-Zuhd (418).","chapter_en":"What Has Been Narrated Concerning the Chambers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The people of Paradise will see those in the lofty chamber just as they see a star in the east or a star in the west, setting or rising upon the horizon, because of the differing ranks among them.” They asked: “O Messenger of Allah, are those the Prophets?” He replied: “Yes, and by the One in whose hand is my soul, also people who believed in Allah and His Messenger and affirmed the truthfulness of the Messengers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2556)، وأحمد (8423)، ونعيم بن حماد في زوائده على الزهد لابن المبارك (418)."},{"num":16275,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ فِي الْجَنَّةِ غُرْفَةً يُرَى ظَاهِرُهَا مِنْ بَاطِنِهَا، وَبَاطِنُهَا مِنْ ظَاهِرِهَا، فَقَالَ أَبُو مُوسَى الْأَشْعَرِيُّ: لِمَنْ هِيَ يَا رَسُولَ اللَّهِ؟ قَالَ: لِمَنْ أَلَانَ الْكَلَامَ، وَأَطْعَمَ الطَّعَامَ، وَبَاتَ لِلَّهِ قَائِمًا وَالنَّاسُ نِيَامٌ."],"takhrij":"حسن: رواه الإمام أحمد (6615) عن حسن، حدثنا ابن لهيعة، حدثني حيي بن عبدالله، عن أبي عبد الرحمن الحُبلي، عن عبد الله بن عمرو، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في غرف الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (6615).","chapter_en":"What Has Been Narrated Concerning the Chambers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “In Paradise there is a chamber whose exterior can be seen from its interior and whose interior can be seen from its exterior.” Abū Mūsā al-Ashʿarī asked: “For whom is it, O Messenger of Allah?” He replied: “For the one who speaks gently, feeds others, and spends the night standing in prayer for Allah while the people are asleep.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2685],"tks":"حسن: رواه الإمام أحمد (6615)."},{"num":16276,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ فِي الْجَنَّةِ غُرْفَةً يُرَى ظَاهِرُهَا مِنْ بَاطِنِهَا، وَبَاطِنُهَا مِنْ ظَاهِرِهَا، أَعَدَّهَا اللَّهُ لِمَنْ أَطْعَمَ الطَّعَامَ، وَأَلَانَ الْكَلَامَ، وَتَابَعَ الصِّيَامَ، وَصَلَّى وَالنَّاسُ نِيَامٌ."],"takhrij":"حسن: رواه الإمام أحمد (22905)، والطبراني في الكبير (3466)، وصحّحه ابن خزيمة (2137)، وابن حبان (509) كلهم من طريق عبد الرزاق –وهو في مصنفه (20883)، عن معمر، عن يحيى بن أبي كثير، عن ابن معانق أو أبي معانق، عن أبي مالك الأشعري، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في غرف الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (22905) and al-Ṭabarānī in al-Muʿjam al-Kabīr (3466), and authenticated by Ibn Khuzaymah (2137) and Ibn Ḥibbān (509).","chapter_en":"What Has Been Narrated Concerning the Chambers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":8,"content":{"translation":{"en":["Abū Mālik al-Ashʿarī narrated that the Messenger of Allah ﷺ said: “In Paradise there is a chamber whose exterior can be seen from its interior and whose interior can be seen from its exterior. Allah has prepared it for the one who feeds others, speaks gently, regularly fasts, and prays while the people are asleep.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2683,12989],"tks":"حسن: رواه الإمام أحمد (22905)، والطبراني في الكبير (3466)، وصححه ابن خزيمة (2137)، وابن حبان (509)."},{"num":16277,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن قيس، عَنْ أَبِيهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ فِي الْجَنَّةِ خَيْمَةً مِنْ لُؤْلُؤَةٍ مُجَوَّفَةٍ، عَرْضُهَا سِتُّونَ مِيلاً، فِي كُلِّ زَاوِيَةٍ مِنْهَا أَهْلٌ، مَا يَرَوْنَ الآخَرِينَ، يَطُوفُ عَلَيْهِمُ الْمُؤْمِنُونَ. وَجَنَّتَانِ مِنْ فِضَّةٍ، آنِيَتُهُمَا وَمَا فِيهِمَا، وَجَنَّتَانِ مِنْ كَذَا، آنِيَتُهُمَا، وَمَا فِيهِمَا، وَمَا بَيْنَ الْقَوْمِ وَبَيْنَ أَنْ يَنْظُرُوا إِلَى رَبِّهِمْ إِلاَّ رِدَاءُ الْكِبْرِ عَلَى وَجْهِهِ فِي جَنَّةِ عَدْنٍ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4879-4880)، ومسلم مفرقا في الجنة وصفة نعيمها وأهلها (2838: 24) وفي الإيمان (180) كلاهما من طريق عبد العزيز بن عبد الصمد، حدثنا أبو عمران الجوني، عن أبي بكر بن عبد الله بن قيس، عن أبيه، فذكره. واللفظ للبخاري ولفظ مسلم نحوه وفيه: جنتان من ذهب بدل جنتان من كذا. إلا أنه فرق الحديث في موضعين في أولهما إلى قوله يطوف عليهم المؤمنون وفي الموضع الثاني: وجنتان من فضة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خيمة الجنة وأوانيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4879-4880), Muslim (24 :2838), and in al-Īmān (180).","chapter_en":"What Has Been Narrated Concerning the Tent of Paradise and Its Vessels","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn Qays narrated that the Messenger of Allah ﷺ said: “In Paradise there is a tent made of a hollow pearl, sixty miles wide. In each corner of it are inhabitants who do not see those in the other corners, and the believers will go around visiting them. There are two Gardens of silver—their vessels and everything within them are of silver—and two Gardens of another kind, with their vessels and everything within them. Nothing stands between the people and their looking at their Lord except the Veil of Majesty over His Face in the Garden of ʿAdn.”"]},"buhuth":{"ar":["واللفظ للبخاري، ولفظ مسلم نحوه، وفيه: جنتان من ذهب بدل وجنتان من كذا، إلا أنه فرّق الحديث في موضعين؛ في أولهما إلى قوله: يطوف عليهم المؤمنون، وفي الموضع الثاني: وجنتان من فضة."],"en":["The wording is al-Bukhārī’s. Muslim narrated a similar wording, with “two Gardens of gold” in place of “two Gardens of another kind.” Muslim divided the report between two places: the first through “the believers will go around visiting them,” and the second beginning with “two Gardens of silver.”"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿حُورٌ مَقْصُورَاتٌ فِي الْخِيَامِ﴾ [الرحمن: ٧٢].","وقال تعالى:","﴿وَيُطَافُ عَلَيْهِمْ بِآنِيَةٍ مِنْ فِضَّةٍ وَأَكْوَابٍ كَانَتْ قَوَارِيرَا ۝ قَوَارِيرَ مِنْ فِضَّةٍ قَدَّرُوهَا تَقْدِيرًا ۝ وَيُسْقَوْنَ فِيهَا كَأْسًا كَانَ مِزَاجُهَا زَنْجَبِيلًا ۝ عَيْنًا فِيهَا تُسَمَّىٰ سَلْسَبِيلًا﴾ [الإنسان: ١٥-١٨].","وقال تعالى:","﴿يُطَافُ عَلَيْهِمْ بِصِحَافٍ مِنْ ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ الْأَنْفُسُ وَتَلَذُّ الْأَعْيُنُ وَأَنْتُمْ فِيهَا خَالِدُونَ﴾ [الزخرف: ٧١].","وقال تعالى:","﴿يَطُوفُ عَلَيْهِمْ وِلْدَانٌ مُخَلَّدُونَ ۝ بِأَكْوَابٍ وَأَبَارِيقَ وَكَأْسٍ مِنْ مَعِينٍ﴾ [سورة الواقعة: ١٧-١٨]."],"en":["Allah, the Exalted, says:","“Fair maidens secluded in pavilions.”","[al-Raḥmān 55:72]","And He, the Exalted, says:","“They will be served with vessels of silver and cups that are crystal—crystal of silver, measured precisely. And they will be given to drink therein from a cup whose mixture is ginger, from a spring therein called Salsabīl.”","[al-Insān 76:15-18]","And He, the Exalted, says:","“They will be served with dishes and cups of gold, and therein will be whatever the souls desire and the eyes delight in, and you will remain therein forever.”","[al-Zukhruf 43:71]","And He, the Exalted, says:","“Immortal youths will circulate among them with cups, pitchers, and a goblet from a flowing spring.”","[al-Wāqiʿah 56:17-18]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4880-4879)، ومسلم (24:2838) وفي الإيمان (180)."},{"num":16278,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن قيس، عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جِنَانُ الْفِرْدَوْسِ أَرْبَعٌ: ثِنْتَانِ مِنْ ذَهَبٍ حِلْيَتُهُمَا وَآنِيَتُهُمَا وَمَا فِيهِمَا، وَثِنْتَانِ مِنْ فِضَّةٍ آنِيَتُهُمَا وَحِلْيَتُهُمَا وَمَا فِيهِمَا، وَلَيْسَ بَيْنَ الْقَوْمِ وَبَيْنَ أَنْ يَنْظُرُوا إِلَى رَبِّهِمْ عَزَّ وَجَلَّ إِلَّا رِدَاءُ الْكِبْرِيَاءِ عَلَى وَجْهِهِ فِي جَنَّةِ عَدْنٍ، وَهَذِهِ الْأَنْهَارُ تَشْخَبُ مِنْ جَنَّةِ عَدْنٍ، ثُمَّ تَصْدَعُ بَعْدَ ذَلِكَ أَنْهَارًا."],"takhrij":"حسن: رواه أحمد: (19731)، وأبو داود الطيالسي (531)، وعبد بن حميد (545)، وأبو نعيم في صفة الجنة (141، 436) كلهم من طرق عن أبي قدامة الحارث بن عبيد الإيادي، قال: حدثنا أبو عمران يعني الجوني، عن أبي بكر بن عبدالله بن قيس، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خيمة الجنة وأوانيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (19731), Abū Dāwūd al-Ṭayālisī (531), ʿAbd ibn Ḥumayd (545), and Abū Nuʿaym in Ṣifat al-Jannah (141).","chapter_en":"What Has Been Narrated Concerning the Tent of Paradise and Its Vessels","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn Qays narrated that the Prophet ﷺ said: “The Gardens of al-Firdaws are four: two of gold—their ornaments, vessels, and everything within them are of gold—and two of silver—their vessels, ornaments, and everything within them are of silver. Nothing stands between the people and their looking at their Lord, Mighty and Majestic, except the Veil of Majesty over His Face in the Garden of ʿAdn. These rivers gush forth from the Garden of ʿAdn, and from there they branch out into further rivers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (19731)، وأبو داود الطيالسي (531)، وعبد بن حميد (545)، وأبو نعيم في صفة الجنة (141)."},{"num":16279,"demo":false,"sanad":"","matn":["عن أبي ذر كان يحدِّث أنّ رسول الله صلى الله عليه وسلم قال: فذكر قصة الإسراء والمعراج، وجاء فيه: ثم أُدخلتُ الجنّةَ فإذا فيها جَنابذُ اللؤلؤ، وإذا ترابُها المسك."],"takhrij":"متفق عليه: رواه البخاريّ في الصلاة (349)، ومسلم في الإيمان (163) كلاهما من حديث يونس، عن ابن شهاب، عن أنس بن مالك، قال: كان أبو ذرّ يحدّث، فذكره في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب ما جاء في وصف تربة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (349) and Muslim (163).","chapter_en":"What Has Been Narrated Concerning the Soil of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abū Dharr used to narrate that the Messenger of Allah ﷺ said, while mentioning the story of al-Isrāʾ and al-Miʿrāj: “Then I was admitted into Paradise, and there I saw domes of pearl, and its soil was musk.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (349)، ومسلم (163)."},{"num":16280,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ:  أَنَّ ابْنَ صَيَّادٍ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ تُرْبَةِ الْجَنَّةِ؟ فَقَالَ: دَرْمَكَةٌ بَيْضَاءُ مِسْكٌ خَالِصٌ."],"takhrij":"صحيح: رواه مسلم في الفتن (93:2928) عن أبي بكر بن أبي شيبة، حدثنا أبو أسامة، عن الجريري، عن أبي نضرة، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في وصف تربة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (93:2928).","chapter_en":"What Has Been Narrated Concerning the Soil of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Abū Saʿīd narrated that Ibn Ṣayyād asked the Prophet ﷺ about the soil of Paradise. He replied: “Fine white flour, pure musk.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16074],"tks":"صحيح: رواه مسلم (93:2928)."},{"num":16281,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ نَاسٌ مِنَ الْيَهُودِ لأُنَاسٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ يَعْلَمُ نَبِيُّكُمْ كَمْ عَدَدُ خَزَنَةِ جَهَنَّمَ؟ قَالُوا: لاَ نَدْرِي حَتَّى نَسْأَلَ نَبِيَّنَا. فَجَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا مُحَمَّدُ، غُلِبَ أَصْحَابُكَ الْيَوْمَ. قَالَ: وَبِمَ غُلِبُوا. قَالَ: سَأَلَهُمْ يَهُودُ: هَلْ يَعْلَمُ نَبِيُّكُمْ كَمْ عَدَدُ خَزَنَةِ جَهَنَّمَ؟ قَالَ: فَمَا قَالُوا. قَالَ: قَالُوا: لاَ نَدْرِي حَتَّى نَسْأَلَ نَبِيَّنَا. قَالَ: أَفَغُلِبَ قَوْمٌ سُئِلُوا عَمَّا لاَ يَعْلَمُونَ؟ فَقَالُوا: لاَ نَعْلَمُ حَتَّى نَسْأَلَ نَبِيَّنَا، لَكِنَّهُمْ قَدْ سَأَلُوا نَبِيَّهُمْ، فَقَالُوا: أَرِنَا اللَّهَ جَهْرَةً عَلَىَّ بِأَعْدَاءِ اللَّهِ، إِنِّي سَائِلُهُمْ عَنْ تُرْبَةِ الْجَنَّةِ، وَهِيَ الدَّرْمَكُ. فَلَمَّا جَاءُوا قَالُوا: يَا أَبَا الْقَاسِمِ، كَمْ عَدَدُ خَزَنَةِ جَهَنَّمَ؟ قَالَ: هَكَذَا وَهَكَذَا. فِي مَرَّةٍ عَشْرَةٌ، وَفِي مَرَّةٍ تِسْعٌ. قَالُوا: نَعَمْ. قَالَ لَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا تُرْبَةُ الْجَنَّةِ. قَالَ: فَسَكَتُوا هُنَيْهَةً، ثُمَّ قَالُوا: خُبْزَةٌ يَا أَبَا الْقَاسِمِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْخُبْزُ مِنَ الدَّرْمَكِ."],"takhrij":"حسن: رواه الترمذي (3327) -واللفظ له-، وأحمد (14883) كلاهما من طريق سفيان -وهو ابن عيينة-، عن مجالد، عن الشعبي، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في وصف تربة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3327), whose wording this is, and Aḥmad (14883).","chapter_en":"What Has Been Narrated Concerning the Soil of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":10,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: Some Jews asked some of the Companions of the Prophet ﷺ: “Does your Prophet know how many keepers Hell has?” They replied: “We do not know until we ask him.” A man then came to the Prophet ﷺ and said: “O Muḥammad, your Companions were defeated today.” He asked: “How were they defeated?” The man replied: “The Jews asked them: ‘Does your Prophet know how many keepers Hell has?’” He asked: “What did they say?” He replied: “They said: ‘We do not know until we ask our Prophet.’” The Prophet ﷺ said: “Are people defeated merely because they were asked about something they did not know and replied, ‘We do not know until we ask our Prophet’? Yet those people asked their own Prophet and said: ‘Show us Allah openly.’ [al-Nisāʾ 4:153] Bring these enemies of Allah to me. I will ask them about the soil of Paradise, which is fine flour.” When they came, they asked: “O Abū al-Qāsim, how many keepers does Hell have?” He gestured like this and like this—once with ten and once with nine. They said: “Yes.” The Prophet ﷺ then asked them: “What is the soil of Paradise?” They remained silent for a short while, then said: “Bread, O Abū al-Qāsim.” The Messenger of Allah ﷺ said: “Bread is made from fine flour.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3327) - واللفظ له -، وأحمد (14883)."},{"num":16282,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  صِنْفَانِ مِنْ أَهْلِ النَّارِ لَمْ أَرَهُمَا: قَوْمٌ مَعَهُمْ سِيَاطٌ كَأَذْنَابِ الْبَقَرِ، يَضْرِبُونَ بِهَا النَّاسَ، وَنِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ، مُمِيلَاتٌ مَائِلَاتٌ، رُءُوسُهُنَّ كَأَسْنِمَةِ الْبُخْتِ الْمَائِلَةِ، لَا يَدْخُلْنَ الْجَنَّةَ، وَلَا يَجِدْنَ رِيحَهَا، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ كَذَا وَكَذَا."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (125:2128) عن زهير بن حرب، حدثنا جرير، عن سهيل، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (125:2128).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “There are two groups among the people of the Fire whom I have not yet seen: people carrying whips like the tails of cattle, with which they strike the people; and women who are clothed yet naked, inclining others and themselves inclining, their heads like the leaning humps of Bactrian camels. They will not enter Paradise nor smell its fragrance, even though its fragrance can be detected from such-and-such a distance.”"]}},"tuhfa":{},"full":1,"rep":[7713,15567,15847],"tks":"صحيح: رواه مسلم (125:2128)."},{"num":16283,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَتَلَ نَفْسًا مُعَاهَدًا لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا يُوجَدُ مِنْ مَسِيرَةِ أَرْبَعِينَ عَامًا."],"takhrij":"صحيح: رواه البخاري (6914) عن قيس بن حفص، حدثنا عبدالواحد، حدثنا الحسن، حدثنا مجاهد، عن عبد الله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6914).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Prophet ﷺ said: “Whoever kills a person under a covenant of protection will not smell the fragrance of Paradise, even though its fragrance can be detected from a journey of forty years.”"]}},"tuhfa":{},"full":1,"rep":[6823],"tks":"صحيح: رواه البخاري (6914)."},{"num":16284,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: سَيَكُونُ قَوْمٌ لَهُمْ عَهْدٌ، فَمَنْ قَتَلَ رَجُلًا مِنْهُمْ لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ عَامًا."],"takhrij":"صحيح: رواه أحمد (16590) عن أبي النضر، قال: حدثنا الأشجعي، عن سفيان، عن الأعمش، عن هلال بن يساف، عن رجل، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (16590).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["A man narrated that the Prophet ﷺ said: “There will be people who have a covenant of protection. Whoever kills one of them will not smell the fragrance of Paradise, even though its fragrance can be detected from a journey of seventy years.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6826],"tks":"صحيح: رواه أحمد (16590)."},{"num":16285,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ مَنْ قَتَلَ نَفْسًا مُعَاهِدَةً لَهُ ذِمَّةُ اللَّهِ وَذِمَّةُ رَسُولِهِ، فَقَدْ أَخْفَرَ بِذِمَّةِ اللَّهِ، فَلاَ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ خَرِيفًا."],"takhrij":"حسن: رواه الترمذي (1403)، وابن ماجه (2687) كلاهما عن محمد بن بشار قال: حدثنا معدي بن سليمان وهو البصري قال: أنبأنا ابن عجلان، عن أبيه، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (1403) and Ibn Mājah (2687).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Indeed, whoever kills a person under covenant who possesses the protection of Allah and the protection of His Messenger has violated the covenant of Allah. He will not smell the fragrance of Paradise, even though its fragrance can be detected from a journey of seventy years.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6824],"tks":"حسن: رواه الترمذي (1403)، وابن ماجه (2687)."},{"num":16286,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مِنْ قَتَلَ نَفْسًا مُعَاهَدَةً بِغَيْرِ حَقِّهَا، لَمْ يَرُحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَ الْجَنَّةِ تُوجَدُ مِنْ مَسِيرَةِ مِائَةِ عَامٍ."],"takhrij":"صحيح: رواه الطبراني في الأوسط –مجمع البحرين (2491-2492) من طرق عن عيسى بن يونس، عن عوف الأعرابي، عن محمد بن سيرين، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ — Majmaʿ al-Baḥrayn (2491-2492).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever unlawfully kills a person under covenant will not smell the fragrance of Paradise, even though the fragrance of Paradise can be detected from a journey of one hundred years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الأوسط - مجمع البحرين (2492-2491)."},{"num":16287,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكَرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَتَلَ نَفْسًا مُعَاهَدَةً بِغَيْرِ حِلِّهَا، حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ أَنْ يَجِدَ رِيحَهَا."],"takhrij":"حسن: رواه أحمد (20383) عن وكيع، حدثنا سفيان، عن يونس ين عبيد، عن الحكم بن الأعرج، عن الأشعث بن ثُرملة، عن أبي بكرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20383).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Abū Bakrah narrated that the Messenger of Allah ﷺ said: “Whoever unlawfully kills a person under covenant, Allah will forbid him even from smelling the fragrance of Paradise.”"]},"buhuth":{"en":["ʿAbd al-Razzāq (10/102) also narrated it from Sufyān al-Thawrī and added:","“Its fragrance can be detected from a journey of one hundred years.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8146],"tks":"حسن: رواه أحمد (20383)."},{"num":16288,"demo":false,"sanad":"","matn":["عَنِ الْحَسَنِ، قَالَ: مَرِضَ مَعْقِلُ بْنُ يَسَارٍ مَرَضًا ثَقُلَ فِيهِ، فَأَتَاهُ ابْنُ زِيَادٍ يَعُودُهُ، فَقَالَ: إِنِّي مُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنِ اسْتُرْعِيَ رَعِيَّةً، فَلَمْ يُحِطْهُمْ بِنَصِيحَةٍ، لَمْ يَجِدْ رِيحَ الْجَنَّةِ، وَرِيحُهَا يُوجَدُ مِنْ مَسِيرَةِ مِائَةِ عَامٍ.","قَالَ ابْنُ زِيَادٍ: أَلَا كُنْتَ حَدَّثْتَنِي بِهَذَا قَبْلَ الْآنَ؟ قَالَ: وَالْآنَ لَوْلَا الَّذِي أَنْتَ عَلَيْهِ لَمْ أُحَدِّثْكَ بِهِ."],"takhrij":"حسن: رواه أحمد (20315) عن هوذة بن خليفة، حدثنا عوف، عن الحسن قال فذكره. وإسناده حسن من أجل هوذة بن خليفة؛ فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20315).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["Al-Ḥasan narrated: Maʿqil ibn Yasār became seriously ill, and Ibn Ziyād came to visit him. Maʿqil said: “I will narrate to you a hadith that I heard from the Messenger of Allah ﷺ. He said: ‘Whoever is entrusted with subjects but does not sincerely look after them will not smell the fragrance of Paradise, though its fragrance can be detected from a journey of one hundred years.’” Ibn Ziyād said: “Why did you not narrate this to me before now?”","He replied: “Even now, were it not for the condition you are in, I would not have narrated it to you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (20315)."},{"num":16289,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عمرو: عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ لَمْ يَرَحْ رَائِحَةَ الْجَنَّةِ، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ سَبْعِينَ عَامًا."],"takhrij":"صحيح: رواه أحمد (6592) والطيالسي (2388) كلاهما من طريق شعبة، عن الحكم، عن مجاهد، عن عبد الله بن عمرو، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (6592) and al-Ṭayālisī (2388).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Prophet ﷺ said: “Whoever attributes himself to someone other than his father will not smell the fragrance of Paradise, even though its fragrance can be detected from a journey of seventy years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (6592) والطيالسي (2388)."},{"num":16290,"demo":false,"sanad":"","matn":["عَنْ عَبْدَالِلَهِ بْنِ عَمْرِو بْنِ الْعَاصِ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: سَيِّدُ رَيْحَانٍ أَهْلُ الْجَنَّةِ الْحِنَّاءُ."],"takhrij":"صحيح: رواه الطبراني في الكبير (13/609 رقم 14527) عن عبدالله بن أحمد، حدثنا أبي، حدثنا معاذ بن هشام، حدثني أبي، عن قتادة، عن أبي أيوب، عن عبدالله بن عمرو بن العاص قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ريح الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (13/609, no. 14527).","chapter_en":"What Has Been Narrated Concerning the Fragrance of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Prophet ﷺ said: “The chief fragrant plant of the people of Paradise is henna.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (609/13 رقم 14527)."},{"num":16291,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، حَدِّثْنَا عَنِ الْجَنَّةِ، مَا بِنَاؤُهَا؟ قَالَ: لَبِنَةُ ذَهَبٍ وَلَبِنَةُ فِضَّةٍ، وَمِلَاطُهَا الْمِسْكُ الْأَذْفَرُ، وَحَصْبَاؤُهَا اللُّؤْلُؤُ وَالْيَاقُوتُ، وَتُرَابُهَا الزَّعْفَرَانُ، مَنْ يَدْخُلُهَا يَنْعَمُ وَلَا يَبْأَسُ، وَيَخْلُدُ وَلَا يَمُوتُ، لَا تَبْلَى ثِيَابُهُ وَلَا يَفْنَى شَبَابُهُ."],"takhrij":"حسن: رواه أحمد (8043)، وعبد بن حميد (1420)، وصحّحه ابن حبان (7387) كلهم من طريق زهير بن معاوية، حدثنا أبو مجاهد سعد الطائي، حدثنا أبو المدلة مولى أم المؤمنين، أنه سمع أبا هريرة يقول: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في لبنة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8043) and ʿAbd ibn Ḥumayd (1420), and authenticated by Ibn Ḥibbān (7387).","chapter_en":"What Has Been Narrated Concerning the Bricks of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated: We said: “O Messenger of Allah, tell us about Paradise. What is its construction like?” He replied: “A brick of gold and a brick of silver. Its mortar is fragrant musk, its pebbles are pearls and rubies, and its soil is saffron. Whoever enters it will live in bliss and never suffer misery, will remain forever and never die, his clothes will never wear out, and his youth will never fade.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13193,16426],"tks":"حسن: رواه أحمد (8043)، وعبد بن حميد (1420)، وصححه ابن حبان (7387)."},{"num":16292,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بِنَاءُ الْجَنَّةِ لَبِنَةٌ مِنْ ذَهَبٍ، وَلَبِنَةٌ مِنْ فِضَّةٍ."],"takhrij":"حسن: رواه أحمد (8747) والبزار –كشف الأستار (3905)، والطبراني في الأوسط (2553) وأبو نعيم في صفة الجنة (137) كلهم من طرق عن عمران القطان، عن قتادة، عن العلاء بن زياد العدوي، عن أبي هريرة، فذكره. واللفظ لأحمد، وزاد البزار: وملاطها المسك.","grade":"حسن","chapter_ar":"باب ما جاء في لبنة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8747), al-Bazzār in Kashf al-Astār (3509), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (2532), and Abū Nuʿaym in Ṣifat al-Jannah (137).","chapter_en":"What Has Been Narrated Concerning the Bricks of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The construction of Paradise consists of a brick of gold and a brick of silver.”"]},"buhuth":{"en":["The wording is Aḥmad’s. Al-Bazzār added: “Its mortar is musk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8747)، والبزار في كشف الأستار (3509)، والطبراني في الأوسط (2553)، وأبو نعيم في صفة الجنة (137)."},{"num":16293,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُنِي دَخَلْتُ الْجَنَّةَ، فَإِذَا أَنَا بِالرُّمَيْصَاءِ امْرَأَةِ أَبِي طَلْحَةَ، وَسَمِعْتُ خَشَفَةً، فَقُلْتُ: مَنْ هَذَا؟ فَقَالَ: هَذَا بِلاَلٌ. وَرَأَيْتُ قَصْرًا بِفِنَائِهِ جَارِيَةٌ، فَقُلْتُ: لِمَنْ هَذَا؟ فَقَالَ: لِعُمَرَ. فَأَرَدْتُ أَنْ أَدْخُلَهُ فَأَنْظُرَ إِلَيْهِ، فَذَكَرْتُ غَيْرَتَكَ. فَقَالَ عُمَرُ: بِأُمِّي وَأَبِي يَا رَسُولَ اللَّهِ! أَعَلَيْكَ أَغَارُ."],"takhrij":"متفق عليه: رواه البخاري في فضائل الصحابة (3679)، ومسلم في فضائل الصحابة (633) كلاهما من حديث محمد بن المنكدر، عن جابر بن عبد الله، قال: فذكره. وهذا لفظ البخاري، ولفظ مسلم نحوه، وفيه: دخلت الجنة فرأيت فيها دارا أو قصرا.... وفي آخره: \"فبكى عمر وقال: أي رسول الله أو عليك يغار؟\".","grade":"متفق عليه","chapter_ar":"باب ما جاء في قصور الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3679) and Muslim (633). This is al-Bukhārī’s wording. Muslim narrated a similar version containing:","chapter_en":"What Has Been Narrated Concerning the Palaces of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Prophet ﷺ said: “I saw myself entering Paradise, and there was al-Rumayṣāʾ—the wife of Abū Ṭalḥah. I heard the sound of footsteps and asked: ‘Who is this?’ It was said: ‘This is Bilāl.’ Then I saw a palace with a young woman in its courtyard. I asked: ‘Whose is this?’ It was said: ‘It belongs to ʿUmar.’ I wanted to enter it and look inside, but I remembered your jealousy.” ʿUmar said: “May my father and mother be sacrificed for you, O Messenger of Allah! Would I be jealous regarding you?”"]},"buhuth":{"en":["“I entered Paradise and saw in it a house or a palace…”","At its end, it states:","“ʿUmar wept and said: ‘O Messenger of Allah, would anyone be jealous regarding you?’”","In another wording of al-Bukhārī (5226):","“I entered Paradise—or I came to Paradise—and saw a palace. I asked: ‘Whose is this?’ They said: ‘It belongs to ʿUmar ibn al-Khaṭṭāb.’ I wanted to enter it, and nothing prevented me except my knowledge of your jealousy.”","And in another wording of al-Bukhārī (7024):","“I entered Paradise and saw a palace of gold. I asked: ‘Whose is this?’ They said: ‘It belongs to a man from Quraysh.’ Nothing prevented me from entering it…”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9872],"tks":"متفق عليه: رواه البخاري (3679)، ومسلم (633). وهذا لفظ البخاري، ولفظ مسلم نحوه، وفيه:."},{"num":16294,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : دَخَلْتُ الْجَنَّةَ، فَإِذَا أَنَا بِقَصْرٍ مِنْ ذَهَبٍ فَقُلْتُ: لِمَنْ هَذَا الْقَصْرُ؟ قَالُوا: لِشَابٍّ مِنْ قُرَيْشٍ، فَظَنَنْتُ أني أَنَا هُوَ، فَقُلْتُ: لِمَنْ هُوَ؟ فَقَالُوا: لِعُمَرَ بْنِ الْخَطَّابِ، قَالَ: فَلَوْلَا مَا عَلِمْتُ مِنْ غَيْرَتِكَ لَدَخَلْتُهُ، فَقَالَ عُمَرُ: عَلَيْكَ يَا رَسُولَ اللَّهِ أَغَارُ؟"],"takhrij":"صحيح: رواه الترمذي (3688)، والنسائي في فضائل الصحابة (26)، وأحمد (12046) –واللفظ له-، وصحّحه ابن حبان (6887) كلهم من طرق عن حميد، عن أنس، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في قصور الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3688), al-Nasā’ī in Faḍāʾil al-Ṣaḥābah (26), and Aḥmad (12046), whose wording this is.","chapter_en":"What Has Been Narrated Concerning the Palaces of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":13,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “I entered Paradise and saw a palace of gold. I asked: ‘Whose palace is this?’ They said: ‘It belongs to a young man from Quraysh.’ I thought that I was that man, so I asked: ‘Whose is it?’ They replied: ‘It belongs to ʿUmar ibn al-Khaṭṭāb.’” He then said: “Had I not known of your jealousy, I would have entered it.” ʿUmar replied: “Would I be jealous regarding you, O Messenger of Allah?”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9874],"tks":"صحيح: رواه الترمذي (3688)، والنسائي في فضائل الصحابة (26)، وأحمد (12046) - واللفظ له -."},{"num":16295,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ فِي الْجَنَّةِ لَشَجَرَةً، يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ، لاَ يَقْطَعُهَا."],"takhrij":"متفق عليه: رواه مسلم في الجنة وصفة نعيمها وأهلها (2827) عن إسحاق بن إبراهيم الحنظلي، أخبرنا المخزومي –وهو المغيرة بن سلمة-، حدثنا وهيب، عن أبي حازم –يعني سلمة بن دينار-، عن سهل بن سعد، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سعة شجر الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2827) and al-Bukhārī (6552).","chapter_en":"What Has Been Narrated Concerning the Vastness of the Trees of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Messenger of Allah ﷺ said: “Indeed, in Paradise there is a tree under whose shade a rider could travel for one hundred years without reaching its end.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12169,13482],"tks":"متفق عليه: رواه مسلم (2827) والبخاري (6552)."},{"num":16296,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ الْجَوَادَ الْمُضَمَّرَ السَّرِيعَ مِائَةَ عَامٍ مَا يَقْطَعُهَا."],"takhrij":"متفق عليه: رواه مسلم في الجنة وصفة نعيمها وأهلها (2828) عن إسحاق بن إبراهيم الحنظلي، أخبرنا المغيرة بن سلمة، حدثنا وهيب، عن أبي حازم قال: فحدثت به النعمان بن أبي عياش، فقال: حدثني أبو سعيد، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سعة شجر الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2828) and al-Bukhārī (6553).","chapter_en":"What Has Been Narrated Concerning the Vastness of the Trees of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Prophet ﷺ said: “Indeed, in Paradise there is a tree beneath whose shade a rider on a swift, well-trained racing horse could travel for one hundred years without reaching its end.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2828) والبخاري (6553)."},{"num":16297,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنَّ فِي الْجَنَّةِ لَشَجَرَةً، يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ، لاَ يَقْطَعُهَا."],"takhrij":"صحيح: رواه البخاري في بدء الخلق (3251) عن روح بن عبد المؤمن، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، حدثنا أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في سعة شجر الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3251).","chapter_en":"What Has Been Narrated Concerning the Vastness of the Trees of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “Indeed, in Paradise there is a tree under whose shade a rider could travel for one hundred years without reaching its end.”"]}},"tuhfa":{},"full":1,"rep":[13484],"tks":"صحيح: رواه البخاري (3251)."},{"num":16298,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  إِنَّ فِي الْجَنَّةِ لَشَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ سَنَةٍ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها (2826) عن قتيبة بن سعيد، حدثنا ليث، عن سعيد بن أبي سعيد المقبري، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في سعة شجر الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2826).","chapter_en":"What Has Been Narrated Concerning the Vastness of the Trees of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Indeed, in Paradise there is a tree beneath whose shade a rider could travel for one hundred years.”"]}},"tuhfa":{},"full":1,"rep":[12170],"tks":"صحيح: رواه مسلم (2826)."},{"num":16299,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ فِي الْجَنَّةِ شَجَرَةً يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ عَامٍ، لاَ يَقْطَعُهَا، وَاقْرَءُوا إِنْ شِئْتُمْ: {وَظِلٍّ مَمْدُودٍ}."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4881)، ومسلم في الجنة (7:2826) كلاهما من طريق أبي الزناد، عن الأعرج، عن أبي هريرة، فذكره. واللفظ للبخاري، ولم يذكر مسلم لفظه بهذا الإسناد، وإنما أحال على حديث قبله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سعة شجر الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4881) and Muslim (7:2826).","chapter_en":"What Has Been Narrated Concerning the Vastness of the Trees of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated, attributing it to the Prophet ﷺ: “Indeed, in Paradise there is a tree beneath whose shade a rider could travel for one hundred years without reaching its end. Recite, if you wish: ‘And extended shade.’ [al-Wāqiʿah 56:30]”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4881)، ومسلم (7:2826)."},{"num":16300,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ آمَنَ بِاللَّهِ وَرَسُولِهِ، وَأَقَامَ الصَّلاَةَ، وَصَامَ رَمَضَانَ، كَانَ حَقًّا عَلَى اللَّهِ أَنْ يُدْخِلَهُ الْجَنَّةَ، هَاجَرَ، فِي سَبِيلِ اللَّهِ، أَوْ جَلَسَ فِي أَرْضِهِ الَّتِي وُلِدَ فِيهَا. قَالُوا: يَا رَسُولَ اللَّهِ، أَفَلاَ نُنَبِّئُ النَّاسَ بِذَلِكَ. قَالَ: إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ، أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِهِ، كُلُّ دَرَجَتَيْنِ مَا بَيْنَهُمَا كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، فَإِذَا سَأَلْتُمُ اللَّهَ فَسَلُوهُ الْفِرْدَوْسَ، فَإِنَّهُ أَوْسَطُ الْجَنَّةِ، وَأَعْلَى الْجَنَّةِ، وَفَوْقَهُ عَرْشُ الرَّحْمَنِ، وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ."],"takhrij":"صحيح: رواه البخاري في التوحيد (7423) عن إبراهيم بن المنذر، حدثني محمد بن فليح، قال: حدثني أبي، حدثني هلال، عن عطاء بن يسار، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب أن الجنة درجات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7423).","chapter_en":"Paradise Has Ranks and Degrees","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Whoever believes in Allah and His Messenger, establishes the prayer, and fasts Ramaḍān, then it is a right upon Allah to admit him into Paradise, whether he emigrates in the path of Allah or remains in the land in which he was born.” They asked: “O Messenger of Allah, should we not give the people this good news?” He replied: “Indeed, in Paradise there are one hundred ranks which Allah has prepared for those who strive in His path. The distance between every two ranks is like the distance between the heaven and the earth. So when you ask Allah, ask Him for al-Firdaws, for it is the central and highest part of Paradise. Above it is the Throne of the Most Merciful, and from it the rivers of Paradise spring forth.”"]},"intro":{"ar":["قال الله تعالى:","﴿أُولَٰئِكَ هُمُ الْمُؤْمِنُونَ حَقًّا لَهُمْ دَرَجَاتٌ عِنْدَ رَبِّهِمْ وَمَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ﴾ [الأنفال: ٤].","وقال تعالى:","﴿الَّذِينَ يَرِثُونَ الْفِرْدَوْسَ هُمْ فِيهَا خَالِدُونَ﴾ [سورة المؤمنون: ١١]."],"en":["Allah, the Exalted, says:","“Those are the true believers. For them are ranks with their Lord, forgiveness, and a noble provision.”","[al-Anfāl 8:4]","And He, the Exalted, says:","“Those who will inherit al-Firdaws; they will remain therein forever.”","[al-Muʾminūn 23:11]"]}},"tuhfa":{},"full":1,"rep":[12698,13290,13612],"tks":"صحيح: رواه البخاري (7423)."},{"num":16301,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فِي الْجَنَّةِ مِائَةُ دَرَجَةٍ، مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، وَالْفِرْدَوْسُ أَعْلاَهَا دَرَجَةً، وَمِنْهَا تُفَجَّرُ أَنْهَارُ الْجَنَّةِ الأَرْبَعَةُ، وَمِنْ فَوْقِهَا يَكُونُ الْعَرْشُ، فَإِذَا سَأَلْتُمُ اللَّهَ، فَسَلُوهُ الْفِرْدَوْسَ."],"takhrij":"صحيح: رواه الترمذي (2531) عن عبد الله بن عبد الرحمن، أخبرنا يزيد بن هارون، أخبرنا همام، حدثنا زيد بن أسلم، عن عطاء بن يسار، عن عبادة بن الصامت، فذكره.","grade":"صحيح","chapter_ar":"باب أن الجنة درجات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2531).","chapter_en":"Paradise Has Ranks and Degrees","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated that the Messenger of Allah ﷺ said: “In Paradise there are one hundred ranks. The distance between every two ranks is like the distance between the heaven and the earth. Al-Firdaws is the highest of them, and from it the four rivers of Paradise spring forth. Above it is the Throne. So when you ask Allah, ask Him for al-Firdaws.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[471,12730,16324],"tks":"صحيح: رواه الترمذي (2531)."},{"num":16302,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِذَا سَمِعْتُمُ الْمُؤَذِّنَ، فَقُولُوا مِثْلَ مَا يَقُولُ، ثُمَّ صَلُّوا عَلَيَّ؛ فَإِنَّهُ مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا، ثُمَّ سَلُوا اللَّهَ لِي الْوَسِيلَةَ؛ فَإِنَّهَا مَنْزِلَةٌ فِي الْجَنَّةِ، لَا تَنْبَغِي إِلَّا لِعَبْدٍ مِنْ عِبَادِ اللَّهِ، وَأَرْجُو أَنْ أَكُونَ أَنَا هُوَ. فَمَنْ سَأَلَ لِي الْوَسِيلَةَ حَلَّتْ لَهُ الشَّفَاعَةُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (384) من طريق كعب بن علقمة، عن عبدالرحمن بن جبير، عن عبد الله بن عمرو بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب أن الجنة درجات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (384).","chapter_en":"Paradise Has Ranks and Degrees","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that he heard the Prophet ﷺ say: “When you hear the mu’adhdhin, repeat what he says, then invoke blessings upon me, for whoever invokes one blessing upon me, Allah will bless him ten times because of it. Then ask Allah to grant me al-Wasīlah, for it is a rank in Paradise that is fitting for only one servant among the servants of Allah, and I hope that I am that servant. Whoever asks Allah to grant me al-Wasīlah will become entitled to my intercession.”"]}},"tuhfa":{},"full":1,"rep":[1897,1910],"tks":"صحيح: رواه مسلم (384)."},{"num":16303,"demo":false,"sanad":"","matn":["عَنْ أَبِي نَجِيحٍ السُّلَمِيِّ، قَالَ: حَاصَرْنَا مَعَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِصْنَ الطَّائِفِ، فَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ بَلَغَ بِسَهْمٍ فَلَهُ دَرَجَةٌ فِي الْجَنَّةِ قَالَ: فَبَلَغْتُ يَوْمَئِذٍ سِتَّةَ عَشَرَ سَهْمًا."],"takhrij":"صحيح: رواه أحمد (17022)، وأبو داود (3965)، والترمذي (1638)، والنسائي (6/26)، وصحّحه ابن حبان (4615)، والحاكم (4371) كلهم من حديث هشام بن أبي عبد الله، عن قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة، عن أبي نجيح السلمي، فذكره. واللفظ لأحمد، وهو عنده مطولا، سبق ذكره في موضعه.","grade":"صحيح","chapter_ar":"باب أن الجنة درجات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17022), Abū Dāwūd (3965), al-Tirmidhī (1638), and al-Nasā’ī (6/26).","chapter_en":"Paradise Has Ranks and Degrees","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abū Najīḥ al-Sulamī narrated: We besieged the fortress of al-Ṭā’if together with the Prophet of Allah ﷺ, and I heard the Messenger of Allah ﷺ say: “Whoever shoots an arrow that reaches the enemy will have a rank in Paradise.” He said: “That day I shot sixteen arrows that reached their targets.”"]}},"tuhfa":{},"full":1,"rep":[9234],"tks":"صحيح: رواه أحمد (17022)، وأبو داود (3965)، والترمذي (1638)، والنسائي (6/26)."},{"num":16304,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَا أَبَا سَعِيدٍ، مَنْ رَضِيَ بِاللهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا، وَجَبَتْ لَهُ الْجَنَّةُ. فَعَجِبَ لَهَا أَبُو سَعِيدٍ، فَقَالَ: أَعِدْهَا عَلَيَّ يَا رَسُولَ اللَّهِ، فَفَعَلَ، ثُمَّ قَالَ: وَأُخْرَى يُرْفَعُ بِهَا الْعَبْدُ مِائَةَ دَرَجَةٍ فِي الْجَنَّةِ، مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالْأَرْضِ. قَالَ: وَمَا هِيَ يَا رَسُولَ اللَّهِ؟ قَالَ: الْجِهَادُ فِي سَبِيلِ اللَّهِ، الْجِهَادُ فِي سَبِيلِ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الإمارة (1884) عن سعيد بن منصور، حدثنا عبدالله بن وهب، حدثني أبو هانئ الخولاني، عن أبي عبد الرحمن الحبلي، عن أبي سعيد الخدري، فذكره.","grade":"صحيح","chapter_ar":"باب أن الجنة درجات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1884).","chapter_en":"Paradise Has Ranks and Degrees","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “O Abū Saʿīd, whoever is pleased with Allah as his Lord, Islam as his religion, and Muḥammad as his Prophet, Paradise becomes obligatory for him.” Abū Saʿīd was amazed by this and said: “Repeat it to me, O Messenger of Allah.” So he repeated it, then said: “There is another deed by which a servant is raised one hundred ranks in Paradise, the distance between every two ranks being like the distance between the heaven and the earth.” He asked: “What is it, O Messenger of Allah?” He replied: “Jihād in the path of Allah. Jihād in the path of Allah.”"]}},"tuhfa":{},"full":1,"rep":[7744],"tks":"صحيح: رواه مسلم (1884)."},{"num":16305,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ قَالَ: أُصِيبَ حَارِثَةُ يَوْمَ بَدْرٍ وَهْوَ غُلاَمٌ، فَجَاءَتْ أُمُّهُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، قَدْ عَرَفْتَ مَنْزِلَةَ حَارِثَةَ مِنِّي، فَإِنْ يَكُ فِي الْجَنَّةِ أَصْبِرْ وَأَحْتَسِبْ، وَإِنْ تَكُنِ الأُخْرَى تَرَ مَا أَصْنَعُ؟ فَقَالَ: وَيْحَكِ، أَوَهَبِلْتِ، أَوَجَنَّةٌ وَاحِدَةٌ هِيَ؟ إِنَّهَا جِنَانٌ كَثِيرَةٌ، وَإِنَّهُ لَفِي جَنَّةِ الْفِرْدَوْسِ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6550) عن عبد الله بن محمد، حدثنا معاوية بن عمرو، حدثنا أبو إسحاق، عن حميد، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب أن الجنة درجات","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6550).","chapter_en":"Paradise Has Ranks and Degrees","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":15,"content":{"translation":{"en":["Anas narrated: Ḥārithah was killed at Badr while still a young boy. His mother came to the Prophet ﷺ and said: “O Messenger of Allah, you know what place Ḥārithah held in my heart. If he is in Paradise, I will remain patient and seek reward from Allah; but if it is otherwise, you will see what I do.” He replied: “Woe to you! Have you lost your senses? Is there only one Paradise? There are many Gardens, and indeed he is in the Garden of al-Firdaws.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6550)."},{"num":16306,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : غَدْوَةٌ فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَلَقَابُ قَوْسِ أَحَدِكُمْ، أَوْ مَوْضِعُ قَدَمٍ مِنَ الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَلَوْ أَنَّ امْرَأَةً مِنْ نِسَاءِ أَهْلِ الْجَنَّةِ اطَّلَعَتْ إِلَى الأَرْضِ لأَضَاءَتْ مَا بَيْنَهُمَا، وَلَمَلأَتْ مَا بَيْنَهُمَا رِيحًا، وَلَنَصِيفُهَا -يَعْنِي الْخِمَارَ- خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا."],"takhrij":"صحيح: رواه البخاري في الرقاق (6568) عن قتيبة، عن إسماعيل بن جعفر، عن حميد، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب موضع قدم أو سوط من الجنة خير من الدنيا وما فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6568). He also narrated it through another route (2796) with the wording:","chapter_en":"The Space of a Footstep or Whip in Paradise Is Better Than the World and Everything in It","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “A morning journey in the path of Allah or an evening journey is better than the world and everything in it. The space occupied by the bow of one of you—or the space of a single foot—in Paradise is better than the world and everything in it. And if a woman from among the women of Paradise were to look toward the earth, she would illuminate everything between them and fill everything between them with fragrance. Even her head-covering is better than the world and everything in it.”"]},"buhuth":{"en":["“The space occupied by the bow of one of you in Paradise, or the space occupied by his whip, is better than the world and everything in it…”","The hadith continues."]}},"tuhfa":{},"full":1,"dr":1,"rep":[16434],"tks":"صحيح: رواه البخاري (6568). ورواه أيضا bukhari(2796) من وجه آخر بلفظ:."},{"num":16307,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَوْضِعُ سَوْطٍ فِي الْجَنَّةِ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَلَغَدْوَةٌ فِي سَبِيلِ اللَّهِ أَوْ رَوْحَةٌ خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6415)، ومسلم في الإمارة (1881) كلاهما من طريق عبد العزيز بن أبي حازم، عن أبيه، عن سهل بن سعد الساعدي، قال: فذكره. واللفظ للبخاري، واقتصر مسلم على الجملة الأخيرة من الحديث.","grade":"متفق عليه","chapter_ar":"باب موضع قدم أو سوط من الجنة خير من الدنيا وما فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6415) and Muslim (1881).","chapter_en":"The Space of a Footstep or Whip in Paradise Is Better Than the World and Everything in It","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Sahl ibn Saʿd narrated: I heard the Prophet ﷺ say: “The space occupied by a whip in Paradise is better than the world and everything in it, and a morning journey in the path of Allah or an evening journey is better than the world and everything in it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6415)، ومسلم (1881)."},{"num":16308,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَقَابُ قَوْسٍ فِي الْجَنَّةِ خَيْرٌ مِمَّا تَطْلُعُ عَلَيْهِ الشَّمْسُ وَتَغْرُبُ. وَقَالَ: لَغَدْوَةٌ أَوْ رَوْحَةٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِمَّا تَطْلُعُ عَلَيْهِ الشَّمْسُ وَتَغْرُبُ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2793)، عن إبراهيم بن المنذر، حدثنا محمد بن فليح، قال: حدثني أبي، عن هلال بن علي، عن عبد الرحمن بن أبي عمرة، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب موضع قدم أو سوط من الجنة خير من الدنيا وما فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2793).","chapter_en":"The Space of a Footstep or Whip in Paradise Is Better Than the World and Everything in It","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The space occupied by a bow in Paradise is better than everything upon which the sun rises and sets.” And he said: “A morning journey or an evening journey in the path of Allah is better than everything upon which the sun rises and sets.”"]}},"tuhfa":{},"full":1,"rep":[7748],"tks":"صحيح: رواه البخاري (2793)."},{"num":16309,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قِيدُ سَوْطِ أَحَدِكُمْ مِنَ الْجَنَّةِ، خَيْرٌ مِنَ الدُّنْيَا وَمِثْلِهَا مَعَهَا، وَلَقَابُ قَوْسِ أَحَدِكُمْ مِنَ الْجَنَّةِ، خَيْرٌ مِنَ الدُّنْيَا وَمِثْلِهَا مَعَهَا، وَلَنَصِيفُ امْرَأَةٍ مِنَ الْجَنَّةِ، خَيْرٌ مِنَ الدُّنْيَا وَمِثْلِهَا مَعَهَا.","قَالَ: قُلْتُ: يَا أَبَا هُرَيْرَةَ: مَا النَّصِيفُ؟ قَالَ: \"الْخِمَارُ\"."],"takhrij":"حسن: رواه أحمد (10270) –واللفظ له-، وأبو نعيم في صفة الجنة (59) كلاهما من طريق الخزرج بن عثمان السعدي قال: حدثنا أبو أيوب مولى لعثمان بن عفان، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب موضع قدم أو سوط من الجنة خير من الدنيا وما فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (10270), whose wording this is, and Abū Nuʿaym in Ṣifat al-Jannah (59).","chapter_en":"The Space of a Footstep or Whip in Paradise Is Better Than the World and Everything in It","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The space occupied by the whip of one of you in Paradise is better than this world and another world equal to it. The space occupied by the bow of one of you in Paradise is better than this world and another world equal to it. And the head-covering of a woman from Paradise is better than this world and another world equal to it.” The narrator said: I asked Abū Hurayrah: “What is the naṣīf?”","He replied: “The head-covering.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (10270) - واللفظ له -، وأبو نعيم في صفة الجنة (59)."},{"num":16310,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ، حَدَّثَنَا أَنَسٌ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُهْدِيَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جُبَّةُ سُنْدُسٍ، وَكَانَ يَنْهَى عَنِ الْحَرِيرِ، فَعَجِبَ النَّاسُ مِنْهَا، فَقَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَمَنَادِيلُ سَعْدِ بْنِ مُعَاذٍ فِي الْجَنَّةِ أَحْسَنُ مِنْ هَذَا."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2615)، ومسلم في فضائل الصحابة (2469) كلاهما من طريق يونس بن محمد، ثنا شيبان، عن قتادة، عن أنس قال: فذكره. انظر فضائل الصحابة، فضائل سعد بن معاذ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مناديل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2615) and Muslim (2469).","chapter_en":"What Has Been Narrated Concerning the Handkerchiefs of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":17,"content":{"translation":{"en":["Anas narrated: A garment of fine silk was gifted to the Prophet ﷺ, although he used to prohibit silk. The people were amazed by it. He said: “By the One in whose hand is the soul of Muḥammad, the handkerchiefs of Saʿd ibn Muʿādh in Paradise are finer than this.”"]}},"tuhfa":{},"full":1,"rep":[10208,15501],"tks":"متفق عليه: رواه البخاري (2615)، ومسلم (2469)."},{"num":16311,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ وَذُكِرَ لَهُ سِدْرَةُ الْمُنْتَهَى، قَالَ: يَسِيرُ الرَّاكِبُ فِي ظِلِّ الْفَنَنِ مِنْهَا مِائَةَ سَنَةٍ، أَوْ يَسْتَظِلُّ بِظِلِّهَا مِائَةُ رَاكِبٍ شَكَّ يَحْيَى فِيهَا فَرَاشُ الذَّهَبِ كَأَنَّ ثَمَرَهَا الْقِلاَلُ."],"takhrij":"حسن: رواه الترمذي (2541)، وهناد بن السري في الزهد (115)، وابن جرير في تفسيره (7235)، والحاكم (3748) كلهم من طريق يونس بن بكير، حدثنا محمد بن إسحاق، عن يحيى بن عباد بن عبد الله بن الزبير، عن أبيه، عن أسماء بنت أبي بكر، قالت: فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في ثمار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2541), Hannād ibn al-Sarī in al-Zuhd (115), and Ibn Jarīr in his Tafsīr (39-3822).","chapter_en":"What Has Been Narrated Concerning the Fruits of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr narrated: I heard the Messenger of Allah ﷺ mention Sidrat al-Muntahā and say: “A rider could travel beneath the shade of one of its branches for one hundred years—or one hundred riders could take shade beneath it,” Yaḥyā was uncertain which wording was used, “and upon it are golden moths, while its fruits are like large jars.”"]},"intro":{"ar":["قال تعالى:","﴿وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ كُلَّمَا رُزِقُوا مِنْهَا مِنْ ثَمَرَةٍ رِزْقًا قَالُوا هَٰذَا الَّذِي رُزِقْنَا مِنْ قَبْلُ وَأُتُوا بِهِ مُتَشَابِهًا وَلَهُمْ فِيهَا أَزْوَاجٌ مُطَهَّرَةٌ وَهُمْ فِيهَا خَالِدُونَ﴾ [سورة البقرة: ٢٥].","وقال تعالى:","﴿فِيهِمَا فَاكِهَةٌ وَنَخْلٌ وَرُمَّانٌ﴾ [سورة الرحمن: ٦٨]."],"en":["Allah, the Exalted, says:","“Give glad tidings to those who believe and perform righteous deeds that they will have Gardens beneath which rivers flow. Whenever they are provided with fruit from them, they will say: ‘This is what we were provided with before,’ and they will be given things resembling one another. They will have purified spouses therein, and they will remain therein forever.”","[al-Baqarah 2:25]","And He, the Exalted, says:","“In both of them are fruits, date-palms, and pomegranates.”","[al-Raḥmān 55:68]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13467],"tks":"حسن: رواه الترمذي (2541)، وهناد بن السري في الزهد (115)، وابن جرير في تفسيره (39-3822)."},{"num":16312,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: كَانَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُونَ: إِنَّ اللَّهَ يَنْفَعُنَا بِالْأَعْرَابِ وَمَسَائِلِهِمْ، أَقْبَلَ أَعْرَابِيٌّ يَوْمًا، فَقَالَ: يَا رَسُولَ اللَّهِ، لَقَدْ ذَكَرَ اللَّهُ فِي الْقُرْآنِ شَجَرَةً مُؤْذِيَةً، وَمَا كُنْتُ أَرَى أَنَّ فِي الْجَنَّةِ شَجَرَةٌ تُؤْذِي صَاحِبَهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَمَا هِيَ؟ قَالَ: السِّدْرُ، فَإِنَّ لَهَا شَوْكًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ﴿فِي سِدْرٍ مَخْضُودٍ﴾ [الواقعة: ٢٨] يَخْضِدُ اللَّهُ شَوْكَهُ فَيُجْعَلُ مَكَانَ كُلِّ شَوْكَةٍ ثَمَرَةٌ، فَإِنَّهَا تُنْبِتُ ثَمَرًا تُفْتَقُ الثَّمَرَةُ مَعَهَا عَنِ اثْنَيْنِ وَسَبْعِينَ لَوْنًا، مَا مِنْهَا لَوْنٌ يُشْبِهُ الْآخَرَ."],"takhrij":"صحيح: رواه الحاكم (3778) –وعنه البيهقي في البعث والنشور (264)-عن أبي العباس محمد بن يعقوب، ثنا الربيع بن سليمان، ثنا بشر بن بكر، ثنا صفوان بن عمرو، عن سليم بن عامر، عن أبي أمامة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ثمار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ḥākim (2/476), and from him by al-Bayhaqī in al-Baʿth wa-l-Nushūr (264).","chapter_en":"What Has Been Narrated Concerning the Fruits of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Abū Umāmah narrated: The Companions of the Messenger of Allah ﷺ used to say: “Allah benefits us through the Bedouins and the questions they ask.” One day a Bedouin came and said: “O Messenger of Allah, Allah has mentioned in the Qurʾān a tree that causes harm, and I never thought there would be a tree in Paradise that could harm its owner.” The Messenger of Allah ﷺ asked: “Which tree is that?” He replied: “The lote-tree, because it has thorns.” The Messenger of Allah ﷺ said: “‘Among thornless lote-trees.’ [al-Wāqiʿah 56:28] Allah will remove its thorns and place a fruit in the place of every thorn. It will bear fruits, each of which will open into seventy-two varieties, no variety resembling another.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13479],"tks":"صحيح: رواه الحاكم (3778)، وعنه البيهقي في البعث والنشور (264)."},{"num":16313,"demo":false,"sanad":"","matn":["عَنْ عُتْبَةَ بن عَبْدِ السُّلَمِيِّ قَالَ: كُنْتُ جَالِسًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ أَعْرَابِيٌّ، فَقَالَ: يَا رَسُولَ اللَّهِ، أَسْمَعُكَ تَذْكُرُ شَجَرَةً فِي الْجَنَّةِ لَا أَعْلَمُ فِي الدُّنْيَا أَكْثَرَ شَوْكًا مِنْهَا -يَعْنِي الطَّلْحَ-، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يَجْعَلُ مَكَانَ كُلِّ شَوْكَةٍ مثل خَصْوَةَ التَّيْسِ الْمَلْبُودِ -يَعْنِي الْخَصِيَّ-، فِيهَا سَبْعُونَ لَوْنًا مِنَ الطَّعَامِ لَا يُشْبِهُ لَوْنٌ الآخر."],"takhrij":"صحيح: رواه الطبراني في الكبير (17/ح 318)، ومسند الشاميين (492) –ومن طريقه أبو نعيم في الحلية (1423)، وفي صفة الجنة (347)- عن أبي زرعة عبد الرحمن بن عمرو الدمشقي، ثنا أبو مسهر ومحمد بن المبارك الصوري قالا: ثنا يحيى بن حمزة، حدثني ثور بن يزيد، عن حبيب بن عبيد, عن عتبة بن عبد السلمي، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ثمار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (17/130) and Musnad al-Shāmiyyīn (492).","chapter_en":"What Has Been Narrated Concerning the Fruits of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulamī narrated: I was sitting with the Messenger of Allah ﷺ when a Bedouin came and said: “O Messenger of Allah, I hear you mentioning a tree in Paradise, yet I know of no tree in this world with more thorns than it”—meaning the ṭalḥ tree. The Messenger of Allah ﷺ replied: “In place of every thorn there will be something like the testicle of a thick-haired he-goat—meaning a castrated one—containing seventy varieties of food, no one variety resembling another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (17/130)، ومسند الشاميين (492)."},{"num":16314,"demo":false,"sanad":"","matn":["عن عُتْبَةَ بن عَبْدِ السُّلَمِيِّ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَا حَوْضُكَ الَّذِي تُحَدِّثُ عَنْهُ؟ قَالَ: كَمَا بَيْنَ الْبَيْضَاءِ إِلَى بُصْرَى، يَمُدُّني اللَّهُ فِيهِ بِكُرَاعٍ لَا يَدْرِي إِنْسَانٌ مِمَّنْ خُلِقَ أَيْنَ طَرَفَيْهِ. فَكَبَّرَ عُمَرُ بْنُ الْخَطَّابِ، فَقَالَ: أَمَّا الْحَوْضُ فَيَرِدُ عَلَيْهِ فُقَرَاءُ الْمُهَاجِرِينَ، الَّذِينَ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ، ويَمُوتُونَ فِي سَبِيلِ اللَّهِ. فَأَرْجُو أَنْ يُورِثْني الْكُرَاعَ فَأَشْرَبَ مِنْهُ. وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ رَبِّي وَعَدَنِي أَنْ يُدْخِلَ الْجَنَّةَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ، ثُمَّ يَشْفَعُ كُلُّ أَلْفٍ لِسَبْعِينَ أَلْفًا، ثُمَّ يَحْثِي رَبِّي تَبَارَكَ وَتَعَالَى بِكَفَّيْهِ ثَلَاثَ حَثَيَاتٍ. فَكَبَّرَ عُمَرُ، وَقَالَ: إِنَّ السَّبْعِينَ الْأُولَى لَيُشَفِّعُهُمُ اللَّهُ فِي آبَائِهِمْ، وَأَبْنَائِهِمْ، وَعَشَائِرِهِمْ، وَأَرْجُو أَنْ يَجْعَلَنِي اللَّهُ فِي إِحْدَى الْحَثَيَاتِ الْأَوَاخِرِ. فَقَالَ الْأَعْرَابِيُّ: يَا رَسُولَ اللَّهِ، فِيهَا فَاكِهَةٌ؟ قَالَ: نَعَمْ، وَفِيهَا شَجَرَةٌ تُدْعَى طُوبَى هِيَ تُطَابِقُ الْفِرْدَوْسَ. فَقَالَ: أَيُّ شَجَرِ أَرْضِنَا تُشْبِهُ؟ قَالَ: لَيْسَ تُشْبِهُ مِنْ شَجَرِ أَرْضِكَ، وَلَكِنْ أَتَيْتَ الشَّامَ؟ قَالَ: لَا، يَا رَسُولَ اللَّهِ، قَالَ: فَإِنَّهَا تُشْبِهُ شَجَرَةً فِي الشَّامِ تُدْعَى الْجَوْزَةَ، تَنْبُتُ عَلَى سَاقٍ وَاحِدٍ، ثُمَّ يَنْتَشِرُ أَعْلَاهَا. قَالَ: فَمَا عِظَمُ أَصْلِهَا؟ قَالَ: لَوِ ارْتَحَلَتْ جَذَعَةٌ مِنْ إِبِلِ أَهْلِكَ لَمَا قَطَعَتْهَا حَتَّى تَنْكَسِرَ تَرْقُوَتُهَا هَرَمًا. قَالَ: فِيهَا عِنَبٌ؟ قَالَ: نَعَمْ. قَالَ: مَا عِظَمُ الْعُنْقُودِ مِنْهَا؟ قَالَ: مَسِيرَةُ شَهْرِ لِلْغُرَابِ الْأَبْقَعِ، لَا يَنْثَنِي وَلَا يَفْتُرُ. قَالَ: فَمَا عِظَمُ الْحِبَّةِ مِنْهُ؟ قَالَ: هَلْ ذَبَحَ أَبُوكَ مِنْ غَنَمِهِ شَيْئًا عَظِيمًا؟ قَالَ: نَعَمْ. قَالَ: فَسَلَخَ إِهَابَهَا فَأَعْطَاهُ أُمَّكَ، فَقَالَ: ادْبَغِي هَذَا، ثُمَّ افْرِي لَنَا مِنْهُ ذَنُوبًا نَرْوي بِهِ ماشِيَتَنَا؟ قَالَ: نَعَمْ. قَالَ: فَإِنَّ تِلْكَ الْحِبَّةَ تُشْبِعُنِي وَأَهْلَ بَيْتِي؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَعَامَّةَ عَشِيرَتِكَ."],"takhrij":"حسن: رواه الطبراني في الأوسط (404) –واللفظ له-، وفي الكبير (17/126-127)، وأحمد (17642) مختصرا كلهم من طريق عامر بن زيد البكالي، أنه سمع عتبة بن عبد السلمي، فذكر مثله. وصحّحه ابن حبان (6450).","grade":"حسن","chapter_ar":"باب ما جاء في ثمار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (404), whose wording this is, in al-Muʿjam al-Kabīr (17/126-127), and by Aḥmad (17642).","chapter_en":"What Has Been Narrated Concerning the Fruits of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulamī narrated: A Bedouin came to the Messenger of Allah ﷺ and asked: “What is this Ḥawḍ that you speak about?” He replied: “It is like the distance between al-Bayḍāʾ and Buṣrā. Allah supplies it for me through an inlet whose two ends no created person knows.” ʿUmar ibn al-Khaṭṭāb proclaimed Allah’s greatness. The Prophet ﷺ said: “As for the Ḥawḍ, the poor among the Muhājirūn who fight in the path of Allah and die in His path will come to it. I hope that the inlet will be granted to me so that I may drink from it.” The Messenger of Allah ﷺ also said: “My Lord has promised me that seventy thousand from my Ummah will enter Paradise without reckoning. Then every thousand of them will intercede for seventy thousand, and then my Lord, Blessed and Exalted, will take three handfuls with His two Hands.” ʿUmar proclaimed Allah’s greatness and said: “The first seventy thousand will surely be enabled by Allah to intercede for their fathers, children, and clans. I hope that Allah will place me among one of the last three handfuls.” The Bedouin asked: “O Messenger of Allah, does Paradise contain fruit?” He replied: “Yes. In it is a tree called Ṭūbā, which extends throughout al-Firdaws.” The Bedouin asked: “Which tree from our land does it resemble?” He replied: “It does not resemble any tree from your land. But have you been to al-Shām?” He replied: “No, O Messenger of Allah.” He said: “It resembles a tree in al-Shām called the walnut tree. It grows from a single trunk, then spreads out above.” He asked: “How large is its trunk?” He replied: “If a young she-camel from the camels of your family were to set out traveling around it, she would not complete the circuit before her collarbone broke from old age.” He asked: “Does it have grapes?” He replied: “Yes.” He asked: “How large is a cluster?” He replied: “A piebald crow could fly for a month without turning aside or tiring before traversing it.” He asked: “How large is a single grape?” The Prophet ﷺ asked: “Has your father ever slaughtered a large he-goat from his sheep?” He replied: “Yes.” He said: “Did he skin it and give its hide to your mother, saying: ‘Tan this, then make from it a large bucket with which we can give our livestock enough water’?” He replied: “Yes.” The Bedouin asked: “Would one such grape satisfy me and my household?” The Prophet ﷺ replied: “And most of your clan as well.”"]},"buhuth":{"en":["Regarding the phrase “through an inlet” (بكراع), the author explains that it means an extremity or channel of water from Paradise. In al-Nihāyah, regarding the hadith of the Ḥawḍ, the phrase means that Allah supplies it through an extremity of the water of Paradise. It is compared to the lower leg of an animal because of its relative narrowness."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13486],"tks":"حسن: رواه الطبراني في الأوسط (404) - واللفظ له -، وفي الكبير (17/126-127)، وأحمد (17642)."},{"num":16315,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال: كسفت الشمس على عهد رسول الله صلى الله عليه وسلم في يوم شديد الحر، فذكر الحديث وجاء فيه: ثم قال: إنه عرض علي كل شيء تولجونه، فعرضت علي الجنة، حتى لو تناولت منها قطفا أخذته -أو قال: تناولت منها قطفا- فقصرت يدي عنه...."],"takhrij":"صحيح: رواه مسلم في الكسوف (904) عن يعقوب بن إبراهيم الدورقي، حدثنا إسماعيل ابن علية، عن هشام الدستوائي، قال: حدثنا أبو الزبير، عن جابر، فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب ما جاء في ثمار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (904).","chapter_en":"What Has Been Narrated Concerning the Fruits of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The sun was eclipsed during the lifetime of the Messenger of Allah ﷺ on an intensely hot day. In the hadith, the Prophet ﷺ said: “Everything that you will enter was shown to me. Paradise was shown to me, to the point that if I had reached for a cluster from it, I would have taken it”—or he said: “I reached for a cluster from it, but my hand fell short of it…”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (904)."},{"num":16316,"demo":false,"sanad":"","matn":["عن عبد الله بن عباس قال: انخسفت الشمس على عهد رسول الله صلى الله عليه وسلم، فذكر الحديث في صلاة الخسوف، وجاء فيه: قالوا: يا رسول الله، رأيناك تناولت شيئا في مقامك، ثم رأيناك كعكعت؟ قال صلى الله عليه وسلم: إني رأيت الجنة، فتناولت عنقودا، ولو أصبته لأكلتم منه ما بقيت الدنيا... الحديث."],"takhrij":"متفق عليه: رواه البخاري في الخسوف (1052)، ومسلم في الخسوف (907) كلاهما من طريق زيد بن أسلم، عن عطاء بن يسار، عن عبد الله بن عباس، قال: فذكره في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب ما جاء في ثمار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1052) and Muslim (907).","chapter_en":"What Has Been Narrated Concerning the Fruits of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: The sun was eclipsed during the lifetime of the Messenger of Allah ﷺ. In the hadith concerning the eclipse prayer, they said: “O Messenger of Allah, we saw you reaching for something while standing, then we saw you draw back.” The Prophet ﷺ replied: “I saw Paradise and reached for a cluster of grapes. Had I obtained it, you would have eaten from it for as long as this world remained.” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1052)، ومسلم (907)."},{"num":16317,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: صَلَّيْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْحِ قَالَ: فَبَيْنَمَا هُوَ فِي الصَّلَاةِ مَدَّ يَدَهُ، ثُمَّ أَخَّرَهَا، فَلَمَّا فَرَغَ مِنَ الصَّلَاةِ، قُلْنَا: يَا رَسُولَ اللَّهِ، صَنَعْتَ فِي صَلَاتِكَ هَذِهِ مَا لَمْ تَصْنَعْ فِي صَلَاةٍ قَبْلَهَا. قَالَ: إِنِّي رَأَيْتُ الْجَنَّةَ قَدْ عُرِضَتْ عَلَيَّ، وَرَأَيْتُ فِيهَا.... قُطُوفُهَا دَانِيَةٌ، حَبُّهَا كَالدُّبَّاءِ، فَأَرَدْتُ أَنْ أَتَنَاوَلَ مِنْهَا، فَأُوحِيَ إِلَيْهَا أَنِ اسْتَأْخِرِي، فَاسْتَأْخَرَتْ، ثُمَّ عُرِضَتْ عَلَيَّ النَّارُ، بَيْنِي وَبَيْنَكُمْ حَتَّى رَأَيْتُ ظِلِّيَ وَظِلَّكُمْ، فَأَوْمَأْتُ إِلَيْكُمْ أَنِ اسْتَأْخَرُوا، فَأُوحِيَ إِلَيَّ أَنْ أَقِرَّهُمْ، فَإِنَّكَ أَسْلَمْتَ وَأَسْلَمُوا، وَهَاجَرْتَ وَهَاجَرُوا، وَجَاهَدْتَ وَجَاهَدُوا، فَلَمْ أَرَ لِي عَلَيْكُمْ فَضْلًا إِلَّا بِالنُّبُوَّةِ."],"takhrij":"حسن: رواه ابن خزيمة (892)، والطحاوي في شرح المشكل (5762)، والحاكم (4/456) كلهم من طريق ابن وهب، أخبرني معاوية بن صالح، حدثني عيسى بن عاصم، عن زر بن حبيش, عن أنس بن مالك، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ثمار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah (892), al-Ṭaḥāwī in Sharḥ al-Mushkil (5762), and al-Ḥākim (4/456).","chapter_en":"What Has Been Narrated Concerning the Fruits of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Mālik narrated: We prayed the dawn prayer with the Messenger of Allah ﷺ. While he was praying, he extended his hand and then drew it back. When he finished the prayer, we asked: “O Messenger of Allah, during this prayer you did something we had not seen you do before.” He replied: “I saw Paradise and saw within it a grapevine whose clusters were hanging down like gourds. I wanted to take from it, but it was revealed to it: ‘Move back,’ so it moved back. Then the Fire was shown to me between myself and you, until I could see my shadow and your shadows. I gestured to you to move back. Then it was revealed to me: ‘Keep them in their places. You submitted and they submitted; you emigrated and they emigrated; you struggled and they struggled.’ So I saw no superiority that I had over you except Prophethood.”"]},"buhuth":{"en":["As for the statement of Allah, the Exalted:","“Whenever they are provided with fruit from it, they will say: ‘This is what we were provided with before,’ and they will be given things resembling one another.”","[al-Baqarah 2:25]","the author explains that they will resemble one another in color and appearance while differing in taste and flavor.","If the fruits of this world had descended from Paradise together with Ādam, as is mentioned in some reports, then their tastes and flavors would not differ.","The statement:","“This is what we were provided with before”","means: in the worldly life, as stated by Ibn Masʿūd, Ibn ʿAbbās, and a group of the Companions and Followers. This is also the interpretation preferred by Ibn Jarīr in his Tafsīr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (892)، والطحاوي في شرح المشكل (5762)، والحاكم (4/456)."},{"num":16318,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: سَمِعَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ، بِقُدُومِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي أَرْضٍ يَخْتَرِفُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنِّي سَائِلُكَ عَنْ ثَلاَثٍ لاَ يَعْلَمُهُنَّ إِلاَّ نَبِيٌّ: فَمَا أَوَّلُ أَشْرَاطِ السَّاعَةِ؟ وَمَا أَوَّلُ طَعَامِ أَهْلِ الْجَنَّةِ؟ وَمَا يَنْزِعُ الْوَلَدُ إِلَى أَبِيهِ أَوْ إِلَى أُمِّهِ؟ قَالَ: أَخْبَرَنِي بِهِنَّ جِبْرِيلُ آنِفًا. قَالَ: جِبْرِيلُ؟! قَالَ: نَعَمْ. قَالَ: ذَاكَ عَدُوُّ الْيَهُودِ مِنَ الْمَلاَئِكَةِ. فَقَرَأَ هَذِهِ الآيَةَ: ﴿مَنْ كَانَ عَدُوًّا لِجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَى قَلْبِكَ﴾ [سورة البقرة: 97]}. أَمَّا أَوَّلُ أَشْرَاطِ السَّاعَةِ فَنَارٌ تَحْشُرُ النَّاسَ مِنَ الْمَشْرِقِ إِلَى الْمَغْرِبِ، وَأَمَّا أَوَّلُ طَعَامِ أَهْلِ الْجَنَّةِ فَزِيَادَةُ كَبِدِ حُوتٍ، وَإِذَا سَبَقَ مَاءُ الرَّجُلِ مَاءَ الْمَرْأَةِ نَزَعَ الْوَلَدَ، وَإِذَا سَبَقَ مَاءُ الْمَرْأَةِ نَزَعَتْ. قَالَ: أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ. يَا."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4480) عن عبدالله بن منير، عن عبدالله بن بكر، حدّثنا حميد، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ذكر أول طعام يأكله أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4480).","chapter_en":"The First Food Eaten by the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Anas narrated: ʿAbdullāh ibn Salām heard that the Messenger of Allah ﷺ had arrived while he was in a field gathering fruit. So he came to the Prophet ﷺ and said: “I will ask you about three things that none knows except a Prophet: What is the first sign of the Hour? What is the first food the people of Paradise will eat? And what causes a child to resemble his father or his mother?” The Prophet ﷺ said: “Jibrīl informed me of them just now.” He said: “Jibrīl?!” The Prophet ﷺ replied: “Yes.” He said: “He is the enemy of the Jews among the angels.” So the Prophet ﷺ recited: “Whoever is an enemy to Jibrīl—indeed, he has brought it down upon your heart.” [al-Baqarah 2:97] Then he said: “As for the first sign of the Hour, it is a fire that will gather the people from the east to the west. As for the first food of the people of Paradise, it will be the extra portion of a fish’s liver. And if the man’s fluid precedes the woman’s fluid, the child will resemble him; and if the woman’s fluid precedes, the child will resemble her.” ʿAbdullāh ibn Salām said: “I testify that there is no deity except Allah, and I testify that you are the Messenger of Allah…” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4480)."},{"num":16319,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَكُونُ الأَرْضُ يَوْمَ الْقِيَامَةِ خُبْزَةً وَاحِدَةً، يَتَكَفَّؤُهَا الْجَبَّارُ بِيَدِهِ، كَمَا يَكْفَأُ أَحَدُكُمْ خُبْزَتَهُ فِي السَّفَرِ، نُزُلاً لأَهْلِ الْجَنَّةِ. فَأَتَى رَجُلٌ مِنَ الْيَهُودِ، فَقَالَ: بَارَكَ الرَّحْمَنُ عَلَيْكَ، يَا أَبَا الْقَاسِمِ، أَلاَ أُخْبِرُكَ بِنُزُلِ أَهْلِ الْجَنَّةِ يَوْمَ الْقِيَامَةِ؟ قَالَ: بَلَى. قَالَ: تَكُونُ الأَرْضُ خُبْزَةً وَاحِدَةً كَمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَظَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِلَيْنَا، ثُمَّ ضَحِكَ حَتَّى بَدَتْ نَوَاجِذُهُ، ثُمَّ قَالَ: أَلاَ أُخْبِرُكَ بِإِدَامِهِمْ؟ قَالَ: إِدَامُهُمْ بَالاَمٌ وَنُونٌ. قَالُوا: وَمَا هَذَا؟ قَالَ: ثَوْرٌ وَنُونٌ، يَأْكُلُ مِنْ زَائِدَةِ كَبِدِهِمَا سَبْعُونَ أَلْفًا."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6520)، ومسلم في صفة القيامة (2792) كلاهما من طريق الليث بن سعد، حدثني خالد بن يزيد، عن سعيد بن أبي هلال، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب ذكر أول طعام يأكله أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6520) and Muslim (2792).","chapter_en":"The First Food Eaten by the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “On the Day of Resurrection, the earth will become a single loaf of bread. The Almighty will turn it over with His Hand just as one of you turns over his bread while traveling, as hospitality for the people of Paradise.” Then a Jewish man came and said: “May the Most Merciful bless you, O Abū al-Qāsim. Shall I tell you about the hospitality of the people of Paradise on the Day of Resurrection?” He replied: “Yes.” The man said: “The earth will become a single loaf of bread,” just as the Messenger of Allah ﷺ had said. The Messenger of Allah ﷺ looked at us and laughed until his molar teeth became visible. The man then said: “Shall I tell you what their accompanying dish will be?” He replied: “Yes.” He said: “Their accompanying dish will be bālām and nūn.” They asked: “What are those?” He replied: “An ox and a fish. Seventy thousand people will eat from the extra portions of their livers.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6520)، ومسلم (2792)."},{"num":16320,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُنْتُ قَائِمًا عِنْدَ رَسُولِ اللَّهِ، فَجَاءَ حَبْرٌ مِنْ أَحْبَارِ الْيَهُودِ، فَقَالَ: السَّلَامُ عَلَيْكَ يَا مُحَمَّدُ! فَدَفَعْتُهُ دَفْعَةً كَادَ يُصْرعُ مِنْهَا. فَقَالَ: لِمَ تَدْفَعُنِي؟ فَقُلْتُ: أَلَا تَقُولُ: يَا رَسُولَ اللَّهِ؟ فَقَالَ الْيَهُودِيُّ: إِنَّمَا نَدْعُوهُ بِاسْمِهِ الَّذِي سَمَّاهُ بِهِ أَهْلُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إنّ اسْمِي مُحَمَّدٌ الَّذِي سَمَّانِي بِهِ أَهْلِي. فَقَالَ الْيَهُودِيُّ: جئتُ أَسْأَلُكَ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَيَنْفَعُكَ شيءٌ إِنْ حدّثْتُك؟. قَالَ: أَسْمَعُ بِأُذُنَيَّ، فَنَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بعُودٍ مَعَهُ فَقَالَ: سَلْ. فَقَالَ الْيَهُودِيُّ: أَيْنَ يَكُونُ النّاسُ يَوْمَ تُبدَّل الْأَرْضُ غيرَ الْأَرْضِ وَالسَّمَاوَاتُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هُمْ فِي الظُّلْمة دُونَ الْجِسْرِ. قَالَ: فَمَنْ أوّل النَّاسِ إِجَازَةً؟ قَالَ: فُقَرَاءُ الْمُهَاجِرِينَ. قَالَ الْيَهُودِيُّ: فَمَا تُحْفَتُهُمْ حِينَ يَدْخُلُونَ الْجَنَّةَ؟ قَالَ: زِيَادَةُ كبدِ النُّون. قَالَ: فَمَا غِذَاؤُهُمْ عَلَى إِثْرِهَا؟ قَالَ: يُنْحَرُ لَهُمْ ثورُ الْجَنَّةِ الَّذِي كَانَ يَأْكُلُ مِنْ أَطْرَافِهَا. قَالَ: فَمَا شَرَابُهُمْ عَلَيْهِ؟ قَالَ: مِنْ عَيْنٍ فِيهَا تُسمّى سَلْسَبِيلًا. قَالَ: صَدَقْتَ.... الحديث."],"takhrij":"صحيح: رواه مسلم في الحيض (315) من حديث أبي سلاّم قال: حدّثني أبو أسماء الرّحبي، أنّ ثوبان مولى رسول الله صلى الله عليه وسلم قال: فذكر الحديث في سياق طويل.","grade":"صحيح","chapter_ar":"باب ذكر أول طعام يأكله أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (315).","chapter_en":"The First Food Eaten by the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":19,"content":{"translation":{"en":["Thawbān, the freedman of the Messenger of Allah ﷺ, narrated: I was standing with the Messenger of Allah ﷺ when a Jewish scholar came and said: “Peace be upon you, O Muḥammad.” I pushed him so forcefully that he nearly fell. He asked: “Why did you push me?” I said: “Why do you not say, ‘O Messenger of Allah’?” The Jewish man replied: “We only call him by the name his family gave him.” The Messenger of Allah ﷺ said: “My name is Muḥammad, the name by which my family named me.” The Jewish man said: “I have come to ask you questions.” The Messenger of Allah ﷺ asked: “Will it benefit you if I answer you?” He replied: “I will listen with my ears.” The Messenger of Allah ﷺ began drawing with a stick he had and said: “Ask.” The Jewish man asked: “Where will the people be on the Day when the earth is changed into another earth and the heavens as well?” The Messenger of Allah ﷺ replied: “They will be in darkness before the bridge.” He asked: “Who will be the first people to cross?” He replied: “The poor among the Muhājirūn.” The Jewish man asked: “What will be their welcoming food when they enter Paradise?” He replied: “The extra portion of the fish’s liver.” He asked: “What will their food be after that?” He replied: “The ox of Paradise that used to graze along its edges will be slaughtered for them.” He asked: “What will they drink with it?” He replied: “From a spring therein called Salsabīl.” The Jewish man said: “You have spoken the truth…” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (315)."},{"num":16321,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا الْكَوْثَرُ؟ قَالَ: ذَاكَ نَهْرٌ أَعْطَانِيهِ اللَّهُ يَعْنِي فِي الْجَنَّةِ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَحْلَى مِنَ الْعَسَلِ، فِيهَا طَيْرٌ أَعْنَاقُهَا كَأَعْنَاقِ الْجُزُرِ. قَالَ عُمَرُ: إِنَّ هَذِهِ لَنَاعِمَةٌ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَكَلَتُهَا أَنْعَمُ مِنْهَا."],"takhrij":"حسن: رواه الترمذيّ (2542) عن عبد بن حميد، أخبرنا عبدالله بن مسلمة، عن محمد بن عبدالله بن مسلم، عن أبيه، عن أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في طير الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2542).","chapter_en":"What Has Been Narrated Concerning the Birds of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":20,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Messenger of Allah ﷺ was asked: “What is al-Kawthar?” He replied: “It is a river Allah has given me—meaning in Paradise—whiter than milk and sweeter than honey. In it are birds whose necks are like the necks of camels.” ʿUmar said: “Those must indeed be delightful!” The Messenger of Allah ﷺ replied: “Those who eat them are even better than they are.”"]},"intro":{"ar":["قال تعالى:","﴿وَلَحْمِ طَيْرٍ مِمَّا يَشْتَهُونَ﴾ [الواقعة: ٢١]."],"en":["Allah, the Exalted, says:","“And the meat of birds from whatever they desire.”","[al-Wāqiʿah 56:21]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[809,13478],"tks":"حسن: رواه الترمذي (2542)."},{"num":16322,"demo":false,"sanad":"","matn":["عَنْ حَكِيمِ بْنِ مُعَاوِيَةَ، عَنْ أَبِيهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ إِنَّ فِي الْجَنَّةِ بَحْرَ الْمَاءِ، وَبَحْرَ الْعَسَلِ، وَبَحْرَ اللَّبَنِ، وَبَحْرَ الْخَمْرِ، ثُمَّ تُشَقَّقُ الأَنْهَارُ بَعْدُ."],"takhrij":"حسن: رواه الترمذي (2571)، وأحمد (20052) كلاهما من طريق يزيد بن هارون قال: أخبرنا الجريري، عن حكيم بن معاوية، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2571) and Aḥmad (20052).","chapter_en":"What Has Been Narrated Concerning the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Muʿāwiyah ibn Ḥaydah al-Qushayrī narrated: I heard the Messenger of Allah ﷺ say: “In Paradise there is a sea of water, a sea of honey, a sea of milk, and a sea of wine. Then the rivers branch out from them afterward.”"]},"intro":{"ar":["قال تعالى:","﴿مَثَلُ الْجَنَّةِ الَّتِي وُعِدَ الْمُتَّقُونَ فِيهَا أَنْهَارٌ مِنْ مَاءٍ غَيْرِ آسِنٍ وَأَنْهَارٌ مِنْ لَبَنٍ لَمْ يَتَغَيَّرْ طَعْمُهُ وَأَنْهَارٌ مِنْ خَمْرٍ لَذَّةٍ لِلشَّارِبِينَ وَأَنْهَارٌ مِنْ عَسَلٍ مُصَفًّى وَلَهُمْ فِيهَا مِنْ كُلِّ الثَّمَرَاتِ وَمَغْفِرَةٌ مِنْ رَبِّهِمْ﴾ [محمد: ١٥]."],"en":["Allah, the Exalted, says:","“The description of the Paradise promised to the righteous is that in it are rivers of water whose taste and smell do not change, rivers of milk whose taste does not change, rivers of wine delightful to those who drink it, and rivers of purified honey. They will have therein every kind of fruit and forgiveness from their Lord.”","[Muḥammad 47:15]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2571)، وأحمد (20052)."},{"num":16323,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنَّ فِي الْجَنَّةِ مِائَةَ دَرَجَةٍ، أَعَدَّهَا اللَّهُ لِلْمُجَاهِدِينَ فِي سَبِيلِهِ، كُلُّ دَرَجَتَيْنِ مَا بَيْنَهُمَا كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، فَإِذَا سَأَلْتُمُ اللَّهَ فَسَلُوهُ الْفِرْدَوْسَ، فَإِنَّهُ أَوْسَطُ الْجَنَّةِ، وَأَعْلَى الْجَنَّةِ، وَفَوْقَهُ عَرْشُ الرَّحْمَنِ، وَمِنْهُ تَفَجَّرُ أَنْهَارُ الْجَنَّةِ."],"takhrij":"صحيح: رواه البخاري في التوحيد (7423) عن إبراهيم بن المنذر، حدثني محمد بن فليح، قال: حدثني أبي، حدثني هلال، عن عطاء بن يسار، عن أبي هريرة، فذكره في سياق طويل.","grade":"صحيح","chapter_ar":"باب ما جاء في أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7423).","chapter_en":"What Has Been Narrated Concerning the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “In Paradise there are one hundred ranks which Allah has prepared for those who strive in His path. The distance between every two ranks is like the distance between the heaven and the earth. So when you ask Allah, ask Him for al-Firdaws, for it is the central and highest part of Paradise. Above it is the Throne of the Most Merciful, and from it the rivers of Paradise spring forth.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7423)."},{"num":16324,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فِي الْجَنَّةِ مِائَةُ دَرَجَةٍ، مَا بَيْنَ كُلِّ دَرَجَتَيْنِ كَمَا بَيْنَ السَّمَاءِ وَالأَرْضِ، وَالْفِرْدَوْسُ أَعْلاَهَا دَرَجَةً وَمِنْهَا تُفَجَّرُ أَنْهَارُ الْجَنَّةِ الأَرْبَعَةُ، وَمِنْ فَوْقِهَا يَكُونُ الْعَرْشُ، فَإِذَا سَأَلْتُمُ اللَّهَ، فَسَلُوهُ الْفِرْدَوْسَ."],"takhrij":"صحيح: رواه الترمذي (2531)، وابن خزيمة في \"التوحيد\" (184)، والحاكم (269) كلهم من طريق همام، حدثنا زيد بن أسلم، عن عطاء بن يسار، عن عبادة بن الصامت، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2531), Ibn Khuzaymah in al-Tawḥīd (184), and al-Ḥākim (1/80).","chapter_en":"What Has Been Narrated Concerning the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated that the Messenger of Allah ﷺ said: “In Paradise there are one hundred ranks, the distance between every two ranks being like the distance between the heaven and the earth. Al-Firdaws is the highest of them, and from it the four rivers of Paradise spring forth. Above it is the Throne. So when you ask Allah, ask Him for al-Firdaws.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[471,12730,16301],"tks":"صحيح: رواه الترمذي (2531)، وابن خزيمة في “التوحيد” (184)، والحاكم (269)."},{"num":16325,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْهَارُ الْجَنَّةِ تَخْرُجُ مِنْ تَحْتِ تِلَالِ، أَوْ مِنْ تَحْتِ جِبَالِ مِسْكٍ."],"takhrij":"حسن: رواه ابن أبي حاتم كما في تفسير ابن كثير (8/386) وابن حبان (7408)، وأبو نعيم في صفة الجنة (313) كلهم من طرق عن أسد بن موسى، حدثنا عبد الرحمن بن ثابت بن ثوبان، حدثنا عطاء بن قرة، عن عبد الله بن ضمرة, عن أبي هريرة، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Ḥātim, as cited in Ibn Kathīr’s Tafsīr (8/386), Ibn Ḥibbān (7408), and Abū Nuʿaym in Ṣifat al-Jannah (313).","chapter_en":"What Has Been Narrated Concerning the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The rivers of Paradise emerge from hills—or from beneath mountains—of musk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي حاتم كما في تفسير ابن كثير (8/386) وابن حبان (7408)، وأبو نعيم في صفة الجنة (313)."},{"num":16326,"demo":false,"sanad":"","matn":["عن أبي أمامة الباهلي قال: سمعت رسول الله صلى الله عليه وسلم يقول: بينا أنا نائم إذ أتاني رجلان، فأخذا بضبعي، فأتيا بي جبلا وعرا فذكر حديثا طويلا وجاء فيه: فإذا أنا بالغلمان يلعبون بين نهرين، فقلت: من هؤلاء؟ قال: هؤلاء ذراري المؤمنين، ثم شرف بي شرفا، فإذا أنا بثلاثة يشربون من خمر لهم، فقلت: من هؤلاء؟ قالوا: هذا إبراهيم، وموسى، وعيسى، وهم ينظرونك."],"takhrij":"صحيح: رواه ابن خزيمة (1986)، وعنه ابن حبان (7491)، والحاكم (2837)، وعنه البيهقي (8006) كلهم من حديث بشر بن بكر، حدثني ابن جابر، حدثني سليم بن عامر، حدثني أبو أمامة الباهلي، فذكره في سياق طويل.","grade":"صحيح","chapter_ar":"باب ما جاء في أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Khuzaymah (1986), from him by Ibn Ḥibbān (7491), and by al-Ḥākim (1/430).","chapter_en":"What Has Been Narrated Concerning the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":21,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī narrated: I heard the Messenger of Allah ﷺ say: “While I was sleeping, two men came to me, took me by my upper arms, and brought me to a rugged mountain.” He then mentioned a lengthy hadith, in which he said: “Then I saw young boys playing between two rivers. I asked: ‘Who are these?’ He said: ‘These are the children of the believers.’ Then I was taken up to a high place, and I saw three men drinking wine of their own. I asked: ‘Who are these?’ They said: ‘This is Ibrāhīm, Mūsā, and ʿĪsā, and they are waiting for you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة (1986)، وعنه ابن حبان (7491)، والحاكم (2837)."},{"num":16327,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  سَيْحَانُ وَجَيْحَانُ، وَالْفُرَاتُ وَالنِّيلُ، كُلٌّ مِنْ أَنْهَارِ الْجَنَّةِ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها (2839) من طرق عن عبيدالله بن عمر، عن خُبيب بن عبد الرحمن، عن حفص بن عاصم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما في الدنيا من أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2839).","chapter_en":"Rivers in This World That Are from the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Sayḥān, Jayḥān, the Euphrates, and the Nile are all among the rivers of Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2839)."},{"num":16328,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فُجِّرَتْ أَرْبَعَةُ أَنْهَارٍ مِنَ الْجَنَّةِ: الْفُرَاتُ، وَالنِّيلُ، وَسَيْحَانُ، وَجَيْحَانُ."],"takhrij":"حسن: رواه أحمد (7544)، وأبو يعلى (5921) كلاهما من طرق عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما في الدنيا من أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (7544) and Abū Yaʿlā (5921).","chapter_en":"Rivers in This World That Are from the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Four rivers have been caused to flow from Paradise: the Euphrates, the Nile, Sayḥān, and Jayḥān.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7544)، وأبو يعلى (5921)."},{"num":16329,"demo":false,"sanad":"","matn":["عَنْ مَالِكِ بن صَعْصَعَةَ قَالَ: فَذَكَرَ حَدِيثَ الإِسْرَاءِ وَالمِعْرَاجِ، وَجَاءَ فِيهِ: وَرُفِعَتْ لِي سِدْرَةُ الْمُنْتَهَى، فَإِذَا نَبِقُهَا كَأَنَّهُ قِلاَلُ هَجَر، وَوَرَقُهَا كَأَنَّهُ آذَانُ الْفُيُولِ، فِي أَصْلِهَا أَرْبَعَةُ أَنْهَارٍ: نَهْرَانِ بَاطِنَانِ، وَنَهْرَانِ ظَاهِرَانِ، فَسَأَلْتُ جِبْرِيلَ، فَقَالَ: أَمَّا الْبَاطِنَانِ: فَفِي الْجَنَّةِ، وَأَمَّا الظَّاهِرَانِ: النِّيلُ وَالْفُرَاتُ. الحديث."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3207)، ومسلم في الإيمان (164) كلاهما من طريق سعيد، حدثنا قتادة قال: حدثنا أنس بن مالك، عن مالك بن صعصعة، فذكره. واللفظ للبخاري، وفي مسلم بلفظ: وحدث نبي الله صلى الله عليه وسلم أنه رأى أربعة أنهار يخرج من أصلها نهران ظاهران، ونهران باطنان، فقلت: يا جبريل، ما هذه الأنهار؟ قال: أما النهران الباطنان فنهران في الجنة، وأما الظاهران: فالنيل والفرات... الحديث.","grade":"متفق عليه","chapter_ar":"باب ما في الدنيا من أنهار الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3207) and Muslim (164). The wording above is al-Bukhārī’s.","chapter_en":"Rivers in This World That Are from the Rivers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":22,"content":{"translation":{"en":["Mālik ibn Ṣaʿṣaʿah narrated, while mentioning the hadith of al-Isrāʾ and al-Miʿrāj: “Sidrat al-Muntahā was raised before me. Its fruits were like the large jars of Hajar, and its leaves were like the ears of elephants. At its base were four rivers: two hidden rivers and two visible rivers. I asked Jibrīl about them. He said: ʿAs for the two hidden rivers, they are in Paradise. As for the two visible rivers, they are the Nile and the Euphrates.’” The hadith continues."]},"buhuth":{"ar":["وفي مسلم بلفظ:","وحدث نبي الله ﷺ أنه رأى أربعة أنهار يخرج من أصلها نهران ظاهران، ونهران باطنان، فقلت: يا جبريل، ما هذه الأنهار؟ قال: أما النهران الباطنان فنهران في الجنة، وأما الظاهران: فالنيل والفرات….","الحديث."],"en":["Muslim narrates it with the wording:","“The Prophet of Allah ﷺ related that he saw four rivers emerging from its base, two visible and two hidden. I asked: ‘O Jibrīl, what are these rivers?’ He replied: ‘The two hidden rivers are two rivers in Paradise, while the two visible rivers are the Nile and the Euphrates…’”","The hadith continues."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3207)، ومسلم (164). واللفظ للبخاري."},{"num":16330,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَزْوَاجَ أَهْلِ الْجَنَّةِ لَيُغَنِّينَ أَزْوَاجَهُنَّ بِأَحْسَنِ أَصْوَاتٍ سَمِعَهَا أَحَدٌ قَطُّ. إِنَّ مِمَّا يُغَنِّينَ بِهِ: نَحْنُ الْخَيْرَاتُ الْحِسَانْ. أَزْوَاجُ قَوْمٍ كِرَامْ. يَنْظُرْنَ بِقُرَّةِ أَعْيَانْ. وَإِنَّ مِمَّا يُغَنِّينَ بِهِ: نَحْنُ الْخَالِدَاتُ فَلَا يَمُتْنَهْ. نَحْنُ الْآمِنَاتُ فَلَا يَخَفْنَهْ. نَحْنُ الْمُقِيمَاتُ فَلَا يَظْعَنَّهْ."],"takhrij":"صحيح: رواه الطبراني في الأوسط (4914)، والصغير (1/259-260) –وعنه أبو نعيم في صفة الجنة (322)- عن أبي رفاعة عمارة بن وثيمة بن موسى بن الفرات المصري قال: حدثنا سعيد بن أبي مريم قال: أخبرنا محمد بن جعفر، عن زيد بن أسلم، عن ابن عمر قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب سماع الصوت الحسن في الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (4917) and al-Muʿjam al-Ṣaghīr (1/259-260), and from him by Abū Nuʿaym in Ṣifat al-Jannah (322).","chapter_en":"Hearing Beautiful Voices in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":23,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “The wives of the people of Paradise will sing to their husbands with the most beautiful voices anyone has ever heard. Among what they will sing is: ‘We are the good and beautiful ones, wives of noble men, looking with eyes full of delight.’ And among what they will sing is: ‘We are the everlasting ones and will never die. We are the secure ones and will never fear. We are the abiding ones and will never depart.’”"]},"intro":{"ar":["قال تعالى:","﴿ادْخُلُوا الْجَنَّةَ أَنْتُمْ وَأَزْوَاجُكُمْ تُحْبَرُونَ﴾ [الزخرف: ٧٠].","وقال تعالى:","﴿فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ﴾ [سورة الروم: ١٥].","قوله: ﴿يُحْبَرُونَ﴾ من الحبور، وهو السرور الشديد، يقال: حبره إذا سره سرورًا تهلل به وجهه، وظهر فيه أثره. ومن نعم الجنة أن أهلها يسمعون الصوت الحسن، يتهلل منه وجوههم، ولذا فسر بعض أهل العلم الحبور بسماع الصوت الحسن.","قال يحيى بن أبي كثير، في قوله عز وجل: ﴿فَهُمْ فِي رَوْضَةٍ يُحْبَرُونَ﴾ قال: السماع. ومعنى السماع مثل ما ورد في الحديث أن الحور العين يرفعن بأصواتهن. رواه الترمذي (٢٥٦٥)."],"en":["Allah, the Exalted, says:","“Enter Paradise, you and your spouses, rejoicing.”","[al-Zukhruf 43:70]","And He, the Exalted, says:","“As for those who believed and performed righteous deeds, they will be rejoicing in a garden.”","[al-Rūm 30:15]","The word “yuḥbarūn” comes from ḥubūr, meaning intense joy. It is said, “He delighted him,” when he brought him such joy that his face became radiant and the effect of that joy became visible upon him.","Among the blessings of Paradise is that its people will hear beautiful voices that cause their faces to brighten with delight. For this reason, some scholars interpreted ḥubūr as hearing beautiful voices.","Yaḥyā ibn Abī Kathīr said concerning the statement of Allah, Mighty and Majestic:","“They will be rejoicing in a garden,”","that it means hearing.","The meaning of this hearing is like what is mentioned in the hadith that the ḥūr al-ʿīn will raise their voices in song. Narrated by al-Tirmidhī (2565)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الأوسط (4914)، والصغير (1/259-260) - وعنه أبو نعيم في صفة الجنة (322)."},{"num":16331,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِنَّ فِي الْجَنَّةِ لَسُوقًا، يَأْتُونَهَا كُلَّ جُمُعَةٍ، فَتَهُبُّ رِيحُ الشَّمَالِ فَتَحْثُو فِي وُجُوهِهِمْ وَثِيَابِهِمْ، فَيَزْدَادُونَ حُسْنًا وَجَمَالًا، فَيَرْجِعُونَ إِلَى أَهْلِيهِمْ وَقَدِ ازْدَادُوا حُسْنًا وَجَمَالًا، فَيَقُولُ لَهُمْ أَهْلُوهُمْ: وَاللهِ لَقَدِ ازْدَدْتُمْ بَعْدَنَا حُسْنًا وَجَمَالًا، فَيَقُولُونَ: وَأَنْتُمْ، وَاللهِ لَقَدِ ازْدَدْتُمْ بَعْدَنَا حُسْنًا وَجَمَالًا."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها (2833) عن سعيد بن عبد الجبار البصري، حدثنا حماد بن سلمة، عن ثابت البناني، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب سوق الجنة وما ينالون فيها من النعيم والجمال","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2833).","chapter_en":"The Market of Paradise and the Bliss and Beauty Its People Will Attain There","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":24,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Indeed, in Paradise there is a market which they will visit every Friday. Then a northern wind will blow over their faces and clothes, and they will increase in beauty and splendor. They will return to their families having increased in beauty and splendor, and their families will say to them: ‘By Allah, you have increased in beauty and splendor since you left us.’ They will reply: ‘And you, by Allah, have also increased in beauty and splendor since we left you.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2833)."},{"num":16332,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ أَنَّ مَا يُقِلُّ ظُفُرٌ مِمَّا فِي الْجَنَّةِ بَدَا لَتَزَخْرَفَتْ لَهُ مَا بَيْنَ خَوَافِقِ السَّمَوَاتِ وَالأَرْضِ، وَلَوْ أَنَّ رَجُلاً مِنْ أَهْلِ الْجَنَّةِ اطَّلَعَ فَبَدَا أَسَاوِرُهُ لَطَمَسَ ضَوْءَ الشَّمْسِ كَمَا تَطْمِسُ الشَّمْسُ ضَوْءَ النُّجُومِ."],"takhrij":"حسن: رواه الترمذي (2538)، وأحمد (1467)، والبغوي في شرح السنة (4377) كلهم من طريق عبد الله بن المبارك -وهو في زهده (416) - قال: أخبرنا بن لهيعة، عن يزيد بن أبي حبيب، عن داود بن عامر بن سعد بن أبي وقاص، عن أبيه، عن جده، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حلية أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2538), Aḥmad (1467), and al-Baghawī in Sharḥ al-Sunnah (4377).","chapter_en":"What Has Been Narrated Concerning the Adornment of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ narrated that the Prophet ﷺ said: “If even an amount from Paradise as small as what a fingernail could carry were to appear, everything between the horizons of the heavens and the earth would be adorned because of it. And if a man from the people of Paradise were to look out and his bracelets became visible, their light would overwhelm the light of the sun just as the sun overwhelms the light of the stars.”"]},"intro":{"ar":["قال تعالى:","﴿إِنَّ اللَّهَ يُدْخِلُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِنْ ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ﴾ [الحج: ٢٣].","وقال تعالى:","﴿أُولَٰئِكَ لَهُمْ جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهَارُ يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِنْ ذَهَبٍ وَيَلْبَسُونَ ثِيَابًا خُضْرًا مِنْ سُنْدُسٍ وَإِسْتَبْرَقٍ مُتَّكِئِينَ فِيهَا عَلَى الْأَرَائِكِ نِعْمَ الثَّوَابُ وَحَسُنَتْ مُرْتَفَقًا﴾ [الكهف: ٣١]."],"en":["Allah, the Exalted, says:","“Indeed, Allah will admit those who believe and perform righteous deeds into Gardens beneath which rivers flow. They will be adorned therein with bracelets of gold and pearls, and their clothing therein will be silk.”","[al-Ḥajj 22:23]","And He, the Exalted, says:","“Those will have Gardens of perpetual residence beneath which rivers flow. They will be adorned therein with bracelets of gold and will wear green garments of fine silk and brocade, reclining therein upon couches. Excellent is the reward, and beautiful is the resting place.”","[al-Kahf 18:31]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2538)، وأحمد (1467)، والبغوي في شرح السنة (4377)."},{"num":16333,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ قَالَ:  كُنْتُ خَلْفَ أَبِي هُرَيْرَةَ، وَهُوَ يَتَوَضَّأُ لِلصَّلَاةِ، فَكَانَ يَمُدُّ يَدَهُ حَتَّى تَبْلُغَ إِبْطَهُ، فَقُلْتُ لَهُ: يَا أَبَا هُرَيْرَةَ، مَا هَذَا الْوُضُوءُ؟ فَقَالَ: يَا بَنِي فَرُّوخَ، أَنْتُمْ هَا هُنَا، لَوْ عَلِمْتُ أَنَّكُمْ هَا هُنَا مَا تَوَضَّأْتُ هَذَا الْوُضُوءَ، سَمِعْتُ خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: تَبْلُغُ الْحِلْيَةُ مِنَ الْمُؤْمِنِ حَيْثُ يَبْلُغُ الْوَضُوءُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (250) عن قتيبة بن سعيد، حدثنا خلف، عن أبي مالك الأشجعي، عن أبي حازم، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حلية أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (250).","chapter_en":"What Has Been Narrated Concerning the Adornment of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abū Ḥāzim narrated: I was behind Abū Hurayrah while he was performing wuḍūʾ for prayer. He washed his arm until the water reached his armpit. I asked: “O Abū Hurayrah, what kind of wuḍūʾ is this?” He replied: “O sons of Farrūkh, are you here? Had I known that you were here, I would not have performed wuḍūʾ like this before you. I heard the Prophet ﷺ, my close friend, say: ‘The adornment of the believer will reach as far as the water of his wuḍūʾ reaches.’”"]}},"tuhfa":{},"full":1,"rep":[12781,13138],"tks":"صحيح: رواه مسلم (250)."},{"num":16334,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَرَّهُ أَنْ يَسْقِيَهُ اللَّهُ عَزَّ وَجَلَّ الْخَمْرَ فِي الْآخِرَةِ، فَلْيَتْرُكْهَا فِي الدُّنْيَا، وَمَنْ سَرَّهُ أَنْ يَكْسُوَهُ اللَّهُ الْحَرِيرَ فِي الْآخِرَةِ، فَلْيَتْرُكْهُ فِي الدُّنْيَا، أَنْهَارَ الْجَنَّةِ تَفْجُرُ مِنْ تَحْتِ تِلَالٍ -أَوْ من تَحْتَ جِبَالِ- الْمِسْكِ، وَلَوْ كَانَ أَدْنَى أَهْلِ الْجَنَّةِ حِلْيَةً عَدَلَتْ بِحِلْيَةِ أَهْلِ الدُّنْيَا جَمِيعًا، لَكَانَ مَا يُحَلِّيهِ اللَّهُ عَزَّ وَجَلَّ بِهِ فِي الْآخِرَةِ أَفْضَلُ مِنْ حِلْيَةِ أَهْلِ الدُّنْيَا جَمِيعًا."],"takhrij":"حسن: رواه البيهقي في البعث والنشور (266) عن أبي عبد الله الحافظ، ومحمد بن موسى بن الفضل قالا: حدثنا أبو العباس محمد بن يعقوب، حدثنا الربيع بن سليمان، حدثنا أسد بن موسى، حدثنا ابن ثوبان (وهو عبد الرحمن بن ثابت بن ثوبان)، عن عطاء بن قرة، عن عبد الله بن ضمرة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في حلية أهل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqī in al-Baʿth wa-l-Nushūr (266).","chapter_en":"What Has Been Narrated Concerning the Adornment of the People of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever would be pleased for Allah, Mighty and Majestic, to give him wine to drink in the Hereafter should leave it in this world. And whoever would be pleased for Allah to clothe him in silk in the Hereafter should leave it in this world. The rivers of Paradise gush forth from beneath hills—or from beneath mountains—of musk. If even the adornment of the lowest-ranking person in Paradise were weighed against the adornment of all the people of this world, what Allah, Mighty and Majestic, adorns him with in the Hereafter would be better than all the adornment of the people of this world.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في البعث والنشور (266)."},{"num":16335,"demo":false,"sanad":"","matn":["عن سهل بن سعد الساعدي يقول: شهدت من رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مجلسا وصف فيه الجنة حتى انتهى، ثم قال صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ في آخر حديثه: فيها ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر ثم اقترأ هذه الآية: ﴿تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ (16) فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ (17)﴾ [السجدة: ١٦ – ١٧]."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2825) من طرق عن ابن وهب، حدثني أبو صخر، أن أبا حازم، حدثه قال: سمعت سهل بن سعد الساعدي يقول فذكره.","grade":"صحيح","chapter_ar":"باب في الجنة ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2825).","chapter_en":"In Paradise Is What No Eye Has Seen, No Ear Has Heard, and What Has Never Occurred to a Human Heart","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["Sahl ibn Saʿd al-Sāʿidī said: I attended a gathering with the Messenger of Allah ﷺ in which he described Paradise until he finished. At the end of his speech, he said: “In it is what no eye has seen, no ear has heard, and what has never occurred to a human heart.” Then he recited: “Their sides forsake their beds as they call upon their Lord in fear and hope, and they spend from what We have provided them. No soul knows what comfort of the eyes has been hidden for them as a reward for what they used to do.” [al-Sajdah 32:16-17]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2825)."},{"num":16336,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ اللَّهُ تَعَالَى: أَعْدَدْتُ لِعِبَادِي الصَّالِحِينَ مَا لاَ عَيْنٌ رَأَتْ، وَلاَ أُذُنٌ سَمِعَتْ، وَلاَ خَطَرَ عَلَى قَلْبِ بَشَرٍ، ذُخْرًا، بَلْهَ مَا أُطْلِعْتُمْ عَلَيْهِ. ثُمَّ قَرَأَ: ﴿فَلاَ تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ﴾ [سورة السجدة: 17]}."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4780)، ومسلم في الجنة (4:2824) كلاهما من طريق الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب في الجنة ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4780) and Muslim (4:2824).","chapter_en":"In Paradise Is What No Eye Has Seen, No Ear Has Heard, and What Has Never Occurred to a Human Heart","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah, the Exalted, says: ‘I have prepared for My righteous servants what no eye has seen, no ear has heard, and what has never occurred to a human heart—as a treasure beyond what you have been shown.’” Then he recited: “No soul knows what comfort of the eyes has been hidden for them as a reward for what they used to do.” [al-Sajdah 32:17]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4780)، ومسلم (4:2824)."},{"num":16337,"demo":false,"sanad":"","matn":["عن الْمُغِيرَةِ بن شُعْبَةَ يرفعه قَالَ: سَأَلَ مُوسَى رَبَّهُ: مَا أَدْنَى أَهْلِ الْجَنَّةِ مَنْزِلَةً؟ قَالَ: هُوَ رَجُلٌ يَجِيءُ بَعْدَمَا أُدْخِلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ، فَيُقَالُ لَهُ: ادْخُلِ الْجَنَّةَ، فَيَقُولُ: أَيْ رَبِّ، كَيْفَ؟ وَقَدْ نَزَلَ النَّاسُ مَنَازِلَهُمْ وَأَخَذُوا أَخَذَاتِهِمْ؟ فَيُقَالُ لَهُ: أَتَرْضَى أَنْ يَكُونَ لَكَ مِثْلُ مُلْكِ مَلِكٍ مِنْ مُلُوكِ الدُّنْيَا؟ فَيَقُولُ: رَضِيتُ رَبِّ، فَيَقُولُ: لَكَ ذَلِكَ، وَمِثْلُهُ وَمِثْلُهُ وَمِثْلُهُ وَمِثْلُهُ، فَقَالَ فِي الْخَامِسَةِ: رَضِيتُ رَبِّ، فَيَقُولُ: هَذَا لَكَ، وَعَشَرَةُ أَمْثَالِهِ، وَلَكَ مَا اشْتَهَتْ نَفْسُكَ، وَلَذَّتْ عَيْنُكَ، فَيَقُولُ: رَضِيتُ رَبِّ، قَالَ: رَبِّ، فَأَعْلَاهُمْ مَنْزِلَةً؟ قَالَ: أُولَئِكَ الَّذِينَ أَرَدْتُ، غَرَسْتُ كَرَامَتَهُمْ بِيَدِي، وَخَتَمْتُ عَلَيْهَا، فَلَمْ تَرَ عَيْنٌ، وَلَمْ تَسْمَعْ أُذُنٌ، وَلَمْ يَخْطُرْ عَلَى قَلْبِ بَشَرٍ، قَالَ: وَمِصْدَاقُهُ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ: ﴿فَلا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ﴾، الْآيَةَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (189) من طرق عن الشعبي، يخبر عن المغيرة بن شعبة، قال: سمعته على المنبر يرفعه إلى رسول الله صلى الله عليه وسلم فذكره.","grade":"صحيح","chapter_ar":"باب في الجنة ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (189).","chapter_en":"In Paradise Is What No Eye Has Seen, No Ear Has Heard, and What Has Never Occurred to a Human Heart","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of Paradise","part_no":67,"group_no":1,"chapter_no":26,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah narrated, attributing it to the Prophet ﷺ: “Mūsā asked his Lord: ‘What is the lowest rank of the people of Paradise?’ He said: ʿIt is a man who will come after the people of Paradise have already been admitted into Paradise. It will be said to him: “Enter Paradise.” He will say: “My Lord, how can I, when the people have already settled in their dwellings and received what was allotted to them?” It will be said to him: “Would you be pleased to have the equivalent of the kingdom of one of the kings of the world?” He will say: “I am pleased, my Lord.” He will say: “You shall have that, and the like of it, and the like of it, and the like of it, and the like of it.” At the fifth, he will say: “I am pleased, my Lord.” He will say: “All of that is yours, and ten times as much. And you shall have whatever your soul desires and whatever delights your eyes.” He will say: “I am pleased, my Lord.” Mūsā then asked: “My Lord, what about those of the highest rank?” He said: “Those are the ones whom I chose. I planted their honor with My Hand and sealed it. No eye has seen it, no ear has heard it, and it has never occurred to a human heart.”” He said: Its confirmation is in the Book of Allah, Mighty and Majestic: “No soul knows what comfort of the eyes has been hidden for them.” [al-Sajdah 32:17]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (189)."},{"num":16338,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَنْ يُدْخِل أَحَدًا عَمَلُهُ الْجَنَّةَ قَالُوا: وَلاَ أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: لاَ، وَلاَ أَنَا، إِلاَّ أَنْ يَتَغَمَّدَنِي اللَّهُ بِفَضْلٍ وَرَحْمَةٍ، فَسَدِّدُوا وَقَارِبُوا، وَلاَ يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ: إِمَّا مُحْسِنًا فَلَعَلَّهُ أَنْ يَزْدَادَ خَيْرًا، وَإِمَّا مُسِيئًا فَلَعَلَّهُ أَنْ يَسْتَعْتِبَ."],"takhrij":"متفق عليه: رواه البخاري في المرض (5673)، ومسلم في صفة القيامة والجنة والنار (75:2816) كلاهما من طريق الزهري، عن أبي عبيد مولى عبد الرحمن بن عوف، عن أبي هريرة قال: فذكره. واللفظ للبخاري ولفظ مسلم مختصر.","grade":"متفق عليه","chapter_ar":"باب لا يدخل الجنة أحد إلا بفضل من الله ورحمته سبحانه","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5673) and Muslim (75 :2816).","chapter_en":"No One Enters Paradise Except by the Grace and Mercy of Allah, Glorified Is He","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “No one will be admitted into Paradise by his deeds alone.” They asked: “Not even you, O Messenger of Allah?” He replied: “Not even me, unless Allah envelops me in His grace and mercy. So strive to remain upon the right course and come as close to perfection as you can. And none of you should wish for death. If he is a doer of good, perhaps he will increase in goodness; and if he is a sinner, perhaps he will seek Allah’s pardon and correction.”"]}},"tuhfa":{},"full":1,"rep":[3528,13140,13611,15142],"tks":"متفق عليه: رواه البخاري (5673)، ومسلم (75 :2816)."},{"num":16339,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا كَانَتْ تَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  سَدِّدُوا، وَقَارِبُوا، وَأَبْشِرُوا، فَإِنَّهُ لَنْ يُدْخِلَ الْجَنَّةَ أَحَدًا عَمَلُهُ. قَالُوا: وَلَا أَنْتَ يَا رَسُولَ اللَّهِ؟ قَالَ: وَلَا أَنَا، إِلَّا أَنْ يَتَغَمَّدَنِيَ اللَّهُ مِنْهُ بِرَحْمَةٍ، وَاعْلَمُوا أَنَّ أَحَبَّ الْعَمَلِ إِلَى اللَّهِ أَدْوَمُهُ وَإِنْ قَلَّ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6464)، ومسلم في صفة القيامة والجنة والنار (2818) كلاهما من طريق موسى بن عقبة، قال: سمعت أبا سلمة بن عبدالرحمن بن عوف، يحدث عن عائشة، فذكرته. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب لا يدخل الجنة أحد إلا بفضل من الله ورحمته سبحانه","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6464) and Muslim (2818).","chapter_en":"No One Enters Paradise Except by the Grace and Mercy of Allah, Glorified Is He","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, used to narrate that the Messenger of Allah ﷺ said: “Remain upon the right course, come as close to perfection as you can, and receive glad tidings, for no one will be admitted into Paradise by his deeds alone.” They asked: “Not even you, O Messenger of Allah?” He replied: “Not even me, unless Allah envelops me in mercy from Him. And know that the deed most beloved to Allah is the one performed most consistently, even if it is small.”"]}},"tuhfa":{},"full":1,"rep":[13246],"tks":"متفق عليه: رواه البخاري (6464)، ومسلم (2818)."},{"num":16340,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَارِبُوا، وَسَدِّدُوا، فَإِنَّهُ لَيْسَ أَحَدٌ مِنْكُمْ يُنَجِّيهِ عَمَلُهُ قَالَوا: وَلَا إِيَّاكَ يَا رَسُولَ اللَّهِ؟ قَالَ: وَلَا إِيَّايَ، إِلَّا أَنْ يَتَغَمَّدَنِي اللَّهُ بِرَحْمَتِهِ."],"takhrij":"صحيح: رواه مسلم في صفة القيامة والجنة والنار (2817)، وأحمد (14628) كلاهما من طريق سُليمان الأعمش، عن أبي سفيان، عن جابر، فذكره. واللفظ لأحمد، ولم يسق مسلم لفظه، وإنما أحال على حديث أبي هريرة قبله.","grade":"صحيح","chapter_ar":"باب لا يدخل الجنة أحد إلا بفضل من الله ورحمته سبحانه","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2817) and Aḥmad (14628).","chapter_en":"No One Enters Paradise Except by the Grace and Mercy of Allah, Glorified Is He","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Jābir narrated that the Messenger of Allah ﷺ said: “Come as close as you can to what is right and remain steadfast, for none of you will be saved by his deeds alone.” They asked: “Not even you, O Messenger of Allah?” He replied: “Not even me, unless Allah envelops me in His mercy.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2817)، وأحمد (14628)."},{"num":16341,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ:  لَا يُدْخِلُ أَحَدًا مِنْكُمْ عَمَلُهُ الْجَنَّةَ، وَلَا يُجِيرُهُ مِنَ النَّارِ، وَلَا أَنَا، إِلَّا بِرَحْمَةٍ مِنَ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في صفة القيامة (77:2817) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل، عن أبي الزبير، عن جابر قال: فذكره.","grade":"صحيح","chapter_ar":"باب لا يدخل الجنة أحد إلا بفضل من الله ورحمته سبحانه","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (77:2817).","chapter_en":"No One Enters Paradise Except by the Grace and Mercy of Allah, Glorified Is He","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Jābir narrated: I heard the Prophet ﷺ say: “The deeds of none of you will admit him into Paradise, nor protect him from the Fire—not even me—except through mercy from Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (77:2817)."},{"num":16342,"demo":false,"sanad":"","matn":["عن أسد بْنِ كُرْز قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَسَدُ بْنَ كُرْزٍ، لَا تَدْخُلُ الْجَنَّةَ بِعَمَلٍ، وَلَكِنْ بِرَحْمَةِ اللَّهِ . قَالَ: وَلَا أَنْتَ يَا رَسُولَ اللَّهِ؟! قَالَ: وَلَا أَنَا، إِلَّا أَنْ يَتَلَاقَنِي اللَّهُ - أَوْ يَتَغَمَّدَنِي - اللَّهُ مِنْهُ بِرَحْمَةٍ."],"takhrij":"حسن: رواه البخاري في التاريخ الكبير (2/49)، والطبراني في الكبير (1001) كلاهما من طريقين عن بقية بن الوليد ، قال: حدثني أرطاة بن المنذر السكوني، قال: حدثني مهاصر بن حبيب الزبيدي ، عن أسد بن كرز ، قال فذكره.","grade":"حسن","chapter_ar":"باب لا يدخل الجنة أحد إلا بفضل من الله ورحمته سبحانه","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Tārīkh al-Kabīr (2/49) and al-Ṭabarānī in al-Muʿjam al-Kabīr (1/316).","chapter_en":"No One Enters Paradise Except by the Grace and Mercy of Allah, Glorified Is He","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Asad ibn Kurz narrated: The Messenger of Allah ﷺ said to me: “O Asad ibn Kurz, no deed will admit you into Paradise; rather, it will be by the mercy of Allah.” I asked: “Not even you, O Messenger of Allah?” He replied: “Not even me, unless Allah comes to my aid or envelops me in mercy from Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في التاريخ الكبير (2/49)، والطبراني في الكبير (1001)."},{"num":16343,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَنَا أَكْثَرُ الْأَنْبِيَاءِ تَبَعًا يَوْمَ الْقِيَامَةِ، وَأَنَا أَوَّلُ مَنْ يَقْرَعُ بَابَ الْجَنَّةِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (331:196) عن أبي كريب محمد بن العلاء، حدثنا معاوية بن هشام، عن سفيان، عن مختار بن فلفل، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب النبي ﷺ أول من يقرع باب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (331:196).","chapter_en":"The Prophet ﷺ Will Be the First to Knock at the Gate of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “I will have the greatest number of followers among the Prophets on the Day of Resurrection, and I will be the first to knock at the gate of Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (331:196)."},{"num":16344,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  آتِي بَابَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ، فَأَسْتَفْتِحُ، فَيَقُولُ الْخَازِنُ: مَنْ أَنْتَ؟ فَأَقُولُ: مُحَمَّدٌ، فَيَقُولُ: بِكَ أُمِرْتُ، لَا أَفْتَحُ لِأَحَدٍ قَبْلَكَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (197) من طرق عن هاشم بن القاسم، حدثنا سليمان بن المغيرة، عن ثابت، عن أنس بن مالك قال: فذكره.","grade":"صحيح","chapter_ar":"باب النبي ﷺ أول من يقرع باب الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (197).","chapter_en":"The Prophet ﷺ Will Be the First to Knock at the Gate of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “I will come to the gate of Paradise on the Day of Resurrection and ask for it to be opened. The gatekeeper will ask: ‘Who are you?’ I will reply: ‘Muḥammad.’ He will say: ‘I was commanded concerning you not to open it for anyone before you.’”"]}},"tuhfa":{},"full":1,"rep":[647,800],"tks":"صحيح: رواه مسلم (197)."},{"num":16345,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  نَحْنُ الْآخِرُونَ الْأَوَّلُونَ يَوْمَ الْقِيَامَةِ. وَنَحْنُ أَوَّلُ مَنْ يَدْخُلُ الْجَنَّةَ. بَيْدَ أَنَّهُمْ أُوتُوا الْكِتَابَ مِنْ قَبْلِنَا وَأُوتِينَاهُ مِنْ بَعْدِهِمْ. فَاخْتَلَفُوا، فَهَدَانَا اللهُ لِمَا اخْتَلَفُوا فِيهِ مِنَ الْحَقِّ. فَهَذَا يَوْمُهُمُ الَّذِي اخْتَلَفُوا فِيهِ. هَدَانَا اللهُ لَهُ - قَالَ: يَوْمُ الْجُمُعَةِ - فَالْيَوْمَُ لَنَا. وَغَدًا لِلْيَهُودِ. وَبَعْدَ غَدٍ لِلنَّصَارَى."],"takhrij":"متفق عليه: رواه مسلم في الجمعة (855: 20) من طريق جرير، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب أن الأمة المحمدية أول من يدخل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (20 :855) and al-Bukhārī (6624).","chapter_en":"The Ummah of Muḥammad ﷺ Will Be the First Nation to Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “We are the last nation in this world, yet the first on the Day of Resurrection, and we will be the first to enter Paradise. They were given the Scripture before us, while we were given it after them. They differed concerning the truth, and Allah guided us to that concerning which they differed. This is their day concerning which they differed, and Allah guided us to it.” He meant Friday. “So today belongs to us, tomorrow to the Jews, and the day after tomorrow to the Christians.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (855: 20) والبخاري (6624)."},{"num":16346,"demo":false,"sanad":"","matn":["عن عبد الله بن مسعود قال: كنا مع رسول الله صلى الله عليه وسلم في قبة، فذكر حديثا طويلا، جاء فيه: إن الجنة لا يدخلها إلا نفس مسلمة... الحديث."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6528)، ومسلم في الإيمان (377:221) كلاهما عن محمد بن بشار، حدثنا محمد بن جعفر غندر، حدثنا شعبة، عن أبي إسحاق، عن عمرو بن ميمون، عن عبد الله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب الجنة لا يدخلها إلا نفس مسلمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6528) and Muslim (377:221).","chapter_en":"None Will Enter Paradise Except a Muslim Soul","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: We were with the Messenger of Allah ﷺ in a tent. He mentioned a lengthy hadith, in which he said: “Indeed, none will enter Paradise except a Muslim soul…” The hadith continues."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6528)، ومسلم (377:221)."},{"num":16347,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بن مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَهُ وَأَوْسَ بْنَ الْحَدَثَانِ أَيَّامَ التَّشْرِيقِ، فناديا: أَنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا مُؤْمِنٌ، وَأَيَّامُ مِنًى أَيَّامُ أَكْلٍ وَشُرْبٍ."],"takhrij":"صحيح: رواه مسلم في الصيام (1142) من طرق عن إبراهيم بن طهمان، عن أبي الزبير، عن ابن كعب بن مالك، عن أبيه، فذكره.","grade":"صحيح","chapter_ar":"باب الجنة لا يدخلها إلا نفس مسلمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1142).","chapter_en":"None Will Enter Paradise Except a Muslim Soul","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Kaʿb ibn Mālik narrated that the Messenger of Allah ﷺ sent him and Aws ibn al-Ḥadathān during the Days of Tashrīq to proclaim: “None will enter Paradise except a believer, and the days of Minā are days of eating and drinking.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1142)."},{"num":16348,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ قَالَ:  لَمَّا كَانَ يَوْمُ خَيْبَرَ أَقْبَلَ نَفَرٌ مِنْ صَحَابَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: فُلَانٌ شَهِيدٌ، فُلَانٌ شَهِيدٌ، حَتَّى مَرُّوا عَلَى رَجُلٍ، فَقَالُوا: فُلَانٌ شَهِيدٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَلَّا، إِنِّي رَأَيْتُهُ فِي النَّارِ فِي بُرْدَةٍ غَلَّهَا أَوْ عَبَاءَةٍ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا ابْنَ الْخَطَّابِ، اذْهَبْ فَنَادِ فِي النَّاسِ، أَِنَّهُ: لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ، قَالَ: فَخَرَجْتُ فَنَادَيْتُ: أَلَا إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (114) عن زهير بن حرب، حدثنا هاشم بن القاسم، حدثنا عكرمة بن عمار قال: حدثني سماك الحنفي أبو زميل قال: حدثني عبد الله بن عباس قال: حدثني عمر بن الخطاب، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الجنة لا يدخلها إلا نفس مسلمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (114).","chapter_en":"None Will Enter Paradise Except a Muslim Soul","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated: On the day of Khaybar, a group of the Companions of the Prophet ﷺ came saying: “So-and-so is a martyr, so-and-so is a martyr.” Then they passed by a man and said: “So-and-so is a martyr.” The Messenger of Allah ﷺ said: “No. I saw him in the Fire because of a cloak—or an outer garment—that he had unlawfully taken from the spoils.” Then the Messenger of Allah ﷺ said: “O Ibn al-Khaṭṭāb, go and proclaim among the people that none will enter Paradise except the believers.” ʿUmar said: So I went out and proclaimed: “Indeed, none will enter Paradise except the believers.”"]}},"tuhfa":{},"full":1,"rep":[98,8044,9085],"tks":"صحيح: رواه مسلم (114)."},{"num":16349,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: قُلْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ هِشَامَ بْنَ الْمُغِيرَةِ كَانَ يَصِلُ الرَّحِمَ، وَيَقْرِي الضَّيْفَ، وَيَفُكُّ الْعُنَاةَ، وَيُطْعِمُ الطَّعَامَ، وَلَوْ أَدْرَكَ أَسْلَمَ، هَلْ ذَلِكَ نَافِعُهُ؟ قَالَ: لَا، إِنَّهُ كَانَ يُعْطِي لِلدُّنْيَا وَذِكْرِهَا وَحَمْدِهَا، وَلَمْ يَقُلْ يَوْمًا قَطُّ: رَبِّ اغْفِرْ لِي يَوْمَ الدِّينِ."],"takhrij":"صحيح: رواه أبويعلى (6965) – واللفظ له- وابن أبي شيبة في مسنده – كما في المطالب العالية- (2871)، والطبراني في الكبير(23/606) كلهم من طرق عن منصور، عن مجاهد، عن أم سلمة قال فذكرته.","grade":"صحيح","chapter_ar":"باب الجنة لا يدخلها إلا نفس مسلمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Yaʿlā (6965), whose wording this is, Ibn Abī Shaybah in his Musnad, as cited in al-Maṭālib al-ʿĀliyah (2871), and al-Ṭabarānī in al-Muʿjam al-Kabīr (23/606).","chapter_en":"None Will Enter Paradise Except a Muslim Soul","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Umm Salamah narrated: I said to the Prophet ﷺ: “Hishām ibn al-Mughīrah used to maintain ties of kinship, honor guests, free captives, and feed people. Had he lived until Islam and accepted it, would those deeds have benefited him?” He replied: “No. He used to give for the sake of this world, its reputation, and its praise, and he never once said: ‘My Lord, forgive me on the Day of Judgment.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (6965) - واللفظ له -، وابن أبي شيبة في مسنده - كما في المطالب العالية - (2871)، والطبراني في الكبير (23/606)."},{"num":16350,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: يَلْقَى إِبْرَاهِيمُ أَبَاهُ آزَرَ يَوْمَ الْقِيَامَةِ، وَعَلَى وَجْهِ آزَرَ قَتَرَةٌ وَغَبَرَةٌ، فَيَقُولُ لَهُ إِبْرَاهِيمُ: أَلَمْ أَقُلْ لَكَ لاَ تَعْصِنِي، فَيَقُولُ أَبُوهُ: فَالْيَوْمَ لاَ أَعْصِيكَ. فَيَقُولُ إِبْرَاهِيمُ: يَا رَبِّ، إِنَّكَ وَعَدْتَنِي أَنْ لاَ تُخْزِيَنِي يَوْمَ يُبْعَثُونَ، فَأَىُّ خِزْىٍ أَخْزَى مِنْ أَبِي الأَبْعَدِ؟ فَيَقُولُ اللَّهُ تَعَالَى: إِنِّي حَرَّمْتُ الْجَنَّةَ عَلَى الْكَافِرِينَ، ثُمَّ يُقَالُ: يَا إِبْرَاهِيمُ، مَا تَحْتَ رِجْلَيْكَ؟ فَيَنْظُرُ، فَإِذَا هُوَ بِذِيخٍ مُلْتَطِخٍ، فَيُؤْخَذُ بِقَوَائِمِهِ فَيُلْقَى فِي النَّارِ."],"takhrij":"صحيح: رواه البخاري في أحاديث الأنبياء (3350) عن إسماعيل بن عبد الله، قال: أخبرني أخي عبد الحميد، عن ابن أبي ذئب، عن سعيد المقبري، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب أن الله حرم الجنة على الكافرين","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3350).","chapter_en":"Allah Has Forbidden Paradise to the Disbelievers","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Ibrāhīm will meet his father Āzar on the Day of Resurrection, and Āzar’s face will be covered with darkness and dust. Ibrāhīm will say to him: ‘Did I not tell you not to disobey me?’ His father will reply: ‘Today I will not disobey you.’ Ibrāhīm will say: ‘My Lord, You promised me that You would not disgrace me on the Day they are resurrected. What disgrace could be greater than my distant father?’ Allah, the Exalted, will say: ‘I have forbidden Paradise to the disbelievers.’ Then it will be said: ‘O Ibrāhīm, what is beneath your feet?’ He will look and see a male hyena smeared with filth. It will be seized by its legs and thrown into the Fire.”"]}},"tuhfa":{},"full":1,"rep":[100,8366,12523,12929,13531],"tks":"صحيح: رواه البخاري (3350)."},{"num":16351,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيَأْخُذَنَّ رَجُلٌ بِيَدِ أَبِيهِ يَوْمَ الْقِيَامَةِ، يُرِيدُ أَنْ يُدْخِلَهُ الْجَنَّةَ، فَيُنَادَى: إِنَّ الْجَنَّةَ لَا يَدْخُلُهَا مُشْرِكٌ، إِنَّ اللَّهَ قَدْ حَرَّمَ الْجَنَّةَ عَلَى كُلِّ مُشْرِكٍ، فَيَقُولُ: رَبِّ، أَبِي رَبِّ، أَبِي، قَالَ: فَيَتَحَوَّلُ فِي صُورَةٍ قَبِيحَةٍ، وَرِيحٍ مُنْتِنَةٍ، فَيَتْرُكُهُ.","قَالَ أَبُو سَعِيدٍ: \"كان أَصْحَابُ مُحَمَّدٍ صلى الله عليه وسلم يَرَوْنَ أَنَّهُ إِبْرَاهِيَمُ، وَلَمْ يَزِدْهُمْ رَسُولُ اللهِ صلى الله عليه وسلم عَلَى ذَلِكَ\"."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (252) –واللفظ له-، والبزار في كشف الأستار (94)، والحاكم (8746) كلهم من حديث المعتمر بن سليمان قال: سمعت أبي يحث عن قتادة، عن عقبة بن عبد الغافر، عن أبي سعيد فذكره.","grade":"صحيح","chapter_ar":"باب أن الله حرم الجنة على الكافرين","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (252), whose wording this is, and al-Bazzār in Kashf al-Astār (94).","chapter_en":"Allah Has Forbidden Paradise to the Disbelievers","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “A man will take his father by the hand on the Day of Resurrection, wanting to bring him into Paradise. Then it will be proclaimed: ‘No polytheist will enter Paradise. Allah has forbidden Paradise to every polytheist.’ The man will say: ‘My Lord! My Lord! My father!’ Then his father will be transformed into an ugly form with a foul smell, so he will leave him.” Abū Saʿīd said: “The Companions of Muḥammad ﷺ understood this man to be Ibrāhīm, and the Messenger of Allah ﷺ did not add anything beyond that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان في صحيحه (252) - واللفظ له -، والبزار في كشف الأستار (94)."},{"num":16352,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ،  أَنَّ أَعْرَابِيًّا قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَتَى السَّاعَةُ؟ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَعْدَدْتَ لَهَا؟ قَالَ: حُبَّ اللهِ وَرَسُولِهِ. قَالَ: أَنْتَ مَعَ مَنْ أَحْبَبْتَ."],"takhrij":"متفق عليه: رواه مسلم في البرّ والصّلة (2639) عن عبد الله بن مسلمة بن قعنب، حدّثنا مالك، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب من أحب الله ورسوله يكون معه في الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2639) and al-Bukhārī (7153).","chapter_en":"Whoever Loves Allah and His Messenger Will Be with Him in Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated that a Bedouin asked the Messenger of Allah ﷺ: “When is the Hour?” The Messenger of Allah ﷺ asked him: “What have you prepared for it?” He replied: “Love for Allah and His Messenger.” He said: “You will be with those whom you love.”"]},"buhuth":{"en":["It is also narrated through another route from Anas ibn Mālik:","While the Prophet ﷺ and I were leaving the mosque, we met a man at the entrance of the mosque.","He asked:","“O Messenger of Allah, when is the Hour?”","The Prophet ﷺ asked:","“What have you prepared for it?”","The man appeared humbled and replied:","“O Messenger of Allah, I have not prepared for it a great amount of fasting, prayer, or charity, but I love Allah and His Messenger.”","He said:","“You will be with those whom you love.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[111,744,13232],"tks":"متفق عليه: رواه مسلم (2639)، والبخاري (7153)."},{"num":16353,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ شَهِدَ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَأَنَّ عِيسَى عَبْدُ اللَّهِ وَرَسُولُهُ، وَكَلِمَتُهُ، أَلْقَاهَا إِلَى مَرْيَمَ، وَرُوحٌ مِنْهُ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، أَدْخَلَهُ اللَّهُ الْجَنَّةَ عَلَى مَا كَانَ مِنَ الْعَمَلِ."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3435) عن صدقة بن الفضل، حدثنا الوليد، عن الأوزاعيّ قال: حدّثني عمير بن هانئ، حدّثني جُنادة بن أبي أميّة، عن عبادة، فذكره.","grade":"متفق عليه","chapter_ar":"باب من شهد بالتوحيد ومات عليه دخل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3435). Muslim (28) narrated it through another route and added:","chapter_en":"Whoever Testifies to Tawḥīd and Dies upon It Will Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated that the Prophet ﷺ said: “Whoever testifies that there is no deity except Allah alone, without partner; that Muḥammad is His servant and Messenger; that ʿĪsā is the servant of Allah and His Messenger, His Word which He cast to Maryam, and a spirit from Him; and that Paradise is true and the Fire is true—Allah will admit him into Paradise regardless of what his deeds had been.”"]},"buhuth":{"en":["“Allah will admit him through whichever of the eight gates of Paradise he wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12708],"tks":"متفق عليه: رواه البخاري (3435) ورواه مسلم (28) من وجه آخر، وزاد:."},{"num":16354,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْتُ لَيْلَةً مِنَ اللَّيَالِي، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي وَحْدَهُ، وَلَيْسَ مَعَهُ إِنْسَانٌ، ـ قَالَ: ـ فَظَنَنْتُ أَنَّهُ يَكْرَهُ أَنْ يَمْشِيَ مَعَهُ أَحَدٌ، ـ قَالَ: ـ فَجَعَلْتُ أَمْشِي فِي ظِلِّ الْقَمَرِ فَالْتَفَتَ فَرَآنِي، فَقَالَ: مَنْ هَذَا. قُلْتُ: أَبُو ذَرٍّ، جَعَلَنِي اللَّهُ فِدَاءَكَ. قَالَ: يَا أَبَا ذَرٍّ تَعَالَهْ. قَالَ: فَمَشَيْتُ مَعَهُ سَاعَةً، فَقَالَ: إِنَّ الْمُكْثِرِينَ هُمُ الْمُقِلُّونَ يَوْمَ الْقِيَامَةِ، إِلاَّ مَنْ أَعْطَاهُ اللَّهُ خَيْرًا، فَنَفَحَ فِيهِ يَمِينَهُ وَشِمَالَهُ وَبَيْنَ يَدَيْهِ وَوَرَاءَهُ، وَعَمِلَ فِيهِ خَيْرًا. قَالَ: فَمَشَيْتُ مَعَهُ سَاعَةً، فَقَالَ لِي: اجْلِسْ هَا هُنَا. قَالَ: فَأَجْلَسَنِي فِي قَاعٍ حَوْلَهُ حِجَارَةٌ، فَقَالَ لِي: اجْلِسْ هَا هُنَا حَتَّى أَرْجِعَ إِلَيْكَ. قَالَ: فَانْطَلَقَ فِي الْحَرَّةِ حَتَّى لاَ أَرَاهُ، فَلَبِثَ عَنِّي فَأَطَالَ اللُّبْثَ، ثُمَّ إِنِّي سَمِعْتُهُ وَهْوَ مُقْبِلٌ، وَهْوَ يَقُولُ: وَإِنْ سَرَقَ، وَإِنْ زَنَى. قَالَ: فَلَمَّا جَاءَ لَمْ أَصْبِرْ حَتَّى قُلْتُ: يَا نَبِيَّ اللَّهِ جَعَلَنِي اللَّهُ فِدَاءَكَ، مَنْ تُكَلِّمُ فِي جَانِبِ الْحَرَّةِ، مَا سَمِعْتُ أَحَدًا يَرْجِعُ إِلَيْكَ شَيْئًا. قَالَ: ذَلِكَ جِبْرِيلُ ـ عَلَيْهِ السَّلاَمُ، ـ عَرَضَ لِي فِي جَانِبِ الْحَرَّةِ، قَالَ: بَشِّرْ أُمَّتَكَ أَنَّهُ مَنْ مَاتَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ، قُلْتُ: يَا جِبْرِيلُ، وَإِنْ سَرَقَ، وَإِنْ زَنَى؟ قَالَ: نَعَمْ. قَالَ: قُلْتُ: وَإِنْ سَرَقَ، وَإِنْ زَنَى؟ قَالَ: نَعَمْ، وَإِنْ شَرِبَ الْخَمْرَ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6443)، ومسلم في الزكاة (33:94) كلاهما عن قتيبة بن سعيد، حدثنا جرير، عن عبد العزيز بن رفيع، عن زيد بن وهب، عن أبي ذر، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب من شهد بالتوحيد ومات عليه دخل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6443) and Muslim (33:94).","chapter_en":"Whoever Testifies to Tawḥīd and Dies upon It Will Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Abū Dharr narrated: One night I went out and saw the Messenger of Allah ﷺ walking alone with no one accompanying him. I thought that perhaps he disliked having anyone walk with him, so I began walking in the shadow of the moon. He turned and saw me and asked: “Who is this?” I replied: “Abū Dharr, may Allah make me your ransom.” He said: “O Abū Dharr, come here.” I walked with him for a while, and he said: “Those who possess much wealth will be the ones with little reward on the Day of Resurrection, except the one to whom Allah gives wealth and he distributes it to his right, to his left, in front of him, and behind him, and uses it in good.” I continued walking with him for a while, then he said: “Sit here.” He seated me in a low area surrounded by stones and said: “Remain here until I return to you.” Then he went into the rocky plain until I could no longer see him. He remained away for a long time. Then I heard him returning while saying: “Even if he steals, and even if he commits fornication.” When he came back, I could not restrain myself and said: “O Prophet of Allah, may Allah make me your ransom, who was speaking to you on the side of the rocky plain? I did not hear anyone responding to you.” He replied: “That was Jibrīl. He appeared to me at the side of the rocky plain and said: ‘Give your Ummah the glad tidings that whoever dies without associating anything with Allah will enter Paradise.’ I said: ‘O Jibrīl, even if he steals and commits fornication?’ He said: ‘Yes.’ I said: ‘Even if he steals and commits fornication?’ He said: ‘Yes, even if he drinks wine.’”"]}},"tuhfa":{},"full":1,"rep":[83],"tks":"متفق عليه: رواه البخاري (6443)، ومسلم (33:94)."},{"num":16355,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ. وَقُلْتُ أَنَا: مَنْ مَاتَ لاَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1238)، ومسلم في الإيمان (92) كلاهما من طريق الأعمش، حدثنا شقيق، عن عبد الله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب من شهد بالتوحيد ومات عليه دخل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1238) and Muslim (92).","chapter_en":"Whoever Testifies to Tawḥīd and Dies upon It Will Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Whoever dies while associating anything with Allah will enter the Fire.” Ibn Masʿūd said: “And I say: Whoever dies without associating anything with Allah will enter Paradise.”"]}},"tuhfa":{},"full":1,"rep":[12165],"tks":"متفق عليه: رواه البخاري (1238)، ومسلم (92)."},{"num":16356,"demo":false,"sanad":"","matn":["عَنْ مُعَاذٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ مَاتَ وَهُوَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ صَادِقًا مِنْ قَلْبِهِ، دَخَلَ الْجَنَّةَ."],"takhrij":"صحيح: رواه أحمد (22003)، والنسائي في عمل اليوم والليلة (1134)، وابن خزيمة في التوحيد (514)، والطبراني في الكبير (20/ح 366) كلهم من طريق محمد بن جعفر، حدثنا شعبة، عن قتادة، عن أنس، عن معاذ قال: فذكره.","grade":"صحيح","chapter_ar":"باب من شهد بالتوحيد ومات عليه دخل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (22003), al-Nasā’ī in ʿAmal al-Yawm wa-l-Laylah (1134), and Ibn Khuzaymah in al-Tawḥīd (514).","chapter_en":"Whoever Testifies to Tawḥīd and Dies upon It Will Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Muʿādh narrated that the Messenger of Allah ﷺ said: “Whoever dies testifying sincerely from his heart that there is no deity except Allah and that Muḥammad is the Messenger of Allah will enter Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (22003)، والنسائي في عمل اليوم والليلة (1134)، وابن خزيمة في التوحيد (514)."},{"num":16357,"demo":false,"sanad":"","matn":["عن معاذ بن جبل قال حين حضرته الوفاة: اكشفوا عني سجف القبة أحدثكم حديثا سمعته من رسول الله صلى الله عليه وسلم يقول: من شهد أن لا إله إلا الله، مخلصا من قلبه، أو يقينا من قلبه، دخل الجنة، ولم تمسه النار."],"takhrij":"صحيح: رواه أحمد (22060)، والحميدي (369)، والطبراني في الكبير (20/ح 63) كلهم من طريق ابن عيينة، عن عمرو بن دينار قال: سمعت جابر بن عبدالله يقول: أخبرني من شهد معاذ بن جبل حين حضرته الوفاة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب من شهد بالتوحيد ومات عليه دخل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (22060), al-Ḥumaydī (369), and al-Ṭabarānī in al-Muʿjam al-Kabīr (20/41).","chapter_en":"Whoever Testifies to Tawḥīd and Dies upon It Will Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["Muʿādh ibn Jabal said when death approached him: “Raise the curtain of the tent from me so that I may narrate to you a hadith I heard from the Messenger of Allah ﷺ.” He said: “Whoever testifies that there is no deity except Allah sincerely from his heart—or with certainty in his heart—will enter Paradise, and the Fire will not touch him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (22060)، والحميدي (369)، والطبراني في الكبير (20/41)."},{"num":16358,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ، إِلاَّ مَنْ أَبَى. قَالُوا: يَا رَسُولَ اللَّهِ، وَمَنْ يَأْبَى؟ قَالَ: مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى."],"takhrij":"صحيح: رواه البخاري في الاعتصام (7280) عن محمد بن سنان، حدثنا فليح، حدثنا هلال بن علي، عن عطاء بن يسار، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب من استجاب للنبي ﷺ وأطاعه دخل الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7280).","chapter_en":"Whoever Responds to the Prophet ﷺ and Obeys Him Will Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “All of my Ummah will enter Paradise except those who refuse.” They asked: “O Messenger of Allah, who would refuse?” He replied: “Whoever obeys me will enter Paradise, and whoever disobeys me has refused.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13714,15649],"tks":"صحيح: رواه البخاري (7280)."},{"num":16359,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ يَضْمَنْ لِي مَا بَيْنَ لَحْيَيْهِ وَمَا بَيْنَ رِجْلَيْهِ أَضْمَنْ لَهُ الْجَنَّةَ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6474) عن محمد بن أبي بكر المقدمي، حدثنا عمر بن علي، عن أبي حازم، عن سهل بن سعد، فذكره.","grade":"صحيح","chapter_ar":"باب من ضمن ما بين لحييه ورجليه فله الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6474).","chapter_en":"Whoever Guarantees What Is Between His Jaws and His Legs Is Guaranteed Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Messenger of Allah ﷺ said: “Whoever guarantees for me what is between his two jaws and what is between his two legs, I guarantee Paradise for him.”"]}},"tuhfa":{},"full":1,"rep":[12869,13382,14551],"tks":"صحيح: رواه البخاري (6474)."},{"num":16360,"demo":false,"sanad":"","matn":["عن صعصعة بن مُعَاوِيَةَ قَالَ: انْتَهَيْتُ إِلَى الرَّبَذَةِ، فَإِذَا أَنَا بِأَبِي ذَرٍّ، قَدْ تَلَقَّانِي بِرَوَاحِلَ قَدْ أَوْرَدَهَا، ثُمَّ أَصْدَرَهَا، وَقَدْ أَعْلَقَ قِرْبَةً فِي عُنُقِ بَعِيرٍ مِنْهَا لِيَشْرَبَ وَيَسْقِيَ أَصْحَابَهُ، وَكَانَ خُلُقًا مِنْ أَخْلَاقِ الْعَرَبِ، قُلْتُ: يَا أَبَا ذَرٍّ مَا لَكَ؟ قَالَ: لِي عَمَلِي. قُلْتُ: إِيهٍ يَا أَبَا ذَرٍّ، مَا سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ؟ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَنْفَقَ زَوْجَيْنِ مِنْ مَالِهِ ابْتَدَرَتْهُ حَجَبَةُ الْجَنَّةِ قُلْنَا: مَا هَذَانِ الزَّوْجَانِ؟ قَالَ: إِنْ كَانَتْ رِجَالًا فَرَجُلَانِ، وَإِنْ كَانَتْ خَيْلًا فَفَرَسَانِ، وَإِنْ كَانَتْ إِبِلًا فَبَعِيرَانِ، حَتَّى عَدَّ أَصْنَافَ الْمَالِ كُلِّهِ."],"takhrij":"صحيح: رواه أحمد (21413) وابن حبان (4643)، والحاكم (2/86) كلهم من طرق عن الحسن، حدثني صعصعة بن معاوية قال: فذكره.","grade":"صحيح","chapter_ar":"باب من أنفق زوجين ابتدرته حجبة الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (21413), Ibn Ḥibbān (4643), and al-Ḥākim (2/86).","chapter_en":"Whoever Spends Two of His Possessions Will Be Rushed to by the Gatekeepers of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Ṣaʿṣaʿah ibn Muʿāwiyah narrated: I arrived at al-Rabadhah and found Abū Dharr. He met me with some riding animals that he had brought to water and then led away. He had hung a waterskin around the neck of one of the camels so that he could drink from it and give drink to his companions. This was among the customs of the Arabs. I asked: “O Abū Dharr, what do you possess?” He replied: “I have my deeds.” I said: “Tell me, O Abū Dharr, what did you hear the Messenger of Allah ﷺ say?” He replied: I heard the Messenger of Allah ﷺ say: “Whoever spends two of his possessions, the gatekeepers of Paradise will rush to receive him.” We asked: “What are these two?” He explained: “If they are men, then two men; if horses, then two horses; if camels, then two camels,” and he continued enumerating all categories of wealth."]},"buhuth":{"en":["Regarding the phrase “two of his possessions,” Ibn Ḥibbān said:","“In the Arabic language, two individual things joined together are called a pair.”","Allah, the Exalted, says:","“And of everything We created two mates, that perhaps you may remember.”","[al-Dhāriyāt 51:49]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (21413) وابن حبان (4643)، والحاكم (2/86)."},{"num":16361,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَقُولُ اللَّهُ تَعَالَى: مَا لِعَبْدِي الْمُؤْمِنِ عِنْدِي جَزَاءٌ، إِذَا قَبَضْتُ صَفِيَّهُ مِنْ أَهْلِ الدُّنْيَا، ثُمَّ احْتَسَبَهُ، إِلاَّ الْجَنَّةُ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6424) عن قتيبة، حدثنا يعقوب بن عبدالرحمن، عن عمرو، عن سعيد المقبري، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب من قبض الله صفيه فاحتسب فله الجنة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6424).","chapter_en":"Whoever Loses a Beloved One Taken by Allah and Patiently Seeks Reward Will Have Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Allah, the Exalted, says: ‘There is no reward with Me for My believing servant, when I take away his beloved one from the people of this world and he patiently seeks My reward, except Paradise.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6424)."},{"num":16362,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: عَجِبَ اللَّهُ مِنْ قَوْمٍ يَدْخُلُونَ الْجَنَّةَ فِي السَّلاَسِلِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (3010) عن محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن محمد بن زياد، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب يدخل الجنة قوم في السلاسل","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3010).","chapter_en":"People Will Enter Paradise in Chains","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah marvels at people who enter Paradise in chains.”"]}},"tuhfa":{},"full":1,"rep":[379],"tks":"صحيح: رواه البخاري (3010)."},{"num":16363,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: اسْتَضْحَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا، فَقِيلَ لَهُ: يَا رَسُولَ اللَّهِ، مَا أَضْحَكَكَ؟ قَالَ: قَوْمٌ يُسَاقُونَ إِلَى الْجَنَّةِ مُقَرَّنِينَ فِي السَّلَاسِلِ."],"takhrij":"حسن: رواه أحمد (22203)، والطبراني في الكبير (8/340)، والبيهقي في الشعب (3605) كلهم من طريق عبد الله بن نمير، حدثنا الأعمش، عن حسين بن واقد الخراساني، عن أبي غالب، عن أبي أمامة، فذكره.","grade":"حسن","chapter_ar":"باب يدخل الجنة قوم في السلاسل","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22203), al-Ṭabarānī in al-Muʿjam al-Kabīr (8/340), and al-Bayhaqī in al-Shuʿab (3605).","chapter_en":"People Will Enter Paradise in Chains","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Abū Umāmah narrated: One day the Messenger of Allah ﷺ laughed. It was asked: “O Messenger of Allah, what made you laugh?” He replied: “People being driven toward Paradise bound together in chains.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22203)، والطبراني في الكبير (8/340)، والبيهقي في الشعب (3605)."},{"num":16364,"demo":false,"sanad":"","matn":["عَنْ أَبِي الطُّفَيْلِ قَالَ: ضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلّمَ فَقِيلَ :: يَا رَسُولَ اللَّهِ مِمّا ضَحِكْتَ ؟؟ قَالَ ::  رَأَيْت أُنَاسًا مِنْ أُمَّتِي يَسَاقُونَ إلَى الْجَنَّةِ فِي السَّلَاسِلِ .."],"takhrij":"حسن: رواه الدولابي في الكنى (1264)، والبزار (2780) كلاهما من طرق عن حبان بن هلال ، قال: حدثنا مبارك بن فضالة ، قال: حدثني كثير أبو محمد ، قال: حدثني أبو الطفيل قال: فذكره. واللفظ للدولابي، وفي بعض ألفاظ البزار نكارة.","grade":"حسن","chapter_ar":"باب يدخل الجنة قوم في السلاسل","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Dūlābī in al-Kunā (1264) and al-Bazzār (2780).","chapter_en":"People Will Enter Paradise in Chains","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Abū al-Ṭufayl narrated: The Messenger of Allah ﷺ laughed. It was asked: “O Messenger of Allah, what made you laugh?” He replied: “I saw people from my Ummah being driven toward Paradise in chains.”"]},"buhuth":{"en":["Regarding the statement:","“They enter Paradise in chains,”","the author says it has two meanings:","1. Disbelievers who were captured and bound in chains, then later accepted Islam, and consequently enter Paradise.","2. Muslims who were bound in chains in the prisons of disbelievers and died there, then enter Paradise with their chains."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الدولابي في الكنى (1264)، والبزار (2780)."},{"num":16365,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَدْخُلُ الْجَنَّةَ أَقْوَامٌ أَفْئِدَتُهُمْ مِثْلُ أَفْئِدَةِ الطَّيْرِ."],"takhrij":"صحيح: رواه مسلم في الجنة وصفة نعيمها وأهلها (2840) عن حجاج بن الشاعر، حدثنا أبو النضر هاشم بن القاسم الليثي، حدثنا إبراهيم –يعني ابن سعد، حدثنا أبي، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب يدخل الجنة أقوام أفئدتهم مثل أفئدة الطير","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2840).","chapter_en":"People Whose Hearts Are Like the Hearts of Birds Will Enter Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “People whose hearts are like the hearts of birds will enter Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2840)."},{"num":16366,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِنَّ فُقَرَاءَ الْمُهَاجِرِينَ يَسْبِقُونَ الْأَغْنِيَاءَ يَوْمَ الْقِيَامَةِ إِلَى الْجَنَّةِ بِأَرْبَعِينَ خَرِيفًا."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2979) عن أبي الطاهر أحمد بن عمرو بن سرح، أخبرنا ابن وهب، أخبرني أبو هانئ، سمع أبا عبد الرحمن الحبلي، يقول: سمعت عبد الله بن عمرو يقول فذكره.","grade":"صحيح","chapter_ar":"باب يدخل الفقراء الجنة قبل الأغنياء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2979).","chapter_en":"The Poor Will Enter Paradise Before the Rich","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: I heard the Messenger of Allah ﷺ say: “The poor among the Muhājirūn will precede the wealthy into Paradise on the Day of Resurrection by forty years.”"]},"buhuth":{"en":["The author states that this specifically concerns the poor among the Muhājirūn."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2979). وهذا خاص بفقراء المهاجرين."},{"num":16367,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فُقَرَاءُ الْمُهَاجِرِينَ يَدْخُلُونَ الْجَنَّةَ قَبْلَ أَغْنِيَائِهِمْ بِخَمْسِمِائَةِ سَنَةٍ."],"takhrij":"حسن: رواه الترمذي (2351)، وابن ماجه (4123) كلاهما من طرق عن عطية العوفي، عن أبي سعيد الخدري، فذكره.","grade":"حسن","chapter_ar":"باب يدخل الفقراء الجنة قبل الأغنياء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2351) and Ibn Mājah (4123).","chapter_en":"The Poor Will Enter Paradise Before the Rich","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “The poor among the Muhājirūn will enter Paradise five hundred years before their wealthy ones.”"]},"buhuth":{"en":["There is no contradiction between forty years and five hundred years, because the difference relates to the varying degrees of poverty and wealth among them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2351)، وابن ماجه (4123)."},{"num":16368,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يَدْخُلُ فُقَرَاءُ الْمُؤْمِنِينَ الْجَنَّةَ قَبْلَ أغنيائهم بخمس مئة عَامٍ."],"takhrij":"حسن: رواه الترمذي (2353، 2354)، وابن ماجه (4122)، وابن حبان (676) كلهم من طريق محمد بن عمرو، عن أبي سلمة، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب يدخل الفقراء الجنة قبل الأغنياء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2354, 2353), Ibn Mājah (4122), and Ibn Ḥibbān (676).","chapter_en":"The Poor Will Enter Paradise Before the Rich","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The poor believers will enter Paradise five hundred years before their wealthy ones.”"]},"buhuth":{"en":["The author notes that this applies generally to all Muslims, including the poor among the Muhājirūn."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2354، 2353)، وابن ماجه (4122)، وابن حبان (676)."},{"num":16369,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، قَالَ: كُنْتُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَطَلَعَتِ الشَّمْسُ، فَقَالَ: يَأْتِي اللهَ قَوْمٌ يَوْمَ الْقِيَامَةِ، نُورُهُمْ كَنُورِ الشَّمْسِ، فَقَالَ أَبُو بَكْرٍ: أَنَحْنُ هُمْ يَا رَسُولَ اللَّهِ؟ قَالَ: لَا، وَلَكُمْ خَيْرٌ كَثِيرٌ، وَلَكِنَّهُمُ الْفُقَرَاءُ وَالْمُهَاجِرُونَ الَّذِينَ يُحْشَرُونَ مِنْ أَقْطَارِ الْأَرْضِ وَقَالَ: طُوبَى لِلْغُرَبَاءِ، طُوبَى لِلْغُرَبَاءِ، طُوبَى لِلْغُرَبَاءِ، فَقِيلَ: مَنِ الْغُرَبَاءُ يَا رَسُولَ اللَّهِ؟ قَالَ: نَاسٌ صَالِحُونَ فِي نَاسِ سَوْءٍ كَثِيرٍ، مَنْ يَعْصِيهِمْ أَكْثَرُ مِمَّنْ يُطِيعُهُمْ."],"takhrij":"حسن: رواه أحمد (7072) عن قتيبة، حدثنا ابن لهيعة، عن الحارث بن يزيد، عن جندب بن عبد الله، عن سفيان بن عوف، عن عبدالله بن عمرو، قال: فذكره.","grade":"حسن","chapter_ar":"باب يدخل الفقراء الجنة قبل الأغنياء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (7072).","chapter_en":"The Poor Will Enter Paradise Before the Rich","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: I was with the Messenger of Allah ﷺ when the sun rose. He said: “Allah will bring forth people on the Day of Resurrection whose light will be like the light of the sun.” Abū Bakr asked: “Are we among them, O Messenger of Allah?” He replied: “No, although you have abundant good. Rather, they are the poor Muhājirūn who will be gathered from the farthest regions of the earth.” He also said: “Glad tidings to the strangers! Glad tidings to the strangers! Glad tidings to the strangers!” It was asked: “Who are the strangers, O Messenger of Allah?” He replied: “Righteous people among a great many evil people; those who disobey them are more numerous than those who obey them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7072)."},{"num":16370,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: هَلْ تَدْرُونَ أَوَّلَ مَنْ يَدْخُلُ الْجَنَّةَ مِنْ خَلْقِ اللهِ؟ قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: أَوَّلُ مَنْ يَدْخُلُ الْجَنَّةَ مِنْ خَلْقِ اللهِ الْفُقَرَاءُ الْمُهَاجِرُونَ، الَّذِينَ تُسَدُّ بِهِمُ الثُّغُورُ، وَيُتَّقَى بِهِمُ الْمَكَارِهُ، وَيَمُوتُ أَحَدُهُمْ وَحَاجَتُهُ فِي صَدْرِهِ، لَا يَسْتَطِيعُ لَهَا قَضَاءً فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لِمَنْ يَشَاءُ مِنْ مَلَائِكَتِهِ: ائْتُوهُمْ فَحَيُّوهُمْ، فَتَقُولُ الْمَلَائِكَةُ: نَحْنُ سُكَّانُ سَمَائِكَ، وَخِيرَتُكَ مِنْ خَلْقِكَ، أَفَتَأْمُرُنَا أَنْ نَأْتِيَ هَؤُلَاءِ فَنُسَلِّمَ عَلَيْهِمْ؟ قَالَ: إِنَّهُمْ كَانُوا عِبَادًا يَعْبُدُونِي، لَا يُشْرِكُونَ بِي شَيْئًا، وَتُسَدُّ بِهِمُ الثُّغُورُ، وَيُتَّقَى بِهِمُ الْمَكَارِهُ، وَيَمُوتُ أَحَدُهُمْ، وَحَاجَتُهُ فِي صَدْرِهِ، لَا يَسْتَطِيعُ لَهَا قَضَاءً قَالَ: فَتَأْتِيهِمُ الْمَلَائِكَةُ عِنْدَ ذَلِكَ، فَيَدْخُلُونَ عَلَيْهِمْ مِنْ كُلِّ بَابٍ: ﴿سَلَامٌ عَلَيْكُمْ بِمَا صَبَرْتُمْ فَنِعْمَ عُقْبَى الدَّارِ﴾ [الرعد:"],"takhrij":"صحيح: رواه أحمد (6571، 6570)، والبزار (2457)، وصحّحه ابن حبان (7421)، والحاكم (2/71-72) كلهم من طرق عن أبي عشانة المعافري حي بن يؤمن، عن عبد الله بن عمرو قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب يدخل الفقراء الجنة قبل الأغنياء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (6570, 6571), al-Bazzār (2457), authenticated by Ibn Ḥibbān (7421), and al-Ḥākim (2/71).","chapter_en":"The Poor Will Enter Paradise Before the Rich","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “Do you know who among Allah’s creation will be the first to enter Paradise?” They replied: “Allah and His Messenger know best.” He said: “The first of Allah’s creation to enter Paradise will be the poor Muhājirūn—those through whom the frontier posts are defended and hardships are warded off. One of them dies while a need remains in his heart that he was unable to fulfill. Allah, Mighty and Majestic, will say to whichever angels He wills: ‘Go to them and greet them.’ The angels will say: ‘We are the inhabitants of Your heaven and the chosen among Your creation. Do You command us to go to these people and greet them?’ He will say: ‘They were servants who worshipped Me and associated nothing with Me. Through them the frontier posts were defended and hardships were warded off. One of them would die while a need remained in his heart that he was unable to fulfill.’ Then the angels will come to them and enter upon them through every gate, saying: ‘Peace be upon you for what you patiently endured. Excellent indeed is the final home.’ [al-Raʿd 13:24]”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10057],"tks":"صحيح: رواه أحمد (6570، 6571)، والبزار (2457)، وصححه ابن حبان (7421)، والحاكم (2/71)."},{"num":16371,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجْتَمِعُونَ يَوْمَ الْقِيَامَةِ، فَيُقَالُ: أَيْنَ فُقَرَاءُ هَذِهِ الأُمَّةِ وَمَسَاكِينُهَا؟ قَالَ: فَيَقُومُونَ، فَيُقَالُ لَهُمْ: مَاذَا عَمِلْتُمْ؟ فَيَقُولُونَ: رَبَّنَا ابْتَلَيْتَنَا فَصَبَرْنَا، وَوَلَّيْتَ الأَمْوَالَ وَالسُّلْطَانَ غَيْرَنَا، فَيَقُولُ اللَّهُ: جَلَّ وعلا: صَدَقْتُمْ، قَالَ: فَيَدْخُلُونَ الْجَنَّةَ قَبْلَ النَّاسِ، وَتَبْقَى شِدَّةُ الْحِسَابِ عَلَى ذَوِي الأَمْوَالِ وَالسُّلْطَانِ، قَالُوا: فَأَيْنَ الْمُؤْمِنُونَ يَوْمَئِذٍ؟ قَالَ: يُوضَعُ لَهُمْ كَرَاسِيُّ مِنْ نُورٍ، وَتُظَلَّلُ عَلَيْهِمُ الْغَمَامُ، يَكُونُ ذَلِكَ الْيَوْمُ أَقْصَرَ عَلَى الْمُؤْمِنِينَ مِنْ سَاعَةٍ مِنْ نَهَارٍ."],"takhrij":"حسن: رواه ابن حبان (7419)، والطبراني (13/553) كلاهما من طريق مسكين بن بكير قال: حدثنا شعبة، عن عمرو بن مرة، عن عبد الله بن الحارث، عن أبي كثير الزبيدي، عن عبد الله بن عمرو، فذكره.","grade":"حسن","chapter_ar":"باب يدخل الفقراء الجنة قبل الأغنياء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (7419) and al-Ṭabarānī (13/553).","chapter_en":"The Poor Will Enter Paradise Before the Rich","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Prophet ﷺ said: “You will be gathered on the Day of Resurrection, and it will be said: ‘Where are the poor and needy of this Ummah?’ They will stand, and it will be asked: ‘What did you do?’ They will say: ‘Our Lord, You tested us and we were patient, while You gave wealth and authority to others besides us.’ Allah will say: ‘You have spoken the truth.’ Then they will enter Paradise before the other people, while the severity of the reckoning will remain upon those who possessed wealth and authority.” They asked: “Where will the believers be at that time?” He replied: “Chairs of light will be placed for them, and clouds will shade them. That Day will be shorter for the believers than an hour of a daytime.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (7419)، والطبراني (13/553)."},{"num":16372,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُنْتُ قَائِمًا عِنْدَ رَسُولِ اللَّهِ، فَجَاءَ حَبْرٌ مِنْ أَحْبَارِ الْيَهُودِ، فَقَالَ: السَّلَامُ عَلَيْكَ يَا مُحَمَّدُ! فَدَفَعْتُهُ دَفْعَةً كَادَ يُصْرعُ مِنْهَا. فَقَالَ: لِمَ تَدْفَعُنِي؟ فَقُلْتُ: أَلَا تَقُولُ: يَا رَسُولَ اللَّهِ؟ فَقَالَ الْيَهُودِيُّ: إِنَّمَا نَدْعُوهُ بِاسْمِهِ الَّذِي سَمَّاهُ بِهِ أَهْلُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إنّ اسْمِي مُحَمَّدٌ الَّذِي سَمَّانِي بِهِ أَهْلِي. فَقَالَ الْيَهُودِيُّ: جئتُ أَسْأَلُكَ. فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَيَنْفَعُكَ شيءٌ إِنْ حدّثْتُك؟. قَالَ: أَسْمَعُ بِأُذُنَيَّ، فَنَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بعُودٍ مَعَهُ، فَقَالَ: سَلْ. فَقَالَ الْيَهُودِيُّ: أَيْنَ يَكُونُ النّاسُ يَوْمَ تُبدَّل الْأَرْضُ غيرَ الْأَرْضِ وَالسَّمَاوَاتُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : هُمْ فِي الظُّلْمة دُونَ الْجِسْرِ. قَالَ: فَمَنْ أوّل النَّاسِ إِجَازَةً؟ قَالَ: فُقَرَاءُ الْمُهَاجِرِينَ."],"takhrij":"صحيح: رواه مسلم في الحيض (315: 34) عن الحسن بن علي الحلواني، حدثنا أبو توبة -هو الربيع بن نافع-، حدثنا معاوية –يعني ابن سلام-، عن زيد-يعني أخاه- أنه سمع أبا سلام، قال: حدثني أبو أسماء الرحبي، أن ثوبان مولى رسول الله صلى الله عليه وسلم قال: فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب يدخل الفقراء الجنة قبل الأغنياء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (34 :315).","chapter_en":"The Poor Will Enter Paradise Before the Rich","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Thawbān, the freedman of the Messenger of Allah ﷺ, narrated: I was standing with the Messenger of Allah ﷺ when a Jewish scholar came and said: “Peace be upon you, O Muḥammad.” I pushed him so forcefully that he nearly fell. He asked: “Why did you push me?” I said: “Why do you not say, ‘O Messenger of Allah’?” The Jewish man replied: “We only call him by the name his family gave him.” The Messenger of Allah ﷺ said: “My name is Muḥammad, the name by which my family named me.” The Jewish man said: “I have come to ask you.” The Messenger of Allah ﷺ asked: “Will it benefit you if I answer you?” He replied: “I will listen with my ears.” The Messenger of Allah ﷺ began drawing with a stick he had and said: “Ask.” The Jewish man asked: “Where will the people be on the Day when the earth is changed into another earth and the heavens as well?” The Messenger of Allah ﷺ replied: “They will be in darkness before the bridge.” He asked: “Who will be the first people to cross?” He replied: “The poor among the Muhājirūn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (315: 34)."},{"num":16373,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : يَخْلُصُ الْمُؤْمِنُونَ مِنَ النَّارِ، فَيُحْبَسُونَ عَلَى قَنْطَرَةٍ بَيْنَ الْجَنَّةِ وَالنَّارِ، فَيُقَصُّ لِبَعْضِهِمْ مِنْ بَعْضٍ مَظَالِمُ كَانَتْ بَيْنَهُمْ فِي الدُّنْيَا، حَتَّى إِذَا هُذِّبُوا وَنُقُّوا أُذِنَ لَهُمْ فِي دُخُولِ الْجَنَّةِ، فَوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لأَحَدُهُمْ أَهْدَى بِمَنْزِلِهِ فِي الْجَنَّةِ مِنْهُ بِمَنْزِلِهِ كَانَ فِي الدُّنْيَا."],"takhrij":"صحيح: رواه البخاري في الرقاق (6535) عن الصلت بن محمد، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، عن أبي المتوكل الناجي، أن أبا سعيد الخدري قال: فذكره.","grade":"صحيح","chapter_ar":"باب انتزاع الغل من صدور أهل الجنة قبل الدخول فيها","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6535).","chapter_en":"Resentment Will Be Removed from the Hearts of the People of Paradise Before They Enter It","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “The believers will be delivered from the Fire, then detained upon a bridge between Paradise and the Fire. Retribution will be taken among them for wrongs they committed against one another in the worldly life. When they have been purified and cleansed, permission will be granted to them to enter Paradise. By the One in whose hand is the soul of Muḥammad, each of them will know his dwelling in Paradise more readily than he knew his dwelling in this world.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَنَزَعْنَا مَا فِي صُدُورِهِمْ مِنْ غِلٍّ إِخْوَانًا عَلَىٰ سُرُرٍ مُتَقَابِلِينَ﴾ [الحجر: ٤٧]."],"en":["Allah, the Exalted, says:","“We will remove whatever resentment is in their hearts, so they will be brothers, facing one another upon couches.”","[al-Ḥijr 15:47]"]}},"tuhfa":{},"full":1,"rep":[12607,12718,13279,16219,16410],"tks":"صحيح: رواه البخاري (6535)."},{"num":16374,"demo":false,"sanad":"","matn":["عن حصين بن عَبْدِ الرَّحْمَنِ قَالَ: كُنْتُ عِنْدَ سَعِيدِ بْنِ جُبَيْرٍ، فَقَالَ:  أَيُّكُمْ رَأَى الْكَوْكَبَ الَّذِي انْقَضَّ الْبَارِحَةَ؟ قُلْتُ: أَنَا، ثُمَّ قُلْتُ: أَمَا إِنِّي لَمْ أَكُنْ فِي صَلَاةٍ، وَلَكِنِّي لُدِغْتُ، قَالَ: فَمَاذَا صَنَعْتَ؟ قُلْتُ: اسْتَرْقَيْتُ، قَالَ: فَمَا حَمَلَكَ عَلَى ذَلِكَ؟ قُلْتُ: حَدِيثٌ حَدَّثَنَاهُ الشَّعْبِيُّ، فَقَالَ: وَمَا حَدَّثَكُمُ الشَّعْبِيُّ؟ قُلْتُ: حَدَّثَنَا عَنْ بُرَيْدَةَ بْنِ حُصَيْبٍ الْأَسْلَمِيِّ، أَنَّهُ قَالَ: لَا رُقْيَةَ إِلَّا مِنْ عَيْنٍ، أَوْ حُمَةٍ، فَقَالَ: قَدْ أَحْسَنَ مَنِ انْتَهَى إِلَى مَا سَمِعَ، وَلَكِنْ حَدَّثَنَا ابْنُ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عُرِضَتْ عَلَيَّ الْأُمَمُ، فَرَأَيْتُ النَّبِيَّ وَمَعَهُ الرُّهَيْطُ، وَالنَّبِيَّ وَمَعَهُ الرَّجُلُ وَالرَّجُلَانِ، وَالنَّبِيَّ لَيْسَ مَعَهُ أَحَدٌ، إِذْ رُفِعَ لِي سَوَادٌ عَظِيمٌ، فَظَنَنْتُ أَنَّهُمْ أُمَّتِي، فَقِيلَ لِي: هَذَا مُوسَى صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَوْمُهُ، وَلَكِنِ انْظُرْ إِلَى الْأُفُقِ، فَنَظَرْتُ فَإِذَا سَوَادٌ عَظِيمٌ، فَقِيلَ لِي: انْظُرْ إِلَى الْأُفُقِ الْآخَرِ، فَإِذَا سَوَادٌ عَظِيمٌ، فَقِيلَ لِي: هَذِهِ أُمَّتُكَ، وَمَعَهُمْ سَبْعُونَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ، ثُمَّ نَهَضَ فَدَخَلَ مَنْزِلَهُ، فَخَاضَ النَّاسُ فِي أُولَئِكَ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ، فَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ صَحِبُوا رَسُولَ اللَّهِ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ وُلِدُوا فِي الْإِسْلَامِ وَلَمْ يُشْرِكُوا بِاللهِ، وَذَكَرُوا أَشْيَاءَ، فَخَرَجَ عَلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَا الَّذِي تَخُوضُونَ فِيهِ؟ فَأَخْبَرُوهُ، فَقَالَ: هُمُ الَّذِينَ لَا يَرْقُونَ، وَلَا يَسْتَرْقُونَ، وَلَا يَتَطَيَّرُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ، فَقَامَ عُكَّاشَةُ بْنُ مِحْصَنٍ، فَقَالَ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: أَنْتَ مِنْهُمْ، ثُمَّ قَامَ رَجُلٌ آخَرُ، فَقَالَ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ."],"takhrij":"متفق عليه: رواه مسلم في الإيمان (220) عن سعيد بن منصور، حدثنا هشيم، أخبرنا حصين بن عبد الرحمن قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (220) and al-Bukhārī (6541). Al-Bukhārī also mentioned part of this account in Kitāb al-Ṭibb (5705).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Ḥuṣayn ibn ʿAbd al-Raḥmān narrated: I was with Saʿīd ibn Jubayr when he asked: “Which of you saw the star that fell last night?” I said: “I did.” Then I added: “I was not praying at the time, however; I had been stung.” He asked: “What did you do?” I replied: “I sought ruqyah.” He asked: “What made you do that?” I replied: “A hadith al-Shaʿbī narrated to us.” He asked: “What did al-Shaʿbī narrate to you?” I said: “He narrated to us from Buraydah ibn al-Ḥuṣayb al-Aslamī that he said: ‘There is no ruqyah except for the evil eye or a venomous sting.’” Saʿīd said: “The one who stops at what he has heard has done well. But Ibn ʿAbbās narrated to us from the Prophet ﷺ that he said: ʿThe nations were shown to me. I saw a Prophet accompanied by a small group, a Prophet accompanied by one or two men, and a Prophet with no one at all. Then a vast multitude was shown to me, and I thought they were my Ummah. But it was said to me: “This is Mūsā ﷺ and his people. Look toward the horizon.” I looked and saw a vast multitude. Then it was said to me: “Look toward the other horizon.” I looked and saw another vast multitude. It was said to me: “This is your Ummah, and with them are seventy thousand who will enter Paradise without reckoning or punishment.”’” Then the Prophet ﷺ stood and entered his home. The people began discussing who those people might be who would enter Paradise without reckoning or punishment. Some said: “Perhaps they are those who accompanied the Messenger of Allah ﷺ.” Others said: “Perhaps they are those who were born in Islam and never associated anything with Allah.” They mentioned various possibilities. Then the Messenger of Allah ﷺ came out to them and asked: “What are you discussing?” They told him, and he said: “They are those who do not perform ruqyah for others, do not ask others for ruqyah, do not believe in evil omens, and place their trust in their Lord.” ʿUkāshah ibn Miḥṣan stood and said: “Ask Allah to make me among them.” He replied: “You are among them.” Then another man stood and said: “Ask Allah to make me among them.” He replied: “ʿUkāshah has preceded you to it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8448,10281],"tks":"متفق عليه: رواه مسلم (220) والبخاري (6541). وذكر البخاري بعض هذه القصة في كتاب الطب (5705)."},{"num":16375,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَدْخُلُ مِنْ أُمَّتِي الْجَنَّةَ سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ، فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: اللَّهُمَّ اجْعَلْهُ مِنْهُمْ، ثُمَّ قَامَ آخَرُ، فَقَالَ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (216) عن عبد الرحمن بن سلام الجمحي، حدثنا الربيع -يعني ابن مسلم-، عن محمد بن زياد، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (216).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Seventy thousand from my Ummah will enter Paradise without reckoning.” A man said: “O Messenger of Allah, ask Allah to make me among them.” He said: “O Allah, make him among them.” Then another man stood and said: “O Messenger of Allah, ask Allah to make me among them.” He replied: “ʿUkāshah has preceded you to it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (216)."},{"num":16376,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي زُمْرَةٌ هِيَ سَبْعُونَ أَلْفًا، تُضِيءُ وُجُوهُهُمْ إِضَاءَةَ الْقَمَرِ فَقَامَ عُكَاشَةُ بْنُ مِحْصَنٍ الأَسَدِيُّ، يَرْفَعُ نَمِرَةً عَلَيْهِ، قَالَ: ادْعُ اللَّهَ لِي يَا رَسُولَ اللَّهِ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: اللَّهُمَّ اجْعَلْهُ مِنْهُمْ ثُمَّ قَامَ رَجُلٌ مِنَ الأَنْصَارِ فَقَالَ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ رَسُولُ اللَّهِ: سَبَقَكَ عُكَاشَةُ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5811) عن أبي اليمان، أخبرنا شعيب، عن الزهري، قال: حدثني سعيد بن المسيب، أن أبا هريرة قال: فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Libās (5811) and Muslim (369 :216).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “A group of seventy thousand from my Ummah will enter Paradise, their faces shining like the moon.” ʿUkāshah ibn Miḥṣan al-Asadī stood, lifting the striped cloak he was wearing, and said: “O Messenger of Allah, ask Allah to make me among them.” He said: “O Allah, make him among them.” Then a man from the Anṣār stood and said: “O Messenger of Allah, ask Allah to make me among them.” The Messenger of Allah ﷺ replied: “ʿUkāshah has preceded you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5811) ومسلم (369 :216)."},{"num":16377,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا زُمْرَةٌ وَاحِدَةٌ مِنْهُمْ عَلَى صُورَةِ الْقَمَرِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (217) عن حرملة بن يحيى، حدثنا عبد الله بن وهب، أخبرني حيوة، قال: حدثني أبو يونس، عن أبي هريرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (217).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Seventy thousand from my Ummah will enter Paradise as a single group, their appearance like the moon.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (217)."},{"num":16378,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ قَالَ فِي حَدِيثِ طَوِيلٍ: فَتَنْجُو أَوَّلُ زُمْرَةٍ وُجُوهُهُمْ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ سَبْعُونَ أَلْفًا لَا يُحَاسَبُونَ، ثُمَّ الَّذِينَ يَلُونَهُمْ كَأَضْوَأِ نَجْمٍ فِي السَّمَاءِ، ثُمَّ كَذَلِكَ، ثُمَّ تَحِلُّ الشَّفَاعَةُ. الحديث."],"takhrij":"صحيح: رواه مسلم في الإيمان (191) من طرق عن روح بن عبادة القيسي، حدثنا ابن جريج، قال: أخبرني أبو الزبير، أنه سمع بن عبد الله يسأل عن الورود، فقال: فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (191).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated in a lengthy hadith: “The first group to be saved will consist of seventy thousand whose faces will be like the full moon. They will not be brought to account. Those who follow them will be like the brightest star in the sky, then those after them likewise. Then intercession will be permitted.” The hadith continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (191)."},{"num":16379,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيَدْخُلَنَّ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَوْ سَبْعُمِائَةِ أَلْفٍ ـ لاَ يَدْرِي أَبُو حَازِمٍ أَيُّهُمَا قَالَ ـ مُتَمَاسِكُونَ، آخِذٌ بَعْضُهُمْ بَعْضًا، لاَ يَدْخُلُ أَوَّلُهُمْ حَتَّى يَدْخُلَ آخِرُهُمْ، وُجُوهُهُمْ عَلَى صُورَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6554)، ومسلم في الإيمان (219) كلاهما عن قتيبة بن سعيد، حدثنا عبد العزيز -يعني ابن أبي حازم-، عن أبي حازم، عن سهل بن سعد، فذكره.","grade":"متفق عليه","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6554) and Muslim (219).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Messenger of Allah ﷺ said: “Seventy thousand from my Ummah—or seven hundred thousand; Abū Ḥāzim was uncertain which he said—will certainly enter Paradise holding closely to one another, each taking hold of the other. The first of them will not enter until the last of them has entered, and their faces will be like the full moon.”"]},"buhuth":{"en":["Regarding the phrase:","“Or seven hundred thousand,”","the author states that it is preferable to adopt the certain wording, “seventy thousand,” as this is supported by the other hadiths.","Regarding the phrase:","“Holding closely to one another, each taking hold of the other,”","the author explains that each will be holding the hand of another. They will enter spread out in a single row, side by side.","This clearly demonstrates the immense width of the gate of Paradise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6554)، ومسلم (219)."},{"num":16380,"demo":false,"sanad":"","matn":["عن عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: قَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ، قَالُوا: وَمَنْ هُمْ يَا رَسُولَ اللَّهِ؟ قَالَ: هُمُ الَّذِينَ لَا يَكْتَوُونَ وَلَا يَسْتَرْقُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ، فَقَامَ عُكَّاشَةُ فَقَالَ: ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: أَنْتَ مِنْهُمْ. قَالَ: فَقَامَ رَجُلٌ، فَقَالَ: يَا نَبِيَّ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (218) عن يحيى بن خلف الباهلي، حدثنا المعتمر، عن هشام بن حسان، عن محمد -يعني ابن سيرين-، قال: حدثني عمران، فذكره.","grade":"صحيح","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (218).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated that the Prophet of Allah ﷺ said: “Seventy thousand from my Ummah will enter Paradise without reckoning.” They asked: “Who are they, O Messenger of Allah?” He replied: “They are those who do not cauterize themselves, do not ask others for ruqyah, and place their trust in their Lord.” ʿUkāshah stood and said: “Ask Allah to make me among them.” He replied: “You are among them.” Then another man stood and said: “O Prophet of Allah, ask Allah to make me among them.” He replied: “ʿUkāshah has preceded you to it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10284],"tks":"صحيح: رواه مسلم (218)."},{"num":16381,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بن عرابة الْجُهَنِيِّ قَالَ: قال رَسُولِ اللَّهِ صلّى الله عليه وسلم: ...وَقَدْ وَعَدَنِي رَبِّي عز وجل أَنْ يُدْخِلَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا لَا حِسَابَ عَلَيْهِمْ، وَلَا عَذَابَ، وَإِنِّي لَأَرْجُو أَنْ لَا يدخلوها حَتَّى تبوؤوا أَنْتُمْ وَمَنْ صَلَحَ مِنْ آبَائِكُمْ وَأَزْوَاجِكُمْ وَذُرِّيَّاتِكُمْ مَسَاكِنَ فِي الْجَنَّةِ."],"takhrij":"صحيح: رواه أحمد (16215) عن إسماعيل بن إبراهيم، قال: حدثنا هشام الدستوائي، عن يحيى بن أبي كثير، عن هلال بن أبي ميمونة، عن عطاء بن يسار، عن رفاعة، في حديث طويل. انظر باب النّزول من كتاب الإيمان.","grade":"صحيح","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (16215).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Rifāʿah ibn ʿArābah al-Juhanī narrated that the Messenger of Allah ﷺ said: “…My Lord, Mighty and Majestic, has promised me that seventy thousand from my Ummah will enter Paradise without reckoning and without punishment. And I hope that they will not enter it until you, together with the righteous among your fathers, spouses, and descendants, have taken up your dwellings in Paradise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (16215)."},{"num":16382,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُرِيَ الْأُمَمَ بِالْمَوْسِمِ، فَرَاثَتْ عَلَيْهِ أُمَّتُهُ، قَالَ: فَأُرِيتُ أُمَّتِي، فَأَعْجَبَنِي كَثْرَتُهُمْ، قَدْ مَلَئُوا السَّهْلَ وَالْجَبَلَ، فَقِيلَ لِي: إِنَّ مَعَ هَؤُلَاءِ سَبْعونَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ، هُمُ الَّذِينَ لَا يَكْتَوُونَ، وَلَا يَسْتَرْقُونَ، وَلَا يَتَطَيَّرُونَ، وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ. فَقَالَ عُكَّاشَةُ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ. فَدَعَا لَهُ، ثُمَّ قَامَ - يَعْنِي آخَرُ - فَقَالَ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مَنَهُمْ. قَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ."],"takhrij":"حسن: رواه أحمد (3819)، والبزار في مسنده –كشف الأستار (3939)، وصحّحه ابن حبان (6084) كلهم من حديث حماد بن سلمة، عن عاصم، عن زر، عن ابن مسعود، فذكره.","grade":"حسن","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (3819), al-Bazzār in his Musnad — Kashf al-Astār (3939), and authenticated by Ibn Ḥibbān (6084).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["Ibn Masʿūd narrated that the nations were shown to the Messenger of Allah ﷺ during the season, and his Ummah was delayed in being shown to him. He said: “Then my Ummah was shown to me, and their great number amazed me. They filled the plain and the mountain. It was said to me: ‘Among these are seventy thousand who will enter Paradise without reckoning. They are those who do not cauterize themselves, do not ask others for ruqyah, do not believe in evil omens, and place their trust in their Lord.’” ʿUkāshah said: “O Messenger of Allah, ask Allah to make me among them.” So he supplicated for him. Then another man stood and said: “O Messenger of Allah, ask Allah to make me among them.” He replied: “ʿUkāshah has preceded you to it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11461],"tks":"حسن: رواه أحمد (3819)، والبزار في مسنده في كشف الأستار (3939)، وصححه ابن حبان (6084)."},{"num":16383,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، أَنَّهُ قَالَ: تَحَدَّثْنَا لَيْلَةً عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَكْرَيْنَا الْحَدِيثَ، ثُمَّ رَجَعْنَا إِلَى أَهْلِنَا، فَلَمَّا أَصْبَحْنَا، غَدَوْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: عُرِضَتْ عَلَيَّ الْأَنْبِيَاءُ بِأُمَمِهَا، وَأَتْبَاعُهَا مِنْ أُمَمِهَا، فَجَعَلَ النَّبِيُّ يَمُرُّ وَمَعَهُ الثَّلَاثَةُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَعَهُ الْعِصَابَةُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَعَهُ النَّفَرُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَعَهُ الرَّجُلُ مِنْ أُمَّتِهِ، وَالنَّبِيُّ مَا مَعَهُ أَحَدٌ مِنْ أُمَّتِهِ، حَتَّى مَرَّ عَلَيَّ مُوسَى بْنُ عِمْرَانَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي كَبْكَبَةٍ مِنْ بَنِي إِسْرَائِيلَ، فَلَمَّا رَأَيْتُهُمْ أَعْجَبُونِي، قُلْتُ: يَا رَبِّ مَنْ هَؤُلَاءِ؟ فَقَالَ: هَذَا أَخُوكَ مُوسَى بْنُ عِمْرَانَ وَمَنْ مَعَهُ مِنْ بَنِي إِسْرَائِيلَ، قُلْتُ: يَا رَبِّ، فَأَيْنَ أُمَّتِي؟ قَالَ: انْظُرْ عَنْ يَمِينِكَ، فَإِذَا الظِّرَابُ ظِرَابُ مَكَّةَ، قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ، قُلْتُ: مَنْ هَؤُلَاءِ يَا رَبِّ، قَالَ: أُمَّتُكَ، قُلْتُ: رَضِيتُ رَبِّ، قَالَ: أَرَضِيتَ؟ قُلْتُ: نَعَمْ، قَالَ: انْظُرْ عَنْ يَسَارِكَ، قَالَ: فَنَظَرْتُ، فَإِذَا الْأُفُقُ قَدْ سُدَّ بِوُجُوهِ الرِّجَالِ، فَقَالَ: رَضِيتَ؟ قُلْتُ: رَضِيتُ، قِيلَ: فَإِنَّ مَعَ هَؤُلَاءِ سَبْعِينَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ، لَا حِسَابَ لَهُمْ، فَأَنْشَأَ عُكَّاشَةُ بْنُ مِحْصَنٍ، أَحَدُ بَنِي أَسَدِ بْنِ خُزَيْمَةَ، فَقَالَ: يَا نَبِيَّ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: اللهُمَّ اجْعَلْهُ مِنْهُمْ، ثُمَّ أَنْشَأُ رَجُلٌ آخَرُ مِنْهُمْ، فَقَالَ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ يَجْعَلَنِي مِنْهُمْ، قَالَ: سَبَقَكَ بِهَا عُكَّاشَةُ."],"takhrij":"صحيح: رواه أحمد (3989) عن محمد بن بكر، قال: أخبرنا سعيد، عن قتادة، عن الحسن، والعلاء بن زياد، عن عمران بن حصين، عن عبد الله بن مسعود، فذكره.","grade":"صحيح","chapter_ar":"باب سبعون ألفًا يدخلون الجنة بغير حساب","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (3989).","chapter_en":"Seventy Thousand Will Enter Paradise Without Reckoning","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: One night we remained with the Messenger of Allah ﷺ talking until the conversation became lengthy, then we returned to our families. The next morning we went to the Messenger of Allah ﷺ, and he said: “Last night the Prophets and the followers from their nations were shown to me. A Prophet would pass with three members of his nation, another Prophet with a group from his nation, another with a small number, another with one man, and another Prophet with no one from his nation. Then Mūsā ibn ʿImrān ﷺ passed before me with a large gathering of the Children of Israel. When I saw them, I was impressed by them. I said: ‘My Lord, who are these?’ He said: ‘This is your brother Mūsā ibn ʿImrān and those with him from the Children of Israel.’ I asked: ‘My Lord, then where is my Ummah?’ He said: ‘Look to your right.’ I looked, and the hills of Makkah were covered with the faces of men. I asked: ‘Who are these, my Lord?’ He said: ‘Your Ummah.’ I said: ‘I am pleased, my Lord.’ He asked: ‘Are you pleased?’ I said: ‘Yes.’ He said: ‘Look to your left.’” The Prophet ﷺ continued: “I looked, and the entire horizon was filled with the faces of men. He asked: ‘Are you pleased?’ I said: ‘I am pleased.’ Then it was said: ‘Among these are seventy thousand who will enter Paradise without reckoning.’” ʿUkāshah ibn Miḥṣan, one of Banū Asad ibn Khuzaymah, stood and said: “O Prophet of Allah, ask Allah to make me among them.” He said: “O Allah, make him among them.” Then another man stood and said: “O Messenger of Allah, ask Allah to make me among them.” He replied: “ʿUkāshah has preceded you to it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11462],"tks":"صحيح: رواه أحمد (3989)."},{"num":16384,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ وَعَدَنِي أَنْ يُدْخِلَ مِنْ أُمَّتِي الْجَنَّةَ سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ. فَقَالَ يَزِيدُ بْنُ الْأَخْنَسِ السُّلَمِيُّ وَاللهِ مَا أُولَئِكَ فِي أُمَّتِكَ إِلَّا كَالذُّبَابِ الْأَصْهَبِ فِي الذِّبَّانِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِنَّ رَبِّي قَدْ وَعَدَنِي سَبْعِينَ أَلْفًا مَعَ كُلِّ أَلْفٍ سَبْعُونَ أَلْفًا وَزَادَنِي ثَلَاثَ حَثَيَاتٍ."],"takhrij":"صحيح: رواه أحمد (22156)، وابن حبان (7246) كلاهما من طريق صفوان بن عمرو، عن سُليم بن عامر الخبائريّ وأبي اليمان الهوزَنيّ، عن أبي أمامة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب يدخل من أمة محمد سبعون ألفًا، مع كل ألف سبعون ألفًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (22156) and Ibn Ḥibbān (7246).","chapter_en":"Seventy Thousand from the Ummah of Muḥammad ﷺ Will Enter Paradise, and with Every Thousand Another Seventy Thousand","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Umāmah narrated that the Messenger of Allah ﷺ said: “Allah has promised me that seventy thousand from my Ummah will enter Paradise without reckoning.” Yazīd ibn al-Akhnas al-Sulamī said: “By Allah, those among your Ummah are only like a reddish fly among all the flies!” The Messenger of Allah ﷺ replied: “My Lord has also promised me seventy thousand with every thousand, and He has additionally granted me three handfuls.”"]},"buhuth":{"en":["Regarding the phrase:","“With every thousand, seventy thousand,”","the author states that this was an additional grant from Allah, Mighty and Majestic, after the Prophet ﷺ asked Him for an increase, as explained in the following hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (22156)، وابن حبان (7246)."},{"num":16385,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: سَأَلْتُ رَبِّي عَزَّ وَجَلَّ فَوَعَدَنِي أَنْ يُدْخِلَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا عَلَى صُورَةِ الْقَمَرِ لَيْلَةِ الْبَدْرِ، فَاسْتَزَدْتُ، فَزَادَنِي مَعَ كُلِّ أَلْفٍ سَبْعِينَ أَلْفًا، فَقُلْتُ: أَيْ رَبِّ، إِنْ لَمْ يَكُنْ هَؤُلَاءِ مُهَاجِرِي أُمَّتِي، قَالَ: إِذَنْ أُكْمِلَهُمْ لَكَ مِنَ الْأَعْرَابِ."],"takhrij":"حسن: رواه أحمد (8707) عن يحيى بن أبي بكير، حدثنا زهير بن محمد، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب يدخل من أمة محمد سبعون ألفًا، مع كل ألف سبعون ألفًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8707).","chapter_en":"Seventy Thousand from the Ummah of Muḥammad ﷺ Will Enter Paradise, and with Every Thousand Another Seventy Thousand","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “I asked my Lord, Mighty and Majestic, and He promised me that seventy thousand from my Ummah would enter Paradise with the appearance of the full moon. I asked Him for more, so He increased them by seventy thousand with every thousand. I said: ‘My Lord, what if those numbers are not completed by the Muhājirūn of my Ummah?’ He said: ‘Then I will complete their number for you from the Bedouins.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8707)."},{"num":16386,"demo":false,"sanad":"","matn":["عَنْ عُتْبَةَ بْنِ عَبْدِ السُّلَمِيِّ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لَهُ: مَا حَوْضُكَ الَّذِي تُحَدِّثُ عَنْهُ؟ قَالَ: هُوَ كَمَا بَيْنَ الْبَيْضَاءِ إِلَى بُصْرَى، ثُمَّ يُمِدُّنِي اللَّهُ عَزَّ وَجَلَّ فِيهِ بِكُرَاعٍ، فلا يَدْرِي بشر مِمَّنْ خُلِقَ أَيْنَ طَرَفَاهُ. قَالَ: فَكَبَّرَ عُمَرُ بن الْخَطَّابِ. فَقَالَ: أَمَّا الْحَوْضُ فيزدحم عَلَيْهِ فُقَرَاءُ الْمُهَاجِرِينَ الَّذِينَ يقتلون فِي سَبِيلِ اللَّهِ، وَيَمُوتُونَ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ، وَأَرْجُو أَنْ يُورِدَنِي الله عَزَّ وَجَلَّ الْكُرَاعَ فَأَشْرَبَ مِنْهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ رَبِّي عَزَّ وَجَلَّ وَعَدَنِي أَنْ يُدْخِلَ الْجَنَّةَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ، ثُمَّ يَشْفَعُ كُلُّ أَلْفٍ بسبعين أَلْفٍ، ثُمَّ يَحْثِي لِي بِكَفَّيْهِ ثَلَاثَ حَثَيَاتٍ، وكبر عُمَرُ فَقَالَ: إِنَّ السَّبْعِينَ الألف الأولين يُشَفِّعُهُمُ اللَّهُ عَزَّ وَجَلَّ فِي آبَائِهِمْ وَأَبْنَائِهِمْ وَعَشَائِرِهِمْ، وَأَرْجُو أَنْ يَجْعَلَنِي اللَّهُ عَزَّ وَجَلَّ فِي أحد الْحَثَيَاتِ الْأَوَاخِرِ."],"takhrij":"حسن: رواه الفسوي في تاريخه (2/341-342)، والطبراني في الكبير (17/126-127) كلاهما من طريق أبي توبة قال: حدثنا معاوية بن سلام، عن زيد بن سلام، أنه سمع أبا سلام قال: حدثني عامر بن زيد البكالي أنه سمع عتبة بن عبد السلمي يقول: فذكره.","grade":"حسن","chapter_ar":"باب يدخل من أمة محمد سبعون ألفًا، مع كل ألف سبعون ألفًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Fasawī in his Tārīkh (2/341-342) and al-Ṭabarānī in al-Muʿjam al-Kabīr (17/126-127).","chapter_en":"Seventy Thousand from the Ummah of Muḥammad ﷺ Will Enter Paradise, and with Every Thousand Another Seventy Thousand","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulamī narrated: A Bedouin came to the Messenger of Allah ﷺ and asked: “What is this Ḥawḍ that you speak about?” He replied: “It is like the distance from al-Bayḍāʾ to Buṣrā. Then Allah, Mighty and Majestic, will supply it for me through an inlet whose two ends no human being among His creation knows.” ʿUmar ibn al-Khaṭṭāb proclaimed Allah’s greatness. He said: “As for the Ḥawḍ, the poor among the Muhājirūn who are killed in the path of Allah and die in the path of Allah, Mighty and Majestic, will crowd around it. I hope that Allah, Mighty and Majestic, will bring me to that inlet so that I may drink from it.” The Messenger of Allah ﷺ said: “My Lord, Mighty and Majestic, has promised me that seventy thousand from my Ummah will enter Paradise without reckoning. Then every thousand will intercede for seventy thousand, and then He will take three handfuls for me with His two Hands.” ʿUmar proclaimed Allah’s greatness and said: “The first seventy thousand will be enabled by Allah, Mighty and Majestic, to intercede for their fathers, their children, and their clans. And I hope that Allah, Mighty and Majestic, will place me in one of the final handfuls.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الفسوي في تاريخه (2/341-342)، والطبراني في الكبير (17/126-127)."},{"num":16387,"demo":false,"sanad":"","matn":["عن شريح بْنِ عبيد مَرِضَ ثَوْبَانُ بِحِمْصَ، وَعَلَيْهَا عَبْدُ اللَّهِ بْنُ قُرْطٍ الْأَزْدِيُّ، فَلَمْ يَعُدْهُ فَدَخَلَ عَلَى ثَوْبَانَ رَجُلٌ مِنَ الْكَلَاعِيِّينَ عَائِدًا. فَقَالَ لَهُ ثَوْبَانُ: أَتَكْتُبُ؟ فَقَالَ: نَعَمْ. فَقَالَ: اكْتُبْ. فَكَتَبَ لِلْأَمِيرِ عَبْدِ اللَّهِ بْنِ قُرْطٍ: مِنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا بَعْدُ، فَإِنَّهُ لَوْ كَانَ لِمُوسَى وعِيسَى مَوْلًى بِحَضْرَتِكَ لَعُدْتَهُ، ثُمَّ طَوَى الْكِتَابَ وَقَالَ لَهُ: أَتُبَلِّغُهُ إِيَّاهُ؟ فَقَالَ: نَعَمْ. فَانْطَلَقَ الرَّجُلُ بِكِتَابِهِ فَدَفَعَهُ إِلَى ابْنِ قُرْطٍ، فَلَمَّا قَرَأَهُ قَامَ فَزِعًا، فَقَالَ النَّاسُ: مَا شَأْنُهُ أَحَدَثَ أَمْرٌ، فَأَتَى ثَوْبَانَ حَتَّى دَخَلَ عَلَيْهِ، فَعَادَهُ وَجَلَسَ عِنْدَهُ سَاعَةً، ثُمَّ قَامَ فَأَخَذَ ثَوْبَانُ بِرِدَائِهِ، وَقَالَ: اجْلِسْ حَتَّى أُحَدِّثَكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، سَمِعْتُهُ يَقُولُ: لَيَدْخُلَنَّ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا لَا حِسَابَ عَلَيْهِمْ، وَلَا عَذَابَ، مَعَ كُلِّ أَلْفٍ سَبْعُونَ أَلْفًا."],"takhrij":"حسن: رواه أحمد (22418) عن أبي اليمان، حدثنا إسماعيل بن عياش، عن ضمضم بن زرعة قال: شريح بن عبيد، فذكر الحديث.","grade":"حسن","chapter_ar":"باب يدخل من أمة محمد سبعون ألفًا، مع كل ألف سبعون ألفًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22418).","chapter_en":"Seventy Thousand from the Ummah of Muḥammad ﷺ Will Enter Paradise, and with Every Thousand Another Seventy Thousand","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Shurayḥ ibn ʿUbayd narrated: Thawbān became ill in Ḥimṣ while ʿAbdullāh ibn Qurṭ al-Azdī was its governor, but he did not visit him. A man from the Kalāʿiyyīn entered upon Thawbān to visit him. Thawbān asked: “Can you write?” He replied: “Yes.” Thawbān said: “Write.” So he wrote to the governor ʿAbdullāh ibn Qurṭ: “From Thawbān, the freedman of the Messenger of Allah ﷺ. To proceed: Had there been a freedman of Mūsā or ʿĪsā present near you, you would have visited him.” Then he folded the letter and asked: “Will you deliver this to him?” The man replied: “Yes.” He went and handed the letter to Ibn Qurṭ. When he read it, he stood up alarmed. The people asked: “What is the matter? Has something happened?” He went to Thawbān, entered upon him, visited him, and sat with him for a while. When he stood to leave, Thawbān took hold of his cloak and said: “Sit down until I narrate to you a hadith I heard from the Messenger of Allah ﷺ.” He said: “Seventy thousand from my Ummah will certainly enter Paradise without reckoning or punishment, and with every thousand will be another seventy thousand.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22418)."},{"num":16388,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الأنماري، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ رَبِّي وَعَدَنِي أَنْ يُدْخَلَ الْجَنَّةَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ، وَيَشْفَعُ كُلُّ أَلْفٍ لِسَبْعِينَ أَلْفًا، ثُمَّ يَحْثِي رَبِّي ثَلَاثَ حَثَيَاتٍ بِكَفَّيْهِ. قَالَ قَيْسٌ: فَقُلْتُ لِأَبِي سَعِيدٍ: أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ؟ قَالَ: نَعَمْ، بِأُذُنِي وَوَعَاهُ قَلْبِي. قَالَ أَبُو سَعِيدٍ: وَذَلِكَ إِنْ شَاءَ اللَّهُ يَسْتَوْعِبُ مُهَاجِرِي أمته، ويُوَفِّيَ اللَّهُ عَزَّ وَجَلَّ بَقِيَّتَهُ مِنْ أَعْرَابِنَا."],"takhrij":"صحيح: رواه الطبراني في الأوسط (406)، وفي الكبير (22/304-305) عن أحمد بن خُليد، حدثنا أبو توبة الربيع بن نافع، حدثنا معاوية بن سلام، عن زيد بن سلام، أنه سمع أبا سلام، يقول: حدثني عبد الله بن عامر، أن قيس بن الحارث الكندي حدثه، أن أبا سعيد الأنماري قال: فذكره.","grade":"صحيح","chapter_ar":"باب يدخل من أمة محمد سبعون ألفًا، مع كل ألف سبعون ألفًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (406) and al-Muʿjam al-Kabīr (22/304-305).","chapter_en":"Seventy Thousand from the Ummah of Muḥammad ﷺ Will Enter Paradise, and with Every Thousand Another Seventy Thousand","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Abū Saʿīd al-Anmārī narrated that the Messenger of Allah ﷺ said: “My Lord has promised me that seventy thousand from my Ummah will enter Paradise without reckoning. Every thousand of them will intercede for seventy thousand, then my Lord will take three handfuls with His two Hands.” Qays said: I asked Abū Saʿīd: “Did you hear this from the Messenger of Allah ﷺ?” He replied: “Yes, with my own ears, and my heart retained it.” Abū Saʿīd said: “That, Allah willing, will encompass the Muhājirūn of his Ummah, and Allah, Mighty and Majestic, will complete the remainder from our Bedouins.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الأوسط (406)، وفي الكبير (22/304-305)."},{"num":16389,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا، قَالُوا: زِدْنَا يَا رَسُولَ اللَّهِ، قَالَ: لِكُلِّ رَجُلٍ سَبْعُونَ أَلْفًا، قَالُوا: زِدْنَا يَا رَسُولَ اللَّهِ، وَكَانَ عَلَى كَثِيبٍ، فَحَثَا بِيَدِهِ، قَالُوا: زِدْنَا يَا رَسُولَ اللَّهِ فَقَالَ: هَذَا وَحَثَا بِيَدِهِ، قَالُوا: يَا نَبِيَّ اللَّهِ، أَبَعْدَ اللَّهُ مَنْ دَخَلَ النَّارَ بَعْدَ هَذَا."],"takhrij":"حسن: رواه أبو يعلى (3783) عن محمد بن أبي بكر المقدمي، حدثنا عبدالقاهر بن السري، حدثنا حميد، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب يدخل من أمة محمد سبعون ألفًا، مع كل ألف سبعون ألفًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (3783).","chapter_en":"Seventy Thousand from the Ummah of Muḥammad ﷺ Will Enter Paradise, and with Every Thousand Another Seventy Thousand","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “Seventy thousand from my Ummah will enter Paradise.” They said: “Give us more, O Messenger of Allah.” He said: “For every one of them, seventy thousand.” They said: “Give us more, O Messenger of Allah.” He was upon a mound, so he scooped with his hand. They again said: “Give us more, O Messenger of Allah.” He said: “And this.” Then he scooped with his hand again. They said: “O Prophet of Allah, may Allah cast far away whoever enters the Fire after all of this.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (3783)."},{"num":16390,"demo":false,"sanad":"","matn":["عن أنس، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَدْخُلُ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا بِغَيْرِ حِسَابٍ، . فَقَالَ أَبُو بَكْرٍ: يَا رَسُولَ اللَّهِ، زِدْنَا، فَقَالَ: وَهَكَذَا. فَقَالَ عُمَرُ: يَا أَبَا بَكْرٍ، إِنْ شَاءَ اللَّهُ أَدْخَلَهُمُ الْجَنَّةَ بِحَفْنَةٍ وَاحِدَةٍ."],"takhrij":"حسن: رواه البزار في كشف الأستار (3548)، عن طالوت بن عباد، حدثنا أبو عوانة، عن أبي هلال، عن قتادة، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب يدخل من أمة محمد سبعون ألفًا، مع كل ألف سبعون ألفًا","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (3548).","chapter_en":"Seventy Thousand from the Ummah of Muḥammad ﷺ Will Enter Paradise, and with Every Thousand Another Seventy Thousand","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":17,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “Seventy thousand from my Ummah will enter Paradise without reckoning.” Abū Bakr said: “O Messenger of Allah, give us more.” He said: “And like this,” gesturing with a handful. ʿUmar then said: “O Abū Bakr, if Allah wills, He can admit them all into Paradise in a single handful.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3548)."},{"num":16391,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي قُبَّةٍ، فَقَالَ: أَتَرْضَوْنَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ. قُلْنَا: نَعَمْ. قَالَ: تَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ. قُلْنَا: نَعَمْ. قَالَ: أَتَرْضَوْنَ أَنْ تَكُونُوا شَطْرَ أَهْلِ الْجَنَّةِ. قُلْنَا: نَعَمْ. قَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، إِنِّي لأَرْجُو أَنْ تَكُونُوا نِصْفَ أَهْلِ الْجَنَّةِ، وَذَلِكَ أَنَّ الْجَنَّةَ لاَ يَدْخُلُهَا إِلاَّ نَفْسٌ مُسْلِمَةٌ، وَمَا أَنْتُمْ فِي أَهْلِ الشِّرْكِ إِلاَّ كَالشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الأَسْوَدِ، أَوْ كَالشَّعْرَةِ السَّوْدَاءِ فِي جِلْدِ الثَّوْرِ الأَحْمَرِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6528)، ومسلم في الإيمان (221: 377) كلاهما عن محمد بن جعفر، حدثنا شعبة، عن أبي إسحاق، عن عمرو بن ميمون، عن عبد الله بن مسعود، فذكره.","grade":"متفق عليه","chapter_ar":"باب في عدد أهل الجنة من هذه الأمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6528) and Muslim (377 :221).","chapter_en":"The Number of the People of Paradise from This Ummah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: We were with the Prophet ﷺ in a tent when he asked: “Would you be pleased to constitute one quarter of the people of Paradise?” We replied: “Yes.” He asked: “Would you be pleased to constitute one third of the people of Paradise?” We replied: “Yes.” He asked: “Would you be pleased to constitute half of the people of Paradise?” We replied: “Yes.” He said: “By the One in whose hand is the soul of Muḥammad, I hope that you will constitute half of the people of Paradise. That is because none will enter Paradise except a Muslim soul, and compared with the people of shirk, you are only like a white hair on the hide of a black bull, or a black hair on the hide of a red bull.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6528)، ومسلم (221: 377)."},{"num":16392,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقُولُ اللَّهُ: يَا آدَمُ. فَيَقُولُ: لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ فِي يَدَيْكَ. قَالَ: يَقُولُ: أَخْرِجْ بَعْثَ النَّارِ. قَالَ: وَمَا بَعْثُ النَّارِ؟ قَالَ: مِنْ كُلِّ أَلْفٍ تِسْعَمِائَةٍ وَتِسْعَةً وَتِسْعِينَ. فَذَاكَ حِينَ يَشِيبُ الصَّغِيرُ، ﴿وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا، وَتَرَى النَّاسَ سَكْرَى وَمَا هُمْ بِسَكْرَى وَلَكِنَّ عَذَابَ اللَّهِ شَدِيدٌ﴾ [سورة الحج: 2]. فَاشْتَدَّ ذَلِكَ عَلَيْهِمْ فَقَالُوا: يَا رَسُولُ اللَّهِ، أَيُّنَا الرَّجُلُ؟ قَالَ: أَبْشِرُوا، فَإِنَّ مِنْ يَأْجُوجَ وَمَأْجُوجَ أَلْفٌ وَمِنْكُمْ رَجُلٌ ـ ثُمَّ قَالَ: ـ وَالَّذِي نَفْسِي فِي يَدِهِ إِنِّي لأَطْمَعُ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ. قَالَ: فَحَمِدْنَا اللَّهَ وَكَبَّرْنَا، ثُمَّ قَالَ: وَالَّذِي نَفْسِي فِي يَدِهِ إِنِّي لأَطْمَعُ أَنْ تَكُونُوا شَطْرَ أَهْلِ الْجَنَّةِ، إِنَّ مَثَلَكُمْ فِي الأُمَمِ كَمَثَلِ الشَّعَرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الأَسْوَدِ، أَوِ الرَّقْمَةِ فِي ذِرَاعِ الْحِمَارِ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6528)، ومسلم في الإيمان (221: 377) كلاهما من حديث جرير، عن الأعمش، عن أبي صالح، عن أبي سعيد الخدري، فذكره.","grade":"متفق عليه","chapter_ar":"باب في عدد أهل الجنة من هذه الأمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6530) and Muslim (379 :222).","chapter_en":"The Number of the People of Paradise from This Ummah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abū Saʿīd narrated that the Messenger of Allah ﷺ said: “Allah will say: ‘O Ādam.’ He will reply: ‘Here I am at Your service and ready to obey You, and all good is in Your Hands.’ Allah will say: ‘Bring forth the contingent of the Fire.’ He will ask: ‘What is the contingent of the Fire?’ Allah will say: ‘From every thousand, nine hundred and ninety-nine.’ That will be the time when the young child turns gray, when every pregnant woman will miscarry, and you will see the people as though intoxicated, though they are not intoxicated; rather, the punishment of Allah is severe.” [al-Ḥajj 22:2] This weighed heavily upon them, so they asked: “O Messenger of Allah, which one of us will be that one?” He replied: “Receive glad tidings. From Yaʾjūj and Maʾjūj there will be one thousand, and from you one.” Then he said: “By the One in whose hand is my soul, I hope that you will constitute one third of the people of Paradise.” We praised Allah and proclaimed His greatness. Then he said: “By the One in whose hand is my soul, I hope that you will constitute half of the people of Paradise. Your likeness among all the nations is like a white hair on the hide of a black bull, or like a mark upon the foreleg of a donkey.”"]},"buhuth":{"en":["Regarding the statement:","“That will be the time when the young child turns gray,”","its meaning corresponds to the statement of Allah, the Exalted:","“Then how will you protect yourselves, if you disbelieve, from a Day that will turn children gray-haired?”","[al-Muzzammil 73:17]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8336],"tks":"متفق عليه: رواه البخاري (6528)، ومسلم (221: 377)."},{"num":16393,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَرْجُو أَنْ يَكُونَ مَنْ يَتَّبِعُنِي مِنْ أُمَّتِي يَوْمَ الْقِيَامَةِ، رُبْعَ أَهْلِ الْجَنَّةِ قَالَ: فَكَبَّرْنَا. قَالَ: أَرْجُو أَنْ يَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ قَالَ: فَكَبَّرْنَا. قَالَ: أَرْجُو أَنْ يَكُونُوا الشَّطْرَ."],"takhrij":"حسن: رواه أحمد (15114)، والبزار في كشف الأستار (3533) كلاهما من طريق ابن جريج قال: أخبرني أبو الزبير أنه سمع جابر بن عبدالله يقول فذكره.","grade":"حسن","chapter_ar":"باب في عدد أهل الجنة من هذه الأمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15114) and al-Bazzār in Kashf al-Astār (3533).","chapter_en":"The Number of the People of Paradise from This Ummah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: I heard the Messenger of Allah ﷺ say: “I hope that those from my Ummah who follow me on the Day of Resurrection will constitute one quarter of the people of Paradise.” We proclaimed Allah’s greatness. Then he said: “I hope that they will constitute one third of the people of Paradise.” We again proclaimed Allah’s greatness. Then he said: “I hope that they will constitute half.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15114)، والبزار في كشف الأستار (3533)."},{"num":16394,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَوَّلُ مَنْ يُدْعَى يَوْمَ الْقِيَامَةِ آدَمُ، فَتَرَاءَى ذُرِّيَّتُهُ، فَيُقَالُ: هَذَا أَبُوكُمْ آدَمُ. فَيَقُولُ: لَبَّيْكَ وَسَعْدَيْكَ. فَيَقُولُ: أَخْرِجْ بَعْثَ جَهَنَّمَ مِنْ ذُرِّيَّتِكَ. فَيَقُولُ: يَا رَبِّ كَمْ أُخْرِجُ؟ فَيَقُولُ: أَخْرِجْ مِنْ كُلِّ مِائَةٍ تِسْعَةً وَتِسْعِينَ. فَقَالُوا: يَا رَسُولَ اللَّهِ، إِذَا أُخِذَ مِنَّا مِنْ كُلِّ مِائَةٍ تِسْعَةٌ وَتِسْعُونَ، فَمَاذَا يَبْقَى مِنَّا؟ قَالَ: إِنَّ أُمَّتِي فِي الأُمَمِ كَالشَّعَرَةِ الْبَيْضَاءِ فِي الثَّوْرِ الأَسْوَدِ."],"takhrij":"صحيح: رواه البخاري في الرقاق (6529)، عن إسماعيل، حدثني أخي، عن سليمان، عن ثور، عن أبي الغيث، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب في عدد أهل الجنة من هذه الأمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6529).","chapter_en":"The Number of the People of Paradise from This Ummah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The first to be called on the Day of Resurrection will be Ādam. His descendants will be shown to him, and it will be said: ‘This is your father Ādam.’ He will say: ‘Here I am at Your service and ready to obey You.’ It will be said: ‘Bring forth from your descendants the contingent for Hell.’ He will ask: ‘My Lord, how many should I bring forth?’ He will say: ‘From every hundred, ninety-nine.’” They asked: “O Messenger of Allah, if ninety-nine out of every hundred of us are taken, then what will remain of us?” He replied: “My Ummah among the other nations is like a white hair on a black bull.”"]}},"tuhfa":{},"full":1,"rep":[8337],"tks":"صحيح: رواه البخاري (6529)."},{"num":16395,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أُنْزِلَتْ ﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ﴾ [سورة الحج: 1] إِلَى قَوْلِهِ تَعَالَى: وَ َلَكِنَّ عَذَابَ اللَّهِ شَدِيدٌ [الحج: 1-٢], قَالَ: نَزَلَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي مَسِيرٍ لَهُ, فَرَفَعَ بِهَا صَوْتَهُ حَتَّى ثَابَ إِلَيْهِ أَصْحَابُهُ, فَقَالَ: أَتَدْرُونَ أَيُّ يَوْمٍ هَذَا؟ يَوْمَ يَقُولُ اللَّهُ لآدَمَ: يَا آدَمُ، قُمْ فَابْعَثْ بَعْثَ النَّارِ مِنْ كُلِّ أَلْفٍ تِسْعَمِائَةٍ وَتِسْعَةً وَتِسْعِينَ إِلَى النَّارِ وَوَاحِدًا إِلَى الْجَنَّةِ., قَالَ: فَكَبُرَ ذَلِكَ عَلَى الْمُسْلِمِينَ, فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : سَدِّدُوا وَقَارِبُوا وَأَبْشِرُوا, فَوَالَّذِي نَفْسِي بِيَدِهِ مَا أَنْتُمْ فِي النَّاسِ إِلَّا كَالشَّامَةِ فِي جَنْبِ الْبَعِيرِ, أَوْ كَالرَّقْمَةِ فِي ذِرَاعِ الدَّابَّةِ, فإن مَعَكُمْ لَخَلِيقَتَيْنِ مَا كَانَتَا مَعَ شَيْءٍ قَطُّ إِلَاّ كَثَّرَتَاهُ: يَأْجُوجَ, وَمَأْجُوجَ, وَمَنْ هَلَكَ مِنْ كَفَرَةِ الإنس والجن."],"takhrij":"صحيح: رواه عبد الرزاق في تفسيره (2/31) –واللفظ له-، وعبد بن حميد (1185)، وصحّحه ابن جبان (7354)، والحاكم (1/29، و4/566)، كلهم من طريق معمر, عن قتادة, عن أنس, فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في عدد أهل الجنة من هذه الأمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by ʿAbd al-Razzāq in his Tafsīr (2/31), whose wording this is, ʿAbd ibn Ḥumayd (1185), and authenticated by Ibn Ḥibbān (7354).","chapter_en":"The Number of the People of Paradise from This Ummah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Mālik narrated: The verses were revealed: “O mankind, fear your Lord. Indeed, the convulsion of the Hour is a tremendous thing…” up to the statement: “…but the punishment of Allah is severe.” [al-Ḥajj 22:1-2] They were revealed to the Prophet ﷺ while he was traveling. He raised his voice reciting them until his Companions gathered around him. He asked: “Do you know what Day this is? It is the Day when Allah will say to Ādam: ‘O Ādam, rise and send forth the contingent of the Fire: from every thousand, nine hundred and ninety-nine to the Fire and one to Paradise.’” This greatly distressed the Muslims. The Prophet ﷺ then said: “Remain upon the right course, come as close as you can, and receive glad tidings. By the One in whose hand is my soul, compared with mankind you are only like a small mark on the side of a camel, or a mark on the foreleg of an animal. For with you are two creations which have never been together with anything except that they greatly increased its number: Yaʾjūj and Maʾjūj, and those who perished among the disbelievers of mankind and the jinn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد الرزاق في تفسيره (2/31) - واللفظ له -، وعبد بن حميد (1185)، وصححه ابن حبان (7354)."},{"num":16396,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ تَعَالَى يَقُولُ يَوْمَ الْقِيَامَةِ لِآدَمَ: قُمْ فَجَهِّزْ مِنْ ذُرِّيَّتِكَ تِسْعَ مِائَةٍ وَتِسْعَةً وَتِسْعِينَ إِلَى النَّارِ، وَوَاحِدًا إِلَى الْجَنَّةِ فَبَكَى أَصْحَابُهُ وَبَكَوْا ثُمَّ قَالَ: لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْفَعُوا رُءُوسَكُمْ فَوَالَّذِي نَفْسِي بِيَدِهِ، مَا أُمَّتِي فِي الْأُمَمِ إِلَّا كَالشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الْأَسْوَدِ فَخَفَّفَ ذَلِكَ عَنْهُمْ."],"takhrij":"حسن: رواه أحمد (27489) عن هيثم، قال: أخبرنا أبو الربيع، عن يونس، عن أبي إدريس، عن أبي الدرداء، فذكره.","grade":"حسن","chapter_ar":"باب في عدد أهل الجنة من هذه الأمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27489).","chapter_en":"The Number of the People of Paradise from This Ummah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Abū al-Dardāʾ narrated that the Prophet ﷺ said: “Allah, the Exalted, will say to Ādam on the Day of Resurrection: ‘Rise and prepare from your descendants nine hundred and ninety-nine for the Fire and one for Paradise.’” His Companions began to weep. Then the Messenger of Allah ﷺ said: “Raise your heads. By the One in whose hand is my soul, my Ummah among the other nations is only like a white hair on the hide of a black bull.” This eased their distress."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8342],"tks":"حسن: رواه أحمد (27489)."},{"num":16397,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَهْلُ الْجَنَّةِ عِشْرُونَ وَمِائَةُ صَفٍّ، ثَمَانُونَ مِنْهَا مِنْ هَذِهِ الأُمَّةِ، وَأَرْبَعُونَ مِنْ سَائِرِ الأُمَمِ."],"takhrij":"صحيح: رواه الترمذي (2546)، وأحمد (22940)، وابن حبان (7459)، والحاكم (274) كلهم من طريق أبي سنان ضرار بن مرة، عن محارب بن دثار، عن ابن بريدة، عن أبيه قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في عدد أهل الجنة من هذه الأمة","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2546), Aḥmad (22940), Ibn Ḥibbān (7459), and al-Ḥākim (1/81-82).","chapter_en":"The Number of the People of Paradise from This Ummah","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":18,"content":{"translation":{"en":["Buraydah narrated that the Messenger of Allah ﷺ said: “The people of Paradise will form one hundred and twenty rows. Eighty of those rows will be from this Ummah, and forty will be from all the other nations.”"]},"buhuth":{"en":["The author explains that this increase beyond one half is to be understood as an additional bounty granted by Allah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2546)، وأحمد (22940)، وابن حبان (7459)، والحاكم (274)."},{"num":16398,"demo":false,"sanad":"","matn":["عَنْ أَبِي التَّيَّاحِ قَالَ:  كَانَ لِمُطَرِّفِ بْنِ عَبْدِ اللَّهِ امْرَأَتَانِ، فَجَاءَ مِنْ عِنْدِ إِحْدَاهُمَا، فَقَالَتِ الْأُخْرَى: جِئْتَ مِنْ عِنْدِ فُلَانَةَ؟ فَقَالَ: جِئْتُ مِنْ عِنْدِ عِمْرَانَ بْنِ حُصَيْنٍ، فَحَدَّثَنَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنَّ أَقَلَّ سَاكِنِي الْجَنَّةِ النِّسَاءُ."],"takhrij":"صحيح: رواه مسلم في الرقاق (2738) عن عبيد الله بن معاذ، حدثنا أبي، حدثنا شعبة، عن أبي التياح قال: فذكره.","grade":"صحيح","chapter_ar":"باب أقل ساكني الجنة النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2738).","chapter_en":"Women Are the Least Numerous Inhabitants of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["Abū al-Tayyāḥ narrated: Muṭarrif ibn ʿAbdullāh had two wives. He came from one of them, and the other asked: “Have you come from so-and-so?” He replied: “I came from ʿImrān ibn Ḥuṣayn, who narrated to us that the Messenger of Allah ﷺ said: ‘Women are the least numerous inhabitants of Paradise.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2738)."},{"num":16399,"demo":false,"sanad":"","matn":["عَنْ عُمَارَةَ بْنِ خُزَيْمَةَ، قَالَ: بَيْنَمَا نَحْنُ مَعَ عَمْرِو بْنِ الْعَاصِ فِي حَجٍّ أَوْ عُمْرَةٍ، فَقَالَ: بَيْنَمَا نَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الشِّعْبِ إِذْ قَالَ: انْظُرُوا، هَلْ تَرَوْنَ شَيْئًا؟ فَقُلْنَا: نَرَى غِرْبَانًا فِيهَا غُرَابٌ أَعْصَمُ أَحْمَرُ الْمِنْقَارِ، وَالرِّجْلَيْنِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَدْخُلُ الْجَنَّةَ مِنَ النِّسَاءِ، إِلَّا مَنْ كَانَ مِنْهُنَّ مِثْلَ هَذَا الْغُرَابِ فِي الْغِرْبَانِ."],"takhrij":"صحيح: رواه أحمد (17770) –واللفظ له-، وأبو يعلى (7343)، والحاكم (8782) كلهم من طريق حماد بن سلمة، حدثنا أبو جعفر الخطمي، عن عمارة بن خزيمة بن ثابت قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب أقل ساكني الجنة النساء","chapter_ur":"","part_ar":"كتاب صفة الجنة والنار، وأهلها","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17770), whose wording this is, Abū Yaʿlā (7343), and al-Ḥākim (4/602).","chapter_en":"Women Are the Least Numerous Inhabitants of Paradise","part_en":"The Description of Paradise, the Fire, and Their Inhabitants","group_ar":"جموع ما جاء في صفة أهل الجنة","group_en":"A Collection of What Has Been Narrated Concerning the Description of the People of Paradise","part_no":67,"group_no":2,"chapter_no":19,"content":{"translation":{"en":["ʿUmārah ibn Khuzaymah narrated: While we were with ʿAmr ibn al-ʿĀṣ during Ḥajj or ʿUmrah, he said: While we were with the Messenger of Allah ﷺ in this mountain pass, he said: “Look. Do you see anything?” We replied: “We see a flock of crows among which there is a white-marked crow with a red beak and red legs.” The Messenger of Allah ﷺ said: “No women will enter Paradise except in a proportion like that crow among the other crows.”"]},"buhuth":{"en":["Regarding the statement:","“Like this crow among the other crows,”","the author explains that it refers to the small number of women entering Paradise, comparable to the rarity of that particular type of crow among other crows."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17770) - واللفظ له -، وأبو يعلى (7343)، والحاكم (8782)."}]);